\section{Gohon's decision algorithm}
Gohon's algorithm~\cite{GOHON} decides whether the commutative closure of a regular language of $A^*$ is regular. Instead of starting from the language, it starts directly from the commutative image of the language. That is, this decision algorithm works directly on $\mathbb{N}^k$. 
When dealing with the commutative closure of sets and when transforming expressions denoting sets, an algebraic approach is both appropriate and useful.


A monoid is a set equipped with an associative binary operation and a neutral element for that operation.
The set $A^*$ is the free monoid over a finite alphabet $A$ with the concatenation as the monoid operation and the empty word $\lambda$  acting as the unit element.
The free commutative monoid generated by a set \( A \) is the quotient of \( A^* \) (the free monoid on \( A \)) by the congruence defined by the relations \( ab = ba \) for all letters \( a \) and \( b \) in \( A \). This commutative monoid is denoted by \( A^\oplus \), where the monoid operation is written as \( + \), and the neutral element is written as \( 0 \).
The monoid $A^\oplus$ is isomorphic to $\mathbb{N}^k$, whose elements are the $k$-tuples of natural numbers $\sigma = (s_1, s_2, \dots , s_k)$. It is also isomorphic to $a^*_1 \times a^*_2 \times \cdots \times a^*_k$ , where $a_1,\dots,a_k$ are the letters of $A$.


Regular expressions are generalised to the setting of ${\mathbb N}^k$
and referred to as rational expressions.
These are defined as one would expect. 

\begin{define}[Rational expression]
A rational expression over $\mathbb{N}^k$ is a formula obtained inductively from elements of $\mathbb{N}^k$ and the 
symbols in $\{\emptyset, \cup, +,\oplus,\left(,\right)\}$ as follows:
$\emptyset$ and every element of $\mathbb{N}^k$ are rational expressions;
If $E$ and $F$ are rational expressions, then $(E \cup F)$, $(E + F)$ and $(E^\oplus)$ are also rational expressions.
\end{define}

The set of   $\mathbb{N}^k$
  denoted by a rational expression 
  is defined similarly to  the set of $A^*$  denoted by a regular expression. 

The set denoted by a rational expression, contained in $\mathbb{N}^k$, is defined in an analogous manner as we defined the set contained in $A^*$ denoted by a regular expression. We simply write $E$ to refer to the set denoted by $E$ and use the standard precedence (first $\oplus$, then $ +$ and last $\cup$).





\begin{define}[Rational set]
A set $S$ of $\mathbb{N}^k$ is rational if
it is denoted by a rational expression over $\mathbb{N}^k$.
%We write $Rat(\mathbb{N}^k)$ to denote the family of rational sets.
\end{define}

The star height of a rational expression is defined for any monoid, we give it just for~${\mathbb N}^k$.

\begin{define}[Star height of a rational expression]
The star height of a rational expression $E$, denoted $h(E)$, is the maximum number of stars nested in the expression $E$. It is defined inductively for rational expressions of $\mathbb{N}^k$:
\begin{align*}
&\text{If }E=\emptyset \text{ or }E \text{ denotes an element of }\mathbb{N}^k \text{ then }
&&h(E)=0.
\\
&\text{If }E=F \cup G\text{ or }E=F + G \text{ then } &&h(E)=\max(h(F),h(G)).
\\
&\text{If }E=F^\oplus \text{ then } && h(E)=1+h(F).
\end{align*}
\end{define}

\begin{ej}
\ejlabel{star}
The star height of ${\big((0,1)^\oplus+(1,0)\big)}^\oplus$ is 2.
\end{ej}

\begin{define}[Star height of a rational set]

The star height of a rational set $S$ of $\mathbb{N}^k$, written $h(S)$, is the minimum star height of the rational expressions of $\mathbb{N}^k$ that denote $S$.
\end{define}

Since the monoid $\mathbb{N}^k$ is commutative, every rational set can be denoted by an expression of star height at most $1$ (see~\cite[Exer. I.6.5]{Sakarovitch}).


\begin{prop}
The star height of a rational set $S\in \mathbb{N}^k$ is at most $1$.
\end{prop}

We therefore define expressions where we restrict the star height.

\begin{define}[Linear expression and semi-linear expression] An expression $E$ denoting a rational set of $\mathbb{N}^k$ is
linear if $E = \gamma+B^\oplus$ where $\gamma \in \mathbb{N}^k$ and $B$ is a finite set of $\mathbb{N}^k$;
it is semi-linear if it is the finite union of linear expressions.
%\end{itemize}
\end{define}
\begin{ej*}[Continuation of \ejref{star}]
${\big((0,1)^\oplus+(1,0)\big)}^\oplus$ is equivalent to the rational expression $(1,0)^\oplus ~\cup~ \Big((1,0)+\big((0,1)\cup(1,0)\big)^\oplus \Big)$ which is semi-linear and has star height $1$.
\end{ej*}

\begin{define}[Non-ambiguous rational operations]
In $\mathbb{N}^k$ we define the non-ambiguous rational operations, a specialization of the rational operations for which we  use the same symbols:

%(Non-ambiguous union) 
$S\cup T$ is non-ambiguous if $S\cap T = \emptyset$;

%(Non-ambiguous addition) 
$S+T$ is non-ambiguous if 
$\forall s,s' \in S, \forall t,t' \in T$, $( s+t = s'+t' )$ implies $(s=s' \text{ and } t=t')$;

%(Non-ambiguous star) 
$S^\oplus = \bigcup\limits_{n \in \mathbb{N}}\underbrace{S+\cdots+S}\limits_{n~times}$ is non-ambiguous if each of the sums and unions are non-ambiguous.
\end{define}

 By commutativity of the monoid, if we consider $S=\{s_1,s_2,\ldots,s_l\}\subseteq \mathbb{N}^k$ then
 $$S^\oplus =s_1^\oplus + s_2^\oplus + \cdots + s_l^\oplus = \{n_1s_1 + n_2s_2 + \cdots + n_ls_l \ : \ n_i \in \mathbb{N} \}.$$
 So, $S^\oplus$ is non-ambiguous if and only if whenever 
 $$n_1s_1+\cdots+n_ls_l = m_1s_1+\cdots+m_ls_l$$
 we have $n_i = m_i$ for each $i$.

 \begin{define}[Free basis]

A finite set $B\subseteq \mathbb{N}^k$ is a free basis if
$B^\oplus$ is a non-ambiguous rational expression.
\end{define}

\begin{ej}
$B = \{(1,0),(3,1),(1,1)\}$ is not free because $2(1,0) + (1,1)=(3,1)$. On the other hand $B'=\{(1,0),(1,1)\}$ is a free basis.
\end{ej}

\begin{define}[Simple expression and semi-simple expression] An expression $E$ denoting a set of $\mathbb{N}^k$ is
%\begin{itemize}
%\item[] 
simple if $E$ is linear ($E = \gamma+B^\oplus$) and $B$ is a free basis;
%\item[] 
and it is semi-simple if it is the unambiguous union of simple expressions.
%\end{itemize}
\end{define}

\begin{ej*}[Continuation of \ejref{star}]
The semi-linear rational expression \linebreak 
$(1,0)^\oplus ~\cup~ (1,0)+((0,1)\cup(1,0))^\oplus$ is not semi-simple.
Both $(1,0)^\oplus$ and $(1,0)+((0,1)\cup(1,0))^\oplus$ are simple because both bases are free. However, their union is ambiguous, because their intersection equals $(1,0)+(1,0)^\oplus$.
An equivalent semi-simple expression is
 $$
 (1,0)^\oplus ~\cup~ \Big((1,1)+\big((0,1)\cup(1,0)\big)^\oplus \Big).
 $$
 These expressions are  depicted in \autoref{fig:diagonal graph}.

