Finally, we consider formal series on $k$ commutative variables $x_1,\dots,x_k$. In particular, we are interested in the characteristic series of sets of $\mathbb{N}^k$.


\begin{define}\deflabel{charseries}
For every rational subset $S$ of ${\mathbb N}^k$ we denote by $\underline{S}$ the characteristic  series of $S$, defined as follows:
For each element $\sigma\in {\mathbb N}^k$, if $\sigma=(s_1,\dots,s_k)\in S$ then   the coefficient of $x_1^{s_1}\cdots x_k^{s_k}$ in $\underline{S}$ is $1$, 
and it is $0$ otherwise.
\end{define}


\begin{note}
Given a formal series $T$ over $k$ commutative variables $x_1,\dots,x_k$ and an element $\sigma=(s_1,\dots,s_k)\in \mathbb{N}^k$ we write $T\left[(s_1,\dots,s_k)\right]$ to denote the coefficient of $x_1^{s_1}\cdots x_k^{s_k}$ in $T$.
\end{note}



\begin{rem}
    The characteristic series $\underline{S}$ of a rational subset $S\subseteq\mathbb{N}^k$ is unique and completely characterizes $S$.
\end{rem}

\begin{prop}[{\cite[Proposition 3.1]{GOHON}}]
\proplabel{serie}
 Let $S$ be a rational set of $\mathbb{N}^k$. 
  Its characteristic series $\underline{S}$ can be computed recursively from any semi-simple expression of $S$, as follows: \\
  Let $\gamma = (c_1, c_2,\ldots, c_k)$ an element of $\mathbb{N}^k$, $E$ and $F$ subexpressions, and $B=\{\beta_1,\beta_2,\ldots,\beta_l\}$ a free basis. Then:
\begin{eqnarray*}
 \underline{\gamma}&=&x_1^{c_1}x_2^{c_2}...x_k^{c_k}
 \\
 \underline{E + F} &=& \underline{E}\ \underline{F}
 \\
 \underline{E\cup F} &=&\underline{E}+\underline{F}
 \\
 \underline{B^\oplus}&=&\frac{1}{(1-\underline{\beta_1})(1-\underline{\beta_2})\cdots(1-\underline{\beta_l})}.
 \end{eqnarray*}
\end{prop}


\begin{rem}
    Note that in \propref{serie} it is essential to consider a semi-simple expression. For instance, the rule $\underline{E\cup F} =\underline{E}+\underline{F}$ would fail to produce coefficients smaller than $1$ in the formal series for an ambiguous union in the expression.
\end{rem}

\begin{ej}
\ejlabel{Sa}
Let $U$ the set denoted by $(1,1)+(1,1)^\oplus$, and depicted in Figure~\ref{fig:grafodiagonal}. Then,
$\underline{U} = \frac{xy}{(1-xy)}$.
\end{ej}



\begin{prop}[{\cite[Proposition 3.3]{GOHON}}]
\proplabel{unique}
Let $S$ be a rational subset of $\mathbb{N}^k$. There exists a unique pair of polynomials $P(S)$ and $Q(S)$ $\in \mathbb{Z}[x_1,x_2,...,x_k]$ satisfying the following conditions:
\begin{enumerate}
\item[] $\underline{S}=P(S)/Q(S)$.
\item[] $P(S)/Q(S)$ is irreducible.
\item[] $Q(S)[(0,\ldots,0)]= 1$; that is, its constant term is $1$.
\end{enumerate}
Furthermore, for every pair of polynomials $P$ and $Q$ $\in \mathbb{Z}[x_1,x_2,...,x_k]$ such that $\underline{S} = P/Q$, there exists
a polynomial $R\in \mathbb{Z}[x_1,x_2,...,x_k]$ such that $P = R. P(S)$ and $Q = R. Q(S)$.
\end{prop}

\begin{rem}
\propref{unique} gives a canonical representation of the rational subsets of $\mathbb{N}^k$ and is fundamental for proving \propref{gohon}, Gohon's main result in~\cite{GOHON}. However, \propref{unique} is false for non-commutative monoids such as $A^\star$.
\end{rem}
%Furthermore, w
% When $S$ is recognizable,  \propref{gohon} tells us how the polynomials of the characteristic series associated with $S$  look like.


As we already mentioned, not every regular language $L\subseteq A^*$ has a regular commutative closure ${\EuScript C}(L)$, as a subset of $A^*$. 
However, the commutative image of every regular set of $A^*$ is always a rational set of ${\mathbb N}^k$.


\begin{rem}
The commutative image $\varphi(L)$ of any regular language $L\subseteq A^*$ is a rational set of ${\mathbb N}^k$.
\end{rem}

On the other hand, the fact that a set $S$ is rational in $\mathbb{N}^k$ says nothing about whether $\varphi^{-1}(S)$ is a regular set of $A^*$ or not. 
A well studied subclass of the rational sets   in {finitely generated} monoids is the class of the recognizable sets~\cite{Sakarovitch}. 
Our interest in these sets  comes from the fact that, for any surjective morphism,  the inverse image of a recognizable set of ${\mathbb N}^k$ is a regular set of $A^*$.

\begin{define}[Recognizable set]
Let $A$ be a finite alphabet and let
$\varphi:A^* \to \mathbb{N}^k$ be the commutative image.
A subset $S$ of $\mathbb{N}^k$ is recognizable if
$\varphi^{-1}(S)$ is regular.
\end{define}

Note that if $S$ is recognizable in $\mathbb{N}^k$ then $\varphi(\varphi^{-1}S)=S$ is rational and thus\linebreak $\text{Rec}(\mathbb{N}^k)\subseteq\text{Rat}(\mathbb{N}^k)$.
The following is an equivalent characterization of recognizable sets that is attributed to Mezei.

\begin{define}[{Mezei~\cite[Corollary II.2.20]{Sakarovitch}}]
\deflabel{mezei}
A set $S$ of $\mathbb{N}^k$ is recognizable if
there exists a family of sets
$\{T_{i,j}\}_{i\in I,1\leq j\leq k}$ with $I$ finite and each $T_{i,j}$  rational subsets of  $\mathbb{N}$
such that
$$
S=\bigcup\limits_{i \in I} T_{i,1} \times \cdots \times T_{i,k}.
$$
\end{define}


\begin{rem}
The characterization of recognizable sets as in \defref{mezei} is not unique.
For instance, when $S$ is $\mathbb{N}$, we already find multiple characterizations:
$1^\oplus$; 
 $1 \cup (1 + 1^\oplus)$;
 $1 \cup \cdots \cup n \cup \left((n+1) + 1^\oplus\right)$;
 $2^\oplus \cup ( 1+2^\oplus)$;  \ldots
\end{rem}


The next result is the main  theorem obtained by Gohon in~\cite{GOHON}.


\begin{prop}[{{Gohon~\cite[Theorem 4.6]{GOHON}}}]
\proplabel{gohon}
For every rational  set $S $ of ${\mathbb{N}^k}$, we can associate a fraction $P/Q=\underline{S}$, where $P$ and $Q$ are polynomials of $k$ commutative variables $x_1,x_2,...,x_k$ with coefficients in $\mathbb{Z}$, such that $S$ is recognizable if and only if $Q=1$, or $Q$ is a product of polynomials of the form $(1-x_j^{p_j})$.
\end{prop}

Gohon's algorithm starts from a semi-simple expression and obtains its characteristic series. 
It reduces the polynomials until all factors of more than one variable in the denominator are simplified. This is possible exactly when the set is recognizable. 


\begin{ej*}[Continuation of \ejref{Sa}] 
$\underline{U} = \frac{xy}{(1-xy)}$.
The set $U$, shown in \autoref{fig:grafodiagonal}, is not recognizable because $\underline{U}$ is irreducible and its denominator features a factor with more than one variable.
In fact, 
 if we consider the alphabet $A=\{a,b\}$
the set $U$ corresponds to  ${\EuScript C}({(ab)^+})=\{w\in A^+ \ :\ |w|_a=|w|_b\}={\EuScript C}({(ab)^*})-\{\lambda\}$, which is not regular.
\end{ej*}
