\begin{define}[Shuffle]
The shuffle of two words $w$ and $v$ in $A^*$, denoted with $w \between v$, is the subset of $A^*$ defined by
$$
w \between v=\{w_1v_1\cdots w_nv_n\ : \
w = w_1\cdots w_n, v = v_1\cdots v_n, \text{with }
w_i,v_j \in A^*\
\text{for each $i,j$ and $n \in \mathbb{N}$}
\}
$$
The shuffle of two words is additively extended to the shuffle of two languages in a natural way. If $L,K\subseteq A^\star$ are two languages, their shuffle is defined as follows:
$$
L \between K= \bigcup\limits_{w\in L, v \in K}w \between v.
$$
\end{define}

\begin{ej}
$ab \between ba = \{abba, baba, baab, abab\}$.
\end{ej}

The shuffle of languages is an associative operation on $\mathcal{P}(A^\star)$. Therefore, if $L_1,\dots,L_l$ are languages, we denote
$$
L_1\between\cdots\between L_l = \bigcup\limits_{w_i \in L_i}w_1 \between \cdots \between w_l.
$$

We introduce the shuffle  product automaton.

\begin{define}[Shuffle product automaton]
Let $\mathcal{A'} = \diples{ Q', A, E', I', T' }$ and \linebreak $\mathcal{A''} = \diples{ Q'', A, E'', I'', T'' }$ be deterministic finite state automata.
We define the shuffle product automaton $\mathcal{A}=\mathcal{A'}\between \mathcal{A''}$ as $\mathcal{A} = \diples{Q' \times Q'', A, E, I' \times I'', T' \times T''}$,
where\begin{align*}
E=&\{((p',p''),a,(q',p'')): p''\in Q'' \text{ and }((p',a,q')\in E'\} \cup
\\
&\{((p',p''),a,(p',q'')): p'\in Q' \text{ and }((p'',a,q'')\in E''\}.
\end{align*}
Inductively, given finite state deterministic automata $\mathcal{A}_1,\dots,\mathcal{A}_n$, we define  an automaton $\mathcal{A}=\mathcal{A}_1\between\dots\between\mathcal{A}_n$ by repeating this procedure.
\end{define}

It is easy to see that $L(\mathcal{A'}\between \mathcal{A''})=L(\mathcal{A'})\between L(\mathcal{A''})$. And, furthermore, that \linebreak
$L(\mathcal{A}_1\between\cdots\between \mathcal{A}_n)=L(\mathcal{A}_1)\between\cdots\between L(\mathcal{A}_n)$.

\begin{prop}
The shuffle of two regular languages in $A^*$ is a regular language.
\end{prop}


\begin{prop}
Let $A'$ and $A''$ be  disjoint alphabets, and let $A=A'\cup A''$ be  the union of both. Suppose we have two finite state deterministic   automata $\mathcal{A'}$ and $\mathcal{A''}$ defined on alphabets $A'$ and $A''$ respectively. If we consider both as  automata on $A$, then the shuffle between them $\mathcal{A'}\between\mathcal{A''}$ is also a deterministic finite state automaton.
\end{prop}

\begin{proof}
Assume, forcontradiction, that $\mathcal{A'}\between\mathcal{A''}$ is not deterministic.
 Since $\mathcal{A'}$ and $\mathcal{A''}$ are deterministic, both have only one initial state, so $\mathcal{A'}\between\mathcal{A''}$  has only one initial state too.
Then there must be a state $(p',p'')$ and a letter $a\in A$ such that there's more than one transition labelled $a$ leaving $(p',p'')$. 
Since the alphabets are disjoint there are two exclusive possibilities: either $a\in A'$ or $a\in A''$. Without loss of generality we assume $a\in A'$.
As there are no transitions in $E''$ labelled with $a$, both must be in~$E'$. So there is more than one transition in $E'$ with origin $p'$ and label $a$. This is impossible because $\mathcal{A}'$ is deterministic.
\end{proof}


\begin{note} In the sequel we  write automaton as an abbreviation of  finite state deterministic automaton.
\end{note}

Now we build the automaton over $A^*$ for any atomic resimple expression,  as we did for~$k=1$.

\begin{prop}
\proplabel{resimple automaton}
Let $R=(c_1,\ldots,c_k)+{B}^\oplus$ be an atomic resimple expression denoting a set $S \subseteq \mathbb{N}^k$. We can build an automaton $\mathcal{A}$ that accepts the language $\varphi^{-1}(S) \subseteq A^*$, where $\varphi$ is the commutative image.
\end{prop}

\begin{proof}
By \propref{atomic resimple denote recognizable} we know that $S$ can be written in the form
$S_1 \times \cdots \times S_k$, where each $S_j$ is denoted by a resimple expression $S_j=c_j+p_j^\oplus$. For each coordinate $j$ we can obtain a complete  automaton $\mathcal{A}_j$ labelled over the alphabet $\{a_j\}$ that accepts $\varphi^{-1}(S_j)$, see \autoref{fig:automatacaracol}.
Consider the automaton $\mathcal{A}_j$ as labelled in the larger alphabet $A=\{a_1,\ldots, a_k\}$. Then the shuffle product
$\mathcal{A} = \mathcal{A}_1 \between\dots\between\mathcal{A}_k$
accepts the language $\varphi^{-1}(S)$.   Observe that $w\in L(\mathcal{A})$, if and only if, for every coordinate $j$ we have  $|w|_{a_j}\in S_j$, which is equivalent to $\varphi(w)\in S$.
\end{proof}


