\begin{prop}
\proplabel{half face}
 Let $S$ be a set of $\mathbb{N}^k$.
 If $S$ has a resimple expression that denotes it then $S $ a recognizable set in  $\mathbb{N}^k)$.
\end{prop}
\begin{proof}
The family of recognizable sets of $\mathbb{N}^k$ forms a Boolean algebra (see~\cite{Sakarovitch}) and by \propref{atomic resimple denote recognizable} we know that atomic resimple expressions denote recognizable sets.
\end{proof}

\begin{define}[Consistent resimple expression]
An expression is resimple {consistent} if it is resimple and all the bases of its atoms are the same.
\end{define}

\begin{ej*}[Continuation of \ejref{Sc}]
The resimple expression $\Big((0,1)+\big((1,0)\cup(0,1)\big)^\oplus \Big) \cup \big((2,0)\cup(0,3)\big)^\oplus$, is not consistent because  $\{(1,0),(0,1)\}\neq\{(2,0),(0,3)\}$.
However, \linebreak
$\big((2,0)\cup(0,1)\big)^\oplus \cup \Big((1,1)+\big((2,0)\cup(0,1)\big)^\oplus \Big)$ is  a consistent resimple expression that denotes the same set.
\end{ej*}



\begin{thm}
\thmlabel{automata}
For any resimple expression denoting a recognizable set
 $S$ in $\mathbb{N}^k$  an automaton can be effectively constructed to recognize the language $\varphi^{-1}(S) \subseteq A^*$, where $\varphi$ is the commutative image.
\end{thm}
\begin{proof}
This is an immediate consequence of the \propref{resimple automaton} and the fact that regular languages in $A^*$ form an effective boolean algebra.
\end{proof}

Propositions~\ref{prop:intersection_is_regular} and~\ref{prop:intersection_is_deterministic} below are standard and can be found in any automata theory book (see for instance~\cite{Sakarovitch}). We give the proof of Proposition~\ref{prop:intersection_is_regular} in detail to introduce the intersection automaton.

\begin{prop}
\label{prop:intersection_is_regular}
The intersection of two regular languages in $A^*$ is regular.
\end{prop}
\begin{proof}
Let $\mathcal{A'} = \diples{ Q', A, E', I', T' }$ and $\mathcal{A''} = \diples{ Q'', A, E'', I'', T'' }$.
We define $\mathcal{A}=\mathcal{A'}\cap\mathcal{A''}$ as $\mathcal{A} = \diples{ Q' \times Q'', A, E, I' \times I'', T' \times T''}$, with 
\begin{align*}
E=&\{((p',p''),a,(q',q'')): (p',a,q')\in E'\text{ and }(p'',a,q'')\in E''\}.
\end{align*}
It is easy to see that $L(\mathcal{A})=L(\mathcal{A'})\cap L(\mathcal{A''})$.
\end{proof}
The automaton $\mathcal{A'}\cap\mathcal{A''}$ that we used in the previous proof is called the \textit{intersection automaton} between the automata $\mathcal{A'}$ and $\mathcal{A''}$ and it is a general construction that allows us to obtain an automaton to recognise the intersection of two languages from two automata that recognise each of those languages. 
\begin{prop}
\label{prop:intersection_is_deterministic}
If $\mathcal{A'}$ and $\mathcal{A''}$ are  deterministic automata, then the intersection automaton $\mathcal{A} = \mathcal{A'}\cap\mathcal{A''}$ is also deterministic.
\end{prop}


We are interested in seeing that the  intersection automaton does not grow significantly.

\begin{prop}
\proplabel{inter}
If $\mathcal{A'}$ and $\mathcal{A''}$ are defined from resimple expressions that are consistent with each other, then the number of states in the intersection automaton $\mathcal{A} = \mathcal{A'} \cap \mathcal{A''}$ for one coordinate is at most the maximum between the number of states in $\mathcal{A'}$ and $\mathcal{A''}$ for that coordinate.
\end{prop}
\begin{proof}
Since in each coordinate the two automata end up with the same period, there is a mapping between the states of the two automata. In each coordinate, the intersection of the two automata is just  the bigger one, see \autoref{fig:pairing},  possibly with different  final states.
\end{proof}

