\title{\TN:~Detecting Type Confusion Bugs in Rust Programs}

\author{
{\rm Hung-Mao Chen$^*$, Xu He$^*$, Shu Wang$^*$$^\dag$, Xiaokuan Zhang$^*$, Kun Sun$^*$}\\
$^*$George Mason University\\
$^\dag$Palo Alto Networks
