The theorem given below will prove that the output produced by the circuit of Fig. \ref{new-genmod-dim1} 
is in the D1 form indeed. 
However, besides the following identity ($a\in\{0, 1\}$)
\begin{equation}
- a = \bar a-1, 
\label{nota}\end{equation} 
we will need the following properties. % provided here with their proofs.

\begin{ppp}
For three natural numbers $0 \leq x, y, z <2^n$, the following equation holds:
\begin{eqnarray}
	&&
		\hspace{-19mm}
	\left| x+y+z \right|_{\fermn}
		\nonumber
	\\
	& \overset{\text{\scriptsize CSA}}{=} &
\left| 2c+s \right|_{\fermn} \nonumber\\
	&=&
\left| 2\cdot2^{n-1}c_{n-1} + 2(c_{n-2}\ldots c_0)  +s \right|_{\fermn} \nonumber \\
	&=&
\left| 2^nc_{n-1} + 2(c_{n-2}\ldots c_0)  +s \right|_{\fermn} \nonumber \\
	&=&
\left| 2(c_{n-2}\ldots c_0) -c_{n-1}  +s \right|_{\fermn} \nonumber \\
	&=&
\left| 2(c_{n-2}\ldots c_0) +\bar c_{n-1}-1  +s \right|_{\fermn} \nonumber	\\
	&=&
\left| (c_{n-2}\ldots c_0 \|c_{n-1})-1  +s \right|_{\fermn}
		\label{csa-ferm}
\end{eqnarray}
\label{prop-csa-ferm}\end{ppp} 
\vspace*{-3ex}

\begin{ppp}
For three natural numbers $ 0 \leq x, y <2^n$ and $0 \leq t \leq 2^n$, the following equation holds: 
\begin{eqnarray}
\left| x+y \right|_{\fermn}
	& = & \left| 2^nc_{n-1} + s \right|_{\fermn} \nonumber \\ 
	& = & \left| s-c_{n-1} \right|_{\fermn} \nonumber \\
	& = & \left| s + \bar c_{n-1} -1 \right|_{\fermn}	\nonumber \\
	& = & \left| t -1 \right|_{\fermn} .
		\label{cpa-dim1}\end{eqnarray}
\label{prop-cpa-dim1}\end{ppp} 
\vspace*{-3ex}

Property \ref{prop-csa-ferm} will be used twice to justify the computations 
executed by two subsequent CSA stages, 
whereas Property \ref{prop-cpa-dim1} will be used to evaluate 
the final result provided by the special version of the 
final adder mod \fermn.


