& = & \Big|X^* +1\Big|_{\fermn} 
	\label{xdim-fin}\\
 & \mbox{and} & \nonumber \\
\left| X -1 \right|_{\fermn} & = & X^* .\label{xstar}
\end{eqnarray}
\label{theorem-dim1}\end{ttt}
