\title[A Generalized Higher-Order LOD Framework]{A Generalized Framework for Higher-Order Localized Orthogonal Decomposition Methods}
\author[M.~Hauck, A.~Lozinski, R.~Maier]{Moritz Hauck$^*$, Alexei Lozinski$^\dagger$, Roland~Maier$^*$}
\address{${}^*$ Institute for Applied and Numerical Mathematics, Karlsruhe Institute of Technology, Englerstr.~2, 76131 Karlsruhe, Germany}
