\begin{lemma}  \label{l2d}
The set of degrees of freedom in \eqref{dof2} uniquely define a $V_T$ function in 
  \eqref{V-T}.
\end{lemma}



\begin{proof} The number of degrees of freedom in \eqref{dof2} is
\an{ \label{n2dof} N_d &=(k-1)^2 + 2(2(k-2))+ 4. }
The number of constraint equations in \eqref{V-T} is, one derivative restriction each
   edge,
\an{\label{n2e} N_e &=4. }
Adding \eqref{n2dof} and \eqref{n2e},  we get
\a{ N_d+N_e &= (k-1)^2 + 4(k-1) + 4=(k+1)^2=\dim Q_k.  }
Thus, to determine a $v_h\in V_T$,  we have a square system of linear equations of $(k+1)^2$
   unknowns.
The uniqueness implies the existence of the solution.

Let $v_h\in V_T$ and $F_m(v_h)=0$ for all dofs in \eqref{dof2}.   We need to show $v_h=0$.

Because $v$ vanishes at $k-1$ points on an edge $\b x_1\b x_2$ and $\partial_x v$ vanishes at
  the two end points, the degree-$k$ polynomial $v|_{\b x_1\b x_2}=0$.
Which implies
\a{ v_h = (y-(\b x_1)_2) q_{k,k-1}}
for some $\ q_{k,k-1}\in \t{span} \{ x^i y^j,
   \ 0\le i\le k, \ 0\le j\le k-1\}$, 
   where $(\b x_1)_2$ is the $y$-coordinate of $\b x_1$.


Because the degree $k-1$ polynomial $\partial_y v|_{\b x_1\b x_2}$ vanishes at $k-2$ points on 
   $\b x_1\b x_2$ and its tangential derivative ($\partial_{xy}v_h$) vanishes at
  the two end points, we  $\partial_y v|_{\b x_1\b x_2}=0$.
Thus, we can factor out another factor that 
\a{ v_h = (y-(\b x_1)_2)^2 q_{k,k-2}}
for some $\ q_{k,k-2}\in \t{span} \{ x^i y^j,
   \ 0\le i\le k, \ 0\le j\le k-2\}$.

  Repeating the calculation on the four edges, we have 
\a{v_h = (x-(\b x_1)_1)^2(x-(\b x_3)_1)^2 (y-(\b x_1)_2)^2(y-(\b x_3)_2)^2q_{k-4}}
for some $\ q_{k-4 }\in Q_{k-4}$.  Evaluating $v_h$ at the inner $(k-3)^2$
   points inside $T$, cf. Figure \ref{f-dof2},  we conclude that $q_{k-4}=0$ and $v_h=0$.
  The lemma is proved. 
\end{proof}


\section{The 3D $C^1$-$Q_k$ Bell finite elements}

For the 3-dimensional $V_T$ in \eqref{V-T}, on a size $h$ cube $T$,  
    the degrees of freedom of the Bell element are defined by, cf.
   Figure \ref{f-dof3}, $F_m(v) = $ 
\an{\label{dof3} \begin{cases}
     v ,\partial_x v, \partial_y v,   \partial_z v,  \partial_{xy} v,  \partial_{xz} v, 
      \partial_{yz} v, \partial_{xyz} v, 
         \ \quad \t{at eight vertices}, \\
      v,  \ \quad\qquad\qquad \qquad\qquad\t{at $k-3$ mid-points on 12 edges}, \\
    \partial_{\b n_1} v, \partial_{\b n_2} v, \partial_{\b n_1\b n_2} v,\ \quad 
        \t{at $k-4$ mid-points on 12 edges}, \\
      v,  \ \quad \qquad\qquad \qquad \t{at $(k-3)^2$ mid-points on 6 face-squares}, \\
  \partial_{\b n} v,  \ \qquad \qquad\qquad \t{at $(k-4)^2$ mid-points on 6 face-squares}, \\
      v,  \ \qquad\quad \qquad \qquad \t{at $(k-3)^3$ mid-points inside the cube}. \end{cases} }

