\begin{lemma}  
The set of degrees of freedom in \eqref{dof3} uniquely define a $V_T$ function in 
  \eqref{V-T}.
\end{lemma}



\begin{proof} The number of degrees of freedom in \eqref{dof3} is
\an{ \label{n3dof} \ad{ N_d &=64+12 (4k-15)+6 ((k-4)^2+(k-3)^2)+(k-3)^3 \\
                       &=k^3 + 3 k^2 - 9 k + 7. }  }
To reduce a 2D $Q_k$ polynomial's degree by 1,  we need to post $2k-1$ constraints for
  $x^k, x^{k} y, \dots, x^k y^k, \dots, x y^{k}$ and $ y^k$.
Thus the number of constraint equations in \eqref{V-T} is,  
\an{\label{n3e} N_e &=6(2k-1). }
Adding \eqref{n3dof} and \eqref{n3e},  we get
\a{ N_d+N_e &=k^3 +3 k^2 + 3 k +1 \\
            & =(k+1)^3=\dim Q_k.  }
Thus, to determine a $v_h\in V_T$ in 3D,  
   we have a square system of linear equations of $(k+1)^3$ unknowns.
The uniqueness implies the existence of the solution.

Let $v_h\in V_T$ and $F_m(v_h)=0$ for all dofs in \eqref{dof3}.   We need to show $v_h=0$.
It would use the proof in 2D several times.

On the top square $\b x_5\b x_6\b x_7\b x_8$, the restriction of $v_h$ is a 2D Bell $C^1$-$Q_k$ element.
By the degrees of freedom $\{ v(\b n_l^{(0)}), \partial_x v(\b n_l^{(1)}),   
   \partial_y v(\b n_l^{(2)}),  \partial_{xy} v(\b n_l^{(4)})\}$ and Lemma \ref{l2d},
   we have $v_h|_{\b x_5\b x_6\b x_7\b x_8} = 0 $ and 
\a{ v_h = (z-(\b x_5)_3) q_{k,k,k-1} }
for some $q_{k,k,k-1} \in \t{span} \{ x^i y^j z^l,
   \ 0\le i,j\le k, \ 0\le l\le k-1\}$.


On the top square $\b x_5\b x_6\b x_7\b x_8$, the restriction of $\partial_z v_h$ is a 2D 
  BFS $C^1$-$Q_{k-1}$ element because of the normal derivative restriction in \eqref{V-T}.
By the degrees of freedom $\{ \partial_{z}v(\b n_l^{(3)}), \partial_{xz} v(\b n_l^{(5)}),   
   \partial_{yz} v(\b n_l^{(6)}),  \partial_{xyz} v(\b n_l^{(7)})\}$ and 
    the uni-solvency of the 2D BFS element,
   we have $\partial_{z}v_h|_{\b x_5\b x_6\b x_7\b x_8} = 0 $ and 
\a{ v_h =(z-(\b x_5)_3)^2 q_{k ,k ,k-2} }
for some $q_{k ,k ,k-2} \in \t{span} \{ x^i y^j z^l,
   \ 0\le i,j\le k, \ 0\le l\le k-2\}$.

Repeating above analysis on the other five face squares,  we obtain 
\an{\label{qk-4} v_h = b^2 q_{k-4} }
for some $q_{k-4} \in Q_{k-4}$, where $b=(x-x_1)( x_1+h-x)(y-y_1)( y_1+h-y)
        (z-z_1)( z_1+h-z)$ and $\b x_1 = (x_1,y_1,z_1)$.


For the $Q_{k-4}$ polynomial $q_{k-4}$ in \eqref{qk-4},
  it and $v_h$ vanish at $(k-3)^3$ internal points, defined in \eqref{dof3}.
Thus $q_{k-4}=0$ and $v_h=0$.
  The lemma is proved. 
\end{proof}



\section{The finite element solution and convergence}



The $C^1$-$Q_k$ ($k\ge 4$) Bell finite element spaces are defined by
\an{ \label{V-h} V_h =\{ v_h \in H^2_0(\Omega) : v_h = \sum_{i=1}^N c_i \phi_i \}, }
where $\{ \phi_i\} $ is a basis of the global space which combines the local basis functions
  dual to the degrees of freedom \eqref{dof2} or \eqref{dof3}.


 The finite element discretization of the biharmonic equation \eqref{bi} reads:
   Find $u\in V_h $ such that
\an{\label{finite} (\Delta u, \Delta v) = (f, v) \quad \forall v\in V_h , }
where $V_h$ is defined in \eqref{V-h}.


\begin{lemma} The finite element equation 
    \eqref{finite} has a unique solution. \end{lemma}

\begin{proof}
By letting $v_h=u_h$ and $f=0$ in the linear equation 
    \eqref{finite},  we get $\Delta u_h=0$ on every $T$.
Because $u_h\in H^2_0(\Omega)$,   $u_h$ is a global solution of the Laplace equation,
\a{ \Delta u=0 \ \t{in }\ \Omega;  \quad u= 0 \ \t{on } \ \partial \Omega. }
By the uniqueness of the solution of the Laplace equation, $u_h=0$.  
Thus,  \eqref{finite} has a unique solution. 
 \end{proof}

  In order to have the optimal order $L^2$ convergence,  we need to assume the
    domain $\Omega$ in \eqref{bi} is regular enough,  for example, a square or a 
      cube,  such that 
\an{\label{regular}           |u|_4 \le C \|f\|_0 .   }


\begin{theorem}  Let $ u\in H^{k+1}\cap H^2_0(\Omega)$ be
    the exact solution of the biharmoic equation \eqref{bi}.  
   Let $u_h$ be the $C^1$-$P_k$ finite element solution of \eqref{finite}.   
   Assuming the full-regularity  \eqref{regular}, it holds 
  \a{  \| u- u_h\|_{0} +  h^2  |  u- u_h |_{2}  
         & \le Ch^{k+1} | u|_{k+1}, \quad k\ge 4.  } 
\end{theorem}

\begin{proof} The proof is standard.  A proof can be found in \cite{Zhang-bubble-p4}.

         Subtracting \eqref{finite}  from \eqref{bi},  we get
\a{ (\Delta( u- u_h), \Delta v_h)=0\quad \forall v_h\in   V_{h }. }
In $H^2_0(\Omega)$, the $H^2$ semi-norm $|u|_2$ is equivalent to the norm $\|\Delta u\|_0$.
For simplicity, we denote $\|\Delta u\|_0$ by $|u|_2$, i.e., omitting the 
  norm equivalence constants.
Applying the Schwarz inequality,  it follows that
\a{    |   u- u_h|_{2}^2  
     & =  (\Delta(  u-  u_h), \Delta(  u- I_h u))\\ 
     &\le |   u- u_h|_{2} |   u- I_h u |_{2} \le Ch^{k-1} |u|_{k+1}
 |   u- u_h|_{2} ,} 
      where $ I_h  u$ is the nodal interpolation defined by the degrees of freedom, i.e,
\a{  I_h u |_T =\sum_{n=1}^{N_T} F_n(u) \phi_n  }
  with $F_n$ and $\phi_n$   defined in \eqref{dof2} or \eqref{dof3}   and 
    their dual basis functions, respectively.
As $V_T\supset P_{k} (T)$ in \eqref{V-T},  
$I_h$ preserves $P_{k} $ polynomials locally.
We can use the spline theory in \cite{Lai} to prove the $H^2$-stability of $I_h$.
Or we can modify the theory of 
    \cite{Girault} to prove the $H^2$-stability of $I_h$.
Then It is routing to get
   the quasi-optimal approximation of the operator, cf. \cite{Scott-Zhang}.

To prove the $L^2$ convergence,  we introduce a dual problem,
  \an{ \label{d2}
    ( \Delta w, \Delta v) &=(u-u_h, v), 
     \quad w\in H^2_0(\Omega), \ \forall v \in H^2_0(\Omega) . }
Thus, by \eqref{d2}, 
\a{ \|u-u_h\|_0^2 &=(\Delta w, \Delta (u-u_h) ) = 
(\Delta (w-w_h), \Delta (u-u_h) ) \\
  & \le C h^2 |w|_4  h^{k-1} |u|_n \le C h^{k+1} |u|_{k+1}\|u-u_h\|_0, }
where $w_h$ is the finite element solution to the equation \eqref{d2}.
We obtain the $L^2$ error bound. The theorem is proved.
\end{proof}












\section{Numerical Experiments}



In the 2D numerical computation,  we solve the biharmonic equation \eqref{bi}
   on the unit square domain $\Omega=(0,1)\times(0,1)$. 
We choose an $f$ in \eqref{bi} so that the exact solution is
\an{\label{s2}
   u = \sin^2(\pi x)  \sin^2(\pi y) .  }  
 We compute the solution \eqref{s2} on the square grids shown in Figure \ref{f-2}, by 
  the newly constructed $C^1$-$Q_k$ Bell finite elements \eqref{V-h},
    and by the standard $C^1$-$Q_k$ BFS elements.
The results are listed in Tables \ref{t1}-\ref{t4}, 
    where we can see that the optimal orders of convergence 
  are achieved in all cases.  
Though both methods have the same order of convergence,
  we can compare further the constants before the order term $O(h^k)$.
For a low polynomial degree $k$,  the new element has roughly $3/4$ of unknowns and 
   twice the errors of the corresponding $C^1$-$Q_k$ BFS element.
See an example in counting the number of unknowns in Figure \ref{f-2e}.
Though the Bell elements take slightly less time by the conjugate gradient solver,
   it seems to be outperformed by the BFS elements for low $k$.
For a high polynomial degree $k$, the new element has roughly $9/10$ of unknowns and 
   about the same errors of the corresponding $C^1$-$Q_k$ BFS element.
The two methods perform about equally well.

