The reduction rules are those of Figure~\ref{fig:figureductionrules}.  As
usual, the reduction relation is written $\lra$, its inverse $\lla$,
its reflexive-transitive closure $\lras$, the reflexive-transitive
closure of its inverse $\llas$, and its reflexive-symmetric-transitive
closure $\equiv$.  The first group of rules correspond to the reduction of
cuts on the connectives $\one$, $\multimap$, $\otimes$, $\with$, $\oplus$, and $\oc$.
The next two groups enable us to commute the interstitial rules sum and prod($a$)
with the introduction rules of the connectives $\one$, $\multimap$,
$\top$, $\with$, and $\oc$, and with the elimination rule of the connectives
$\otimes$ and $\oplus$.
For instance, the rule
\(
  \pair{t}{u} \plus \pair{v}{w} \lra  \pair{t \plus v}{u \plus w}
\)
pushes the symbol $\plus$ inside the pair.  The zero-ary commutation rules add
and multiply the scalars:
\(
  {a.\star} \plus b.\star \lra  (a+b).\star
\),
\(
  a \dotprod b.\star \lra  (a \times b).\star
\).


\subsection{Correctness}\label{sec:correctness}
We now prove the subject reduction, confluence, strong normalisation, and introduction
properties of the $\OC$-calculus.

\subsubsection{Subject reduction}
\label{sec:SR}
The subject reduction property is not completely trivial.  As noted in the
introduction, we commute the sum rule with the introductions \emph{as much as
possible}. It is not possible in the case of the connectives $\otimes$ and
$\oplus$, since it would break subject reduction.  For example, the rule $(t\otimes u)\plus(v\otimes w)\lra (t\plus v)\otimes(u\plus w)$ would not be valid.
Intuitivelly, if we consider the $\otimes$ to be a mathematical tensor product and $+$ a vector sums, it is clear that the rule is not valid.
Formally, it suffices to check that we have
\(
  \varnothing;x^A,y^A\vdash (x\otimes y)\plus (y\otimes x):A\otimes A
\)
but
\(
  \varnothing;x^A,y^A \nvdash (x \plus y)\otimes (y \plus x):A\otimes A
\),
since the rule $\otimes_i$ is multiplicative. 

\begin{restatable}[Subject reduction]{theorem}{SR}
%\begin{theorem}[Subject reduction]
  \label{thm:SR}
  If $\Upsilon; \Gamma \vdash t:A$ and $t \lra u$, then $\Upsilon; \Gamma \vdash u:A$.
%\end{theorem}
\end{restatable}
\begin{proof}
  By induction on the relation $\lra$. The proof is given in Appendix~\ref{proof:SR}.
\end{proof}

\subsubsection{Confluence}

\begin{theorem}[Confluence]
\label{thm:Confluence}
The $\OC$-calculus is confluent.
\end{theorem}

\begin{proof}
The reduction system of Figure~\ref{fig:figureductionrules} applied to
well-formed proof-terms is left linear and has no critical pairs.  By
\cite[Theorem 6.8]{Nipkow}, it is confluent.
\end{proof}

\subsubsection{Strong normalisation}\label{sec:ST}
We now prove that all reduction sequences are finite.  To handle the symbols
$\plus$ and $\dotprod$ and the associated reduction rules, we prove the strong
normalisation of an extended reduction system, in the spirit of Girard's
ultra-reduction\footnote{Ultra-reduction is used, in particular, in the
adequacy of the connectives $\plus$ and $\dotprod$.}~\cite{GirardPhDThesis},
whose strong normalisation obviously implies that of the rules of
Figure~\ref{fig:figureductionrules}.


\begin{definition}[Ultra-reduction]
  Ultra-reduction is defined with the rules of Figure~\ref{fig:figureductionrules},
  plus the rules
  \[
    t \plus u  \lra  t \qquad\qquad
    t \plus u  \lra  u \qquad\qquad
    a \dotprod t  \lra  t
  \]
\end{definition}

Our proof is a direct extension from the proof of the $\mathcal L^{\mathcal
S}$-calculus~\cite{DiazcaroDowekMSCS24}.  We use a presentation ready to be
extended to polymorphism, by following the method introduced by
Tait~\cite{TaitJSL67} for Gödel's System T and generalised to System F by
Girard~\cite{GirardPhDThesis}.

\begin{definition}
  $\SN$ is the set of strongly normalising proof-terms and $Red(t)$ is the set of one-step reducts of $t$. That is,
  $\SN = \{ t \mid t\textrm{ strongly normalises}\}$ and $Red(t) = \{u\mid t\lra u\}$.
\end{definition}

\begin{definition}[Reducibility candidates]
  A set of proof-terms $E$ is a reducibility candidate if and only if the following conditions are satisfied.

    (CR1) $E \subseteq \SN$.

    (CR2) If $t \in E$ and $t \lra t'$, then $t' \in E$.

    (CR3) If $t$ is not an introduction and $Red(t) \subseteq E$, then $t \in E$.

The set of all reducibility candidates is called $\mathcal R$. 
\end{definition}

\begin{definition}
  Let $E,F$ be sets of proof-terms. We define the following sets.
  \begin{align*}
    E \hatmultimap F &= \{t \in \SN \mid \textrm{if }t \lras \lambda x^A.u\textrm{, then for every }v \in E, (v/x)u \in F\}\\
    E \hatotimes F &= \{t \in \SN \mid \textrm{if }t \lras u \otimes v\textrm{, then }u \in E\textrm{ and }v \in F\}\\
    E \hatand F &= \{t \in \SN \mid \textrm{if }t \lras \langle u,v \rangle\textrm{, then }u \in E\textrm{ and }v \in F\}\\
    E \hatoplus F &= \{t \in \SN \mid \textrm{if }t \lras \inl(u)\textrm{,\,then\,}u \in E\textrm{\,and if }t \lras \inr(v)\textrm{,\,then }v \in F\}\\
    \hatbang E &= \{t \in \SN \mid \textrm{if }t \lras \oc u\textrm{, then }u \in E\}
  \end{align*}
\end{definition}

\begin{remark}
  Notice that ultra-reduction is used to define the sets $E \hatotimes F$ and $E \hatoplus F$. Indeed, we only need to require, for example, that the term reduces to a tensor, and not to a linear combination of tensors, since any linear combination will itself reduce by the ultra-reduction rules.
\end{remark}

\begin{definition}
  For any proposition $A$, the set of proof-terms $\llbracket A \rrbracket$ is defined as follows:
  \[
    \begin{array}{r@{\,}l@{\qquad}r@{\,}l@{\qquad}r@{\,}l@{\qquad}r@{\,}l}
      \llbracket\one\rrbracket &= \SN
      &\llbracket A \otimes B \rrbracket &= \llbracket A \rrbracket \hatotimes \llbracket B \rrbracket
      &\llbracket \zero \rrbracket &= \SN
      &\llbracket A \oplus B \rrbracket &= \llbracket A \rrbracket \hatoplus \llbracket B \rrbracket\\
      \llbracket A \multimap B \rrbracket &= \llbracket A \rrbracket \hatmultimap \llbracket B \rrbracket 
      &\llbracket \top \rrbracket &= \SN
      &\llbracket A \with B \rrbracket &= \llbracket A \rrbracket \hatand \llbracket B \rrbracket
      &\llbracket \oc A \rrbracket &= \hatbang\llbracket A\rrbracket
    \end{array}
  \]
\end{definition}


\begin{restatable}{lemma}{typeinterpretationsarerc}
%\begin{lemma}
  \label{lem:typeinterpretationsarerc}
  For any proposition $A$, $\llbracket A \rrbracket \in \mathcal R$.
%\end{lemma}
\end{restatable}
\begin{proof}
  By induction on $A$. The proof is given in Appendix~\ref{proof:ST}.
\end{proof}

\begin{lemma}[Variables]
  \label{lem:Var}
  For any proposition $A$, the set $\llbracket A \rrbracket$ contains all the proof-term variables.
\end{lemma}
\begin{proof}
  By Lemma~\ref{lem:typeinterpretationsarerc}, $\llbracket A \rrbracket\in \mathcal R$. Since $Red(x)$ is empty, by CR3, $x \in \llbracket A \rrbracket$.
\end{proof}  


\begin{restatable}[Adequacy for strong normalisation]{lemma}{adequacy}
  \label{lem:adequacy}
  If $\Upsilon;\Gamma\vdash t:A$, then for any substitution $\sigma$ such that for each $x^B\in\Upsilon\cup\Gamma$, $\sigma(x)\in\llbracket B\rrbracket$, we have
  $\sigma t \in \llbracket A \rrbracket$.
\end{restatable}
  \begin{proof}
  By induction on $t$.
%
  If $t$ is a variable, then, by hypothesis, $\sigma t \in \llbracket A
  \rrbracket$. For the other proof-term constructors, we use the adequacy
  lemmas provided in Appendix~\ref{proof:Adequacy}.
\end{proof}


\begin{theorem}[Strong normalisation]\label{thm:ST}
  If $\Upsilon;\Gamma\vdash t:A$, then,
  $t\in\SN$.
\end{theorem}

\begin{proof}
  By Lemma~\ref{lem:Var}, for each $x^B\in\Upsilon\cup\Gamma$, $x^{B}\in\llbracket B \rrbracket$.  Then, by Lemma~\ref{lem:adequacy}, $t = \mathsf{id}(t) \in \llbracket A \rrbracket$. Hence, by Lemma~\ref{lem:typeinterpretationsarerc}, $t\in\SN$. 
\end{proof}


\subsubsection{Introduction property}\label{sec:introductionthm}

\begin{restatable}[Introduction]{theorem}{introductions}
%  \begin{theorem}[Introduction]
  \label{thm:introductions}
  Let $t$ be a closed irreducible proof-term of $A$.
  \begin{itemize}
    \item If $A$ is $\one$, then $t$ has the form $a.\star$.

    \item If $A$ has the form $B \multimap C$, then $t$ has the form
      $\lambda x^B.u$.

    \item If $A$ has the form $B \otimes C$, then $t$ has the form $u \otimes v$,
      $u \plus v$, or $a \dotprod u$.

    \item If $A$ is $\top$, then $t$ is $\langle \rangle$.

    \item The proposition $A$ is not $\zero$.

    \item If $A$ has the form $B \with C$, then $t$ has the form
      $\pair{u}{v}$.

    \item If $A$ has the form $B \oplus C$, then $t$ has the form $\inl(u)$, $\inr(u)$, $u \plus v$, or $a \dotprod u$.
    \item If $A$ has the form $\oc B$, then $t$ has the form $\oc u$.
  \end{itemize}
%  \end{theorem}
\end{restatable}
\begin{proof}
  By induction on $t$. The proof is given in
Appendix~\ref{proof:introductionthm}.
\end{proof}

\subsection{Encodings}\label{sec:secvectorsmatrices}
In this section, we present the encodings for vectors
(Section~\ref{sec:secvectors}) and matrices
(Section~\ref{sec:secmatrices}), which were
initially introduced in~\cite{DiazcaroDowekMSCS24} and are replicated here for
self-containment. 

Since $\mathcal S$ is a semiring, we work with semimodules.
However, to help intuition, the reader may think of $\mathcal S$ as a field,
obtaining a vector space instead.

\subsubsection{Vectors}
\label{sec:secvectors}

As there is one rule $\one_i$ for each scalar $a$, there is one closed
irreducible proof-term $a.\star$ for each scalar $a$.  Thus, the closed irreducible
proof-terms $a.\star$ of $\one$ are in one-to-one correspondence with the elements
of ${\mathcal S}$.  Therefore, the proof-terms $\pair{a.\star}{b.\star}$ of $\one
\with \one$ are in one-to-one correspondence with the elements of ${\mathcal S}^2$, the
proof-terms $\pair{\pair{a.\star}{b.\star}}{c.\star}$ of $(\one \with \one) \with
\one$, and also the proof-terms $\pair{a.\star}{\pair{b.\star}{c.\star}}$ of $\one
\with (\one \with \one)$, are in one-to-one correspondence with the elements
of ${\mathcal S}^3$, etc.

\begin{definition}[The set ${\mathcal V}$]
  The set ${\mathcal V}$ is inductively defined as follows: $\one \in
  {\mathcal V}$, and if $A$ and $B$ are in ${\mathcal V}$, then so is $A
  \with B$.
\end{definition}

We now show that if $A \in {\mathcal V}$, then the set of closed
irreducible proof-terms of $A$ has a structure of $\mathcal S$-semimodule.

\begin{definition}[Zero vector]
  If $A \in {\mathcal V}$, we define the proof-term $0_A$ of $A$ by induction
on $A$.  If $A = \one$, then $0_A = 0.\star$.  If $A = A_1 \with A_2$,
then $0_A = \pair{0_{A_1}}{0_{A_2}}$.
\end{definition}

\begin{lemma}[$\mathcal S$-semimodule structure~\citeintitle{Lemma 3.4}{DiazcaroDowekMSCS24}] \label{lem:vecstructure}
  If $A \in {\mathcal V}$ and $t$, $t_1$, $t_2$, and $t_3$ are closed proof-terms of
  $A$, then
  \begin{multicols}{2}
    \begin{enumerate}
      \item $(t_1 \plus t_2) \plus t_3 \equiv t_1 \plus (t_2 \plus t_3)$
      \item $t_1 \plus t_2 \equiv t_2 \plus t_1$
      \item $t \plus 0_A \equiv t$
      \item $a \dotprod b \dotprod t \equiv (a \times b) \dotprod t$
      \item $1 \dotprod t \equiv t$
      \item $a \dotprod (t_1 \plus t_2) \equiv a \dotprod t_1 \plus a \dotprod t_2$
      \item $(a + b) \dotprod t \equiv a \dotprod t \plus b \dotprod t$
	\qed
    \end{enumerate}
  \end{multicols}
\end{lemma}

\begin{definition}[Dimension of a proposition in ${\mathcal V}$]
To each proposition $A \in {\mathcal V}$, we associate a positive
natural number $d(A)$, which is the number of occurrences of the
symbol $\one$ in $A$: $d(\one) = 1$ and $d(B
\with C) = d(B) + d(C)$.
\end{definition}

If $A \in {\mathcal V}$ and $d(A) = n$, then the closed irreducible proof-terms
of $A$ and the vectors of ${\mathcal S}^n$ are in one-to-one
correspondence.

\begin{definition}[One-to-one correspondence]
\label{def:onetoone}
Let $A \in {\mathcal V}$ with $d(A) = n$.  To each closed irreducible
proof-term $t$ of $A$, we associate a vector $\underline{t}$ of ${\mathcal
  S}^n$ as follows:

  If $A = \one$, then $t = a.\star$. We let $\underline{t} =
  \left(\begin{smallmatrix} a \end{smallmatrix}\right)$.

  If $A = A_1 \with A_2$, then $t = \pair{u}{v}$.  We let
  $\underline{t}$ be the vector with two blocks $\underline{u}$ and
  $\underline{v}$: $\underline{t} = \left(\begin{smallmatrix}
    \underline{u}\\\underline{v} \end{smallmatrix}\right)$.

To each vector ${\bf u}$ of ${\mathcal S}^n$, we associate a closed irreducible proof-term $\overline{\bf u}^A$ of $A$ as follows:

If $n = 1$, then ${\bf u} = \left(\begin{smallmatrix}
  a \end{smallmatrix}\right)$. We let $\overline{\bf u}^A = a.\star$.

If $n > 1$, then $A = A_1 \with A_2$, let $n_1$ and $n_2$ be
  the dimensions of $A_1$ and $A_2$.  Let ${\bf u}_1$ and ${\bf u}_2$
  be the two blocks of ${\bf u}$ of $n_1$ and $n_2$ lines, so ${\bf u}
  = \left(\begin{smallmatrix} {\bf u}_1\\ {\bf
      u}_2\end{smallmatrix}\right)$.  We let $\overline{\bf u}^A =
    \pair{\overline{{\bf u}_1}^{A_1}}{\overline{{\bf u}_2}^{A_2}}$.
\end{definition}

We extend the definition of $\underline{t}$ to any closed proof-term of
$A$, $\underline{t}$ is by definition $\underline{t'}$ where $t'$ is
the irreducible form of $t$.

The next theorem shows that the symbol $\plus$ expresses the sum of
vectors and the symbol $\dotprod$, the product of a vector by a scalar.

\begin{theorem}[Sum and scalar product of vectors~\citeintitle{Lemmas 3.7 and 3.8}{DiazcaroDowekMSCS24}]
\label{thm:parallelsum}
Let $A \in {\mathcal V}$, $u$ and $v$ two closed proof-terms of $A$, and $a\in\mathcal S$ a scalar.
Then, $\underline{u \plus v} = \underline{u} + \underline{v}$ and
$\underline{a \dotprod u} = a \underline{u}$.
\end{theorem}

\subsubsection{Matrices}
\label{sec:secmatrices}

We now want to prove that if $A, B \in {\mathcal V}$ with $d(A) = m$
and $d(B) = n$, and $F$ is a linear function from ${\mathcal S}^m$ to
${\mathcal S}^n$, then there exists a closed proof-term $f$ of $A
\multimap B$ such that, for all vectors ${\bf u} \in {\mathcal S}^m$,
$\underline{f~\overline{\bf u}^A} = F({\bf u})$.  This can
equivalently be formulated as the fact that if $M$ is a matrix with
$m$ columns and $n$ lines, then there exists a closed proof-term $f$ of $A
\multimap B$ such that for all vectors ${\bf u} \in {\mathcal S}^m$,
$\underline{f~\overline{\bf u}^A} = M {\bf u}$.

A similar theorem has been proved also in~\cite{odot} for a non-linear
calculus. 

\begin{theorem}[Matrices~\citeintitle{Theorem 3.10}{DiazcaroDowekMSCS24}]
  \label{thm:matrices}
  Let $A, B \in {\mathcal V}$ with $d(A) = m$ and $d(B) = n$ and let $M$
  be a matrix with $m$ columns and $n$ lines, then there exists a closed
  proof-term $t$ of $A \multimap B$ such that, for all vectors ${\bf u} \in
  {\mathcal S}^m$, $\underline{t~\overline{\bf u}^A} = M {\bf u}$.
  \qed
\end{theorem}

\begin{example}[Matrices with two columns and two lines]
  The matrix
  $\left(\begin{smallmatrix} a & c\\b & d \end{smallmatrix}\right)$
  is expressed as the proof-term
    $t = \lambda x^{\one \with \one}. \elimwith^1(x,y^\one.
    \elimone(y,\pair{a.\star}{b.\star})) \plus \elimwith^2(x,z^\one.
    \elimone(z,\pair{c.\star}{d.\star}))$.
  Then,
    $t~\pair{e.\star}{f.\star} \lras
    \pair{(a \times e + c \times f).\star}{(b \times e + d \times f).\star}$.
\end{example}

\subsection{Linearity}
\label{sec:seclinearity}
In this section, we state the converse to Theorem~\ref{thm:matrices}, that is,
that if $A,B \in {\mathcal V}$, then each closed proof-term $t$ of $A \multimap B$
expresses a linear function.

This result is trivially false when we consider the exponential connective.  For example, the
proof-term $f = \lambda x^{\oc\one}.\elimbang(x, y^{\one}. 2.\star)$ of proposition
$!\one\multimap\one$ represents the constant function $2$, which is not linear.
Indeed,
\[
  f~(\oc (a.\star) \plus \oc (b.\star))
  \lra^*
  2.\star
  \neq
  4.\star
  \llas
  (f~\oc a.\star) \plus (f~\oc b.\star)
\]


Hence, this section refers to the $\mathcal{L^S}$-calculus,
which is the $\OC$-calculus without $\oc$,
and, as with the previous section, it is included here only for self-containment. The results of this section has been presented in~\cite{DiazcaroDowekMSCS24}. 
The $\mathcal{L^S}$-calculus is obtained by removing the proof-terms $\oc t$ and $\elimbang(t, x^A.u)$ from the syntax (cf.~Section~\ref{sec:secls}), together with their corresponding reduction rules (cf.~Figure~\ref{fig:figureductionrules}). Additionally, we remove the deduction rules ax, $\oc_i$, and $\oc_e$ (cf.~Figure~\ref{fig:figuretypingrules}). With these changes, all interesting judgements have the shape $\varnothing;\Gamma\vdash t:A$; thus, we simply write $\Gamma\vdash t:A$ instead.


We want to state that for any closed proof-term $t$ of $A \multimap B$, if $u_1$ and
$u_2$ are closed proof-terms of $A$, then 
\begin{equation}
  \label{eq:equiv}
  t~(u_1 \plus u_2) \equiv t~u_1 \plus t~u_2 
  \qquad\qquad\textrm{and}\qquad\qquad
  t~(a \dotprod u_1) \equiv a \dotprod t~u_1
\end{equation}

The property, however, is not true in general. Consider, for example,
\(
  t = \lambda x^\one.\lambda y^{\one\multimap\one}. y~x
\)
and we have 
\[
  t~(1.\star \plus\,2.\star)
  \lras \lambda y^{\one\multimap\one}. y~3.{\star}
  \not\equiv
  \lambda y^{\one\multimap\one}. {(y~1.\star)} \plus {(y~2.\star)}
  \llas
  (t~{1.\star}) \plus (t~{2.\star})
\]

Nevertheless, although the proof-terms $\lambda y^{\one\multimap\one}.
y~3.\star$ and $\lambda y^{\one\multimap\one}. {(y~1.\star)} \plus
{(y~2.\star)}$ are not equivalent, if we apply them to the identity $\lambda
z^\one. z$, then both proof-terms
$(\lambda y^{\one\multimap\one}.
y~3.\star)~\lambda z^\one. z$ and $(\lambda y^{\one\multimap\one}.
{(y~1.\star)} \plus {(y~2.\star)})~\lambda z^\one. z$ reduce to
$3.\star$.  This leads to the introduction of a notion of observational equivalence.

For convenience, if $\fv(t) \subseteq \{x\}$, we will use the the notation
$t[u]$ for $(u/x)t$.

\begin{definition}[Observational equivalence]\label{def:obseq}
  Two proof-terms $t_1$ and $t_2$ of a proposition $B$ are {\em observationally
  equivalent}, $t_1 \sim t_2$, if for all propositions $C$ in ${\mathcal V}$ and
  for all proof-terms $c$ such that $x^B \vdash c:C$, we have 
  \(
  c[t_1] \equiv c[t_2]
  \).
\end{definition}

We first state 
(Theorem~\ref{thm:linearity}) that for any proof-term $t$ of $B\in\mathcal V$ such
that $x^A \vdash t:B$, we have the property~\eqref{eq:equiv}.
Then, Corollary~\ref{cor:corollary0} generalises the proof-term for any $B$ stating
the observational equivalence. Finally, Corollary~\ref{cor:corollary2} is just a
reformulation of it, in terms of linear functions.

\begin{theorem}[Linearity \citeintitle{Theorem 4.10}{DiazcaroDowekMSCS24}]
  \label{thm:linearity}
  In the ${\mathcal{L^S}}$-calculus, if $A$ is a proposition, $B$ is proposition of ${\mathcal V}$, $t$ is
  a proof-term such that $x^A \vdash t:B$ and $u_1$ and $u_2$ are two closed
  proof-terms of $A$, then
  \(
  t[u_1 \plus u_2] \equiv t[u_1] \plus t[u_2]
  \)
  and
  \(
  t[a \dotprod u_1] \equiv a \dotprod t[u_1]
  \).
  \qed
\end{theorem}

\begin{corollary}[\hspace{-.1mm}\citeintitle{Corollary 4.11}{DiazcaroDowekMSCS24}]
  \label{cor:corollary0}
  In the ${\mathcal{L^S}}$-calculus, if $A$ and $B$ are any propositions,
  $t$ a proof-term such that $x^A \vdash t:B$, and
  $u_1$ and $u_2$ two closed proof-terms of $A$, then  
  \(
  t[u_1 \plus u_2] \sim t[u_1] \plus t[u_2]
  \)
  and
  \(
  t[a \dotprod u_1] \sim a \dotprod t[u_1]
  \).
  \qed
\end{corollary}

Finally, the next corollary is the converse of Theorem~\ref{thm:matrices}.

\begin{corollary}[\hspace{-.1mm}{\protect\cite[Corollary 4.13]{DiazcaroDowekMSCS24}}]
  \label{cor:corollary2}
  In the ${\mathcal{L^S}}$-calculus, let $A, B \in {\mathcal V}$, such that $d(A) = m$ and $d(B) = n$, 
  and  $t$ be a closed proof-term of $A \multimap B$.
  Then the function $F$ from ${\mathcal S}^m$ to ${\mathcal S}^n$,
  defined as
  $F({\bf u}) = \underline{t~\overline{\bf u}^A}$ is linear.
  \qed
\end{corollary}

\section{Denotational semantics}\label{sec:denotationalsemantics}
\subsection{The categorical construction and its properties}
In this section, we introduce the fundamental categorical constructions that serve as the basis for defining the denotational semantics of the $\OC$-calculus. These constructions are inspired by the work of Bierman~\cite{bierman} on intuitionistic linear logic. Many of the additive properties required for our setting have been established in a recent draft~\cite{DiazcaroMalherbe24}, which develops a categorical semantics for the $\mathcal L\odot^{\mathcal S}$-calculus~\cite{DiazcaroDowekMSCS24}, an extension of the $\mathcal{L^S}$-calculus incorporating the non-deterministic \emph{sup} connective $\odot$. We adapt these constructions to incorporate the exponential connective $\oc$.

\subsubsection{Linear categories}
The first key definition is that of a linear category (Definition~\ref{def:linearcategory}). To introduce it properly, we first recall some basic notions and properties (Definitions~\ref{def:symmetricmonoidalcomonad}, \ref{def:coalgebra}, \ref{def:categoryofcoalgebras}, and \ref{def:commutativecomonoid}, and Theorem~\ref{thm:adjunction}).

\begin{definition}[Symmetric monoidal comonad \citeintitle{Definition  28}{bierman}]\label{def:symmetricmonoidalcomonad}
	A comonad on a category $\mathcal C$ is a triple $(\oc,\varepsilon,\delta)$ where $\oc:\mathcal C \to \mathcal C$, and $\varepsilon:\oc \Rightarrow Id$, $\delta:Id \Rightarrow \oc$ are natural transformations which make the following diagrams commute:
	% https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[ampersand replacement=\&,cramped]
	{\oc A} \&\& {\oc \oc A} \&\&\&\& {\oc A} \\
	\\
	{\oc \oc A} \&\& {\oc \oc \oc A} \&\& {\oc A} \&\& {\oc \oc A} \&\& {\oc A}
	\arrow["{\delta_A}", from=1-1, to=1-3]
	\arrow["{\delta_A}"', from=1-1, to=3-1]
	\arrow["{\oc \delta_A}", from=1-3, to=3-3]
	\arrow[equals, from=1-7, to=3-5]
	\arrow["{\delta_A}", from=1-7, to=3-7]
	\arrow[equals, from=1-7, to=3-9]
	\arrow["{\delta_{\oc A}}"', from=3-1, to=3-3]
	\arrow["{\varepsilon_{\oc A}}", from=3-7, to=3-5]
	\arrow["{\oc \varepsilon_A}"', from=3-7, to=3-9]
\end{tikzcd}\]

If $\mathcal C$ is a symmetric monoidal category, a comonad is symmetric monoidal when $\oc$ is a symmetric monoidal functor and $\varepsilon$, $\delta$ are monoidal natural transformations.
\end{definition}

\begin{notation}
	In a symmetric monoidal category $(\mathcal C, \otimes, I)$, a symmetric monoidal comonad is denoted by\\ $(\oc, \varepsilon, \delta, m_{A,B}, m_I)$, where $m_{A,B}: \oc A \otimes \oc B \to \oc(A \otimes B)$ and $m_I: I \to \oc I$ are the structure morphisms that make $\oc$ a monoidal functor.
\end{notation}

\begin{definition}[Coalgebra \citeintitle{Definition 29}{bierman}]\label{def:coalgebra}
	Given a comonad $(\oc, \varepsilon, \delta)$ on a category $\mathcal C$, a coalgebra is a pair $(A, h_A: A \to \oc A)$ where $A$ is an object of $\mathcal C$ and $h_A$ is a morphism in $\mathcal C$ which makes the following diagrams commute:
	% https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[ampersand replacement=\&,cramped]
	A \&\& {\oc A} \&\& A \&\& {\oc A} \\
	\\
	{\oc A} \&\& {\oc \oc A} \&\&\&\& A
	\arrow["{h_A}", from=1-1, to=1-3]
	\arrow["{h_A}"', from=1-1, to=3-1]
	\arrow["{\oc h_A}", from=1-3, to=3-3]
	\arrow["{h_A}", from=1-5, to=1-7]
	\arrow[equals, from=1-5, to=3-7]
	\arrow["{\varepsilon_A}", from=1-7, to=3-7]
	\arrow["{\delta_A}"', from=3-1, to=3-3]
\end{tikzcd}\]

	A coalgebra morphism between two coalgebras $(A,h)$ and $(A',h')$ is a morphism $f:A \to A'$ in $\mathcal C$ which makes the following diagram commute:
	% https://q.uiver.app/#q=WzAsNCxbMCwwLCJBIl0sWzIsMCwiXFxvYyBBIl0sWzAsMiwiQSciXSxbMiwyLCJcXG9jIEEnIl0sWzAsMSwiaCJdLFswLDIsImYiLDJdLFsxLDMsIlxcb2MgZiJdLFsyLDMsImgnIiwyXV0=&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[ampersand replacement=\&,cramped]
	A \&\& {\oc A} \\
	\\
	{A'} \&\& {\oc A'}
	\arrow["h", from=1-1, to=1-3]
	\arrow["f"', from=1-1, to=3-1]
	\arrow["{\oc f}", from=1-3, to=3-3]
	\arrow["{h'}"', from=3-1, to=3-3]
\end{tikzcd}\]
\end{definition}

\begin{definition}[Category of coalgebras \citeintitle{Definition 30}{bierman}]\label{def:categoryofcoalgebras}
	Given a comonad $(\oc, \varepsilon, \delta)$ on a category $\mathcal C$, we can form the category of coalgebras ${\mathcal C}^{\oc}$. Its objects are the coalgebras, and its morphisms are the coalgebra morphisms in $\mathcal C$.
\end{definition}

The category of coalgebras is dual to the notion of Eilenberg-Moore category of a monad \cite[Page 139]{maclane}.

\begin{theorem}[Adjunction between $\mathcal C$ and $\mathcal C^\oc$ \citeintitle{Dual of Theorem 1, page 140}{maclane}]\label{thm:adjunction}
	Given a comonad $(\oc, \varepsilon, \delta)$ on a category $\mathcal C$, let $F:\mathcal C^\oc \to \mathcal C$ and $G:\mathcal C \to \mathcal C^\oc$ such that $F((A,h)) = A$ and $G(A) = (\oc A,\delta_A)$. Then $F \dashv G$, where the unit of adjuction is $\eta_{(A,h)} = h$ and the counit is $\varepsilon'_A = \varepsilon_A$.
	\qed
\end{theorem}

\begin{definition}[Commutative comonoid \citeintitle{Definitions 31 and 32}{bierman}]\label{def:commutativecomonoid}
	Given a symmetric monoidal category\\ $(\mathcal C, \otimes, I, \alpha, \rho, \lambda, \sigma)$, a commutative comonoid in $\mathcal C$ is a triple $(C, d, e)$ where $C$ is an object in $\mathcal C$, and $d:C \to C \otimes C$ and $e:C \to I$ are morphisms in $\mathcal C$ such that the following diagrams commute:

	% https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[ampersand replacement=\&,cramped,column sep=small]
	{C \otimes C} \&\& C \&\& {C \otimes C} \&\&\& C \&\&\& C \&\& {C \otimes C} \\
	\\
	{C \otimes (C \otimes C)} \&\&\&\& {(C \otimes C) \otimes C} \& {I \otimes C} \&\& {C \otimes C} \&\& {C \otimes I} \& C \&\& {C \otimes C}
	\arrow["{id_C \otimes d}"', from=1-1, to=3-1]
	\arrow["d"', from=1-3, to=1-1]
	\arrow["d", from=1-3, to=1-5]
	\arrow["{d \otimes id_C}", from=1-5, to=3-5]
	\arrow["{\lambda_C^{-1}}"', from=1-8, to=3-6]
	\arrow["d", from=1-8, to=3-8]
	\arrow["{\rho_C^{-1}}", from=1-8, to=3-10]
	\arrow["d", from=1-11, to=1-13]
	\arrow[equals, from=1-11, to=3-11]
	\arrow["{\sigma_{C,C}}", from=1-13, to=3-13]
	\arrow["{\alpha_{C,C,C}}"', from=3-1, to=3-5]
	\arrow["{e \otimes id_C}", from=3-8, to=3-6]
	\arrow["{id_C \otimes e}"', from=3-8, to=3-10]
	\arrow["d"', from=3-11, to=3-13]
\end{tikzcd}\]

A comonoid morphism between two comonoids $(C, d, e)$ and $(C', d', e')$ is a morphism $f:C \to C'$ such that the following diagrams commute:
% https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[ampersand replacement=\&,cramped]
	C \&\& {C'} \&\& C \&\& {C'} \\
	\\
	I \&\& I \&\& {C \otimes C} \&\& {C' \otimes C'}
	\arrow["f", from=1-1, to=1-3]
	\arrow["e"', from=1-1, to=3-1]
	\arrow["{e'}", from=1-3, to=3-3]
	\arrow["f", from=1-5, to=1-7]
	\arrow["d"', from=1-5, to=3-5]
	\arrow["{d'}", from=1-7, to=3-7]
	\arrow[equals, from=3-1, to=3-3]
	\arrow["{f \otimes f}"', from=3-5, to=3-7]
\end{tikzcd}\]
\end{definition}

\begin{definition}[Linear category \citeintitle{Definition 35}{bierman}]\label{def:linearcategory}
A linear category consists of a symmetric monoidal closed category $(\mathcal{C},\otimes,I)$ with finite products and coproducts, equipped with a symmetric monoidal comonad $(\oc, \varepsilon, \delta, m_{A,B}, m_I)$, such that:
  \begin{enumerate}
    \item For every free $\oc$-coalgebra $(\oc A, \delta_A)$ there are two distinguished monoidal natural transformations with components $e_A:\oc A \to I$ and $d_A:\oc A \to \oc A \otimes \oc A$ which form a commutative comonoid and are coalgebra morphisms.
    \item Whenever $f:(\oc A,\delta_A) \to (\oc B,\delta_B)$ is a coalgebra morphism between free coalgebras, then it is also a comonoid morphism.
  \end{enumerate}
\end{definition}

The second condition can be generalised to any coalgebra morphism:

\begin{lemma}[\hspace{-0.1mm}\citeintitle{Corollary 3}{bierman}]\label{lem:biermanprop}
	Whenever $f: (A, h) \to (A', h')$ is a coalgebra morphism between any two coalgebras, then it is a comonoid morphism.
	\qed
\end{lemma}

In the next section we use the fact that the following constructions are coalgebras:
\begin{lemma}[\hspace{-0.1mm}\citeintitle{Propositions 7 and 8}{bierman}]\label{lem:biermancoalgebras}
	Given a monoidal comonad $(\oc, \varepsilon, \delta, m_{A,B}, m_I)$ on a symmetric monoidal category $\mathcal C$, then $(\oc A, \delta_A:\oc A \to \oc \oc A)$ and $(I, m_I: I \to \oc I)$ are coalgebras.
	\qed
\end{lemma}

