	\label{lem:generalizacionprop9}
	Given a monoidal comonad $(\oc, \varepsilon, \delta, m_{A,B}, m_I)$ on a symmetric monoidal category $\mathcal C$, and a coalgebra $(A,h: A \to \oc A)$, then $(A \otimes A, m \circ (h \otimes h))$ is a coalgebra.
% \end{lemma}
\end{restatable}
