	See Appendix~\ref{proof:gen9}.
\end{proof}

\subsubsection{Generalised properties}\label{subsec:genprop}
This section provides generalised versions of $\varepsilon$ and $\delta$ (from Definition~\ref{def:symmetricmonoidalcomonad}), and of $e$ and $d$ (from Definition~\ref{def:linearcategory}). These generalisations are useful for handling the typing contexts of the calculus, and follow the definitions given in \cite[Appendix~A]{Maneggia}. We give their definitions (Definition~\ref{def:generalizededeepsilon}) and several properties.

\begin{definition}[Generalised versions of $\varepsilon$, $\delta$, $e$, and $d$]\label{def:generalizededeepsilon}~
  \begin{itemize}
    \item $\varepsilon_{A_1, \dots, A_n}:\bigotimes_{i=1}^n \oc A_i \to \bigotimes_{i=1}^n A_i$
      \[
	\varepsilon_{A_1, \dots, A_n} = \left\{
	  \begin{array}{ll}
	    I \xrightarrow{id_I} I & n=0\\
	    \oc A_1 \xrightarrow{\varepsilon_{A_1}} A_1 & n=1\\
	    (\bigotimes_{i=1}^{n-1}\oc A_i) \otimes \oc A_n \xrightarrow{\varepsilon_{A_1, \dots, A_{n-1}} \otimes \varepsilon_{A_n}} \bigotimes_{i=1}^n A_i & n > 1
	  \end{array}
	\right.
      \]
     \item $\delta_{A_1, \dots, A_n}:\bigotimes_{i=1}^n \oc A_i \to \oc (\bigotimes_{i=1}^n \oc A_i)$
     \[
      \delta_{A_1, \dots, A_n} = \left\{
        \begin{array}{ll}
          I \xrightarrow{m_I} \oc I & n=0\\
          \oc A_1 \xrightarrow{\delta_{A_1}} \oc \oc A_1 & n=1\\
          (\bigotimes_{i=1}^{n-1}\oc A_i) \otimes \oc A_n \xrightarrow{\delta_{A_1, \dots, A_{n-1}} \otimes \delta_{A_n}} \oc (\bigotimes_{i=1}^{n-1}\oc A_i) \otimes \oc \oc A_n \xrightarrow{m} \oc (\bigotimes_{i=1}^n \oc A_i) & n>1
        \end{array}
      \right.
     \]

    \item $e_{A_1, \dots, A_n}: \bigotimes_{i=1}^n \oc A_i \to I$
      \[
	e_{A_1, \dots, A_n} = \left\{
	  \begin{array}{ll}
	    I \xrightarrow{id_I} I & n=0\\
	    \oc A_1 \xrightarrow{e_{A_1}} I & n=1\\
	    (\bigotimes_{i=1}^{n-1}\oc A_i) \otimes \oc A_n \xrightarrow{e_{A_1, \dots, A_{n-1}} \otimes e_{A_n}} I \otimes I \xrightarrow{\lambda_I} I & n > 1
	  \end{array}
	\right. 
      \]
     \item $d_{A_1, \dots, A_n}:\bigotimes_{i=1}^n \oc A_i \to (\bigotimes_{i=1}^n \oc A_i) \otimes (\bigotimes_{i=1}^n \oc A_i)$
     \[
      d_{A_1, \dots, A_n} = \left\{
        \begin{array}{ll}
          I \xrightarrow{\lambda_I^{-1}} I \otimes I & n=0\\
          \oc A_1 \xrightarrow{d_{A_1}} \oc A_1 \otimes \oc A_1 & n=1\\
          (\bigotimes_{i=1}^{n-1} \oc A_i) \otimes \oc A_n \xrightarrow{d_{A_1, \dots, A_{n-1}} \otimes d_{A_n}} ((\bigotimes_{i=1}^{n-1} \oc A_i) \otimes (\bigotimes_{i=1}^{n-1} \oc A_i)) \otimes (\oc A_n \otimes \oc A_n)\\ 
          \phantom{(\bigotimes_{i=1}^{n-1} \oc A_i) \otimes \oc A_n} \xrightarrow{id \otimes \sigma \otimes id} (\bigotimes_{i=1}^n \oc A_i) \otimes (\bigotimes_{i=1}^n \oc A_i) & n>1
        \end{array}
      \right.
     \]
  \end{itemize}
\end{definition}

\begin{restatable}{lemma}{dnat}
	% \begin{lemma}
	  \label{lem:dnat}
		For every $n$, $d_{A_1, \dots, A_n}$ is a natural transformation.
	% \end{lemma}
\end{restatable}
\begin{proof}
