\subsubsection{Semiadditive categories}
The next key ingredient is the notion of semiadditive category (Definition~\ref{def:semiadditivecategory}) and semiadditive functor (Definition~\ref{def:semiadditivefunctor}). To introduce these concepts, we need to recall the notions of zero object and zero morphism (Definition~\ref{def:zeroobject}), as well as the sum of morphisms (Definition~\ref{def:homsetsum}). We then state that any category with biproducts admits a semiadditive structure (Theorem~\ref{thm:semiadditivestructure}) and that its hom-sets carry a natural semiring structure (Corollary~\ref{cor:semiringstructure}).
We also state the preservation of the biproduct structure by semiadditive functors (Lemma~\ref{lem:semiadditiveiso}), a property we will need in what follows.

\begin{definition}[Zero object and zero morphism]\label{def:zeroobject}
	A zero object $\mathbf 0$ in a category $\mathcal C$ is an object which is both initial and terminal.
%
	In a category $\mathcal C$ with zero object $\mathbf 0$, a morphism $f: A \to B$ is a zero morphism when it factors through $\mathbf 0$. It is unique for every pair of objects, and we denote it by $0_{A,B}$.
\end{definition}

\begin{definition}[Sum of morphisms]\label{def:homsetsum}
  Let $\mathcal C$ be a category with biproduct, let $\Delta = \langle id, id \rangle$, $\nabla = [id, id]$ and let $f,g:A \to B$. Then, $f+g:A \to B$ is defined as the morphism that makes the following diagram commute:
	% https://q.uiver.app/#q=WzAsNCxbMCwwLCJBIl0sWzAsMiwiQSBcXG9wbHVzIEEiXSxbMywyLCJCIFxcb3BsdXMgQiJdLFszLDAsIkIiXSxbMCwxLCJcXERlbHRhIiwxXSxbMiwzLCJcXG5hYmxhIiwxXSxbMCwzLCJmICsgZyIsMV0sWzEsMiwiZiBcXG9wbHVzIGciLDFdXQ==
\[\begin{tikzcd}[ampersand replacement=\&,cramped]
	A \&\&\& B \\
	\\
	{A \oplus A} \&\&\& {B \oplus B}
	\arrow["{f + g}", from=1-1, to=1-4]
	\arrow["\Delta"', from=1-1, to=3-1]
	\arrow["{f \oplus g}"', from=3-1, to=3-4]
	\arrow["\nabla"', from=3-4, to=1-4]
\end{tikzcd}\]
\end{definition}


\begin{definition}[Semiadditive category \citeintitle{Chapter I, Section 18}{mitchell}]\label{def:semiadditivecategory}
	A semiadditive category is a category $\mathcal C$ together with an abelian monoid structure on each of its morphism sets, subject to the following conditions:
	\begin{enumerate}
		\item The composition functions $[B \to C] \times [A \to B] \to [A \to C]$ are bilinear.
		\item The zero elements of the monoids behave as zero morphisms.
	\end{enumerate}
\end{definition}

\begin{theorem}[Semiadditive structure \citeintitle{Proposition 18.4}{mitchell}]\label{thm:semiadditivestructure}
  Suppose that $\mathcal C$ is a category with biproducts. Then $\mathcal C$ has a unique semiadditive structure, where the abelian monoid structure operation is given by Definition~\ref{def:homsetsum}, and the identity is given by the zero morphisms.
	\qed
\end{theorem}

\begin{corollary}[Semiring structure \citeintitle{Corollary 3.4}{DiazcaroMalherbe24}]\label{cor:semiringstructure}
	In a category with biproduct every $Hom(A,A)$ is a semiring, where addition is given by Definition~\ref{def:homsetsum}, with unit $0_{A,A}$ and product is given by composition, with unit $id_A$.
	\qed
\end{corollary}

\begin{definition}[Semiadditive functor]\label{def:semiadditivefunctor}
	Let $\mathcal C, \mathcal D$ be semiadditive categories. A functor $F:\mathcal C \to \mathcal D$ is semiadditive when the mapping of morphisms preserves the monoid structure.
\end{definition}

\begin{lemma}[\hspace{-.1mm}\citeintitle{Lemma 3.9}{DiazcaroMalherbe24}]\label{lem:semiadditiveiso}
  Let $F: \abscat \to \abscat$ be a semiadditive functor. Then, $F(A) \oplus F(B)$ and $F(A \oplus B)$ are naturally isomorphic, with the
  isomorphisms given by $f = \langle F(\pi_1), F(\pi_2)\rangle$ and $f^{-1} = [F(i_1), F(i_2)]$.
  \qed
\end{lemma}
\subsubsection{The category \texorpdfstring{$\abscat$}{C-!-S}}
Finally, we define the category $\abscat$ (Definition~\ref{def:abscat}), which will serve as the basis for the denotational semantics of the $\OC$-calculus.


\begin{definition}[The category $\abscat$]\label{def:abscat}
	Let $\scalars$ be a fixed semiring. We define $\abscat$ to be a linear category with biproduct $\oplus$ where there is a monomorphism from $\scalars$ to $Hom(I,I)$ and where the functor $\oc$ is semiadditive.
\end{definition}

\begin{notation}
  In the category $\abscat$, the symmetric monoidal structure is given by $(\abscat, \otimes, I)$ where the coherence isomorphisms are denoted by:
  \begin{align*}
    \alpha_{A,B,C} : A \otimes (B \otimes C) &\to (A \otimes B) \otimes C &
    \lambda_A : I \otimes A & \to A &
    \rho_A : A \otimes I & \to A &
    \sigma_{A,B} : A \otimes B &\to B \otimes A
  \end{align*}
  the biproduct maps are denoted by:
  \begin{align*}
    \pi_1 : A \oplus B &\to A & 
    \pi_2 : A \oplus A &\to B & 
    i_1 : A &\to A \oplus B &
    i_2 : B &\to A \oplus B
  \end{align*}
  and the semiring monomorphism is denoted by $\mono{\cdot}: \scalars \to Hom(I,I)$.
\end{notation}


The following is an example of a concrete category with the properties stated in Definition~\ref{def:abscat}.

\begin{example}
  The category $(\sm,\otimes,\scalars,\oplus)$, where objects are semimodules over the semiring $\scalars$, arrows are semimodule homomorphisms, the tensor product is the tensor product over semimodules and the biproduct is the Cartesian product. This category is symmetric monoidal closed, and the map $\mono{a}:\scalars \to \scalars$ is defined as $b \mapsto a \cdot_\scalars b$ for every $a \in \scalars$. The first model for the $\mathcal L^\scalars$-calculus has been defined in this category \cite{DiazcaroMalherbe24v2}.

  \begin{itemize}
    \item We can define a monoidal adjunction between $\sm$ and $\set$, which induces a monoidal comonad.

    Let $F:\set \to \sm$ be the functor defined by its action on $X$ and $f:X \to Y$ in $\set$:
    \begin{align*}
      FX &= \{\sum_{x \in X} s_x \cdot x \mid s_x \in \scalars\} &
      Ff(\sum_{x \in X} s_x \cdot x) &= \sum_{x \in X} s_x \cdot (f x)
      \end{align*}

    where $\sum$ are formal finite sums.

    Let $\phi_{XY}:FX \otimes FY \to F(X \times Y)$ and $\phi_\scalars:\scalars \to F \singleton$ be the following natural transformations:
    \begin{align*}
      \phi_{XY} \left(\sum_k(\sum_i s_{ik} \cdot x_{ik}) \otimes (\sum_j s'_{jk} \cdot y_{jk})\right) &= \sum_{ijk} (s_{ik} s'_{jk}) \cdot (x_{ik}, y_{jk}) &
      \phi_\scalars(s) &= s \cdot \ast
    \end{align*}

    With these definitions, $(F,\phi)$ is a strong monoidal functor.

    Let $G:\sm \to \set$ be the forgetful functor, and let $\theta_{MN}:GM \times GN \to G(M \otimes N)$ and $\theta_\singleton:\singleton \to G\scalars$ be the following natural transformations:
    \begin{align*}
      \theta_{MN}(x, y) &= x \otimes y &
      \theta_\singleton(\ast) &= 1_\scalars
    \end{align*}

    With these definitions, $(G,\theta)$ is a monoidal functor. $(F,\phi) \dashv (G,\theta)$ is a monoidal adjunction, where the counit of adjuction $\varepsilon:FG \Rightarrow Id$ and the unit of adjunction $\eta: Id \Rightarrow GF$ are given by:
    \begin{align*}
      \varepsilon_M \left(\sum_{x \in GM} s_x \cdot x\right) &= \sum_{x \in GM} s_x \bullet_M x &
      \eta_X(x) &= 1_\scalars \cdot x
    \end{align*}

    Let $m_{MN}:FGM \otimes FGN \to FG(M \otimes N)$ and $m_\scalars:\scalars \to FG \scalars$ be the following natural transformations:
    \begin{align*}
      m_{MN} &= F \theta_{MN} \circ \phi_{GM\ GN} &
      m_\scalars &= F \theta_\singleton \circ \phi_\scalars
    \end{align*}

    With these definitions, $(FG,m)$ is a monoidal functor, and the monoidal adjunction $((F,\phi),(G,\theta),\eta,\varepsilon)$ induces the monoidal comonad $(FG,\varepsilon:FG \Rightarrow Id,\delta:FG \Rightarrow FGFG,m)$, where $\delta = F \eta G$.

    \item  For every $M$ in $\sm$, $(FGM, d_M:FGM \to FGM \otimes FGM, e_M:FGM \to \scalars)$ is a commutative comonoid, where $d_M$ and $e_M$ are monoidal natural transformations defined as:
    \begin{align*}
      d_M &= \phi^{-1} \circ F \Delta &
      e_M &= \phi^{-1} \circ F \oc
    \end{align*}

    $d_M:(FGM,\delta_M) \to (FGM \otimes FGM, m_{FGM\ FGM} \circ (\delta_M \otimes \delta_M))$ and $e_M:(FGM, \delta_M) \to (\scalars,m_\scalars)$ are coalgebra morphisms.

    \item In $\sm$, when $f:(FGA,\delta_A) \to (FGB,\delta_B)$ is a coalgebra morphism, it is also a comonoid morphism.
  \end{itemize}

  Therefore, $\sm$ is a linear category.

  Additionally, $FG$ is a semiadditive functor. Let $f,g:A \to B$ in $\sm$, then the following diagrams commute:

