\subsubsection{Distribution and scalar maps}
In this section, we define the distribution maps $dist$, $\gamma$, and $\varphi$ in $\abscat$ (Definition~\ref{def:distmaps}) and prove that they are natural transformations (Lemma~\ref{lem:distmaps}). We also introduce the scalar map $\hat{a}_A$ (Lemma~\ref{lem:hatanat}), and establish several useful properties it satisfies with respect to the unit object, the tensor product, the biproduct, and the hom-functor (Lemma~\ref{lem:hataprop}). Then, we show that the scalar map is compatible with $\oc$ (Lemma~\ref{lem:ahatbang}).

Corollaries~\ref{cor:nablasemiadditive} and~\ref{cor:deltasemiadditive} establish properties of the distribution maps with respect to $\nabla$ and $\Delta$, respectively. These results follow from Lemmas~\ref{lem:nablasemiadditive} and~\ref{lem:deltasemiadditive}.
Finally, Lemma~\ref{lem:sigmanabladelta} states the compatibility of the monoidal symmetry induced by the biproduct with $\nabla$ and $\Delta$.

\begin{definition}[Distribution maps]\label{def:distmaps} 
	In the category $\abscat$ we define the isomorphisms $dist: (A \oplus B) \otimes C \to (A \otimes C) \oplus (B \otimes C)$, $\gamma :[A \to B \oplus C] \to [A \to B] \oplus [A \to C]$ and $\varphi :\oc (A \oplus B) \to \oc A \oplus \oc B$ as follows:
	\begin{align*}
		dist &= \langle \pi_1 \otimes id, \pi_2 \otimes id\rangle  &\qquad\qquad  \gamma &= \langle[id \to \pi_1], [id \to \pi_2]\rangle  &\qquad\qquad  \varphi &= \langle \oc \pi_1, \oc \pi_2 \rangle\\
		dist^{-1} &= [i_1 \otimes id, i_2 \otimes id]  &  \gamma^{-1} &= [[id \to i_1], [id \to i_2]] &  \varphi^{-1} &= [\oc i_1, \oc i_2]
	\end{align*}
\end{definition}

\begin{lemma}\label{lem:distmaps}
	$dist$, $\gamma$ and $\varphi$ are natural transformations.
\end{lemma}
\begin{proof}
	$- \otimes A$, $[A \to -]$ and $\oc$ are semiadditive functors, and $dist$, $\gamma$, $\varphi$ are the natural isomorphisms corresponding to Lemma~\ref{lem:semiadditiveiso}.
\end{proof}

\begin{lemma}[Scalar map \citeintitle{Lemma 3.11}{DiazcaroMalherbe24}]\label{lem:hatanat}
	Let $a: I \to I$ in $\abscat$. The map
    $\hat{a}_A: A \to A$ where $\hat a_A = \rho_A \circ (id \otimes a) \circ \rho_A^{-1}$ defines a natural transformation between the identity functors.
    \qed
\end{lemma}

\begin{lemma}[Properties of the scalar map \citeintitle{Lemmas 3.12 and 3.14}{DiazcaroMalherbe24}]~ \label{lem:hataprop}
  \label{lem:ahathom}
	\begin{enumerate}
		\item $\hat a_I = a$
		\item $\hat a_{A \otimes B} = \hat a_A \otimes id_B = id_A \otimes \hat a_B$
		\item $\hat a_{A \oplus B} = \hat a_A \oplus \hat a_B$
		\item $\hat{a}_{[A \to B]} = [A \to \hat a_B]$
		  \qed
	\end{enumerate}
\end{lemma}


