\begin{lemma}\label{lem:nablasemiadditive}
	Let $F:\abscat \to \abscat$ be a semiadditive functor. Then,
	\(
	  \nabla \circ \langle F(\pi_1), F(\pi_2) \rangle = F(\nabla)
	\).
\end{lemma}
\begin{proof}
	We show that $F(\nabla) \circ [F(i_1),F(i_2)] = \nabla$:
  \begin{align*}
    F(\nabla) \circ [F(i_1),F(i_2)] 
    &= F([id,id]) \circ [F(i_1),F(i_2)]\\ 
    &= [F([id,id]) \circ F(i_1), F([id,id]) \circ F(i_2)]\\
    &= [F([id,id] \circ i_1), F([id,id] \circ i_2)]\\
    &= [F(id), F(id)]\\
    &= [id, id]\\
    &= \nabla
  \end{align*}

  Therefore, $F(\nabla) \circ [F(i_1),F(i_2)] \circ \langle F(\pi_1), F(\pi_2) \rangle = \nabla \circ \langle F(\pi_1), F(\pi_2) \rangle$, and by the isomorphisms from Lemma~\ref{lem:semiadditiveiso}, $[F(i_1),F(i_2)] \circ \langle F(\pi_1), F(\pi_2) \rangle = id$.
\end{proof}

\begin{corollary}\label{cor:nablasemiadditive}~ 
	\begin{enumerate}
		\item $\nabla \circ dist = \nabla \otimes id$
		\item $\nabla \circ \gamma = [A \to \nabla]$
		\item $\nabla \circ \varphi = \oc \nabla$
	\end{enumerate}
\end{corollary}
\begin{proof}
	$- \otimes A$, $[A \to -]$ and $\oc$ are semiadditive functors, we conclude by Lemma~\ref{lem:nablasemiadditive}.
\end{proof}

\begin{lemma}[\hspace{-0.1mm}\citeintitle{Lemma 3.19}{DiazcaroMalherbe24}]\label{lem:deltasemiadditive}
	Let $F: \abscat \to \abscat$ be a semiadditive functor. Then,
	\(
	  [F(i_1), F(i_2)] \circ \Delta = F(\Delta)
	\).
	\qed
\end{lemma}

\begin{corollary}\label{cor:deltasemiadditive}~ 
	\begin{enumerate}
		\item $dist^{-1} \circ \Delta = \Delta \otimes id$
		\item $\gamma^{-1} \circ \Delta = [A \to \Delta]$
		\item $\varphi^{-1} \circ \Delta = \oc \Delta$
	\end{enumerate}
\end{corollary}
\begin{proof}
	$- \otimes A$, $[A \to -]$ and $\oc$ are semiadditive functors, we conclude by Lemma~\ref{lem:deltasemiadditive}.
\end{proof}

\begin{lemma}[\hspace{-0.1mm}\citeintitle{Lemma 3.21}{DiazcaroMalherbe24}]\label{lem:sigmanabladelta}~ 
	\begin{enumerate}
		\item $(\nabla \oplus \nabla) \circ (id \oplus \sigma' \oplus id) = \nabla$
		\item $(id \oplus \sigma' \oplus id) \circ (\Delta \oplus \Delta) = \Delta$
	\end{enumerate}
	Here $\sigma'$ is the monoidal symmetry induced by the biproduct.
	\qed
\end{lemma}

\subsection{Interpretation of the calculus}
In this section, we define the interpretation of the $\OC$-calculus in $\abscat$. We begin by introducing the interpretation of types (Definition~\ref{def:interpretation}) and typing contexts (Definition~\ref{def:interpretationcontext}). We then define the interpretation of the typing rules (Definition~\ref{def:ruleinterpretation}), for which we first introduce a convenient notation for the duplication of banged contexts.


\begin{definition}[Interpretation of types]\label{def:interpretation}
	\begin{align*}
		\interpretation{\one} &= I
			& \interpretation{\zero} &= \mathbf 0\\
		\interpretation{A \multimap B} &= [\interpretation{A} \to \interpretation{B}]
			& \interpretation{A \with B} &= \interpretation{A} \oplus \interpretation{B}\\
		\interpretation{A \otimes B} &= \interpretation{A} \otimes \interpretation{B}
			& \interpretation{A \oplus B} &= \interpretation{A} \oplus \interpretation{B}\\
		\interpretation{\top} &= \mathbf 0
			& \interpretation{\bang A} &= \oc \interpretation{A}
	  \end{align*}
\end{definition}

\begin{notation}
  \begin{align*}
    \bang \varnothing &= \varnothing&
    \bang (x^A, \Gamma) &= x^{\bang A}, \bang \Gamma&
    \varnothing,\Gamma &= \Gamma, \varnothing = \Gamma&
  \end{align*}
\end{notation}


\begin{definition}[Interpretation of typing contexts]\label{def:interpretationcontext}
  \begin{align*}
		\interpretation{\varnothing} &= I&
		\interpretation{x^A,\Gamma} &= \interpretation{A} \otimes \interpretation{\Gamma}
  \end{align*}
\end{definition}

\begin{notation}[Duplication of banged contexts]
  $\overline{d}_{\Upsilon, \Gamma, \Delta} : \interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \otimes \interpretation{\Delta} \to \interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \otimes \interpretation{\bang \Upsilon} \otimes \interpretation{\Delta}$
  \begin{align*}
    &	\overline{d}_{\Upsilon, \Gamma, \Delta} =\\
    & \left\{
      \begin{array}{ll}
	\interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \otimes \interpretation{\Delta} \xrightarrow{d_\Upsilon \otimes id} \interpretation{\bang \Upsilon} \otimes \interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \otimes \interpretation{\Delta} \xrightarrow{id \otimes \sigma \otimes id} \interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \otimes \interpretation{\bang \Upsilon} \otimes \interpretation{\Delta} & \Gamma \neq \varnothing, \Delta \neq \varnothing\\
	\interpretation{\bang \Upsilon} \otimes \interpretation{\Delta} \xrightarrow{d_\Upsilon \otimes id} \interpretation{\bang \Upsilon} \otimes \interpretation{\bang \Upsilon} \otimes \interpretation{\Delta} \xrightarrow{\rho^{-1} \otimes id} \interpretation{\bang \Upsilon} \otimes I \otimes \interpretation{\bang \Upsilon} \otimes \interpretation{\Delta} & \Gamma = \varnothing, \Delta \neq \varnothing\\
	\interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \xrightarrow{d_\Upsilon \otimes id} \interpretation{\bang \Upsilon} \otimes \interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \xrightarrow{id \otimes \sigma} \interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \otimes \interpretation{\bang \Upsilon} \xrightarrow{id \otimes \rho^{-1}} \interpretation{\bang \Upsilon} \otimes \interpretation{\Gamma} \otimes \interpretation{\bang \Upsilon} \otimes I & \Gamma \neq \varnothing, \Delta = \varnothing
      \end{array}
    \right.
  \end{align*}
\end{notation}

