\section{Proofs of the correctness properties (Section~\ref{sec:correctness})}
  \subsection{Theorem~\ref{thm:SR} (Subject Reduction)}\label{proof:SR}
  As usual, we need a substitution lemma to prove subject reduction (Theorem~\ref{thm:SR}).

\begin{lemma}[Substitution]
  \label{lem:polysubstitution}
  ~
  \begin{enumerate}
    \item If $\Upsilon;\Gamma, x^B \vdash t:A$ and $\Upsilon;\Delta \vdash u:B$, then $\Upsilon;\Gamma, \Delta \vdash (u/x)t:A$.
    \item If $\Upsilon, x^B;\Gamma \vdash t:A$ and $\Upsilon;\varnothing\vdash u:B$, then $\Upsilon;\Gamma\vdash (u/x)t:A$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  ~
  \begin{enumerate}
    \item By induction on $t$.
      \begin{itemize}
	\item If $t = x$, then $\Gamma$ is empty and $A = B$. Thus, $\Upsilon;\Gamma, \Delta \vdash (u/x)t:A$ is the same as $\Upsilon;\Delta \vdash u:B$ and this is valid by hypothesis.

	\item If $t = v \plus w$, then $\Upsilon;\Gamma, x^B \vdash v:A$ and $\Upsilon;\Gamma, x^B \vdash w:A$. By the induction hypothesis, $\Upsilon;\Gamma, \Delta \vdash (u/x)v:A$ and $\Upsilon;\Gamma, \Delta \vdash (u/x)w:A$. Therefore, by rule sum, $\Upsilon;\Gamma, \Delta \vdash (u/x)(v \plus w):A$.

	\item If $t = a \dotprod v$, then $\Upsilon;\Gamma, x^B \vdash v:A$. By the induction hypothesis, $\Upsilon;\Gamma, \Delta \vdash (u/x)v:A$. Therefore, by rule prod($a$), $\Upsilon;\Gamma, \Delta \vdash (u/x)(a \dotprod v):A$.

	\item If $t = \elimone(v, w)$, then there are $\Gamma_1, \Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon;\Gamma_1, x^B \vdash v:\one$ and $\Upsilon;\Gamma_2 \vdash w:A$, by the induction hypothesis $\Upsilon;\Gamma_1, \Delta \vdash (u/x)v:\one$. By rule $\one_e$, $\Upsilon;\Gamma, \Delta \vdash \elimone((u/x)v, w):A$.
	    \item If $\Upsilon;\Gamma_1 \vdash v:\one$ and $\Upsilon;\Gamma_2, x^B \vdash w:A$, by the induction hypothesis $\Upsilon;\Gamma_2, \Delta \vdash (u/x)w:A$. By rule $\one_e$, $\Upsilon;\Gamma, \Delta \vdash \elimone(v,(u/x)w):A$.
	  \end{itemize}
	  Therefore, $\Upsilon;\Gamma, \Delta \vdash (u/x)\elimone(v,w):A$.

	\item If $t = \lambda y^C.v$, then $A = C \multimap D$ and $\Upsilon;\Gamma, x^B, y^C \vdash v:D$. By the induction hypothesis, $\Upsilon;\Gamma, y^C, \Delta \vdash (u/x)v:D$. Therefore, by rule $\multimap_i$, $\Upsilon;\Gamma, \Delta \vdash (u/x)\lambda y^C.v:C \multimap D$.

	\item If $t = v~w$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon;\Gamma_1, x^B \vdash v:C \multimap A$ and $\Upsilon;\Gamma_2 \vdash w:C$, by the induction hypothesis $\Upsilon;\Gamma_1, \Delta \vdash (u/x)v:C \multimap A$. By rule $\multimap_e$, $\Upsilon;\Gamma, \Delta \vdash (u/x)v~w:A$.
	    \item If $\Upsilon;\Gamma_1 \vdash v:C \multimap A$ and $\Upsilon;\Gamma_2, x^B \vdash w:C$, by the induction hypothesis $\Upsilon;\Gamma_2, \Delta \vdash (u/x)w:C$. By rule $\multimap_e$, $\Upsilon;\Gamma, \Delta \vdash v~(u/x)w:A$.
	  \end{itemize}
	  Therefore, $\Upsilon;\Gamma, \Delta \vdash (u/x)(v~w):A$.

	\item If $t = v \otimes w$, then $A = C \otimes D$ and there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon;\Gamma_1, x^B \vdash v:C$ and $\Upsilon;\Gamma_2 \vdash w:D$, by the induction hypothesis $\Upsilon;\Gamma_1, \Delta \vdash (u/x)v:C$. By rule $\otimes_i$, $\Upsilon;\Gamma, \Delta \vdash ((u/x)v) \otimes w:C \otimes D$.
	    \item If $\Upsilon;\Gamma_1 \vdash v:C$ and $\Upsilon;\Gamma_2, x^B \vdash w:D$, by the induction hypothesis $\Upsilon;\Gamma_2, \Delta \vdash (u/x)w:D$. By rule $\otimes_i$, $\Upsilon;\Gamma, \Delta \vdash v \otimes ((u/x)w):C \otimes D$.
	  \end{itemize}
	  Therefore, $\Upsilon;\Gamma, \Delta \vdash (u/x)(v \otimes w):C \otimes D$.

	\item If $t = \elimtens(v, y^C z^D.w)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon;\Gamma_1, x^B \vdash v:C \otimes D$ and $\Upsilon;\Gamma_2, y^C, z^D \vdash w:A$, by the induction hypothesis $\Upsilon;\Gamma_1, \Delta \vdash (u/x)v:C \otimes D$. By rule $\otimes_e$, $\Upsilon;\Gamma, \Delta \vdash \elimtens((u/x)v, y^C z^D.w):A$.
	    \item If $\Upsilon;\Gamma_1 \vdash v:C \otimes D$ and $\Upsilon;\Gamma_2, x^B, y^C, z^D \vdash w:A$, by the induction hypothesis $\Upsilon;\Gamma_2, y^C, z^D, \Delta \vdash (u/x)w:A$. By rule $\otimes_e$, $\Upsilon;\Gamma, \Delta \vdash \elimtens(v, y^C z^D.(u/x)w):A$.
	  \end{itemize}
	  Therefore, $\Upsilon;\Gamma, \Delta \vdash (u/x)\elimtens(v, y^C z^D.w):A$.

	\item If $t = \langle\rangle$, then $A = \top$. By rule $\top_i$ $\Upsilon;\Gamma, \Delta \vdash \langle\rangle:\top$.

	\item If $t = \elimzero(v)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon;\Gamma_1, x^B \vdash v:\zero$, by the induction hypothesis $\Upsilon;\Gamma_1, \Delta \vdash (u/x)v:\zero$. By rule $\zero_e$, $\Upsilon;\Gamma, \Delta \vdash \elimzero((u/x)v):A$.
	    \item If $\Upsilon;\Gamma_1 \vdash v:\zero$ and $x \notin \fv(v)$, by rule $\zero_e$ $\Upsilon;\Gamma, \Delta \vdash \elimzero(v):A$.
	  \end{itemize}
	  Therefore, $\Upsilon;\Gamma, \Delta \vdash (u/x)\elimzero(v):A$.

	\item If $t = \langle v, w \rangle$, then $A = C \with D$, $\Upsilon;\Gamma, x^B \vdash v:C$ and $\Upsilon;\Gamma, x^B \vdash w:D$. By the induction hypothesis, $\Upsilon;\Gamma, \Delta \vdash (u/x)v:C$ and $\Upsilon;\Gamma, \Delta \vdash (u/x)w:D$. By rule $\with_i$, $\Upsilon;\Gamma, \Delta \vdash (u/x)\langle v,w \rangle:C \with D$.

	\item If $t = \elimwith^1(v, y^C.w)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon;\Gamma_1, x^B \vdash v:C \with D$ and $\Upsilon;\Gamma_2, y^C \vdash w:A$, by the induction hypothesis $\Upsilon;\Gamma_1, \Delta \vdash (u/x)v:C \with D$. By rule $\with_{e1}$, $\Upsilon;\Gamma, \Delta \vdash \elimwith^1((u/x)v, y^C.w):A$.
	    \item If $\Upsilon;\Gamma_1 \vdash v:C \with D$ and $\Upsilon;\Gamma_2, x^B, y^C \vdash w:A$, by the induction hypothesis $\Upsilon;\Gamma_2, y^C, \Delta \vdash (u/x)w:A$. By rule $\with_{e1}$, $\Upsilon;\Gamma, \Delta \vdash \elimwith^1(v, y^C.(u/x)w):A$.
	  \end{itemize}
	  Therefore, $\Upsilon;\Gamma, \Delta \vdash (u/x)\elimwith^1(v, y^C.w):A$.

	\item If $t = \elimwith^2(v, y^D.w)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon;\Gamma_1, x^B \vdash v:C \with D$ and $\Upsilon;\Gamma_2, y^D \vdash w:A$, by the induction hypothesis $\Upsilon;\Gamma_1, \Delta \vdash (u/x)v:C \with D$. By rule $\with_{e2}$, $\Upsilon;\Gamma, \Delta \vdash \elimwith^2((u/x)v, y^D.w):A$.
	    \item If $\Upsilon;\Gamma_1 \vdash v:C \with D$ and $\Upsilon;\Gamma_2, x^B, y^D \vdash w:A$, by the induction hypothesis $\Upsilon;\Gamma_2, y^D, \Delta \vdash (u/x)w:A$. By rule $\with_{e2}$, $\Upsilon;\Gamma, \Delta \vdash \elimwith^2(v, y^D.(u/x)w):A$.
	  \end{itemize}
	  Therefore, $\Upsilon;\Gamma, \Delta \vdash (u/x)\elimwith^2(v, y^D.w):A$.

	\item If $t = \inl(v)$, then $A = C \oplus D$ and $\Upsilon;\Gamma, x^B \vdash v:C$. By the induction hypothesis, $\Upsilon;\Gamma, \Delta \vdash (u/x)v:C$. Therefore, by rule $\oplus_{i1}$, $\Upsilon;\Gamma, \Delta \vdash (u/x)\inl(v):C \oplus D$.

	\item If $t = \inr(v)$, then $A = C \oplus D$ and $\Upsilon;\Gamma, x^B \vdash v:D$. By the induction hypothesis, $\Upsilon;\Gamma, \Delta \vdash (u/x)v:D$. Therefore, by rule $\oplus_{i2}$, $\Upsilon;\Gamma, \Delta \vdash (u/x)\inr(v):C \oplus D$.

	\item If $t = \elimplus(v, y^C.w, z^D.s)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon;\Gamma_1, x^B \vdash v:C \oplus D$, $\Upsilon;\Gamma_2, y^C \vdash w:A$ and $\Upsilon;\Gamma_2, z^D \vdash s:A$, by the induction hypothesis $\Upsilon;\Gamma_1, \Delta \vdash (u/x)v:C \oplus D$. By rule $\oplus_e$, $\Upsilon;\Gamma, \Delta \vdash \elimplus((u/x)v, y^C.w, z^D.s):A$.
	    \item If $\Upsilon;\Gamma_1 \vdash v:C \oplus D$, $\Upsilon;\Gamma_2, x^B, y^C \vdash w:A$ and $\Upsilon;\Gamma_2, x^B, z^D \vdash s:A$, by the induction hypothesis $\Upsilon;\Gamma_2, y:C \vdash (u/x)w:A$ and $\Upsilon;\Gamma_2, z:D \vdash (u/x)s:A$. By rule $\oplus_e$,\\ $\Upsilon;\Gamma, \Delta \vdash \elimplus(v, y^C.(u/x)w, z^D.(u/x)s):A$.
	  \end{itemize}
	  Therefore, $\Upsilon;\Gamma, \Delta \vdash (u/x)\elimplus(v, y^C.w, z^D.s):A$.

	\item If $t = \oc v$, this is not possible since the linear context should be empty.

	\item If $t = \elimbang(v, y^C.w)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and there are two cases.
	  \begin{itemize}
	    \item If $\Upsilon; \Gamma_1, x^B \vdash v:\oc C$ and $\Upsilon, y^C; \Gamma_2 \vdash w:A$, by the induction hypothesis $\Upsilon; \Gamma_1, \Delta \vdash (u/x) v:\oc C$. By rule $\oc_e$, $\Upsilon; \Gamma, \Delta \vdash \elimbang((u/x)v, y^C.w):A$.
	    \item If $\Upsilon; \Gamma_1 \vdash v:\oc C$ and $\Upsilon, y^C; \Gamma_2, x^B \vdash w:A$, by the induction hypothesis $\Upsilon, y^C; \Gamma_2, \Delta \vdash (u/x)w:A$. By rule $\oc_e$,\\ $\Upsilon; \Gamma, \Delta \vdash \elimbang(v, y^C.(u/x)w):A$.
	  \end{itemize}
	  Therefore, $\Upsilon; \Gamma, \Delta \vdash (u/x)\elimbang(v, y^C.w):A$.

      \end{itemize}
    \item By induction on $t$.
      \begin{itemize}
	\item If $t = x$, then $\Gamma$ is empty and $A = B$. Thus, $\Upsilon;\Gamma \vdash (u/x)t:A$ is the same as $\Upsilon;\varnothing \vdash u:B$ and this is valid by hypothesis.

	\item If $t = y \neq x$, then either $\Gamma = \{y^A\}$ or $\Gamma$ is empty and $y^A \in \Upsilon$.
	  \begin{itemize}
	    \item In the first case, $\Upsilon; y^A \vdash y:A$ by rule lin-ax.
	    \item In the second case, $\Upsilon; \varnothing \vdash y:A$ by rule ax.
	  \end{itemize}
	  Therefore, $\Upsilon; \Gamma \vdash y:A$.

	\item If $t = v \plus w$, then $\Upsilon, x^B;\Gamma \vdash v:A$ and $\Upsilon, x^B;\Gamma \vdash w:A$. By the induction hypothesis, $\Upsilon;\Gamma \vdash (u/x)v:A$ and $\Upsilon;\Gamma \vdash (u/x)w:A$. Therefore, by rule sum, $\Upsilon;\Gamma \vdash (u/x)(v \plus w):A$.

	\item If $t = a \dotprod v$, then $\Upsilon, x^B;\Gamma \vdash v:A$. By the induction hypothesis, $\Upsilon;\Gamma \vdash (u/x)v:A$. Therefore, by rule prod($a$), $\Upsilon;\Gamma \vdash (u/x)(a \dotprod v):A$.

	\item If $t = \elimone(v, w)$, then there are $\Gamma_1, \Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon, x^B; \Gamma_1 \vdash v:\one$ and $\Upsilon, x^B; \Gamma_2 \vdash w:A$. By the induction hypothesis, $\Upsilon; \Gamma_1 \vdash (u/x)v:\one$ and $\Upsilon; \Gamma_2 \vdash (u/x)w:A$. By rule $\one_e$, $\Upsilon; \Gamma \vdash (u/x)\elimone(v, w):A$.

	\item If $t = \lambda y^C.v$, then $A = C \multimap D$ and $\Upsilon, x^B;\Gamma, y^C \vdash v:D$. By the induction hypothesis, $\Upsilon;\Gamma, y^C \vdash (u/x)v:D$. Therefore, by rule $\multimap_i$, $\Upsilon;\Gamma \vdash (u/x)\lambda y^C.v:C \multimap D$.

	\item If $t = v~w$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon, x^B; \Gamma_1 \vdash v:C \multimap A$ and $\Upsilon, x^B; \Gamma_2 \vdash w:C$. By the induction hypothesis, $\Upsilon; \Gamma_1 \vdash (u/x)v:C \multimap A$ and $\Upsilon; \Gamma_2 \vdash (u/x)w:C$. By rule $\multimap_e$, $\Upsilon;\Gamma \vdash (u/x)(v~w):A$.

	\item If $t = v \otimes w$, then $A = C \otimes D$ and there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon, x^B; \Gamma_1 \vdash v:C$ and $\Upsilon, x^B; \Gamma_2 \vdash w:D$. By the induction hypothesis, $\Upsilon; \Gamma_1 \vdash (u/x)v:C$ and $\Upsilon; \Gamma_2 \vdash (u/x)w:D$. By rule $\otimes_i$, $\Upsilon;\Gamma \vdash (u/x)(v \otimes w):C \otimes D$.

	\item If $t = \elimtens(v, y^C z^D.w)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon, x^B; \Gamma_1 \vdash v:C \otimes D$ and $\Upsilon, x^B; \Gamma_2, y^C, z^D \vdash w:A$. By the induction hypothesis, $\Upsilon; \Gamma_1 \vdash (u/x)v:C \otimes D$ and $\Upsilon; \Gamma_2, y^C, z^D \vdash (u/x)w:A$. By rule $\otimes_e$, $\Upsilon;\Gamma \vdash (u/x)\elimtens(v, y^C z^D.w):A$.

	\item If $t = \langle\rangle$, then $A = \top$. By rule $\top_i$ $\Upsilon;\Gamma \vdash \langle\rangle:\top$.

	\item If $t = \elimzero(v)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$ and $\Upsilon, x^B; \Gamma_1 \vdash v:\zero$. By the induction hypothesis $\Upsilon; \Gamma_1 \vdash (u/x)v:\zero$. By rule $\zero_e$, $\Upsilon;\Gamma \vdash (u/x)\elimzero(v):A$.

	\item If $t = \langle v, w \rangle$, then $A = C \with D$, $\Upsilon, x^B;\Gamma \vdash v:C$ and $\Upsilon, x^B;\Gamma \vdash w:D$. By the induction hypothesis, $\Upsilon;\Gamma, \vdash (u/x)v:C$ and $\Upsilon;\Gamma, \vdash (u/x)w:D$. By rule $\with_i$, $\Upsilon;\Gamma \vdash (u/x)\langle v,w \rangle:C \with D$.

	\item If $t = \elimwith^1(v, y^C.w)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon, x^B; \Gamma_1 \vdash v:C \with D$ and $\Upsilon, x^B; \Gamma_2, y^C \vdash w:A$. By the induction hypothesis, $\Upsilon; \Gamma_1 \vdash (u/x)v:C \with D$ and $\Upsilon; \Gamma_2, y^C \vdash (u/x)w:A$. By rule $\with_{e1}$, $\Upsilon;\Gamma \vdash (u/x)\elimwith^1(v, y^C.w):A$.

	\item If $t = \elimwith^2(v, y^D.w)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon, x^B; \Gamma_1 \vdash v:C \with D$ and $\Upsilon, x^B; \Gamma_2, y^C \vdash w:A$. By the induction hypothesis, $\Upsilon; \Gamma_1 \vdash (u/x)v:C \with D$ and $\Upsilon; \Gamma_2, y^C \vdash (u/x)w:A$. By rule $\with_{e2}$, $\Upsilon;\Gamma \vdash (u/x)\elimwith^2(v, y^D.w):A$.

	\item If $t = \inl(v)$, then $A = C \oplus D$ and $\Upsilon, x^B;\Gamma \vdash v:C$. By the induction hypothesis, $\Upsilon;\Gamma \vdash (u/x)v:C$. Therefore, by rule $\oplus_{i1}$, $\Upsilon;\Gamma \vdash (u/x)\inl(v):C \oplus D$.

	\item If $t = \inr(v)$, then $A = C \oplus D$ and $\Upsilon, x^B;\Gamma \vdash v:D$. By the induction hypothesis, $\Upsilon;\Gamma \vdash (u/x)v:D$. Therefore, by rule $\oplus_{i2}$, $\Upsilon;\Gamma \vdash (u/x)\inr(v):C \oplus D$.

	\item If $t = \elimplus(v, y^C.w, z^D.s)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon, x^B; \Gamma_1 \vdash v:C \oplus D$, $\Upsilon, x^B; \Gamma_2, y^C \vdash w:A$ and $\Upsilon, x^B; \Gamma_2, z^D \vdash s:A$. By the induction hypothesis, $\Upsilon; \Gamma_1 \vdash (u/x)v:C \oplus D$, $\Upsilon; \Gamma_2, y^C \vdash (u/x)w:A$ and $\Upsilon; \Gamma_2, z^D \vdash (u/x)s:A$. By rule $\oplus_e$,\\ $\Upsilon;\Gamma \vdash (u/x)\elimplus(v, y^C.w, z^D.s):A$.

	\item If $t = \oc v$, then $A = \oc C$, $\Gamma$ is empty and $\Upsilon, x^B; \varnothing \vdash v:C$. By the induction hypothesis $\Upsilon; \varnothing \vdash (u/x)v:C$, and by rule $\oc_i$ $\Upsilon; \varnothing \vdash (u/x)\oc v: \oc C$.

	\item If $t = \elimbang(v, y^C.w)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon, x^B; \Gamma_1 \vdash v:\oc C$ and $\Upsilon, x^B; \Gamma_2, y^C \vdash w:A$. By the induction hypothesis, $\Upsilon; \Gamma_1 \vdash (u/x)v:\oc C$ and $\Upsilon; \Gamma_2, y^C \vdash (u/x)w:A$. By rule $\oc_e$, $\Upsilon; \Gamma \vdash (u/x)\elimbang(v, y^C.w):A$.\qedhere
      \end{itemize}
  \end{enumerate}
\end{proof}

\SR*
\begin{proof}
  By induction on the relation $\lra$. 
  \begin{itemize}
    \item If $t = \elimone(a.\star, v)$ and $u = a \dotprod v$, then $\Upsilon;\Gamma \vdash v:A$. Therefore, by rule prod($a$), $\Upsilon;\Gamma \vdash a \dotprod v:A$.

    \item If $t = (\lambda x^B.v_1)~v_2$ and $u = (v_2/x)v_1$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon;\Gamma_1, x^B \vdash v_1:A$ and $\Upsilon;\Gamma_2 \vdash v_2:B$. By Lemma~\ref{lem:polysubstitution}, $\Upsilon;\Gamma \vdash (v_2/x)v_1:A$.

    \item If $t = \elimtens(v_1 \otimes v_2, x^B y^C.v_3)$ and $u = (v_1/x, v_2/y)v_3$, then there are $\Gamma_1$, $\Gamma_2$ and $\Gamma_3$ such that $\Gamma = \Gamma_1, \Gamma_2, \Gamma_3$, $\Upsilon;\Gamma_1 \vdash v_1:B$, $\Upsilon;\Gamma_2 \vdash v_2:C$ and $\Upsilon;\Gamma_3, x^B, y^C \vdash v_3:A$. By Lemma~\ref{lem:polysubstitution} twice, $\Upsilon;\Gamma \vdash (v_1/x, v_2/y)v_3:A$.

    \item If $t = \elimwith^1(\langle v_1, v_2 \rangle, x^B.v_3)$ and $u = (v_1/x)v_3$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon;\Gamma_1 \vdash v_1:B$, $\Upsilon;\Gamma_1 \vdash v_2:C$ and $\Upsilon;\Gamma_2, x^B \vdash v_3:A$. By Lemma~\ref{lem:polysubstitution}, $\Upsilon;\Gamma \vdash (v_1/x)v_3:A$.

    \item If $t = \elimwith^2(\langle v_1, v_2 \rangle, x^B.v_3)$ and $u = (v_2/x)v_3$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon;\Gamma_1 \vdash v_1:C$, $\Upsilon;\Gamma_1 \vdash v_2:B$ and $\Upsilon;\Gamma_2, x^B \vdash v_3:A$. By Lemma~\ref{lem:polysubstitution}, $\Upsilon;\Gamma \vdash (v_2/x)v_3:A$.

    \item If $t = \elimplus(\inl(v_1), x^B.v_2, y^C.v_3)$ and $u = (v_1/x)v_2$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon;\Gamma_1 \vdash v_1:B$, $\Upsilon;\Gamma_2, x^B \vdash v_2:A$ and $\Upsilon;\Gamma_2, y^C \vdash v_3:A$. By Lemma~\ref{lem:polysubstitution}, $\Upsilon;\Gamma \vdash (v_1/x)v_2:A$.

    \item If $t = \elimplus(\inr(v_1), x^B.v_2, y^C.v_3)$ and $u = (v_1/y)v_3$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon;\Gamma_1 \vdash v_1:C$, $\Upsilon;\Gamma_2, x^B \vdash v_2:A$ and $\Upsilon;\Gamma_2, y^C \vdash v_3:A$. By Lemma~\ref{lem:polysubstitution}, $\Upsilon;\Gamma \vdash (v_1/y)v_3:A$.

    \item If $t = \elimbang(\oc v_1, x^B.v_2)$ and $u = (v_1/x)v_2$, then $\Upsilon; \varnothing \vdash v_1:B$ and $\Upsilon, x^B; \Gamma \vdash v_2:A$. By Lemma~\ref{lem:polysubstitution}, $\Upsilon; \Gamma \vdash (v_1/x)v_2:A$.

    \item If $t = {a.\star} \plus b.\star$ and $u = (a+b).\star$, then $A = \one$ and $\Gamma$ is empty. By rule $\one_i$($a+b$), $\Upsilon; \varnothing \vdash (a+b).\star:\one$.

    \item If $t = (\lambda x^B.v_1) \plus (\lambda x^B.v_2)$ and $u = \lambda x^B.(v_1 \plus v_2)$, then $A = B \multimap C$, $\Upsilon; \Gamma, x^B \vdash v_1:C$ and $\Upsilon; \Gamma, x^B \vdash v_2:C$. By rule sum, $\Upsilon; \Gamma, x^B \vdash v_1 \plus v_2:C$. Therefore, by rule $\multimap_i$, $\Upsilon; \Gamma \vdash \lambda x^B.(v_1 \plus v_2): B \multimap C$.

    \item If $t = \elimtens(v_1 \plus v_2, x^B y^C.v_3)$ and $u = \elimtens(v_1, x^B y^C.v_3) \plus \elimtens(v_2, x^B y^C.v_3)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon; \Gamma_1 \vdash v_1:B \otimes C$, $\Upsilon; \Gamma_1 \vdash v_2:B \otimes C$ and $\Upsilon; \Gamma_2, x^B, y^C \vdash v_3:A$. By rule $\otimes_e$, $\Upsilon; \Gamma \vdash \elimtens(v_1, x^B y^C.v_3):A$ and $\Upsilon; \Gamma \vdash \elimtens(v_2, x^B y^C.v_3):A$. Therefore, by rule sum, $\Upsilon; \Gamma \vdash \elimtens(v_1, x^B y^C.v_3) \plus \elimtens(v_2, x^B y^C.v_3):A$.

    \item If $t = \langle\rangle \plus \langle\rangle$ and $u = \langle\rangle$, then $A = \top$. By rule $\top_i$, $\Upsilon;\Gamma \vdash \langle\rangle:\top$.

    \item If $t = \langle v_1, v_2 \rangle \plus \langle v_3, v_4 \rangle$ and $u = \langle v_1 \plus v_3, v_2 \plus v_4 \rangle$, then $A = B \with C$, $\Upsilon; \Gamma \vdash v_1:B$, $\Upsilon; \Gamma \vdash v_2:C$, $\Upsilon; \Gamma \vdash v_3:B$ and $\Upsilon; \Gamma \vdash v_4:C$. By rule sum, $\Upsilon; \Gamma \vdash v_1 \plus v_3:B$ and $\Upsilon; \Gamma \vdash v_2 \plus v_4:C$. Therefore, by rule $\with_i$, $\Upsilon; \Gamma \vdash \langle v_1 \plus v_3, v_2 \plus v_4 \rangle:B \with C$.

    \item If $t = \elimplus(v_1 \plus v_2, x^B.v_3, y^C.v_4)$ and $u = \elimplus(v_1, x^B.v_3, y^C.v_4) \plus \elimplus(v_2, x^B.v_3, y^C.v_4)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon; \Gamma_1 \vdash v_1:B \oplus C$, $\Upsilon; \Gamma_1 \vdash v_2:B \oplus C$, $\Upsilon; \Gamma_2, x^B \vdash v_3:A$ and $\Upsilon; \Gamma_2, y^C \vdash v_4:A$. By rule $\oplus_e$, $\Upsilon; \Gamma \vdash \elimplus(v_1, x^B.v_3, y^C.v_4):A$ and $\Upsilon; \Gamma \vdash \elimplus(v_2, x^B.v_3, y^C.v_4):A$. Therefore, by rule sum, $\Upsilon; \Gamma \vdash \elimplus(v_1, x^B.v_3, y^C.v_4) \plus \elimplus(v_2, x^B.v_3, y^C.v_4):A$.

    \item If $t = \oc v_1 \plus \oc v_2$ and $u = \oc (v_1 \plus v_2)$, then $A = \oc B$, $\Upsilon; \varnothing \vdash v_1:B$ and $\Upsilon; \varnothing \vdash v_2:B$. By rule sum, $\Upsilon; \varnothing \vdash v_1 \plus v_2:B$. By rule $\oc_i$, $\Upsilon; \varnothing \vdash \oc(v_1 \plus v_2):\oc B$.

    \item If $t = a \dotprod b.\star$ and $u = (a \times b).\star$, then $A = \one$ and $\Gamma$ is empty. By rule $\one_i$($a \times b$), $\Upsilon; \varnothing \vdash (a \times b).\star:\one$.

    \item If $t = a \dotprod \lambda x^B.v$ and $u = \lambda x^B.a \dotprod v$, then $A = B \multimap C$ and $\Upsilon; \Gamma, x^B \vdash v:C$. By rule prod($a$), $\Upsilon; \Gamma, x^B \vdash a \dotprod v:C$. Therefore, by rule $\multimap_i$, $\Upsilon; \Gamma \vdash \lambda x^B.a \dotprod v:B \multimap C$.

    \item If $t = \elimtens(a \dotprod v_1, x^B y^C.v_2)$ and $u = a \dotprod \elimtens(v_1, x^B y^C.v_2)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon; \Gamma_1 \vdash v_1:B \otimes C$ and $\Upsilon; \Gamma_2, x^B, y^C \vdash v_2:A$. By rule $\otimes_e$, $\Upsilon; \Gamma \vdash \elimtens(v_1, x^B y^C.v_2):A$. Therefore, by rule prod($a$), $\Upsilon; \Gamma \vdash a \dotprod \elimtens(v_1, x^B y^C.v_2):A$.

    \item If $t = a \dotprod \langle\rangle$ and $u = \langle\rangle$, then $A = \top$. Therefore, by rule $\top_i$, $\Upsilon; \Gamma \vdash \langle\rangle:\top$.

    \item If $t = a \dotprod \langle v_1, v_2 \rangle$ and $u = \langle a \dotprod v_1, a \dotprod v_2 \rangle$, then $A = B \with C$, $\Upsilon; \Gamma \vdash v_1:B$ and $\Upsilon; \Gamma \vdash v_2:C$. By rule prod($a$), $\Upsilon; \Gamma \vdash a \dotprod v_1:B$ and $\Upsilon; \Gamma \vdash a \dotprod v_2:C$. Therefore, by rule $\with_i$, $\Upsilon; \Gamma \vdash \langle a \dotprod v_1, a \dotprod v_2 \rangle:B \with C$.

    \item If $t = \elimplus(a \dotprod v_1, x^B.v_2, y^C.v_3)$ and $u = a \dotprod \elimplus(v_1, x^B.v_2, y^C.v_3)$, then there are $\Gamma_1$ and $\Gamma_2$ such that $\Gamma = \Gamma_1, \Gamma_2$, $\Upsilon; \Gamma_1 \vdash v_1:B \oplus C$, $\Upsilon; \Gamma_2, x^B \vdash v_2:A$ and $\Upsilon; \Gamma_2, y^C \vdash v_3:A$. By rule $\oplus_e$, $\Upsilon; \Gamma \vdash \elimplus(v_1, x^B.v_2, y^C.v_3):A$. Therefore, by rule prod($a$), $\Upsilon; \Gamma \vdash a \dotprod \elimplus(v_1, x^B.v_2, y^C.v_3):A$.

    \item If $t = a \dotprod \oc v$ and $u = \oc(a \dotprod v)$, then $A = \oc B$ and $\Upsilon; \varnothing \vdash v:B$. By rule prod($a$), $\Upsilon; \varnothing \vdash a \dotprod v: B$. By rule $\oc_i$, $\Upsilon; \varnothing \vdash \oc(a \dotprod v): \oc B$.\qedhere
  \end{itemize}
\end{proof}

\subsection{Lemma~\ref{lem:typeinterpretationsarerc}}\label{proof:ST}
\typeinterpretationsarerc*
\begin{proof}
  By induction on $A$.
  \begin{itemize}
    \item If $A = \one$, $\SN$ has the properties CR1, CR2, and CR3.
    \item If $A = B \multimap C$:
      \begin{itemize}
        \item Let $t \in \llbracket B \rrbracket \hatmultimap \llbracket C \rrbracket$, then $t \in \SN$.
        \item Let $t \in \llbracket B \rrbracket \hatmultimap \llbracket C \rrbracket$ such that $t \lra t'$. Then $t' \in \SN$, and if $t' \lras \lambda x^D.u$, $t \lras \lambda x^D.u$. Therefore, for all $v \in \llbracket B \rrbracket$, $(v/x)u \in \llbracket C \rrbracket$.
        \item Let $t$ be a proof-term that is not an introduction such that $Red(t) \subseteq \llbracket B \rrbracket \hatmultimap \llbracket C \rrbracket$. Since $Red(t) \subseteq \SN$, $t \in \SN$. If $t \lras \lambda x^D.u$, the rewrite sequence has at least one step because $t$ is not an introduction. Then, there is a proof-term $t' \in Red(t)$ such that $t' \lras \lambda x^D.u$. Therefore, for all $v \in \llbracket B \rrbracket$, $(v/x)u \in \llbracket C \rrbracket$.
      \end{itemize}
    \item If $A = B \otimes C$:
      \begin{itemize}
        \item Let $t \in \llbracket B \rrbracket \hatotimes \llbracket C \rrbracket$, then $t \in \SN$.
        \item Let $t \in \llbracket B \rrbracket \hatotimes \llbracket C \rrbracket$ such that $t \lra t'$. Then $t' \in \SN$, and if $t' \lras u \otimes v$, $t \lras u \otimes v$. Therefore, $u \in \llbracket B \rrbracket$ and $v \in \llbracket C \rrbracket$.
        \item Let $t$ be a proof-term that is not an introduction such that $Red(t) \subseteq \llbracket B \rrbracket \hatotimes \llbracket C \rrbracket$. Since $Red(t) \subseteq \SN$, $t \in \SN$. If $t \lras u \otimes v$, the rewrite sequence has at least one step because $t$ is not an introduction. Then, there is a proof-term $t' \in Red(t)$ such that $t' \lras u \otimes v$. Therefore, $u \in \llbracket B \rrbracket$ and $v \in \llbracket C \rrbracket$.
      \end{itemize}
    \item If $A = \top$, $\SN$ has the properties CR1, CR2, and CR3.
    \item If $A = \zero$, $\SN$ has the properties CR1, CR2, and CR3.
    \item If $A = B \with C$:
    \begin{itemize}
      \item Let $t \in \llbracket B \rrbracket \hatand \llbracket C \rrbracket$, then $t \in \SN$.
      \item Let $t \in \llbracket B \rrbracket \hatand \llbracket C \rrbracket$ such that $t \lra t'$. Then $t' \in \SN$, and if $t' \lras \langle u,v \rangle$, $t \lras \langle u,v \rangle$. Therefore, $u \in \llbracket B \rrbracket$ and $v \in \llbracket C \rrbracket$.
      \item Let $t$ be a proof-term that is not an introduction such that $Red(t) \subseteq \llbracket B \rrbracket \hatand \llbracket C \rrbracket$. Since $Red(t) \subseteq \SN$, $t \in \SN$. If $t \lras \langle u,v \rangle$, the rewrite sequence has at least one step because $t$ is not an introduction. Then, there is a proof-term $t' \in Red(t)$ such that $t' \lras \langle u,v \rangle$. Therefore, $u \in \llbracket B \rrbracket$ and $v \in \llbracket C \rrbracket$.
    \end{itemize}
    \item If $A = B \oplus C$:
      \begin{itemize}
        \item Let $t \in \llbracket B \rrbracket \hatoplus \llbracket C \rrbracket$, then $t \in \SN$.
        \item Let $t \in \llbracket B \rrbracket \hatoplus \llbracket C \rrbracket$ such that $t \lra t'$. Then $t' \in \SN$, and if $t' \lras \inl(u)$, $t \lras \inl(u)$. Therefore, $u \in \llbracket B \rrbracket$. If $t' \lras \inr(v)$, $t \lras \inr(v)$. Therefore, $v \in \llbracket C \rrbracket$.
        \item Let $t$ be a proof-term that is not an introduction such that $Red(t) \subseteq \llbracket B \rrbracket \hatoplus \llbracket C \rrbracket$. Since $Red(t) \subseteq \SN$, $t \in \SN$. If $t \lras \inl(u)$, the rewrite sequence has at least one step because $t$ is not an introduction. Then, there is a proof-term $t' \in Red(t)$ such that $t' \lras \inl(u)$. Therefore, $u \in \llbracket B \rrbracket$. If $t \lras \inr(v)$, the rewrite sequence has at least one step because $t$ is not an introduction. Then, there is a proof-term $t' \in Red(t)$ such that $t' \lras \inr(v)$. Therefore, $v \in \llbracket C \rrbracket$.
      \end{itemize}
    \item If $A = \oc B$:
      \begin{itemize}
	\item Let $t \in \hatbang\llbracket B\rrbracket$, then $t\in \SN$.
	\item Let $t \in \hatbang\llbracket B \rrbracket$ such that $t \lra t'$. Then $t' \in \SN$, and if $t' \lras \oc u$, $t \lras\oc u$. Therefore, $u \in \llbracket B \rrbracket$. 
	\item Let $t$ be a proof-term that is not an introduction such that $Red(t) \subseteq \hatbang\llbracket B \rrbracket$. Since $Red(t) \subseteq \SN$, $t \in \SN$. If $t \lras \oc u$, the rewrite sequence has at least one step because $t$ is not an introduction. Then, there is a proof-term $t' \in Red(t)$ such that $t' \lras \oc u$. Therefore, $u \in \llbracket B \rrbracket$.\qedhere 
      \end{itemize}
  \end{itemize}
\end{proof}

\subsection{Adequacy lemmas for the proof of Lemma~\ref{lem:adequacy}}
\label{proof:Adequacy}

In Lemmas~\ref{lem:sum}
to~{\ref{lem:elimbang}},
we prove the adequacy of each proof-term constructor. If $t$ is a strongly
normalising proof-term, we write $|t|$ for the maximum length of a reduction
sequence issued from $t$.

\begin{lemma}[Normalisation of a sum]
    \label{lem:terminationsum}
    If $t$ and $u$ strongly normalise, then so does $t \plus u$. 
  \end{lemma}
  \begin{proof}
    We prove that all the one-step reducts of 
    $t \plus u$ strongly normalise, by induction first on 
    $|t| + |u|$ and then on the size of $t$. 

    If the reduction takes place in $t$ or in $u$ we apply the induction
    hypothesis.
    Otherwise, the reduction occurs at the root and the rule used is one of 
    \[
      \begin{array}{r@{\,}l@{\qquad}r@{\,}l}
	{a.\star} \plus {b.\star} &\lra  (a + b).\star
	&	\pair{t'_1}{t'_2} \plus \pair{u'_1}{u'_2} &\lra  \pair{t'_1 \plus u'_1}{t'_2 \plus u'_2}\\
	(\lambda x^A.t') \plus (\lambda x^A.u') &\lra  \lambda x^A.(t' \plus u')
	&	\oc t' \plus \oc u' &\lra \oc(t' \plus u')\\
	\langle \rangle \plus \langle \rangle &\lra \langle \rangle
	&	t \plus u &\lra t\\
	&
	&	t \plus u &\lra u
      \end{array}
    \]

    In the first case, the proof-term $(a + b).\star$ is irreducible, hence it
    strongly normalises. In the second, {and fifth, and sixth}, 
    by induction hypothesis, the proof-term $t' \plus u'$
    strongly normalises, thus so do the proof-terms
    $\lambda x^A.(t' \plus u')$, and $\oc (t'\plus u')$.
    In the third, the proof-term $\langle \rangle$ is irreducible, hence it
    strongly normalises. 
    In the fourth, 
    by induction hypothesis, the proof-terms
    $t'_1 \plus u'_1$ and $t'_2 \plus u'_2$
    strongly normalise, hence so does the proof-term
    $\pair{t'_1 \plus u'_1}{t'_2 \plus u'_2}$.
    In the sixth and seventh, the proof-terms $t$ and $u$ strongly normalise. 
  \end{proof}

  \begin{lemma}[Normalisation of a product]
  \label{lem:terminationprod}
  If $t$ strongly normalises, then so does $a \dotprod t$. 
  \end{lemma}
  \begin{proof}
  We prove that all the one-step reducts of 
  $a \dotprod t$ strongly normalise, by induction first on 
  $|t|$ and then on the size of $t$. 

  If the reduction takes place in $t$, we apply the induction
  hypothesis.
  Otherwise, the reduction occurs at the root, and the rule used is either
  \[
    \begin{array}{r@{\,}l@{\qquad}r@{\,}l}
      a \dotprod b.\star &\lra  (a \times b).\star
      &		a \dotprod \pair{t'_1}{t'_2} &\lra  \pair{a \dotprod t'_1}{a \dotprod t'_2}\\
      a \dotprod (\lambda x^A.t') &\lra  \lambda x^A. a \dotprod t'
      &		a \dotprod \oc t' &\lra \oc (a \dotprod t')\\
      a \dotprod \langle \rangle &\lra  \langle \rangle
      &		a \dotprod t &\lra t 
    \end{array}
  \]
  In the first case, the proof-term $(a \times b).\star$ is irreducible,
  hence it strongly normalises. In the second, { fifth, and sixth}, by induction hypothesis,
  the proof-term $a \dotprod t'$ strongly normalises, thus so do the proof-terms
  $\lambda x^A.a \dotprod t'$,  and $\oc (a \dotprod t')$.  In the third, the proof-term $\langle
  \rangle$ is irreducible, hence it strongly normalises.  In the
  fourth, by induction hypothesis, the proof-terms $a \dotprod t'_1$ and
  $a \dotprod t'_2$ strongly normalise, hence so does the proof-term
  $\pair{a \dotprod t'_1}{a \dotprod t'_2}$. In the sixth, the proof-term $t$
  strongly normalises. 
  \end{proof}

\begin{lemma}[Adequacy of $\plus$]
\label{lem:sum}
If $\Upsilon;\Gamma \vdash t_1:A$, $\Upsilon;\Gamma \vdash t_2:A$, $t_1 \in \llbracket A \rrbracket$, and $t_2 \in \llbracket A
\rrbracket$, then $t_1 \plus t_2 \in \llbracket A \rrbracket$.
\end{lemma}
\begin{proof}
  By induction on $A$.
  The proof-terms $t_1$ and $t_2$ strongly normalise.  Thus, by
  Lemma~\ref{lem:terminationsum}, the proof-term $t_1 \plus t_2$ strongly
  normalises.
  Furthermore:
  \begin{itemize}
    \item If the proposition $A$ has the form $\one$, $\top$, or $\zero$, then $t_1\plus t_2\in\SN=\llbracket A\rrbracket$.
    \item If the proposition $A$ has the form $B \multimap C$, and $t_1
      \plus t_2 \lra^* \lambda x^B. v$ then either $t_1 \lra^*
      \lambda x^B. u_1$, $t_2 \lra^* \lambda x^B. u_2$, and $u_1
      \plus u_2 \lra^* v$, or $t_1 \lra^* \lambda x^B. v$, or $t_2
      \lra^* \lambda x^B. v$.

      In the first case, as $t_1$ and $t_2$ are in $\llbracket A
      \rrbracket$, for every $w$ in $\llbracket B \rrbracket$, $(w/x)u_1
      \in \llbracket C \rrbracket$ and $(w/x)u_2 \in \llbracket C
      \rrbracket$.  By induction hypothesis, $(w/x)(u_1 \plus u_2) =
      (w/x)u_1 \plus (w/x)u_2 \in \llbracket C \rrbracket$ and by
      {CR2}, $(w/x)v \in \llbracket C \rrbracket$.

      In the second and the third, as $t_1$ and $t_2$ are in $\llbracket A
      \rrbracket$, for every $w$ in $\llbracket B \rrbracket$, $(w/x)v \in
      \llbracket C \rrbracket$.

    \item If the proposition $A$ has the form $B \otimes C$, and $t_1
      \plus t_2 \lra^* v \otimes v'$ then $t_1 \lra^* v \otimes v'$, or
      $t_2 \lra^* v \otimes v'$.  As $t_1$ and $t_2$ are in $\llbracket
      A \rrbracket$, $v \in \llbracket B \rrbracket$ and $v' \in
      \llbracket C \rrbracket$.

    \item If the proposition $A$ has the form $B \with C$, and $t_1 \plus t_2
      \lra^* \pair{v}{v'}$ then $t_1 \lra^* \pair{u_1}{u'_1}$, $t_2 \lra^*
      \pair{u_2}{u'_2}$, $u_1 \plus u_2 \lra^* v$, and $u'_1 \plus u'_2
      \lra^* v'$, or $t_1 \lra^* \pair{v}{v'}$, or $t_2 \lra^*
      \pair{v}{v'}$.

      In the first case, as $t_1$ and $t_2$ are in $\llbracket A
      \rrbracket$, $u_1$ and $u_2$ are in $\llbracket B \rrbracket$ and
      $u'_1$ and $u'_2$ are in $\llbracket C \rrbracket$.  By induction
      hypothesis, $u_1 \plus u_2 \in \llbracket B \rrbracket$ and $u'_1
      \plus u'_2 \in \llbracket C \rrbracket$ and by {CR2}, $v \in \llbracket B \rrbracket$ and $v'
      \in \llbracket C \rrbracket$.

      In the second and the third, as $t_1$ and $t_2$ are in $\llbracket A
      \rrbracket$, $v \in \llbracket B \rrbracket$ and $v' \in \llbracket
      C \rrbracket$.

    \item If the proposition $A$ has the form $B \oplus C$, and $t_1 \plus
      t_2 \lra^* \inl(v)$ then $t_1 \lra^* \inl(v)$ or $t_2 \lra^*
      \inl(v)$.  As $t_1$ and $t_2$ are in $\llbracket A \rrbracket$, $v
      \in \llbracket B \rrbracket$.

      The proof is similar if $t_1 \plus t_2 \lra^* \inr(v)$.
    \item
	If the proposition $A$ has the form $\oc B$, and $t_1 \plus t_2
	\lra^* \oc v$ then $t_1 \lra^*\oc u_1$, $t_2 \lra^*
	\oc u_2$, $u_1 \plus u_2 \lra^* v$, or $t_1 \lra^* \oc v$, or $t_2 \lra^* \oc v$.
	In the first case, as $t_1$ and $t_2$ are in $\llbracket A
	\rrbracket$, $u_1$ and $u_2$ are in $\llbracket B \rrbracket$.
	By induction hypothesis, $u_1 \plus u_2 \in \llbracket B \rrbracket$,
	and by {CR2}, $v \in \llbracket B \rrbracket$.
	In the second and the third, as $t_1$ and $t_2$ are in $\llbracket A
	\rrbracket$, $v \in \llbracket B \rrbracket$.\qedhere
  \end{itemize}
\end{proof}

\begin{lemma}[Adequacy of $\dotprod$]
\label{lem:prod}
If $\Upsilon;\Gamma \vdash t:A$ and $t \in \llbracket A \rrbracket$, then $a \dotprod t \in \llbracket A
\rrbracket$.
\end{lemma}

\begin{proof}
  By induction on $A$.  The proof-term $t$ strongly normalises.  Thus, by
  Lemma~\ref{lem:terminationprod}, the proof-term $a \dotprod t$ strongly
  normalises.  Furthermore:

  \begin{itemize}
    \item If the proposition $A$ has the form $\one$, $\top$, or $\zero$, then $a\dotprod t\in\SN=\llbracket A\rrbracket$.
    \item If the proposition $A$ has the form $B \multimap C$, and $a
      \dotprod t \lra^* \lambda x^B. v$ then either $t \lra^* \lambda
      x^B. u$ and $a \dotprod u \lra^* v$, or $t \lra^* \lambda
      x^B. v$.

      In the first case, as $t$ is in $\llbracket A \rrbracket$, for
      every $w$ in $\llbracket B \rrbracket$, $(w/x)u \in \llbracket C
      \rrbracket$.  By induction hypothesis, $(w/x) (a \dotprod u) = a
      \dotprod (w/x)u \in \llbracket C \rrbracket$ and by
      {CR2}, $(w/x)v \in \llbracket C \rrbracket$.

      In the second, as $t$ is in $\llbracket A \rrbracket$, for every $w$
      in $\llbracket B \rrbracket$, $(w/x)v \in \llbracket C \rrbracket$.

    \item If the proposition $A$ has the form $B \otimes C$, and $a
      \dotprod t \lra^* v \otimes v'$ then $t \lra^* v \otimes v'$.  As $t$
      is in $\llbracket A \rrbracket$, $v \in \llbracket B \rrbracket$ and
      $v' \in \llbracket C \rrbracket$.

    \item If the proposition $A$ has the form $B \with C$, and $a \dotprod t
      \lra^* \pair{v}{v'}$ then $t \lra^* \pair{u}{u'}$, $a \dotprod u
      \lra^* v$, and $a \dotprod u' \lra^* v'$, or $t \lra^* \pair{v}{v'}$.

      In the first case, as $t$ is in $\llbracket A \rrbracket$, $u$ is in
      $\llbracket B \rrbracket$ and $u'$ is in $\llbracket C \rrbracket$.
      By induction hypothesis, $a \dotprod u \in \llbracket B \rrbracket$
      and $a \dotprod u' \in \llbracket C \rrbracket$ and by
      {CR2}, $v \in \llbracket B \rrbracket$ and $v'
      \in \llbracket C \rrbracket$.

      In the second, as $t$ is in $\llbracket A \rrbracket$, $v \in
      \llbracket B \rrbracket$ and $v' \in \llbracket C \rrbracket$.


    \item If the proposition $A$ has the form $B \oplus C$, and $a \dotprod t
      \lra^* \inl(v)$ then $t \lra^* \inl(v)$.
      Then, by {CR2},
      $\inl(v) \in \llbracket A \rrbracket$ hence, $v \in \llbracket
      B \rrbracket$.

      The proof is similar if $a \dotprod t \lra^* \inr(v)$.
    \item 
	If the proposition $A$ has the form $\oc B$, and $a \dotprod t \lra^* \oc v$ then $t \lra^* \oc u$ and $a \dotprod u \lra^* v$, or $t \lra^* \oc v$.
	In the first case, as $t$ is in $\llbracket A \rrbracket$, $u$ is in
	$\llbracket B \rrbracket$.
	By induction hypothesis, $a \dotprod u \in \llbracket B \rrbracket$
	and by {CR2}, $v \in \llbracket B \rrbracket$.
	In the second, as $t$ is in $\llbracket A \rrbracket$, $v \in
	\llbracket B \rrbracket$.\qedhere
  \end{itemize}
\end{proof}

\begin{lemma}[Adequacy of $a.\star$]
  \label{lem:star}
   $a.\star \in \llbracket \one \rrbracket$.
  \end{lemma}

  \begin{proof}
  As $a.\star$ is irreducible, it strongly normalises, hence
  $a.\star \in \llbracket \one \rrbracket$.
  \end{proof}

  \begin{lemma}[Adequacy of $\lambda$]
  \label{lem:abstraction}
  If, for all $u \in \llbracket A \rrbracket$, $(u/x)t \in \llbracket B
  \rrbracket$, then $\lambda x^C.t \in \llbracket A \multimap B
  \rrbracket$.
  \end{lemma}

  \begin{proof}
  By Lemma~\ref{lem:Var}, $x \in \llbracket A \rrbracket$, thus
  $t = (x/x)t \in \llbracket B \rrbracket$. Hence, $t$ strongly
  normalises.  Consider a reduction sequence issued from $\lambda
  x^C.t$.  This sequence can only reduce $t$ hence it is finite. Thus,
  $\lambda x^C.t$ strongly normalises.

  Furthermore, if $\lambda x^C.t \lras \lambda x^C.t'$, then
  $t \lra^* t'$.  Let $u \in \llbracket A \rrbracket$,
  $(u/x)t \lra^* (u/x)t'$.
  As $(u/x)t \in \llbracket B
  \rrbracket$, by {CR2}, $(u/x)t' \in
  \llbracket B \rrbracket$.
  \end{proof}

  \begin{lemma}[Adequacy of $\otimes$]
  \label{lem:tensor}
  If $t_1 \in \llbracket A \rrbracket$ and $t_2 \in \llbracket B
  \rrbracket$, then $t_1 \otimes t_2 \in \llbracket A \otimes B
  \rrbracket$.
  \end{lemma}

  \begin{proof}
  The proof-terms $t_1$ and $t_2$ strongly normalise. Consider a reduction
  sequence issued from $t_1 \otimes t_2$.  This sequence can only reduce
  $t_1$ and $t_2$, hence it is finite.  Thus, $t_1 \otimes t_2$ strongly
  normalises.

  Furthermore, if $t_1 \otimes t_2 \lras t'_1 \otimes t'_2$,
  then $t_1 \lra^* t'_1$ and $t_2 \lra^* t'_2$.  By {CR2},
  $t'_1 \in \llbracket A \rrbracket$ and $t'_2 \in
  \llbracket B \rrbracket$. 
  \end{proof}


  \begin{lemma}[Adequacy of $\langle \rangle$]
  \label{lem:unit}
  $\langle \rangle \in \llbracket \top \rrbracket$.
  \end{lemma}

  \begin{proof}
  As $\langle \rangle$ is irreducible, it strongly normalises, hence
  $\langle \rangle \in \llbracket \top \rrbracket$. 
  \end{proof}

  \begin{lemma}[Adequacy of $\pair{}{}$]
  \label{lem:pair}
  If $t_1 \in \llbracket A \rrbracket$ and $t_2 \in \llbracket B
  \rrbracket$, then $\pair{t_1}{t_2} \in \llbracket A \with B
  \rrbracket$.
  \end{lemma}

  \begin{proof}
  The proof-terms $t_1$ and $t_2$ strongly normalise. Consider a reduction
  sequence issued from $\pair{t_1}{t_2}$.  This sequence can only
  reduce $t_1$
  and $t_2$, hence it is finite.  Thus, $\pair{t_1}{t_2}$
  strongly normalises.

  Furthermore, if $\pair{t_1}{t_2} \lras \pair
  {t'_1}{t'_2}$, then $t_1 \lra^* t'_1$ and $t_2 \lra^* t'_2$.  By
  {CR2}, $t'_1 \in \llbracket A \rrbracket$ and
  $t'_2 \in \llbracket B \rrbracket$. 
  \end{proof}

  \begin{lemma}[Adequacy of $\inl$]
  \label{lem:inl}
  If $t \in \llbracket A \rrbracket$, then $\inl(t) \in \llbracket A
  \oplus B \rrbracket$.
  \end{lemma}

  \begin{proof}
  The proof-term $t$ strongly normalises. Consider a reduction sequence
  issued from $\inl(t)$.  This sequence can only reduce $t$, hence it is
  finite.  Thus, $\inl(t)$ strongly normalises.

  Furthermore, if $\inl(t) \lras \inl(t')$, then $t \lra^* t'$.  By {CR2}, $t' \in \llbracket A
  \rrbracket$. And $\inl(t)$ never reduces to $\inr(t')$. 
  \end{proof}

  \begin{lemma}[Adequacy of $\inr$]
  \label{lem:inr}
  If $t \in \llbracket B \rrbracket$, then $\inr(t) \in \llbracket A
  \oplus B \rrbracket$.
  \end{lemma}

  \begin{proof}
    Similar to the proof of Lemma~\ref{lem:inl}. 
  \end{proof}

  \begin{lemma}[Adequacy of $\oc$]
    \label{lem:bang}
    If $t \in \llbracket A\rrbracket$, then $\oc t \in \llbracket\oc A\rrbracket$.
  \end{lemma}
  \begin{proof}
    The proof-term $t$ strongly normalises. Consider a reduction sequence
    issued from $\oc t$.  This sequence can only reduce $t$, hence it is
    finite.  Thus, $\oc t$ strongly normalises.
    Furthermore, if $\oc t \lras \oc t'$, then $t \lra^* t'$.  By CR2, $t' \in \llbracket A
    \rrbracket$. 
  \end{proof}

  \begin{lemma}[Adequacy of $\elimone$]
  \label{lem:elimone}
  If $t_1 \in \llbracket \one \rrbracket$ and $t_2 \in \llbracket C \rrbracket$, 
  then $\elimone(t_1,t_2) \in \llbracket C \rrbracket$.
  \end{lemma}

  \begin{proof}
  The proof-terms $t_1$ and $t_2$ strongly normalise.  We prove, by
  induction on $|t_1| + |t_2|$, that $\elimone(t_1,t_2)
  \in \llbracket C \rrbracket$.  Using {CR3}, we only
  need to prove that every of its one step reducts is in $\llbracket C
  \rrbracket$.  If the reduction takes place in $t_1$ or $t_2$, then we
  apply {CR2} and the induction hypothesis.

  Otherwise, the proof-term $t_1$ is $a.\star$ and the
  reduct is $a \dotprod t_2$. We conclude with Lemma~\ref{lem:prod}. 
  \end{proof}

  \begin{lemma}[Adequacy of application]
  \label{lem:application}
  If $t_1 \in \llbracket A \multimap B \rrbracket$ and $t_2 \in
  \llbracket A \rrbracket$, then $t_1~t_2 \in \llbracket B
  \rrbracket$.
  \end{lemma}

  \begin{proof}
  The proof-terms $t_1$ and $t_2$ strongly normalise. We prove, by induction
  on $|t_1| + |t_2|$, that $t_1~t_2 \in \llbracket B \rrbracket$. Using
  {CR3}, we only need to prove that every of its one
  step reducts is in $\llbracket B \rrbracket$.  If the reduction takes
  place in $t_1$ or in $t_2$, then we apply {CR2}
  and the induction hypothesis.

  Otherwise, the proof-term $t_1$ has the form $\lambda x^C.u$ and the reduct
  is $(t_2/x)u$.  As $\lambda x^C.u \in \llbracket A \multimap B
  \rrbracket$, we have $(t_2/x)u \in \llbracket B \rrbracket$. 
  \end{proof}

  \begin{lemma}[Adequacy of $\elimtens$]
  \label{lem:elimtens}
  If $t_1 \in \llbracket A \otimes B \rrbracket$,
  for all $u$ in $\llbracket A \rrbracket$,
  for all $v$ in $\llbracket B \rrbracket$,
  $(u/x,v/y)t_2 \in \llbracket C \rrbracket$, 
  then $\elimtens(t_1, x^D y^E.t_2) \in \llbracket C \rrbracket$.
  \end{lemma}

  \begin{proof}
  By Lemma~\ref{lem:Var}, $x \in \llbracket A \rrbracket$ and $y \in
  \llbracket B \rrbracket$, thus $t_2 = (x/x,y/y)t_2 \in \llbracket C
  \rrbracket$.  Hence, $t_1$ and $t_2$ strongly normalise.  We prove, by
  induction on $|t_1| + |t_2|$, that $\elimtens(t_1,
  x^D y^E.t_2) \in \llbracket C \rrbracket$.  Using
  {CR3}, we only need to prove that every of its one
  step reducts is in $\llbracket C \rrbracket$.  If the reduction takes
  place in $t_1$ or $t_2$, then we apply {CR2} and the
  induction hypothesis. Otherwise, either:
  \begin{itemize}
  \item The proof-term $t_1$ has the form $w_2 \otimes w_3$ and the reduct is
    $(w_2/x,w_3/y)t_2$. As
    $w_2 \otimes w_3 \in \llbracket A \otimes B \rrbracket$, we
    have $w_2 \in \llbracket A \rrbracket$
  and $w_3 \in \llbracket B \rrbracket$. 
    Hence, $(w_2/x,w_3/y)t_2 \in
    \llbracket C \rrbracket$.

  \item The proof-term $t_1$ has the form $t_1' \plus t''_1$ and the
    reduct is\\ $\elimtens(t'_1, x^D y^E.t_2) \plus
    \elimtens(t''_1, x^D y^E.t_2)$. As $t_1
    \lra t'_1$ with an ultra-reduction rule, we have by
    {CR2}, $t'_1 \in \llbracket A \otimes B
    \rrbracket$.  Similarly, $t''_1 \in \llbracket A \otimes B
    \rrbracket$.  Thus, by induction hypothesis, $\elimtens(t'_1,
    x^D y^E.t_2) \in \llbracket A \otimes B \rrbracket$
    and $\elimtens(t''_1, x^D y^E.t_2) \in \llbracket A
    \otimes B \rrbracket$.  We conclude with Lemma~\ref{lem:sum}.

  \item The proof-term $t_1$ has the form $a \dotprod t_1'$ and the
    reduct is $a \dotprod \elimtens(t'_1, x^D y^E.t_2)$. As $t_1
    \lra t'_1$ with an ultra-reduction rule, we have by
    {CR2}, $t'_1 \in \llbracket A \oplus B
    \rrbracket$.  
    Thus, by induction hypothesis, $\elimtens(t'_1,
    x^D y^E.t_2) \in \llbracket A \otimes B \rrbracket$.
    We conclude with Lemma~\ref{lem:prod}. \qedhere
  \end{itemize}
  \end{proof}

  \begin{lemma}[Adequacy of $\elimzero$]
  \label{lem:elimzero}
  If $t \in \llbracket \zero \rrbracket$, 
  then $\elimzero(t) \in \llbracket C \rrbracket$.
  \end{lemma}

  \begin{proof}
  The proof-term $t$ strongly normalises.  Consider a reduction sequence
  issued from $\elimzero(t)$.  This sequence can only reduce $t$, hence it
  is finite.  Thus, $\elimzero(t)$ strongly normalises.  Moreover, it
  never reduces to an introduction. 
  \end{proof}

  \begin{lemma}[Adequacy of $\elimwith^1$]
  \label{lem:elimwith1}
  If $t_1 \in \llbracket A \with B \rrbracket$
  and, for all $u$ in $\llbracket A \rrbracket$,
  $(u/x)t_2 \in \llbracket C \rrbracket$, 
  then $\elimwith^1(t_1, x^D.t_2) \in \llbracket C \rrbracket$.
  \end{lemma}

  \begin{proof}
  By Lemma~\ref{lem:Var}, $x \in \llbracket A \rrbracket$
  thus $t_2 = (x/x)t_2 \in \llbracket C
  \rrbracket$.  Hence, $t_1$ and $t_2$ strongly normalise.  We prove, by
  induction on $|t_1| + |t_2|$, that $\elimwith^1(t_1, x^D.t_2)
  \in \llbracket C \rrbracket$.  Using {CR3}, we only
  need to prove that every of its one step reducts is in $\llbracket C
  \rrbracket$.  If the reduction takes place in $t_1$ or $t_2$, then we
  apply {CR2} and the induction hypothesis.

  Otherwise, the proof-term $t_1$ has the form $\pair{u}{v}$ and the
  reduct is $(u/x)t_2$.  As $\pair{u}{v} \in \llbracket A
  \with B \rrbracket$, we have $u \in \llbracket A \rrbracket$.
  Hence, $(u/x)t_2 \in \llbracket C \rrbracket$. 
  \end{proof}

  \begin{lemma}[Adequacy of $\elimwith^2$]
  \label{lem:elimwith2}
  If $t_1 \in \llbracket A \with B \rrbracket$ and,
  for all $u$ in $\llbracket B \rrbracket$,
  $(u/x)t_2 \in \llbracket C \rrbracket$, 
  then $\elimwith^2(t_1, x^D.t_2) \in \llbracket C \rrbracket$.
  \end{lemma}

  \begin{proof}
  Similar to the proof of Lemma~\ref{lem:elimwith1}. 
  \end{proof}

  \begin{lemma}[Adequacy of $\elimplus$]
  \label{lem:elimplus}
  If $t_1 \in \llbracket A \oplus B \rrbracket$, for all $u$ in $\llbracket A
  \rrbracket$, $(u/x)t_2 \in \llbracket C \rrbracket$, and, for all $v$
  in $\llbracket B \rrbracket$, $(v/y)t_3 \in \llbracket C \rrbracket$,
  then $\elimplus(t_1, x^D.t_2, y^E.t_3) \in \llbracket C \rrbracket$.
  \end{lemma}

  \begin{proof}
  By Lemma~\ref{lem:Var}, $x \in \llbracket A \rrbracket$, thus $t_2 =
  (x/x)t_2 \in \llbracket C \rrbracket$. In the same way, $t_3 \in
  \llbracket C \rrbracket$.  Hence, $t_1$, $t_2$, and $t_3$ strongly
  normalises.  We prove, by induction on $|t_1| + |t_2| + |t_3|$,
  that $\elimplus(t_1, x^D.t_2,
  y^E.t_3) \in \llbracket C \rrbracket$.  Using {CR3}, we
  only need to prove that every of its one step reducts
  is in $\llbracket C \rrbracket$.  If the reduction takes place in
  $t_1$, $t_2$, or $t_3$, then we apply {CR2} and
  the induction hypothesis. Otherwise, either:
  \begin{itemize}
  \item The proof-term $t_1$ has the form $\inl(w_2)$ and the reduct is
    $(w_2/x)t_2$. As $\inl(w_2) \in \llbracket A \oplus B \rrbracket$, we
    have $w_2 \in \llbracket A \rrbracket$.  Hence, $(w_2/x)t_2 \in
    \llbracket C \rrbracket$.

  \item The proof-term $t_1$ has the form $\inr(w_3)$ and the reduct is
    $(w_3/x)t_3$. As $\inr(w_3) \in \llbracket A \oplus B \rrbracket$, we
    have $w_3 \in \llbracket B \rrbracket$.  Hence, $(w_3/x)t_3 \in
    \llbracket C \rrbracket$.

  \item The proof-term $t_1$ has the form $t_1' \plus t''_1$ and the
    reduct is $\elimplus(t'_1, x^D.t_2, y^E.t_3) \plus
    \elimplus(t''_1, x^D.t_2, y^E.t_3)$. As $t_1
    \lra t'_1$ with an ultra-reduction rule, we have by
    {CR2}, $t'_1 \in \llbracket A \oplus B
    \rrbracket$.  Similarly, $t''_1 \in \llbracket A \oplus B
    \rrbracket$.  Thus, by induction hypothesis, $\elimplus(t'_1,
    x^D.t_2, y^E.t_3) \in \llbracket A \oplus B \rrbracket$
    and $\elimplus(t''_1, x^D.t_2, y^E.t_3) \in \llbracket A
    \oplus B \rrbracket$.  We conclude with Lemma~\ref{lem:sum}.

  \item The proof-term $t_1$ has the form $a \dotprod t_1'$ and the
    reduct is $a \dotprod \elimplus(t'_1, x^D.t_2, y^E.t_3)$. As $t_1
    \lra t'_1$ with an ultra-reduction rule, we have by
    {CR2}, $t'_1 \in \llbracket A \oplus B
    \rrbracket$.  
    Thus, by induction hypothesis, $\elimplus(t'_1,
    x^D.t_2, y^E.t_3) \in \llbracket A \oplus B \rrbracket$.
    We conclude with Lemma~\ref{lem:prod}. \qedhere
  \end{itemize}
  \end{proof}

\begin{lemma}[Adequacy of $\elimbang$]\label{lem:elimbang}
  If $t_1 \in \llbracket \oc A \rrbracket$
  and, for all $u$ in $\llbracket A \rrbracket$,
  $(u/x)t_2 \in \llbracket B \rrbracket$, 
  then $\elimbang(t_1, x^C.t_2) \in \llbracket B \rrbracket$.
\end{lemma}

\begin{proof}
  By Lemma~\ref{lem:Var}, $x \in \llbracket A \rrbracket$
  thus $t_2 = (x/x)t_2 \in \llbracket B
  \rrbracket$.  Hence, $t_1$ and $t_2$ strongly normalise.  We prove, by
  induction on $|t_1| + |t_2|$, that $\elimbang(t_1, x^C.t_2)
  \in \llbracket B \rrbracket$.  Using CR3, we only
  need to prove that every of its one step reducts is in $\llbracket B
  \rrbracket$.  If the reduction takes place in $t_1$ or $t_2$, then we
  apply CR2 and the induction hypothesis.

  Otherwise, the proof-term $t_1$ has the form $\oc u$ and the
  reduct is $(u/x)t_2$.  As $\oc u \in \llbracket \oc A \rrbracket$, we have $u \in \llbracket A \rrbracket$.
  Hence, $(u/x)t_2 \in \llbracket B \rrbracket$. 
\end{proof}

\subsection{Theorem~\ref{thm:introductions} (Introduction)}\label{proof:introductionthm}
\introductions*
\begin{proof}
  By induction on $t$.

  We first remark that, as the proof-term $t$ is closed, it is not a
  variable. Then, we prove that it cannot be an elimination.
  \begin{itemize}
    \item If $t = \elimone(u,v)$, then $u$ is a closed
      irreducible proof-term of $\one$, hence, by induction
      hypothesis, it has the form $a.\star$
      and the proof-term $t$ is reducible.

    \item If $t = u~v$, then $u$ is a closed  irreducible proof-term of $B
      \multimap A$, hence, by induction hypothesis, it has the form
      $\lambda \abstr{x:B}u_1$ and the proof-term $t$ is reducible.


    \item If $t = \elimtens(u,x^B y^C.v)$, then $u$ is a closed
      irreducible proof-term of $B \otimes C$, hence, by induction hypothesis, it
      has the form $u_1 \otimes u_2$, $u_1 \plus u_2$, or $a \dotprod
      u_1$ and the proof-term $t$ is reducible.

    \item If $t = \elimzero(u)$, then $u$ is a closed irreducible proof-term of
      $\zero$ and, by induction hypothesis, no such proof-term exists.

    \item If $t = \elimwith^1(u,x^B.v)$, then $u$ is a closed
      irreducible proof-term of $B \with C$, hence, by induction
      hypothesis, it has the form $\pair{u_1}{u_2}$
      and the proof-term $t$ is reducible.

    \item If $t = \elimwith^2(u,x^C.v)$, then $u$ is a closed
      irreducible proof-term of $B \with C$, hence, by induction
      hypothesis, it has the form $\pair{u_1}{u_2}$
      and the proof-term $t$ is reducible.

    \item If $t = \elimplus(u,x^B.v,y^C.w)$, then $u$ is a closed
      irreducible proof-term of $B \oplus C$, hence, by induction hypothesis, it
      has the form $\inl(u_1)$, $\inr(u_1)$, $u_1 \plus u_2$, or $a \dotprod
      u_1$ and the proof-term $t$ is reducible.

    \item If $t = \elimbang(u,x^B.v)$, then $u$ is a closed
      irreducible proof-term of $\oc B$, hence, by induction
      hypothesis, it has the form $\oc u_1$
      and the proof-term $t$ is reducible.


  \end{itemize}

  Hence, $t$ is an introduction, a sum, or a product.

  \begin{itemize}
    \item It $t$ has the form $a.\star$, then $A$ is $\one$. 
    \item If it has the form $\lambda x^B.u$, then $A$ has the form $B \multimap C$.
    \item If it has the form $u \otimes v$, then $A$ has the form $B \otimes C$.
    \item If it is $\langle \rangle$, then $A$ is $\top$.
    \item If it has the form $\pair{u}{v}$, then $A$ has the form $B \with C$.
    \item If it has the form $\inl(u)$ or $\inr(u)$, then $A$ has the form $B \oplus C$.
    \item If it has the form $\oc u$, then $A$ has the form $\oc B$.
  \end{itemize}
  We prove that, if it has the form $u \plus v$ or $a \dotprod u$, $A$ has
  the form $B \otimes C$ or $B \oplus C$.
  \begin{itemize}
    \item 
      If $t = u \plus v$, then the proof-terms $u$ and $v$ are two closed and irreducible proof-terms of $A$.
      \begin{itemize}
	\item     If $A = \one$ then, by induction hypothesis, they both have the form $a.\star$ and the proof-term $t$ is reducible.
	\item If $A$ has the form $B \multimap C$ then, by induction hypothesis, they are both abstractions and the proof-term $t$ is reducible.
	\item If $A = \top$ then, by induction hypothesis, they both are $\langle \rangle$ and the proof-term $t$ is reducible.
	\item If $A = \zero$ then, they are irreducible proof-terms of $\zero$ and, by induction hypothesis, no such proof-terms exist.
	\item If $A$ has the form $B \with C$, then, by induction hypothesis, they are both pairs and the proof-term $t$ is reducible.  Hence, $A$ has the form $B \otimes C$ or $B \oplus C$.
	\item If $A$ has the form $\oc B$, then, by induction hypothesis, they both have exponential connectives in head position, and the proof-term $t$ is reducible.
      \end{itemize}

    \item
      If $t = a \dotprod u$, then the proof-term $u$ is a closed and irreducible proof-term of $A$.
      \begin{itemize}
	\item If $A = \one$ then, by induction hypothesis, $u$ has the form $a.\star$ and the proof-term $t$ is reducible.
	\item If $A$ has the form $B \multimap C$ then, by induction hypothesis, it is an abstraction and the proof-term $t$ is reducible.
	\item If $A = \top$ then, by induction hypothesis, it is $\langle \rangle$ and the proof-term $t$ is reducible.
	\item If $A = \zero$ then, it is an irreducible proof-term of $\zero$ and, by induction hypothesis, no such proof-term exists.
	\item If $A$ has the form $B \with C$, then, by induction hypothesis, it is a pair and the proof-term $t$ is reducible.  Hence, $A$ has the form $B \otimes C$ or $B \oplus C$.
	\item If $A$ has the form $\oc B$, then, by induction hypothesis, it has an exponential connective in head position and the proof-term $t$ is reducible.\qedhere
      \end{itemize}
  \end{itemize}
\end{proof}

