\subsection{Technical lemmas to prove Soundness}\label{proof:technical}

Lemmas \ref{lem:substitutionaux} to \ref{lem:eprop} are auxiliary results used in the proofs of substitution and soundness (Lemmas \ref{lem:nonlinearsubstitution} and \ref{lem:linearsubstitution}, and Theorem \ref{thm:soundness}).

\begin{lemma}
	\label{lem:substitutionaux}
	  Let $g: \bigotimes_{i=1}^n \oc A_i \otimes I \to D$ and let $f$ such that:
	  \begin{align*}
		  f =& \bigotimes_{i=1}^n \oc A_i
		  \xrightarrow{d_{A_1, \dots, A_n}}
		  \bigotimes_{i=1}^n \oc A_i \otimes \bigotimes_{i=1}^n \oc A_i
		  \xrightarrow{\delta_{A_1, \dots, A_n} \otimes id}
		  \oc (\bigotimes_{i=1}^n \oc A_i) \otimes 
		  \bigotimes_{i=1}^n \oc A_i\\
		  &\xrightarrow{\oc (\rho^{-1}) \otimes id}
		  \oc (\bigotimes_{i=1}^n \oc A_i \otimes I) \otimes 
		  \bigotimes_{i=1}^n \oc A_i
		  \xrightarrow{\oc g \otimes id}
		  \oc D \otimes
