\end{proof}

\subsection{Adequacy}\label{proof:adequacy}
\semanticsadequacy*
\begin{proof}
  By induction on the size of $A$.
  \begin{itemize}
    \item Let $A = \one$. By Theorems~\ref{thm:SR}, \ref{thm:introductions}, and \ref{thm:ST}, we have $t \lras a.\star$ and $r \lras b.\star$. By Theorem~\ref{thm:soundness}, $\interpretation{t} = \interpretation{a.\star}$ and $\interpretation{r} = \interpretation{b.\star}$. Hence, since $\interpretation{t} = \interpretation{r}$, the following diagram commutes:

    % https://q.uiver.app/#q=WzAsNCxbMCwwLCJcXG9jIEkgXFxvdGltZXMgSSJdLFsyLDAsIlxcb2MgSSJdLFs0LDAsIkkiXSxbNiwwLCJJIl0sWzAsMSwiXFxyaG8iXSxbMSwyLCJlX0kiXSxbMiwzLCJcXG1vbm97YX0iLDAseyJjdXJ2ZSI6LTN9XSxbMiwzLCJcXG1vbm97Yn0iLDIseyJjdXJ2ZSI6M31dXQ==&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[cramped]
	{\oc I \otimes I} && {\oc I} && I && I
	\arrow["\rho", from=1-1, to=1-3]
	\arrow["{e_I}", from=1-3, to=1-5]
	\arrow["{\mono{a}}", curve={height=-18pt}, from=1-5, to=1-7]
	\arrow["{\mono{b}}"', curve={height=18pt}, from=1-5, to=1-7]
\end{tikzcd}\]

Since $e_I \circ \rho \circ \rho^{-1} \circ m_I = id_I$, we have that $\mono{a} = \mono{b}$. Therefore $a=b$, because $\mono{\cdot}$ is a monomorphism, and then $t \equiv r$.

    \item Let $A = B \multimap C$. By Theorems~\ref{thm:SR}, \ref{thm:introductions} and \ref{thm:ST}, we have $t \lras \lambda x^B.t'$ and $r \lras \lambda x^B.r'$. By Theorem~\ref{thm:soundness}, $\interpretation{t} = \interpretation{\lambda x^B.t'}$ and $\interpretation{r} = \interpretation{\lambda x^B.r'}$. Hence, since $\interpretation{t} =\interpretation{r}$, the following diagram commutes:

    % https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[cramped]
	{\oc I \otimes I} && {[\interpretation B \to \oc I \otimes I \otimes \interpretation B]} && {[\interpretation B \to \interpretation C]}
	\arrow["{\eta_{\interpretation B}}", from=1-1, to=1-3]
	\arrow["{[\interpretation B \to \interpretation{t'}]}", curve={height=-18pt}, from=1-3, to=1-5]
	\arrow["{[\interpretation B \to \interpretation{r'}]}"', curve={height=18pt}, from=1-3, to=1-5]
\end{tikzcd}\]

Therefore, we have $\interpretation{t'} = \interpretation{r'}$, by the bijection arising from the adjunction. By Lemma~\ref{lem:linearsubstitution}, we have that for all $w$ such that $\vdash w:B$:
\begin{align*}
  \interpretation{(w/x)t'} &= \interpretation{t'} \circ (id \otimes \interpretation{w}) \circ (id \otimes \sigma) \circ (d_I \otimes id)\\
  \interpretation{(w/x)r'} &= \interpretation{r'} \circ (id \otimes \interpretation{w}) \circ (id \otimes \sigma) \circ (d_I \otimes id)
\end{align*}

Then, $\interpretation{(w/x)t'} = \interpretation{(w/x)r'}$. Hence, by the induction hypothesis, $(w/x)t' \equiv (w/x)r'$. Since this is true for all $w$, we have $\lambda x^B.t' \equiv \lambda x^B.r'$. Therefore, $t \equiv \lambda x^B.t' \equiv \lambda x^B.r' \equiv r$.

    \item Let $A = B \otimes C$. Any elimination context for $t$ and $r$ has the shape $K = K'[\elimtens(\_, x^B y^C.u)]$, where $\varnothing;x^B,y^C \vdash u:D$ with $|D| < |B \otimes C|$. By definition, we have that
    \begin{align*}
      \interpretation{\elimtens(t,x^B y^C.u)} &= \interpretation{u} \circ \sigma \circ (\interpretation{t} \otimes id) \circ \overline d\\
      \interpretation{\elimtens(r,x^B y^C.u)} &= \interpretation{u} \circ \sigma \circ (\interpretation{r} \otimes id) \circ \overline d
    \end{align*}

    $\interpretation{t} = \interpretation{r}$ by hypothesis, therefore $\interpretation{\elimtens(t,x^B y^C.u)} = \interpretation{\elimtens(r,x^B y^C.u)}$. Thus, by the induction hypothesis, we have $\elimtens(t,x^B y^C.u) \equiv \elimtens(r,x^B y^C.u)$.

      Hence,
      \(
	K[t]=K'[\elimtens(t,x^B y^C.u)]\equiv  K'[\elimtens(r,x^B y^C.u)]=K[r]
      \).

      Then, $t\equiv r$.

    \item Let $A = \top$. 
      There is no elimination context ${\_}^\top\vdash K:\one$, then the observational equivalence is vacuously true.

    \item Let $A = \zero$. By Theorems~\ref{thm:SR}, \ref{thm:introductions} and \ref{thm:ST}, this case is not possible.

    \item Let $A = B \with C$. By Theorems~\ref{thm:SR}, \ref{thm:introductions} and \ref{thm:ST}, we have $t \lras \pair{t_1}{t_2}$ and $r \lras \pair{r_1}{r_2}$. By Theorem~\ref{thm:soundness}, $\interpretation{t} = \interpretation{\pair{t_1}{t_2}}$ and $\interpretation{r} = \interpretation{\pair{r_1}{r_2}}$. Hence, since $\interpretation{t} = \interpretation{r}$, the following diagram commutes:

    % https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[cramped]
	{\oc I \otimes I} && {(\oc I \otimes I) \oplus (\oc I \otimes I)} && {\interpretation B \oplus \interpretation C}
	\arrow["\Delta", from=1-1, to=1-3]
	\arrow["{\interpretation{t_1} \oplus \interpretation{t_2}}", curve={height=-18pt}, from=1-3, to=1-5]
	\arrow["{\interpretation{r_1} \oplus \interpretation{r_2}}"', curve={height=18pt}, from=1-3, to=1-5]
\end{tikzcd}\]

Since $\pi_1 \circ (f \oplus g) \circ \Delta = f$, and $\pi_2 \circ (f \oplus g) \circ \Delta = g$, we have that $\interpretation{t_1} = \interpretation{r_1}$ and $\interpretation{t_2} = \interpretation{r_2}$. Hence, by the induction hypothesis, we have $t_1 \equiv r_1$ and $t_2 \equiv r_2$. Therefore, $t \equiv \pair{t_1}{t_2} \equiv \pair{r_1}{r_2} \equiv r$.

    \item Let $A = B \oplus C$. Any elimination context for $t$ and $r$ has the shape $K = K'[\elimplus(\_, x^B.u, y^C.v)]$, where $\varnothing;x^B \vdash u:D$ and $\varnothing;y^C \vdash v:D$ with $|D| < |B \oplus C|$. By definition, we have that
    \begin{align*}
      \interpretation{\elimplus(t, x^B.u, y^C.v)} &= [\interpretation{u},\interpretation{v}] \circ (\sigma \oplus \sigma) \circ dist \circ (\interpretation{t} \otimes id) \circ \overline{d}\\
      \interpretation{\elimplus(r, x^B.u, y^C.v)} &= [\interpretation{u},\interpretation{v}] \circ (\sigma \oplus \sigma) \circ dist \circ (\interpretation{r} \otimes id) \circ \overline{d}
    \end{align*}

    $\interpretation{t} = \interpretation{r}$ by hypothesis, therefore $\interpretation{\elimplus(t, x^B.u, y^C.v)} = \interpretation{\elimplus(r, x^B.u, y^C.v)}$. Thus, by the induction hypothesis, we have $\elimplus(t, x^B.u, y^C.v) \equiv \elimplus(r, x^B.u, y^C.v)$.

      Hence,
      \(
	K[t]=K'[\elimplus(t, x^B.u, y^C.v)]\equiv  K'[\elimplus(r, x^B.u, y^C.v)]=K[r]
      \).

      Then, $t\equiv r$.
    \item Let $A = \oc B$. By Theorems~\ref{thm:SR}, \ref{thm:introductions} and \ref{thm:ST}, we have $t \lras \oc t'$ and $r \lras \oc r'$. By Theorem~\ref{thm:soundness}, $\interpretation{t} = \interpretation{\oc t'}$ and $\interpretation{r} = \interpretation{\oc r'}$. Hence, since $\interpretation{t} = \interpretation{r}$, the following diagram commutes:

    % https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[cramped]
	{\oc I \otimes I} && {\oc I} && {\oc\oc I} && {\oc(\oc I \otimes I)} && {\oc \interpretation B}
	\arrow["\rho", from=1-1, to=1-3]
	\arrow["{\delta_I}", from=1-3, to=1-5]
	\arrow["{\oc(\rho^{-1})}", from=1-5, to=1-7]
	\arrow["{\oc \interpretation{t'}}", curve={height=-18pt}, from=1-7, to=1-9]
	\arrow["{\oc \interpretation{r'}}"', curve={height=18pt}, from=1-7, to=1-9]
\end{tikzcd}\]

Let $h = \oc(\rho^{-1}) \circ \delta_I \circ \rho$, then $(\oc I \otimes I, h: \oc I \otimes I \to \oc(\oc I \otimes I))$ is a coalgebra because the following diagrams commute:
% https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[ampersand replacement=\&,cramped]
	{\oc I \otimes I} \&\& {\oc I} \&\& {\oc\oc I} \&\& {\oc(\oc I \otimes I)} \\
	\\
	\&\&\&\& {\oc I} \&\& {\oc I \otimes I}
	\arrow["{\rho_{\oc I}}", from=1-1, to=1-3]
	\arrow[equals, from=1-1, to=3-7, rounded corners, to path={(\tikztostart.south) |- ([yshift=-2ex]\tikztotarget.south) -- (\tikztotarget.south)}]
	\arrow["{\delta_I}", from=1-3, to=1-5]
	\arrow[""{name=0, anchor=center, inner sep=0}, equals, from=1-3, to=3-5]
	\arrow["{\oc(\rho^{-1}_{\oc I})}", from=1-5, to=1-7]
	\arrow["{\varepsilon_{\oc I}}"{description}, dashed, from=1-5, to=3-5]
	\arrow["{(3)}"{description}, draw=none, from=1-5, to=3-7]
	\arrow["{\varepsilon_{\oc I \otimes I}}", from=1-7, to=3-7]
	\arrow["{\rho^{-1}_{\oc I}}"{description}, dashed, from=3-5, to=3-7]
	\arrow["{(1)}"{description}, curve={height=18pt}, draw=none, from=1-1, to=0]
	\arrow["{(2)}"{description}, draw=none, from=1-5, to=0]
\end{tikzcd}\]
(1) commutes trivially, (2) commutes because $(\oc,\varepsilon,\delta)$ is a comonad and (3) commutes by naturality of $\varepsilon$.
% https://q.uiver.app/#&macro_url=https%3A%2F%2Fgist.githubusercontent.com%2Fmivnisky%2Ff508b096a7b5ccc39bc9f47973d7cada%2Fraw%2F74cd11f2bf8e73032a5eadee050317b53d4d616d%2Fgistfile1.txt
\[\begin{tikzcd}[ampersand replacement=\&,cramped]
	{\oc I \otimes I} \&\& {\oc I} \&\& {\oc\oc I} \&\& {\oc(\oc I \otimes I)} \\
	\\
	{\oc I} \\
	\\
	{\oc\oc I} \\
	\\
	{\oc(\oc I \otimes I)} \&\& {\oc\oc I} \&\& {\oc\oc\oc I} \&\& {\oc\oc(\oc I \otimes I)}
	\arrow["{\rho_{\oc I}}", from=1-1, to=1-3]
	\arrow["{\rho_{\oc I}}"', from=1-1, to=3-1]
	\arrow["{\delta_I}", from=1-3, to=1-5]
	\arrow["{\oc(\rho^{-1}_{\oc I})}", from=1-5, to=1-7]
	\arrow[""{name=0, anchor=center, inner sep=0}, "{\delta_{\oc I}}"{description}, dashed, from=1-5, to=7-5]
	\arrow[""{name=1, anchor=center, inner sep=0}, "{\delta_{\oc I \otimes I}}", from=1-7, to=7-7]
	\arrow[equals, from=3-1, to=1-3]
	\arrow[""{name=2, anchor=center, inner sep=0}, "{\delta_I}"', from=3-1, to=5-1]
	\arrow["{\oc(\rho^{-1}_{\oc I})}"', from=5-1, to=7-1]
	\arrow[equals, from=5-1, to=7-3]
	\arrow["{\oc\rho_{\oc I}}"', from=7-1, to=7-3]
	\arrow["{\oc \delta_I}"', from=7-3, to=7-5]
	\arrow["{\oc\oc(\rho^{-1}_{\oc I})}"', from=7-5, to=7-7]
	\arrow["{(5)}"{description}, draw=none, from=1, to=0]
	\arrow["{(4)}"{description}, draw=none, from=2, to=0]
\end{tikzcd}\]
(4) commutes because $(\oc, \varepsilon, \delta)$ is a comonad and (5) commutes by naturality of $\delta$.

Then, by Theorem~\ref{thm:adjunction} there is an adjunction between $\abscat$ and its category of coalgebras such that the component of the unit of adjunction for $(\oc I \otimes I,h)$ is given by $\eta_{(\oc I \otimes I,h)} = h$. This implies that $\interpretation{t'} = \interpretation{r'}$ because the commuting diagram asserts the equality of the application of the adjunction isomorphism to $\interpretation{t'}$ and $\interpretation{r'}$. By the induction hypothesis we have $t' \equiv r'$, and therefore $t \equiv \oc t' \equiv \oc r' \equiv r$.\qedhere
  \end{itemize}
\end{proof}

