    % \item[\textbf{\emph{(ii)}}] $l_z^i (\bOmega, \gamma)$ is $\ell_f$-Lipschitz continuous for all $z$.
    % \end{itemize}
    Then, the following upper bound holds for Algorithm 1:   %for $\{ \bOmega_t \}, \{ \gamma_t \}$ in Algorithm \ref{dynamic weight optimization}, it holds that
    \begin{eqnarray}
        \cE_C \le \frac{4}{\eta T} \!+\! 6 \sqrt{3 \ell'_{f}\ell_{f}^2\frac{\beta}{\eta}} \!+\! 3\eta \ell_f^4.
        \label{eq_Theorem1_Ec}
    \end{eqnarray}
    %     \frac{1}{T}\sum_{t=0}^{T} \mathbb{E}[\lVert d(\bOmega, \gamma) - d(\bOmega, \gamma^*) \rVert^2]
    %     \cE_c \le \frac{4}{\eta T} \!+\! 6 \sqrt{3 \ell'_{f}\ell_{f}^2\frac{\beta}{\eta}} \!+\! 3\eta \ell_f^4. \nonumber
    % \end{equation}
\end{theorem}
\begin{IEEEproof}
Due to the limit of space, we provide a sketch of proof of the above theorem as follows. According to Lemma 18 in \cite{chen2023three}, there always exists a positive constant $\rho$ such that the following holds
\begin{eqnarray}
    \cE_C \le \rho + \frac{4}{\eta T}(1+\rho^{-1}\beta T C_1) + \eta C_2,
\end{eqnarray}
where $C_{1} =\frac{1}{T} \sum_{t=0}^{T-1} \mathbb{E}\|\nabla L(\bOmega_{t+1}) + \nabla L(\bOmega_{t})\| \cdot \| \sum_{i\in \{a, p , n\}} \nabla l^i(\bOmega_t, \gamma_{t+1}^i, {d^i_{t,3}})\|$ and $C_{2} = \frac{1}{T} \sum_{t=0}^{T-1} \mathbb{E} \| \sum_{i\in \{a, p , n\}} \nabla l^i(\bOmega_t, \gamma_t^i, {d^i_{t,1}})^{\top} \nabla l^i(\bOmega_t, \gamma_t^i, {d^i_{t,2}}) \|^{2}$.
% \begin{eqnarray}
% && C_{1} =\frac{1}{T} \!\! \sum\limits_{t=0}^{T-1} \! \mathbb{E}\|\nabla L(\bOmega_{t+1}) \!+\!\! \nabla L(\bOmega_{t})\| %\nonumber \\
%     \cdot \| \!\!\!\!\!\!\! \sum\limits_{i\in \{a, p , n\}} \!\!\!\!\!\!\! \nabla l^i(\bOmega_t, \gamma_{t+1}^i, {d^i_{t,3}})\|, \nonumber \\
% && C_{2} = \frac{1}{T} \sum\limits_{t=0}^{T-1} \mathbb{E} \| \!\!\!\! \sum\limits_{i\in \{a, p , n\}} \!\!\!\! \nabla l^i(\bOmega_t, \gamma_t^i, {d^i_{t,1}})^{\top} \nabla l^i(\bOmega_t, \gamma_t^i, {d^i_{t,2}}) \|^{2}. \nonumber
% \end{eqnarray}

According to the Lipschitz property, $C_1$ and $C_2$ are bounded by $6\ell'_{f}\ell_{f}$ and $3\ell_{f}^2$, respectively. By setting $\rho = 2 \sqrt{3 \beta \ell'_{f}\ell_{f}^2/\eta}$, we can obtain the result in (\ref{eq_Theorem1_Ec}). % Theorem \ref{Theorem_UpperBoundCError}.
