\begin{theorem}%[Optimization Error]
\label{Theorem_UpperBoundGError}
Suppose the Frobenius norm of the summation of gradients of all agents is upper bounded by constant, i.e, $\mathbb{E}[\| \sum_{i\in \{a, p, n\}} \gamma^i \nabla l^i_m (\bOmega_m, \cD^i) \|_\text{F}^2] \le U^2$ for $U$ is a constant. Then, the G-error of Algorithm 1 is upper bounded by $\cE_G \le \cO(T^{\frac{1}{2}}D^{-\frac{1}{2}})$.
\end{theorem}

\begin{IEEEproof}
