					\node[below right of=C] (D2) {$b$};
					\node[right of=D1] (E1) {$a$};
					\node[right of=D2] (E2) {$b$};

					\path[shorten <= 5pt, line width=0.1pt]
					(A.center) edge node {} (B1.center)
					(A.center) edge node {} (B2.center)
					(B1.center) edge node {} (C.center)
					(B2.center) edge node {} (C.center)
					(C.center) edge node {} (D1.center)
