	\subsection{Contexts}

	\begin{definition}[Multi-contexts]
		For $m \in \integers^*$, let $\Xi = \{\square_1, \dots, \square_m\}$ be a set of $m$ distinct letters such that $\Xi \cap \Sigma = \emptyset$.
		The set of \emph{$m$-contexts} $\Ct{m}$ is the subset of $\mathrm{SP}(\Sigma \cup \Xi)$ of pomsets containing exactly one element labelled by~$\square_j$ for all $j \in \{1, \ldots, m\}$.
	\end{definition}

	Given $c \in \Ct{m}$ and $w_1, \dots, w_m \in \SP$, we denote by $c[w_1, \dots, w_m]$ the pomset where $\square_j$ has been replaced by $w_j$.
	Intuitively, a $m$-context is a pomset pattern featuring $\square_j$ placeholder symbols that can be replaced by pomsets.
	We write $\SP = \Ct{0}$.

	We simply call 1-contexts \emph{contexts}, and always denote their placeholder symbol $\square$.
	Pomset contexts are called $\square$-terms in \cite{lodaya98kleene,LW98:Algebra,LW00:sp,lodaya01kleene}, but the symbol $\xi$ is used instead of $\square$.
	Given $c_1, c_2 \in \Ct{1}$, $c_1[c_2] \in \Ct{1}$ stands for the context obtained by replacing $\square$ with $c_2$ in $c_1$.
	$c_2$ is then said to be a \emph{subcontext} of $c_1[c_2]$.
	For $w \in \SP$, a \emph{split} of $w$ is a pair $(c, z) \in \Co \times \SP$ such that $w = c[z]$.
	Note that $z$ is a subpomset of $w$.
	Finally, given $C \subseteq \Ct{1}$ and $A \subseteq \SP \cup \Ct{1}$, we define the set $C[A] = \{c[z] \mid c \in C, z \in A\}$. 		

	Given a pomset recognizer $\PR = (M, \odot, \obar, \neut, i, F)$, note that $\PR(w_1) = \PR(w_2)$ does not imply that for all $c \in \Ct{1}$, $\PR(c[w_1]) = \PR(c[w_2])$.
	Indeed, it might be that $\eval(w_1), \eval(w_2) \in F$ but $\eval(w_1) \neq \eval(w_2)$: $w_1$ and $w_2$ lead to different accepting states, thus potentially yielding a different result whenever inserted in $c$ then evaluated in $\PR$.
	As a consequence, $\eval(c[w_1])$ may differ from $\eval(c[w_2])$. However, the following result holds:

	\begin{lemma}[Freeness of PRs~{\cite[Lem. 29]{DBLP:conf/fossacs/HeerdtKR021}}]
		\label{lem:free_context}
		For all $w_1, w_2 \in \SP$, 
		if $\eval(w_1) = \eval(w_2)$, then for all $c \in \Ct{1}$, $\eval(c[w_1]) = \eval(c[w_2])$.
	\end{lemma}	

