	\subsection{Inducing a refinement}

	Algorithm \ref{algo:handle_ce} characterizes $\Llambda$:
	it relies on Algorithm \ref{algo:find_ebp} to find a representative of a new component $p$ and a matching distinguishing context $c$, but does \textbf{not} use $c$ to immediately refine $\B_p$.
	Indeed, $c$ is of arbitrary size, being inferred from an arbitrarily long counter-example;
	an overly large context in $\C$ would weight down future membership queries.

	Instead, it merely expands $p$ (Line \ref{algo:handle_ce:new_component}) and relies only on Algorithms \ref{algo:make_consistent} and \ref{algo:make_assoc} to refine $\B$ and $\Hyp$ (Lines \ref{algo:handle_ce:consistency_loop_start} and \ref{algo:handle_ce:consistency_loop_end}), therefore keeping $\C$ closed by Property~\ref{prop:c_subclosed}.
	Fixing a consistency defect may result in an associativity defect appearing and vice versa, hence the loop.

	Should a lack of associativity or consistency defects prevents a new component for $p$ from being refined, Algorithm~\ref{algo:handle_ce} also adds $c[p]$ and $c[p']$ to a counter-example pool $\ce$ it maintains (Line~\ref{algo:handle_ce:refine_later}) for any representative $p' \in \as_\Hyp(p)$ in order to guarantee that $p$ and $p'$ are eventually distinguished (see Property~\ref{prop:sharp}).
	By Theorem~\ref{th:always_refine}, this loop eventually depletes $\ce$ and ends.

	\begin{algorithm}
		\caption{$\mathtt{HandleCE}(w)$ where $w \in \SPplus$ is such that $\Hyp(w) \neq \Mod(w)$}
		\label{algo:handle_ce}
		\begin{algorithmic}[1]
			\State $\ce \gets \{w\}$
			\While{$\exists u \in \ce, \Mod(u) \neq \Hyp(u)$} \label{algo:handle_ce:while_cond}
				\State $(c, p) \gets \mathtt{FindEBP}(\square, u)$
				\State $\ce \gets \ce \cup \{c[p]\} \cup \{c[p'] \mid p' \in \as_\Hyp(p)\}$ \label{algo:handle_ce:refine_later}
				\State $\mathtt{Expand}(p)$ \label{algo:handle_ce:new_component}
				\Repeat \label{algo:handle_ce:consistency_loop_start}
				\Until{$\mathtt{MakeConsistent}() \land \mathtt{MakeAssoc}()$} \label{algo:handle_ce:consistency_loop_end}
				\State $\Hyp \gets \mathtt{BuildHypothesis}(S, \B)$	\label{algo:handle_ce:build_hyp}	
			\EndWhile
		\end{algorithmic}
	\end{algorithm}


	\subsection{The main loop}

	Algorithm \ref{algo:main} first initializes the pack of components $\B$ and the hypothesis $\Hyp$ by expanding the empty pomset $\varepsilon$.
	There are no consistency and associativity defects to fix that early due to the first iteration of $\B$ having at most two classes.

	It then submits $\Hyp$ to the teacher.
	If the equivalence query returns a counter-example $w$, it then proceeds to apply Algorithm \ref{algo:handle_ce} to identify new components and refine $\Hyp$ accordingly.
	Otherwise, a model $\Hyp$ equivalent to $\Mod$ has been learnt and the algorithm returns $\Hyp$.

	Lines \ref{algo:main:fix_comp_start} and \ref{algo:main:fix_comp_end} guarantee that $\Hyp$ is compatible before submitting an equivalence query.
	Note that this compatibility test is free (although the counter-example handling is obviously not) due to the membership query $\Mod(c[s])$ having already been performed during either the sifting of $s$ through $\D$ or the refinement of $\B_s$.

	\begin{algorithm}[H]
		\caption{$\mathtt{Learn}()$}
		\label{algo:main}
		\begin{algorithmic}[1]
			\State $S, \B, \D \gets \emptyset, \emptyset, \mathtt{Tree}(\square)$
			\State $\mathtt{Expand}(\varepsilon)$			
			\State $\Hyp \gets \mathtt{BuildHypothesis}(S, \B)$  \label{algo:main:first_hyp}
			\While{$\exists w \in \SP$, $\Hyp(w) \neq \Mod(w)$} \label{algo:main:find_ce}
				\State $\mathtt{HandleCE}(w)$ \label{algo:main:handle_ce}
				\While{$\exists B \in \B$, $\exists s \in B$, $\exists c \in \C_B$, $\Hyp(c[s]) \neq \Mod(c[s])$} \label{algo:main:fix_comp_start}
					\State $\mathtt{HandleCE}(c[s])$ \label{algo:main:fix_comp_end}
				\EndWhile
			\EndWhile
			\State \Return \Hyp
		\end{algorithmic}
	\end{algorithm}



	\section{Termination, Correctness, and Complexity}	


	\subsection{Properties of the hypothesis}

	$\Llambda$ \cite{DBLP:conf/birthday/HowarS22} on finite automata maintains a prefix-closed set of access sequences and a suffix-closed set of distinguishing suffixes.
	We show that similar results hold on pomsets as well.

	\begin{property}[Closedness of access sequences]
		\label{prop:s_subclosed}
		$S$ is subpomset-closed.
	\end{property}

	\begin{proof}
		With the exception of $\varepsilon$, new elements of $S$ are only ever added by promoting elements of $S^+$ (Line~\ref{algo:expand:init_end} of Algorithm~\ref{algo:expand}, Lines~\ref{algo:refine:b0_no_as} and \ref{algo:refine:b1_no_as} of Algorithm~\ref{algo:refine}, Line~\ref{algo:handle_ce:new_component} of Algorithm~\ref{algo:handle_ce});
		$S^+$ itself is inductively defined as the union of $\Sigma$ and the composition of elements of $S$.
	\end{proof}

	Similarly, $S \cup S^+$ is subpomset-closed.
	We show below that an associative, consistent, and compatible $(\B, S, \D)$ induces a minimal hypothesis $\Hyp$.

	\begin{lemma}[Reachability of the hypothesis]
		\label{lem:reach}
		An associative, consistent $(\B, S, \D)$ induces a hypothesis $\Hyp$ such that:
		\begin{enumerate*}
			\item $\eval_\Hyp(s) = \B_s$ for all $s \in S \cup S^+$,
			\item $\Hyp$ is reachable.
		\end{enumerate*}
	\end{lemma}

	\begin{proof}
		$S \cup S^+$ being subpomset closed, we can rely on a proof by induction on $s$ to prove that for any $s \in S \cup S^+$, $\eval_\Hyp(s) = \B_s$.
		\begin{description}
			\item[Base case.] $\eval_H(\varepsilon) = i_\Hyp(\varepsilon) = \neut_\Hyp = \B_\varepsilon$ and, for any $a \in \Sigma$, $\eval_\Hyp(a) = i_\Hyp(a) = \B_a$ by definition of the hypothesis $\Hyp$.

			\item[Inductive case.] 	Now, let $s_1 \circ s_2 \in S \cup S^+$ for some $\circ \in \operators$;
			$S \cup S^+$ being subpomset-closed, $s_1, s_2 \in S \cup S^+$.
			By induction hypothesis, $\eval_H(s_i) = \B_{s_i}$ for $i \in \{1, 2\}$.
			Then $\eval_\Hyp(s_1 \circ s_2) = \eval_\Hyp(s_1) \circ_\Hyp \eval_\Hyp(s_2) = \B_{s_1} \circ_\Hyp \B_{s_2} = \B_{s_1 \circ s_2}$ by definition of $\Hyp$ and consistency of $\B$. Thus \textbf{1.} holds.
		\end{description}
		\textbf{2.} is a direct consequence of $\eval_\Hyp(s) = \B_s$ for any $s \in S$.
	\end{proof}

	\begin{lemma}[Partial compatibility]
		\label{lem:s_splus_compatibility}
		An associative, consistent $(\B, S, \D)$ induces a $(S \cup S^+)$-compatible hypothesis $\Hyp$.
	\end{lemma}

	\begin{proof}
		By Lemma~\ref{lem:reach}, for any $s \in S \cup S^+$, $\eval_\Hyp(s) = \B_s$. By definition of $\Hyp$, $\Hyp(s) = 1 \iff \eval_\Hyp(s) \in F_\Hyp \iff \B_s \in F_\Hyp \iff \forall s' \in \B_s, \Mod(s') = 1$. Thus, $\Hyp(s) = \Mod(s)$.
	\end{proof}

	\begin{property}[Closedness of distinguishing contexts]
		\label{prop:c_subclosed}
		$\C$ is such that, for any $c \in \C$, either $c = \square$ or there exist $c' \in \C$, $s \in S \setminus \{\varepsilon\}$, and $\circ \in \operators$ such that $c = c'[\square \circ s]$ or $c = c'[s \circ \square]$.
	\end{property}

	\begin{proof}
		\ref{algo:make_assoc:refine_1}
		With the exception of $\square$, new elements of $\C$ are only ever added by Line~\ref{algo:make_consistent:refine} of Algorithm~\ref{algo:make_consistent} or Lines~\ref{algo:make_assoc:refine_1} and \ref{algo:make_assoc:refine_2} of Algorithm~\ref{algo:make_assoc};
		both additions follow the desired pattern.
	\end{proof}

	\begin{theorem}[Minimality]
		\label{th:minimal}
		Given a hypothesis $\Hyp$ induced from an associative, consistent $(\B, S, \D)$, if $\Hyp$ is compatible, then it is minimal.
	\end{theorem}

	\begin{proof}
		First, by Lemma~\ref{lem:reach}, we know that $\Hyp$ is reachable.
		Let $B_1, B_2 \in \B$ be such that $B_1 \neq B_2$.
		By Invariant~3 of Property~\ref{prop:invariants}, there exist $c \in \C_{B_1} \cap \C_{B_2}$, $s_1 \in B_1$, $s_2 \in B_2$, $\Mod(c[s_1]) \neq \Mod(c[s_2])$.
		$\Hyp$ being compatible, $\Hyp(c[s_1]) = \Mod(c[s_1])$ and $\Hyp(c[s_2]) = \Mod(c[s_2])$.
		Thus, $\Hyp(c[s_1]) \neq \Hyp(c[s_2])$.
		$\Hyp$ is therefore minimal.
	\end{proof}


	\subsection{Using counter-examples to identify new components}

	We assume in this section that $\B$ is a consistent, associative partition from which a hypothesis $\Hyp$ is inferred.
	We first prove that a breaking point can always be found on the leftmost branch of every term of a counter-example, that is, the branch Algorithm \ref{algo:find_ebp} focuses on.
	This branch choice is arbitrary: indeed, the proof of Property~\ref{prop:exists_bp} can be applied to any branch.
	This breaking point may not be effective, i.e. resulting in a new component being discovered.

	\begin{property}
		\label{prop:exists_bp}
		Given a counter-example $w \in \SPplus$ such that $\Hyp(w) \neq \Mod(w)$, given a split $(c, z)$ of $w$ such that $\agree(c, z) = 1$, there exists a breaking point $(c', z')$ or $(c', \circ, z_1, z_2)$ such that $c$ is a subcontext of $c'$ and either $w = c'[z']$ or $w = c'[z_1 \circ z_2]$. 
	\end{property}

	\begin{proof}
		There exists a sequence $(c_0, z_0), \ldots, (c_k, z_k)$ of splits of $w$ such that $(c_0, z_0) = (c, z)$, $z_k \in \Sigma$, and for all $j \in \{0, \ldots, k-1\}$, $c_{j+1} = c_j[\square \circ_j z'_j]$ for some $\circ_j \in \operators$ and $z'_j \in \SPplus$.
		Intuitively, we explore the leftmost sub-branch of a term of $\ST{z}$ and the resulting splits of $w$ until we reach a leaf.
		We define the Booleans $\agree_j = \agree(c_j, z_j)$ for $j \in \{0, \ldots, k\}$.
		By hypothesis, $\agree_0 = 1$.
		Assume that $\exists j \in \{0, \ldots, k\}$, $\agree_j = 0$.
		Therefore, there exists $u \in \{0, \ldots, j\}$, $\agree_u = 1$ but $\agree_{u+1} = 0$, and $(c_u, \circ_u, z_{u+1}, z'_u)$ is a breaking point by definition.
		If no such $u$ exists, then $\agree_k = 1$ and the split $(c_k, b_k)$ is a breaking point.
	\end{proof}

	The following theorem is one of our main results:
	it states that from a counter-example, by looking for breaking points, we can find a representative $p$ of a new component that is distinguished by a context $c'$ from any other representative $p'$ of its current component.

	\begin{theorem}[Correction and termination of Algorithm \ref{algo:find_ebp}]
		\label{th:find_ebp}
		Given $c \in \Co$ and $z \in \SPplus$ such that $\Hyp(c[z]) \neq \Mod(c[z])$ and $\agree(c, z) = 1$, $\mathtt{FindEBP}(c, z)$ terminates and returns a pair $(c', p) \in \Co \times S^+ $ such that $\forall p' \in \as_\Hyp(p)$, $\Mod(c'[p]) \neq \Mod(c'[p'])$.
	\end{theorem}

	\begin{proof}
		We prove this theorem by induction on the depth $\depth{z}$ of the pomset $z$.
		\begin{description}
			\item[Base case.] If $\depth{z} = 0$, $z \in \Sigma$ and $z \in S \cup S^+$ by definition of $S^+$.
			Due to $\agree(c, z) = 1$, for any $p' \in \as_\Hyp(z)$, $\Hyp(c[p']) = \Mod(c[p'])$;
			but $\Hyp(c[z]) \neq \Mod(c[z])$ by hypothesis;
			as a direct consequence, $z \not\in \as_\Hyp(z)$, hence $z \not\in S$, thus $z \in S^+$.
			Moreover, $\Mod(c[z]) \neq \Mod(c[p'])$.
			The base case therefore holds for $c' = c$ and $p = z$.

			\item[Inductive case.] Assume that $\depth{z} = m+1$ for some $m \in \integers$ and that the theorem holds for smaller depths.
			Consider a canonical decomposition $z = z_1 \circ z_2$.

			As long as $(c, \circ, z_1, z_2)$ is not a breaking point, Algorithm \ref{algo:find_ebp} inductively calls $\mathtt{FindEBP}(c[\square \circ z_2], z_1)$ (Lines \ref{algo:find_ebp:find_bp_start} and \ref{algo:find_ebp:find_bp_end}).
			By Property \ref{prop:exists_bp}, one will be found eventually; we assume w.l.o.g. that $(c, \circ, z_1, z_2)$ is a breaking point, as shown by Figure \ref{fig:breaking_point}.

			By Definition \ref{def:bp}, for any $p' \in \as_\Hyp(z)$, $\Hyp(c[p']) = \Mod(c[p'])$ \textbf{(\romannumeral 1)} and there exists $p_1 \in \as_\Hyp(z_1)$, $\Hyp(c[p_1 \circ z_2]) \neq \Mod(c[p_1 \circ z_2])$ \textbf{(\romannumeral 2)}.		
			Let us consider one such $p_1$.
			We perform a case disjunction on predicate $\agree(c[p_1 \circ \square], z_2)$ \textbf{(\romannumeral 3)}.
			\begin{description}
				\item[{$\agree(c[p_1 \circ \square], z_2)$} is false.] Let $p_2 \in \as_\Hyp(z_2)$ such that $\Hyp(c[p_1 \circ p_2]) \neq \Mod(c[p_1 \circ p_2])$.
				By Property \ref{prop:freeness_as}, for any $p' \in \as_\Hyp(z)$, $\Hyp(c[p']) = \Hyp(c[p_1 \circ p_2])$.
				By \textbf{\romannumeral 1}, $\Mod(c[p_1 \circ p_2]) \neq \Mod(c[p'])$  \textbf{(\romannumeral 4)}.	
				Let $p = p_1 \circ p_2 \in S \cup S^+$ and $c' = c$.
				By Property \ref{prop:freeness_as}, $\as_\Hyp(z) = \as_\Hyp(p)$.
				Therefore, by \textbf{\romannumeral 4}, $p \not\in \as_\Hyp(p)$, hence $p \not\in S$ and $p \in S^+$.
				The theorem holds.

				\item[{$\agree(c[p_1 \circ \square], z_2)$} is true.] \textbf{\romannumeral 3} holds.
				Moreover, by \textbf{\romannumeral 2}, $c[p_1 \circ \square][z_2]$ is a counter-example.
				Finally, $\depth{z_2} < \depth{z}$ due to $z_1 \circ z_2$ being a canonical decomposition of $z$.
				We can apply the induction hypothesis to $\mathtt{FindEBP}(c[p_1 \circ \square], z_2)$, and the theorem holds. 
			\end{description}
		\end{description}

		By induction and case disjunction, we have proven that the theorem holds.
	\end{proof}

	\begin{corollary}
		\label{cor:new_component}
		Given a counter-example $w \in \SP$ such that $\Hyp(w) \neq \Mod(w)$, a call to $\mathtt{FindEBP}(\square, w)$ returns a pair $(c', p) \in \Co \times S^+$ such that for any $p' \in S$, $p \not\sim_L p'$.
	\end{corollary}

	\begin{proof} 
		By Lemma~\ref{lem:s_splus_compatibility}, $\forall p \in \as_\Hyp(w)$, $\Hyp(p) = \Mod(p)$.
		Thus, $\agree(\square, w) = 1$.
		We can therefore apply Algorithm~\ref{algo:find_ebp} to $(\square, w)$ and by Theorem~\ref{th:find_ebp}, $\mathtt{FindEBP}(\square, w)$ returns a pair $(c, p) \in \Co \times S^+$ such that for any $p' \in \as_\Hyp(p)$, $\Mod(c[p]) \neq \Mod(c[p'])$.
		Moreover, by Invariant~3 of Property~\ref{prop:invariants}, for any $p' \in S \setminus \as_\Hyp(p)$, there exists $c' \in \C$ such that $\Mod(c'[p]) \neq \Mod(c'[p'])$. 
	\end{proof}


	\subsection{Termination and correction of the refinement process}

	\begin{lemma}
		\label{lem:term_cons_assoc}
		Algorithms~\ref{algo:make_consistent} and \ref{algo:make_assoc}
		\begin{enumerate*}
			\item terminate and
			\item induce a refinement if they return $\bot$.
		\end{enumerate*}

	\end{lemma}

	\begin{proof}
		Each iteration of either algorithm's main loop leads to a refinement and increases the size $|B|$ of the pack of components.
		But by Invariant 4 of Property~\ref{prop:invariants}, $|B| \leq |\qspace{L}|$, thus these loops must end and \textbf{1.} holds.

		\textbf{2.} trivially holds: if the main loop is executed at least once, the call to \texttt{Refine} will increase $|B|$ and the algorithm will return $\bot$ instead of $\top$.
	\end{proof}

	\begin{theorem}
		\label{th:always_refine}
		Algorithm \ref{algo:handle_ce}
		\begin{enumerate*}
			\item terminates and
			\item induces a refinement of $\B$.
		\end{enumerate*}
	\end{theorem}

	\begin{proof}
		If $\mathtt{MakeConsistent}() \land \mathtt{MakeAssoc}()$ is false, then at least one new class is added to~$\B$.
		But $|\B| \leq |\qspace{L}|$ by Invariant 4 of Property \ref{prop:invariants}.
		Lines~\ref{algo:handle_ce:consistency_loop_start} and \ref{algo:handle_ce:consistency_loop_end} therefore terminate.  

		Moreover, assume by contradiction that Algorithm \ref{algo:handle_ce} doesn't terminate. For any counter-example $w$, by Corollary~\ref{cor:new_component}, a call to $\mathtt{FindEBP}(\square, w)$ returns a pomset $p$ that is $\sim_L$-distinguished from all the other existing elements of $S$;
		then $p$ is then immediately added to~$S$ (Line~\ref{algo:handle_ce:new_component}).
		Thus, there would exist an infinite sequence of pomsets distinguished pairwise by ${\sim_L}$. But $\qspace{L}$ is finite by Theorem~\ref{th:myhill_nerode}, hence a contradiction. \textbf{1.} therefore holds.

		Finally, if Algorithm~\ref{algo:handle_ce} doesn't induce a refinement then it doesn't terminate:
		$\Hyp$ is not updated and $\Hyp(w) \neq \Mod(w)$ still holds.
		Thus, \textbf{2.} holds.
	\end{proof}

	A component of $\B$ may at some point feature more than one access sequence if Algorithm~\ref{algo:handle_ce} inserts a new representative that cannot be immediately separated from its original class by an inconsistency or an associativity defect.
	Nevertheless, it remains a temporary issue:

	\begin{property}
		\label{prop:sharp}
		Algorithm \ref{algo:handle_ce} terminates with $\B$ being sharp.
	\end{property}

	\begin{proof}
		Until Line~\ref{algo:main:first_hyp} of Algorithm~\ref{algo:main}, $\B$ is trivially sharp.
		Assume by contradiction that $\B$ ceases being sharp after some terminating call to Algorithm~\ref{algo:handle_ce}.
		Let $\Hyp$ and $\B$ be respectively the last hypothesis~(Line~\ref{algo:handle_ce:build_hyp}) and the last pack of components inferred by this call.
		If $\B$ is not sharp, by definition, there exist $B \in \B$, $p_1, p_2 \in \as_\B(B)$, $p_1 \neq p_2$ and $p_2$ has been added to $S$ by the algorithm after $p_1$.
		By Theorem~\ref{th:find_ebp}, there exists $c \in \Co$ such that $\Mod(c[p_1]) \neq \Mod(c[p_2])$ \textbf{(\romannumeral 1)}, and both $c[p_1]$ and $c[p_2]$ have been added to $\ce$ (Line~\ref{algo:handle_ce:refine_later}).

		By Property~\ref{prop:freeness_as}, since $p_1$ and $p_2$ belong to the same class $B$, $\Hyp(c[p_1]) = \Hyp(c[p_2])$ \textbf{(\romannumeral 2)}.
		By \textbf{\romannumeral 1} and \textbf{\romannumeral 2} either $\Hyp(c[p_1]) \neq \Mod(c[p_1])$ or $\Hyp(c[p_2]) \neq \Mod(c[p_2])$.
		Thus, there still exists a counter-example in the pool $\ce$, the loop condition in Line~\ref{algo:handle_ce:while_cond} is still verified and $\B$ can't be the last pack of components inferred as this new iteration of the loop will result in $\B$ being updated (Line~\ref{algo:handle_ce:new_component}).
		By contradiction, the property holds.
	\end{proof}

	\begin{theorem}[Correctness of $\Llambda$]
		\label{th:correctness}
		Algorithm \ref{algo:main}
		\begin{enumerate*}
			\item terminates and
			\item returns a PR $\Hyp$ such that $\Lang{\Hyp} = L$.
		\end{enumerate*}
	\end{theorem}

	\begin{proof}
		By Theorem~\ref{th:always_refine}, each call to \texttt{HandleCE} Line~\ref{algo:main:handle_ce} always yields a refinement, i.e. increases $|\B|$, hence $|\qspace{\Hyp}|$.
		But by Invariant 4 of Property~\ref{prop:invariants}, $|\B| \leq |\qspace{L}|$, thus there can be only a finite number of calls to \texttt{HandleCE}, and the algorithm terminates. 
		\textbf{1.} holds.

		\textbf{2.} obviously follows: consider the hypothesis $\Hyp$ returned.
		Assume that $\Lang{\Hyp} \neq L$;
		then $\exists w \in \SP$, $\Hyp(w) \neq \Mod(w)$.
		But the loop Line~\ref{algo:main:find_ce} should not have ended and should have instead lead to a further refinement of $\Hyp$.
		By contradiction, $\Lang{\Hyp} = L$.	
	\end{proof}


	\subsection{Complexity analysis}

	Let $|M| = n$ be the size of the target minimal pomset recognizer $\Mod$, $k = |\Sigma|$ the size of the alphabet, $m$ and $d$ the maximal size and depth of counter-examples returned by the MAT.
	We conduct a comparative theoretical analysis of query and symbol complexities, comparing our algorithm to the $L^*$ adaptation of~\cite{DBLP:conf/fossacs/HeerdtKR021}.

	\subsubsection{Query complexity}

	\paragraph{Building the pack of components.}

	Due to each element of $S$ being eventually distinguished from all the others, $|S| \leq n$ and $|S^+| \leq n^2 + k$.
	In a similar fashion, new elements are only ever added to $\C$ when they result in a new class being added to $\B$, thus $|\C| \leq n$.

	We build the pack of components by sifting every element of $S$ and $S^+$ through $\D$.
	The worst-case scenario arises when $\D$ is a linear tree of depth $n-1$: sifting a pomset may then require up to $n-1$ membership requests.
	Computing $\B$ then results in $\bigo(n^3 + k \cdot n)$ membership queries.
	In the best case scenario, $\D$ is a complete binary tree of depth $\lceil\log_2(n)\rceil$:
	we then perform $\bigo(\log_2(n) \cdot n^2 + k \cdot \log_2(n))$ membership queries.

	Both cases are similar to $L^*$, whose set of distinguishing contexts is of size $\lceil\log_2(n)\rceil$ in a best case scenario, and $n$ in the worst case scenario.
	A predictable result, due to the same property holding for finite automata.

	\paragraph{Handling counter-examples.}

	As a secondary result of the proof of Theorem~\ref{th:find_ebp}, given a counter-example $w$, $\mathtt{FindEBP}(\square, w)$ performs at most $d$ recursive calls.
	If we assume $\B$ is sharp, each call asks only two membership queries (Lines~\ref{algo:find_ebp:find_bp_start} and \ref{algo:find_ebp:check_ebp_end}).
	In that case, $\mathtt{FindEBP}(\square, w)$ only requires $\bigo(d)$ membership queries.

	Let us compare $\mathtt{FindEBP}$ to the function $\mathtt{HCE}$ outlined in \cite{DBLP:conf/fossacs/HeerdtKR021} that instead relies on a prefix traversal of a term of a counter-example instead of exploring a single branch on the fly.
	$\mathtt{HCE}$ performs at most $\bigo(m)$ membership queries.
	Thus, the closer to a perfect binary tree the term of $w$ considered, the more $\mathtt{FindEBP}$ outperforms $\mathtt{HCE}$: the former will perform at most $\bigo(\log_2(m))$ queries and the latter, $\bigo(m)$.
	However, if instead canonical terms are linear trees, then $d = \Theta(m)$ and both algorithms perform $\bigo(m)$ queries.

	In the context of the $\Llambda$ algorithm, while executing Algorithm~\ref{algo:handle_ce}, $\B$ may not be sharp and a component may feature up to $n$ access sequences.
	Computing the agreement predicates on Lines~\ref{algo:find_ebp:check_ebp_start} and \ref{algo:find_ebp:ebp_found_start} therefore requires $\bigo(n)$ membership queries.
	Thus, $\mathtt{FindEBP}(\square, w)$ finds a new component in $\bigo(n \cdot d)$ membership queries in the worst case scenario.

	Rivest-Schapire's method~\cite{DBLP:journals/iandc/RivestS93} for finite words identifies a breaking point in a counter-example $w$ by performing a binary search over the totally ordered set of prefixes of $w$, achieving logarithmic complexity w.r.t. the length of $w$.
	However, it is worth noting that, for series-parallel pomsets, the set of subpomsets of a counter-example $w$ forms a partial order that prevents us from searching for a breaking point dichotomically.

	\paragraph{Total number of queries.}	

	In both cases, the number of equivalence queries is bounded by $n$: in the worst case scenario, each counter-example results in only one component being added to $\B$.
	Finally, our algorithm performs at most $\bigo(n^3 + k \cdot n + d \cdot n^2)$ membership queries, whereas \cite{DBLP:conf/fossacs/HeerdtKR021}'s adaptation of $L^*$  performs at most $\bigo(n^3 + k \cdot n + m \cdot n)$.
	Were we to replace $\mathtt{HCE}$ with $\mathtt{FindEBP}$, $L^*$ would require $\bigo(n^3 + k \cdot n + d \cdot n)$ membership queries at most instead.

	Theoretically, $\Llambda$'s delayed refinements may burden the counter-example handling process and lead to higher query complexity than $L^*$;
	it has however been shown by Howar et al.~\cite{DBLP:conf/birthday/HowarS22} that $\Llambda$ is competitive with state-of-the-art active learning algorithms for rational languages and therefore outperforms $L^*$ due to delayed refinements being rare.
	It remains to be seen if such an observation holds for recognizable pomset languages.

	\subsubsection{Symbol complexity}

	Estimating the symbol complexity of an active learning algorithm is of great practical use.
	Merely bounding the number of queries overlooks the fact that the actual execution time of membership queries depends on the size of the input.

	\paragraph{A study of representatives and contexts.}	

	Let us estimate the size of $S$'s greatest access sequence: in the worst case scenario, the $i+1$-th representative $s_{i+1} \in S^+$ added to $S$ is the composition of two copies of the current largest element $s_i$ of $S \setminus \{\varepsilon\}$ for $1 \leq i < n$.
	Thus, $|s_{i+1}| = 2 \cdot |s_i| + 1$ and trivially, $|s_n| = \bigo(2^n)$.
	For any $s \in S \cup S^+$, $|s| = \bigo(2^n)$.
	An identical property holds for \cite{DBLP:conf/fossacs/HeerdtKR021}'s adaptation of $L^*$.

	The same is not true of $\C$.
	Let us estimate the size of $\C$'s greatest context: in the worst case scenario, the $i+1$-th context $c_{i+1}$ added to $\C$ is of the form $c_i[\square \circ s]$ where $s \in S$ and $c_i$ is the current largest element of $\C$ for $1 < i < n$, hence $|c_{i+1}| \leq |c_i| + 1 + |s|$.
	Trivially, $|c_n| = \bigo(n \cdot 2^n)$.
	Thus, for any $c \in \C$, $|c| = \bigo(n \cdot 2^n)$.
	In $L^*$'case, distinguishing contexts are directly extracted from the counter-examples and for any $c \in \C$, $|c| = \bigo(m)$.

	\paragraph{Total symbol complexity.}	

	In order to build its observation table, $L^*$ thus requires $\bigo((2^{n} + m) \cdot n^3 + k \cdot m \cdot n)$ symbols,
	while $\Llambda$ takes $\bigo(2^{n} \cdot n^4 + k \cdot 2^n \cdot n^2)$ symbols to build $\B$.
	Moreover, each membership query performed by \texttt{FindEBP} and \texttt{HCE} alike takes up to $\bigo(m + d \cdot 2^n)$ symbols, the worst case scenario being a right linear tree such that $d$ branches have to be replaced by their access sequences.
	\texttt{FindEBP} performs $\bigo(d \cdot n^2)$ membership queries, whereas \texttt{HCE} performs $\bigo(m \cdot n)$.
	Thus, the total symbol complexity of $L^*$ is $\bigo((2^{n} + m) \cdot n^3 + k \cdot m \cdot n + m \cdot n \cdot (m + d \cdot 2^n))$, and the symbol complexity of $\Llambda$ is $\bigo(2^{n} \cdot n^4 + k \cdot 2^n \cdot n^2 + d \cdot n^2 \cdot (m + d \cdot 2^n))$.

	It is therefore worth pointing out that $\Llambda$'s symbol complexity here does not depend on $m$ with the unavoidable exception of the counter-example handling procedure.
	Due to $m$ being arbitrary large, should $m = \Omega(n \cdot 2^n)$, then the extra symbols carried by the needlessly large distinguishing contexts directly inferred from counter-examples will burden every further membership query performed by $L^*$ to extend its observation table.



	\section{Generating Test Suites for Equivalence Queries}

	The use of equivalence queries in active learning algorithms is paradoxical: we are striving to infer a formal model from a black box yet our method requires that we compare the hypotheses we submit to the very model we are trying to learn. Practically speaking, we can only rely on membership queries.

	We remedy this issue by designing a suitable finite test suite ensuring general equivalence between two pomsets recognizers.
	Naturally, this is not possible in the general case. However, we assume that the size of the model is bounded w.r.t. to the hypothesis we submit.
	This test suite extends to recognizable languages of series-parallel pomsets the $W$-method \cite{DBLP:journals/tse/Chow78} originally applied to finite state machines accepting words.

	\begin{definition}[Equivalence on a test suite]
		Let $Z \subseteq \SP$.
		Two pomset recognizers $\PR_1$ and $\PR_2$ are said to be \emph{$Z$-equivalent}, written $\Hyp \equiv_Z \Mod$, if for any $z \in Z$, $\Hyp(z) = \Mod(z)$.
	\end{definition}

	We will in this section consider a hypothesis $\Hyp = (H, \cdot_\Hyp, \parallel_\Hyp, \neut_\Hyp, \eval_\Hyp, F_\Hyp)$ and a model $\Mod = (M, \cdot_\Mod, \parallel_\Mod, \neut_\Mod, \eval_\Mod, F_\Mod)$ sharing the same alphabet such that $\Hyp$ and $\Mod$ are minimal, $|H| = n$, and we know a bound $k$ such that $0 \leq |M|-|H| \leq k$.


	\subsection{Computing a state cover}

	The active learning algorithm computes a set of pomsets (the representatives) that reach every state of the hypothesis built, and a set of contexts that distinguish these states. We provide a generic definition of these notions:

	\begin{definition}[State cover]
		A set $P \subseteq \SP$ is a \emph{state cover} of a reachable pomset recognizer $\PR = (R, \odot, \obar, \neut, i, F)$ if $\varepsilon \in P$ and every $r \in R$ admits an access sequence $p \in P$.
	\end{definition}

	\begin{definition}[Characterisation set]
		A set of contexts $W \subseteq \Ct{1}$ is a \emph{characterization set} of a pomset recognizer $\PR = (R, \odot, \obar, \neut, i, F)$ if $\square \in W$ and for any $r_1, r_2 \in R$, if $r_1$ and $r_2$ are distinguishable, then $\exists c \in W$, $\PR(c[r_1]) \neq \PR(c[r_2])$.
	\end{definition}

	The definitions of minimality and characterisation sets result in the following property:

	\begin{property}
		Given a minimal pomset recognizer $\PR = (R, \odot, \obar, \neut, i, F)$, a characterization set $W$ of $P$, and two states $r_1, r_2 \in R$, if for any $c \in W, \PR(c[r_1]) = \PR(c[r_2])$, then $r_1 = r_2$.
		\label{prop:W_equiv}
	\end{property}

	The first step of the $W$-method consists in designing a state cover of the unknown model $\Mod$ that extends a known state cover of the hypothesis $\Hyp$ by relying on the bound $k$ we postulated and our knowledge that states distinguished in $\Hyp$ are still distinguished in $\Mod$.

	\begin{definition}[Extending a state cover.]
		Let $P$ be a state cover of $\Hyp$. We introduce the set $\Lcov{i}{P} = \{c[p] \mid m \in \integers, c \in \Ct{m}, \depth{c} \leq i, p \in P^m\}$.
	\end{definition}

	Intuitively, $\Lcov{i}{P}$ consists of all pomsets obtained by inserting access sequences of $P$ in a multi-context of height equal to or smaller than $i$.

	\begin{theorem}
		Let $P$ be a state cover of $\Hyp$ and $W$ a characterisation set of $\Hyp$ such that $\Hyp \equiv_{W[P]} \Mod$. Then $\Lcov{k}{P}$ is a state cover of $\Mod$.
		\label{th:canonical_state_cover}
	\end{theorem}

	\begin{proof}
		Let us first prove that $P$ covers at least $n$ distinguishable states of $\Mod$ \textbf{(\romannumeral 1)}.
		Indeed, consider two distinguishable states $h_1$ and $h_2$ among the $n$ states of $\Hyp$.
		Let $p_1$ (resp. $p_2$) be an access sequence of $h_1$ (resp. $h_2$) in $P$.
		$W$ being a characterisation set of $\Hyp$, $\exists c \in W$, $\Hyp(c[p_1]) \neq \Hyp(c[p_2])$.
		But $\Hyp \equiv_{W[P]} \Mod$ and $c[p_1], c[p_2] \in W[P]$, therefore $\Mod(c[p_1]) \neq \Mod(c[p_2])$;
		states $\eval_\Mod(p_1)$, $\eval_\Mod(p_2)$ are distinguished in $\Mod$ and \textbf{\romannumeral 1} holds.

		Consider a state $q \in M$ and an access sequence $w$ of $q$ in $\Mod$.
		Let us prove that there exists an access sequence $w'$ of $q$ and an evaluation tree $\tau' \in \evat{\Mod}{w'}$ that admits no repetition of states along any branch \textbf{(\romannumeral 2)}.
		Assume that such a repetition occurs in an evaluation tree $\tau$ of $w$, as shown in Figure~\ref{fig:eval_w}: then there exist two contexts $c_1, c_2 \in \Co$, a pomset $z \in \SP$, and a state $q' \in M$ such that $w = c_1[c_2[z]]$ and $q' = \eval_\Mod(z) = \eval_\Mod(c_2[z])$.
		Let $w' = c_1[z]$.
		Then $\eval_\Mod(w') = \eval_\Mod(c_1[z]) = \eval_\Mod(c_1[c_2[z]]) = \eval_\Mod(w)$ by Lemma~\ref{lem:free_context}, and we can remove at least one repetition from the branches of $\tau$, as shown in Figure~\ref{fig:eval_w_p}.
		Repeating this procedure yields an execution tree without repetitions along its branches that evaluates to $q$; \textbf{\romannumeral 2} holds.

