\thmrecolorateoneequiv*
\begin{proof}
We show the second item.  
The first item  
follows from the second and \autoref{thm:natrank-of-letters-and-words}.

We name the state of $\aut{A}[{\sim}]$ corresponding to class $[u]$ by $q_x$ where $x$ is the least word in the shortlex order that resides in $[u]$. 
Since $\aut{A}^\vigor_u$ is the automaton structure induced from $\equiv_u^\vigor$, by definition for every word $y$ if on reading $y$ the automaton reaches state $q_x$ then $y \equiv_u^\vigor x$.
Assume $w[..k]$ reaches state $q_x$. Thus, $w[..k]\equiv_u^\vigor x$.
It follows from \autoref{def:robustness} that for all $z\in\Sigma^*$, in particular $z=\varepsilon$ we have $\infixrank_{L_u}(u,\domsuf_{L_u}(x))=\infixrank_{L_u}(u,\domsuf_{L_u}(w[..k])$.
Note that the LHS is $\kappa(q_x)=\kappa(\aut{P}^\vigor_u(w[..k])$ and the RHS is $\letterrank_{L_u}(w,k)$. Thus, the claim follows.
\end{proof}

\thmrecoloratemanyequiv*
\begin{proof}
We show the second item.  
The first item  
follows from the second and \autoref{thm:natrank-of-letters-and-words}.

We use $\inf_{\sim_L}(w)$ for the set 
$\{[u]_{\sim_L}~|~ \forall i. \exists j>i.\ w[..j]\in [u]\}.$
Suppose $w=uv^\omega$, $u\sim_L uv$, $\wordrank_L(w)=d$ and  $\inf_{\sim_L}(w)=\{u_1,...,u_l\}$ and $m\geq l$ is the number of equivalence classes of $\sim_L$.
Let $y$ be a shortest infix of some repetition of $v$ that suffices to conclude the rank of $uv^\omega$.
That is,  $v^n=v'v''$ for some $n\in\mathbb{N}$, $v'v''\in\Sigma^*$ and $v''=xy$ for some $x,y\in\Sigma^*$ where $y=\domsuf_L(v'')$.\footnote{E.g., for $L_{a\text{-seq}}$, $u=b$, $v=bbaa$ we have $y=aa$. For $L_{a\text{-seq}}$, $u=b$, $v=a$ we have $y=aaa$.}
Then $\infixrank_L(uv'x,y)=d$. 
Let $u_i$ be such that $uv'xy_i'\sim_L u_i$ for some  $y_i'y_i''=y$. Then $\infixrank_L(uv'xy_i',y_i''y)=d$.
It follows from~\autoref{thm:recolorate-one-equiv} that $\kappa_{i}(\aut{P}_{u_i}(y_i''y))=d$ for every $i\in[1..l]$. 

Let $\rho_w=q_0,q_1,...$ be the run of $\aut{P}^\vigor_L$ on $w$ where $q_i=(c_i,p_{i,1},p_{i,2},...,p_{i,m})$. 
Then for every $i\in\mathbb{N}$ such that $y$ is a suffix of $w[..i]$ we have that $\kappa_{j}(p_{i,j})=d$ for all $j\in[1..l]$ and for infinitely many such $i's$ we have that $c_i\in[1..l]$.
Thus, $\kappa(\aut{P}^\vigor_L(w[..i]))=\kappa_{c_i}(p_{i,c_i})=d$ for infinitely many $i'$s. 
Recall that we have already established in \autoref{thm:recolorate-one-equiv} that for some $n_0\in\mathbb{N}$ it holds that
$\kappa_{j}(p_{n,j})\geq d$
for every $n>n_0$ and $j\in[1..l]$. 
It follows that the minimal rank visited infinitely often by $\aut{P}$ when running on $w$ is $\wordrank(w)$.
\end{proof}

\lempotentiallineartime*
\begin{proof}
We start with the computation of $\infixrank_L(u,v)$.

First we compute the MSCCs of $\aut{P}$.
     A state is termed \emph{transient} if it is not part of any MSCC (recall that a singleton $\{q\}$ is an MSCC only if there is a self-loop on $q$).
    Then we classify the MSCCs into \emph{rejecting}, \emph{accepting} or \emph{mixed}. An MSCC is \emph{rejecting} (resp. \emph{accepting}) if all its ranks are odd (resp. even) and it is \emph{mixed} otherwise. A rejecting (resp. accepting) MSCC is \emph{terminal} if only rejecting (resp. accepting) MSCCs are reachable from it. 

    Let $q_u$ and $q_{uv}$ be the states reached on reading $u$ and $uv$, resp. from the initial state.
If $q_{uv}$ is transient return $\infty$, if $q_{uv}$ resides in a rejecting (resp. accepting) terminal MSCC return $-1$ (resp. $-2)$.  


    Otherwise, let $d$ be the minimal rank visited when reading $v$ starting from $q_u$.
    Remove all states with rank lower than $d$ and check if there is a path from $q_{uv}$ to $q_u$ (can be done by a BFS). If so, $\infixrank_L(u,v)=d$. Otherwise, decrease $d$ by $1$ and perform the same for the new value. The 
    runtime is $O(m|E|{+}|uv|)$ where $m$ is the number of different ranks in the automaton, and $E$ are the edges of $\aut{P}$.

    For $\predomsuf_{L_u}(v)$, let $l=|v|$. 
    We compute first $d_1,d_2,d_3,... ,d_{l}$ and $d'_1,d'_2,d'_3,... ,d'_{l}$ where 
    $d_i=\infixrank(u,v[i..])$ and $d'_i=\infixrank(u,v[i..))$ for $i\in[1..l]$.
    If there is an $i$ for which $d_i<d'_i$, then $l$ is influential.
    Once we know whether $l$ is influential, we conclude whether $\predomsuf_{L_u}(v)$ should be the longest or the shortest suffix available, as defined in \autoref{def:dom-ind}. If index $l$ is not influential then the predominant index is the smallest $j$ such that $d_j=d_l$. 
    Otherwise, the predominant index is the biggest $j$ such that $d_j=d_1$.
    Given $j$ is the predominant index, the predominant suffix $\predomsuf_{L_u}(v)$ is $v[j..]$.
\end{proof}


\lemcomputerbstpfromp*
\begin{proof}
First we find the equivalence classes of $\sema{\aut{P}}$ as discussed above. Then for each equivalence class $u$, we can compute $\equiv_u^\vigor$, using an active learning algorithm such as $L^\star$~\cite{Angluin87} where the observation table entry $(x,y)$ is filled with the results of {$\infixrank_L(u,\predomsuf_{L_u}(xy))$} 
that by \autoref{lem:potential-linear-time} can be answered in polynomial time. Equivalence queries are answered via the polynomial time equivalence algorithm~\cite{AngluinF24} for $\aut{P}_{q_u}$ where $q_u$ is the state of $\aut{P}$ reached by reading $u$. This will result in $\aut{P}_u^\vigor$. From $\aut{P}_{u_i}^\vigor$ of all equivalence classes $u_i$ we can construct $\aut{P}^\vigor$ following \autoref{def:rbst-dpa}. 
\end{proof}


\propedgecolorcorrectness*
\begin{proof}
We modify $\aut{P}^\vigor$ by removing $-2$-terminal and $-1$-terminal MSCCs, and introducing states $q_\top$ ranked $-2$ (resp. $q_\bot$ ranked $-1$) for every state $q$ with a transition to $-2$-terminal (resp. $-1$-terminal) MSCC. 
Then, remove every edge $(q,\sigma,q')$ where $q'$ is in a $-2$-terminal (resp. $-1$-terminal) MSCC and replace it by an edge $(q,\sigma,q_\top)$ (resp. $(q,\sigma,q_\bot)$) and an edge $(q_\top,\varepsilon,q)$ (resp. $(q_\bot,\varepsilon,q))$. 
That is, for each such state $q$ its own dedicated state $q_\top$ (resp. $q_\bot$) is added.
 According to \autoref{def:letter-color}, reading the letter $\sigma$ by going through edge $(q,\sigma,q_{\top})$ (resp. $(q,\sigma,q_\bot
)$) gets the white (resp. black) letter color, because the $q_\top$ (resp. $q_\bot$) represents the accepting (resp. rejecting) terminal MSCCs. Therefore, the color of the corresponding edge is white (resp. black). Let $\aut{P}^\truerobustness$ be the resulting forgetful parity automaton.


For the equality $\sema{\aut{P}^\vigor}=\sema{\aut{P}^\truerobustness}$, let  $w\in\Sigma^\omega$, and let
$\rho_w=q_0q_1q_2...$ be the run of $\aut{P^\vigor}$ on $w$ and $\rho'_w=q'_0q'_1q'_2...$ be the run of $\aut{P}^\truerobustness$ on $w$.
If a negative rank is never traversed by $\aut{P}^\vigor$ then
$\kappa(q_i)=\kappa(q'_i)$ for every $i$ and so $w$ is accepted by both $\aut{P}^\vigor$ and $\aut{P}^\truerobustness$ if the minimum rank visited infinitely often is even.
If a negative rank is traversed by $\aut{P}^\vigor$, then if the first such rank is $-2$, then for some $j$ we have $\kappa(q_j)=-2$ and $\kappa(q_i)\geq 0$ for all $i<j$.
In this case $\kappa(q_k)=-2$ for all $k>j$ and so $w\in\sema{\aut{P}^\vigor}$.
Since in $\aut{P}^\truerobustness$ we also have $\kappa'(q'_j)=-2$ and $\kappa'(q'_i)\geq 0$ for all $i<j$,
by the definition of a forgetful DPA, $w\in\sema{\aut{P}^\truerobustness}$.
Similarly, if the first negative rank is $-1$ then it is $-1$ all along in $\aut{P}^\vigor$ and so $w\notin\sema{\aut{P}^\vigor}$ and it is not in $\sema{\aut{P}^\truerobustness}$ by the definition of a forgetful parity automaton.

Since  $\aut{P}^\vigor$ has the correct ranks, it has the correct colors of transitions when black/white edges are not involved.
In $\aut{P}^\truerobustness$ also runs with black/white edges are colored correctly since the transition to the dedicated state $q_\top$ (resp. $q_\bot$) colors the edge correctly with white (resp. black) and then the $\varepsilon$-transition mimics the forgetfulness by going back to the same state and allowing all colors to be read from there.
\end{proof}

\propcomputevalue*

\begin{proof} 
    Following \autoref{clm:rbst-dcmp-to-aut-dcmp} we can compute the robustness decomposition $(x,y)$ of $w=uv^\omega$ in polynomial time, by finding the first state $q$ the word loops at. 
    By \autoref{prop:edge-color-correctness} there is a one-to-one correlation between the colors of the infixes $x$ and $y$ and the colors of the edges traversed when reading them in $\aut{P}_L^\truerobustness$. Applying \autoref{def:infix-scr}
    we can compute the corresponding average scores $\tau_x$ and $\tau_y$.   
    We note that $w\in L$ if either a white edge is traversed in reading $xy$ (and no black edge is traversed before) or the minimal rank  visited when reading $y$ from $q$ is even. We set $a_w$ accordingly. 
    By \autoref{def:rbst-scr} the robustness value of $w$ is $(a_w,\tau_y,|x|(\tau_x-\tau_y))$. All the procedures described above can be done in time polynomial in {$|uv|{+}|\aut{P}_L^\truerobustness|$}.
\end{proof}


\clmrbstdcmptoautdcmp*
\begin{proof}
    We have to show that  $(u,v)$ is the shortest decomposition satisfying $w=uv^\omega$, $\infixrank_L(u,v)=\wordrank_L(w)$.
    Let $d$ be the minimal rank on the $v$-loop from $q$.
    By \autoref{rmrk:rbst-equiv-classes} we have that $uv\sim_L u$.
    By \autoref{thm:recolorate-many-equiv} if $\rho_w=q_0q_1q_2...$ is the run of 
    $\aut{P}^\truerobustness_L$  on $w$, then $\kappa(q_i)=\letterrank_L(w,i)$ for every $i\in\mathbb{N}$.
    It follows that $\min (\inf \{\letterrank_L(w,i)~|~i\in\mathbb{N}\})=d$. By \autoref{thm:natrank-of-letters-and-words} $\wordrank_L(w)=d$.

    We show that $\infixrank_L(u,v)=d$.
    Assume this is not the case, then either (i) $\infixrank_L(u,v)=d'>d$ or (ii) $\infixrank_L(u,v)=d'<d$.
    In the first case, by \autoref{def:infix-rank} there exists $z\in\Sigma^*$ such that $\wordrank(u(vz)^\omega)=d'$ and $uvz\sim_L u$.
    Note that the run of $\aut{P}^\truerobustness_L$ on $u(vz)^\omega$ visits state $q$ with rank $d<d'$. This contradicts \autoref{thm:natrank-of-letters-and-words}.  In the second case, by \autoref{def:infix-rank} for all words $z\in\Sigma^*$ such that $uvz\sim_L u$ we have that $\wordrank_L(u(vz)^\omega)\leq d'$.
    But for $z=\epsilon$ we know $\wordrank_L(u(v\varepsilon)^\omega)=d>d'$. Contradiction.

    To see that it is the shortest such decomposition, let
     $|u|=l$ and $q_1,q_2,...,q_l$ be the sequence of states obtained by reading $u$ from $q_\epsilon$. Note that $q_l=q$.
    Assume towards contradiction that there exists a shorter decomposition $(u',v')$ of $w$. Since $w$ is a lasso word and there is one final loop of $w$ on $\aut{P}_L^\truerobustness$, it holds that the period $v'$ is some rotation of $v$. Then $u'\prec u$ and there exists $q_i$ for some $i\in[1..l)$ that reaches the final loop before $q$ while reading $u$. This contradicts that $q$ is the first state of the final loop that is reached.
\end{proof}


\section{Additional examples and figures}

\subsection{Additional motivating examples}

\begin{example}[Response time, Starting time]\label{ex:responset_time}
    A common LTL property is $L=\allowbreak\ltlG(r \to \ltlF g)$ stipulating that every request (signal $r$) should eventually be followed by a grant (signal $g$). 
    Assume the alphabet $\Sigma=2^{\{r,g\}}=\{rg,r\overline{g},\overline{r}g,\overline{rg}\}$.
    Wrt $L$, many papers~\cite{BloemCHJ09,BloemGHJ09,BloemCGHHJKK14,AlmagorBK16,BartocciBNR18,AlmagorK20,HenzingerS21,HenzingerMS22} 
    view $(r\overline{g}\cdot (\overline{rg})^i \cdot \overline{r}g)^\omega$ as more robust than $(r\overline{g} \cdot (\overline{rg})^j \cdot \overline{r}g)^\omega$ if $i<j$. That is, we view a trace where the response time is shorter as more robust compared to one where it is longer. 

    Wrt $L'=\signal{reset}^*\cdot \signal{start}\cdot (\signal{busy}^*\cdot \signal{done})^\omega$ for $i<j$ we require (using first letter abbreviations of the signals) 
     $(r)^i  s (b^k  d)^\omega \gtrbst_{L'}
    (r)^j s  (b^k  d)^\omega$
    where $\gtrbst_L$ stands for \emph{more robust wrt $L$}. That is, we view a trace where the \signal{start} signal arrives earlier as more robust.
\end{example}

\begin{example}[No redundant grants]\label{ex:no-redundant-grants}
    In the context of synthesis, it is observed that the above property $\ltlG(r \to \ltlF g)$ is not strong enough as it puts no requirements on issuing grants~\cite{BloemCHJ09,BloemCGHHJKK14}. In real implementations issuing grants is costly and often one strengthens this property by requiring no redundant grants. The resulting property is $L''=\ltlG(r \to \ltlF g) \wedge \ltlG (g \to \ltlX [\neg g \ltlW r]) \wedge [\neg g \ltlW r]$. 
    Here 
    we would like $(r\overline{g}\cdot \overline{rg}\cdot \overline{r}g)^\omega \gtrbst_{L''} (r\overline{g}\cdot \overline{rg}\cdot  (\overline{r}g)^2)^\omega \gtrbst_{L''} (r\overline{g}\cdot \overline{rg}\cdot (\overline{r}g)^i)^\omega$ for $i>2$. That is, we prefer traces with fewer redundant grants.
\end{example}

\begin{example}[Avoid debts]\label{ex:avoid-debts}
Consider the language  $L=a\Sigma^\omega \vee bc^\omega$. 
If the first letter is $a$ then there are no further requirements. If the first letter is $b$ then there is a constant demand that $c$ will hold in every future tick. Thus any word starting with $a$ should be preferred over any word starting with $b$, which in a sense constantly creates a debt that should be satisfied in the future. This example together with $L_{a\text{-seq}}$ from \autoref{ex:diff-priorities-for-red-yellow-green-cycles} illustrate the requirement that words that create less debts should be preferred over words that create more debts.
\end{example}

\subsection{Additions to aid understanding the technical details}

\begin{remark}[Injection Sequences]\label{remark-exists-I}
   Note that \autoref{def:inf-nat-rank-minuses} uses 
    the \emph{existence} of a sequence $I$ of injection points.    
    For a given language $L$ and given word $w$ there could be sequences $I'$ and $I''$ such that $I'$ can be used in the definition to prove that the natural rank of $w$ wrt $L$ is what it is, while $I''$ cannot. Consider for instance $L_{a\text{-seq}}$ and $w=a^\omega$. Recall that 
$L_{a\text{-seq}}=\infty a \wedge (\infty aa \to \infty aaa)$.
We have that $\wordrank_{L_{a\text{-seq}}}(w)=0$. The sequence $I''=1,2,3,4,...$ cannot be used to show this, since, e.g. $(ab)^\omega\in\inj_{I''}(w)$ yet $\wordrank_{L_{a\text{-seq}}}((ab)^\omega)=2>\wordrank_{L_{a\text{-seq}}}(w)$. 
The sequence $I'=5,10,15,20,...$ however, can be used, as for any injection in these points, the rank of the resulting word will be $0$. Put otherwise, the definition of natural rank~\cite{EhlersS22} is not specific about which sequence of points can be used, it merely requires that such a sequence exists.
\end{remark}

\begin{example}[$\infixrank$ for $L_{\text{mod}2}$]\label{ex:infix-rank-mod-2}
    Consider $L_{\text{mod}2}=\infty a~\bigvee~(|w|_{a}$ is even $\wedge~\neg \infty c)~\bigvee~(|w|_{a}$ is odd $\wedge~\neg \infty b)$ over $\Sigma=\{a,b,c\}$
    where $|w|_a$ is the number of occurrences of the letter $a$ in $w$. 
    It has two equivalence classes $e_0$ and $e_1$ where
    for $i\in\{0,1\}$ the equivalence class $e_i$ consists of all word $w$ for which $(|w|_a \mod 2)=i$.
    We have that 
    $$\infixrank_{L_{\text{mod}2}}(u,v)=\left\{ 
\begin{array}{l@{\quad}l}
   2  &  \text{if } u \in e_0 \text{ and } v=b^* \\
   2  &  \text{if } u\in e_1 \text{ and } v=c^* \\
   1  &  \text{if } u\in e_0 \text{ and } v=(b\cup c)^*c(b\cup c)^* \\
   1  &  \text{if } u\in e_1 \text{ and } v=(b\cup c)^*b(b\cup c)^* \\
   0 & \text{if } u\in e_0  \text{ and } v=\Sigma^*a\Sigma^* \\
   0 & \text{if } u\in e_1  \text{ and } v=\Sigma^*a\Sigma^*
\end{array}
    \right.$$
\end{example}


\begin{example}[Computing whether an index is influential]\label{ex:influential}
    Consider the language $L_{a\text{-seq}}$ from \autoref{ex:diff-priorities-for-red-yellow-green-cycles}.
    Let $w=abbaaaaabbba^\omega$. We show how to calculate whether $k$ is influential wrt  $i=1$ for $k=3,5$.

    For $k=3$, following \autoref{def:influential}, we check whether there exists $j\in[1..3]$ for which there is a decrease in the natural rank of $w[j..k)$ when the last index $k$ is taken into account. We thus compare the natural rank of $\epsilon$ to the rank of $b$ (for $j{=}3$), of $b$ compared to $bb$ (for $j{=}2)$, and of $ab$ compared to $abb$ (for $j{=}1$). We get that $\infixrank_{L_{a\text{-seq}}}(ab,\epsilon)=3$ and $\infixrank_{L_{a\text{-seq}}}(ab,b)=3$. There is no decrease in the natural rank. Similarly, $\infixrank_{L_{a\text{-seq}}}(a,b)=3$ and $\infixrank_{L_{a\text{-seq}}}(a,bb)=3$ and $\infixrank_{L_{a\text{-seq}}}(\epsilon,ab)=2$ and $\infixrank_{L_{a\text{-seq}}}(\epsilon,abb)=2$.
    That is, there is no decrease in natural rank of $w[j..k)$ for any $j$. Therefore, $k=3$ is not influential wrt $i=1$.

    For $k=5$, for searching for the index $j$ that follows the requirements of \autoref{def:influential} we compare the natural rank of $\epsilon$ and $a$ (for $j{=}5$), of $a$ and $aa$ (for $j{=}4)$, of $ba$ and $baa$ (for $j{=}3)$, of $bba$ and $bbaa$ (for $j{=}2)$, and last of $abba$ and $abbaa$ (for $j{=}1$). We have $\infixrank_{L_{a\text{-seq}}}(abba,\epsilon)=3$ and $\infixrank_{L_{a\text{-seq}}}(abba,a)=2$, showing there is a decrease in the natural rank. 
    Thus, there is at least one index $j$ for which there is a decrease in the natural rank of $w[j..k)$, then $k{=}5$ is influential wrt $i{=}1$.
\end{example}



\begin{example}[Dominant suffixes and natural ranks of letters]\label{ex:nat-rank-calcs}
    Consider $L_{a\text{-seq}}$. Recall that $L_{a\text{-seq}}$ is $\infty a \wedge (\infty aa \to \infty aaa)$.
    \autoref{ex:seq-of-natrank-domnid-inf-a-if-aa-then-aaa} shows the calculation of the natural rank of the first $9$ letters of the word $w{=}abbaaaaab{...}$, where the row $i_w(k)$ signifies whether the $k$-th index is influential. The role of the other rows can be inferred from the row title.
    \autoref{ex:seq-of-natrank-domnid-inf-ab} does the same for the word $w{=}bbaababbb{...}$ and $L_{\infty ab}$.
\end{example}
