\title{On the spectra of prefix-reversal graphs}

\author[1]{Sa\'ul A. Blanco}
\affiliation[1]{organization={Department of Computer Science, Indiana University}, city={Bloomington, IN},
postcode={47408}, country={U.S.A.}}
