        &= \vec{0}_m^{\;\top} - \overrightarrow{2(n-j-i+1)}_m^\top + \vec{0}_m^{\;\top}
    \end{align*}
    The entries of $D(m,n) \vl$ are all
    \begin{align*}
        - \overrightarrow{2(j-1)}_m^\top &= \mathbf{0}_m \vec{0}_m^{\;\top} \cdot i + \mathbf{0}_m \overrightarrow{(-1)}_m^\top \cdot (j-i-1) + 2(j-1)I_m \overrightarrow{(-1)}_m^\top  \\ &\qquad + \mathbf{0}_m \overrightarrow{(-1)}_m^\top \cdot (n-i-j) + \mathbf{0}_m \overrightarrow{(n-2i)}_m^\top + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (i-1)\\
        &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} - \overrightarrow{2(j-1)}_m^\top + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    Thus, the entry in $M^\pm(m,n) \vl$ in position $j$ is $\overrightarrow{-2(n-i)}_m^\top$.

    \textbf{When $j=n-i+1$ the $j^{\text{th}}$ entry of $C^\pm(m,n) \vl$} is
    \begin{align*}
       \vec{0}_m^{\;\top}  &= C^\pm(m) \vec{0}_m^{\;\top} \cdot i + \mathbf{0}_m \overrightarrow{(-1)}_m^\top \cdot (n-2i) + \mathbf{0}_m \overrightarrow{(n-2i)}_m^\top + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (i-1)\\
       &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    The $j^{\text{th}}$ entry of $D(m,n) \vl$ is
    \begin{align*}
        \overrightarrow{2(n-i)(n-2i)}_m^\top &= \mathbf{0}_m \vec{0}_m^{\;\top} \cdot i + \mathbf{0}_m \overrightarrow{(-1)}_m^\top \cdot (n-2i) + 2(j-1)I_m \overrightarrow{(n-2i)}_m^\top \\ &\qquad + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (i-1)\\
        &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} - \overrightarrow{2(n-2i)(j-1)}_m^\top + \vec{0}_m^{\;\top}.
    \end{align*}
    Thus, the entry in $M^\pm(m,n) \vl$ in position $j$ is $\overrightarrow{2(n-i)(n-2i)}_m^\top$.

    \textbf{Finally, when $n-i+1 < j \leq n$ the entries of $C^\pm(m,n) \vl$} are all 
    \begin{align*}
        \vec{0}_m^{\;\top} &= C^\pm(m) \vec{0}_m^{\;\top} \cdot (n-j+1) + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (i+j-n-1) \\ &\qquad + \mathbf{0}_m \overrightarrow{(-1)}_m^\top \cdot (n-2i) +\mathbf{0}_m \overrightarrow{(n-2i)}_m^\top + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (i-1)\\
        &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    The entries of $D(m,n) \vl$ are all
    \begin{align*}
        \vec{0}_m^{\;\top} &= \mathbf{0}_m \vec{0}_m^{\;\top} \cdot i + \mathbf{0}_m \overrightarrow{(-1)}_m^\top \cdot (n-2i) + \mathbf{0}_m \overrightarrow{(n-2i)}_m^\top \\ &\qquad + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (i+j-n-2) + 2(j-1)I_m \vec{0}_m^{\;\top} + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (n-j) \\
        &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    Thus, the entry in $M^\pm(m,n) \vl$ in position $j$ is $\vec{0}_m^{\;\top}$. 
    Therefore, it follows that $M^\pm(m,n)\vl=\lambda\vl$, as desired.   

    \textbf{Case $m\equiv0\pmod4$.} Moreover, notice that we can see the matrix $M^{\pm}(m,n)$ as a block matrix with $n\times n$ blocks, each of which is one of the following $m\times m$ circulant matrices: $\textbf{0}_{m}$ or $C^\pm(m)$. Therefore, $\lambda I_{mn}-M^{\pm}(m,n)$ can be regarded as a block matrix with $n\times n$ blocks, each of them being either the $m\times m$ circulant matrix $\mathbf{0}_{m}$, $C^{\pm}(m)$, or $(\lambda-2i)I_{m}-C^{\pm}(m)$ with $0\leq i\leq n-1$ (the latter being the case of the diagonal blocks). Therefore, by Theorem~\ref{thm:Silvester} and the Leibniz formula for $\det(\lambda I_{mn}-M^{\pm}(m,n))$ yields
    \[
    \det(\lambda I_{mn}-M^{\pm}(m,n))=\det\left(\sum_{\sigma\in S_n}\sign(\sigma)M_{1,\sigma(1)}M_{2,\sigma(2)}\cdots M_{n,\sigma(n)}\right),
    \] where $M_{i,j}$ denotes the circulant matrix at position $(i,j)$ in the block matrix $\lambda I_{mn}-M^{\pm}(m,n)$. Thus,
    \begin{align*}
        \det(\lambda I_{mn}-M^{\pm}(m,n))%&=\det\left(\sum_{\sigma\in S_n}\sign(\sigma)M_{1,\sigma(1)}M_{2,\sigma(2)}\cdots M_{n,\sigma(n)}\right)\\
        &=\det\left(\sum_{\substack{\sigma\in S_n \\ \sigma\neq \operatorname{Id}_n}}\sign(\sigma)M_{1,\sigma(1)}M_{2,\sigma(2)}\cdots M_{n,\sigma(n)}+\prod_{i=0}^{n-1}(\lambda-2i)I_{mn}\right),
    \end{align*} where $\operatorname{Id}_n$ denotes the identity permutation of $S_n$. If $\lambda=2i$ for some $i\in[0,n-1]$, $\lambda I_{mn}-M^{\pm}(m,n)$, seen as a block matrix, has one row and one column where each non-zero block is $C^\pm(m)$. Therefore, Theorem~\ref{thm:Silvester} gives that above expression has the form
    \[
    \det(C^\pm(m)\mathcal{M}),
    \] for some matrix $\mathcal{M}$. Therefore, if $\lambda=2i$ for some $i\in[0,n-1]$, then $\det(\lambda I_{mn}-M^\pm(m,n))=\det(C^\pm(m))\det(\mathcal{M})$. By Lemma~\ref{lem:multipleof4}, it follows that for any $\lambda\in\{2i:i\in[0,n-1]\}$, $\det(\lambda I_{mn}-M^\pm(m,n))=0$. So in the case that $m\equiv0\pmod 4$, the spectrum of $\pmn$ contains all even integers in the set $[0,2n]$.
\end{proof}

