 %   If $m>2$, then the spectrum of $P(m,n)$ contains the values $\{ 2\cos\left(2\pi\cdot\ell/m\right) \mid \ell \in [0,m] \}$.
%\end{thm}

\section{The directed case $P(m,n)$}\label{sec:directed}

Let us now consider the case $Cay(S(m,n),R^+_n)$. In this case, the graph obtained is directed if $m>2$. Note that in the case of $m=1,2$ each prefix reversal is its own inverse while when $m>2$ the inverse of $r_i^+ \in R^+_n$ is $r^-_i$ and $r^-_i \not\in R^+_n$.

\begin{thm}\label{thm:directed}
    If $m>2$, the spectrum of $P(m,n)$ contains the set $[0,n]\setminus\{\lfloor n/2\rfloor\}$
\end{thm}
\begin{proof}
    Our proof is a description of the following eigenvalue-eigenvector pairs for $M^+(m,n)$.

Since $P(m,n)$ is $n$-regular (both in and out degree for each vertex is $n$) The eigenvalue $n$ has an eigenvector that is the $mn$-dimensional vector with all 1 entries. 

In general, the eigenvalue $n-i$, with $1\leq i< \lfloor n/2\rfloor$ has a corresponding eigenvector
\[
(\underbrace{0,\ldots,0}_{mi\text{ times}},\underbrace{-1,\ldots,-1}_{m(n-2i) \text{ times}},\underbrace{n-2i,\ldots,n-2i}_{m\text{ times}},\underbrace{0,\ldots,0}_{m(i-1)\text{ times}})^\top.
\] Furthermore, if $n$ is even, say $n=2\ell$ for some positive integer $\ell$, then the eigenvalue $\ell-i$ with $1\leq i\leq  \ell$ has a corresponding eigenvector
\[
(\underbrace{0,\ldots,0}_{m(\ell-i)\text{ times}},\underbrace{-2i+1,\ldots, -2i+1}_{m\text{ times}},\underbrace{1,\ldots,1}_{m(2i-1)\text{ times}},\underbrace{0,\ldots,0}_{m(\ell-i)\text{ times}})^\top. 
\] Moreover, if $n$ is odd, say $n=2\ell+1$ for some positive integer $\ell$, then the eigenvalue $\ell+1$ has a corresponding eigenvector 
\[
(\underbrace{0,\ldots,0}_{m\ell\text{ times}},\underbrace{-1,\ldots, -1}_{m\text{ times}},\underbrace{1,\ldots,1}_{m\text{ times}},\underbrace{0,\ldots,0}_{m(\ell-1)\text{ times}})^\top.
\]
Finally, if $n$ is odd, say $n=2\ell+1$ for some positive integer $\ell$, then the eigenvalue $\ell-i$ with $1\leq i\leq  \ell$ has a corresponding eigenvector
\[
(\underbrace{0,\ldots,0}_{m(\ell-i)\text{ times}},\underbrace{-2i,\ldots, -2i}_{m\text{ times}},\underbrace{1,\ldots,1}_{2mi\text{ times}},\underbrace{0,\ldots,0}_{m(\ell-i)\text{ times}})^\top.
\] Combining all the expressions, it follows that the spectrum of $M^+(m,n)$ contains the set $[0,n]\setminus\{\lfloor n/2\rfloor\}$. Therefore, by Proposition~\ref{prop:method}, the spectrum of $P(m,n)$ contains the set $[0,n]\setminus\{\lfloor n/2\rfloor\}$.

Once again we will verify one particular case, the other cases can be approached in a similar manner. We shall verify the case where $n = 2\ell +1$ that $\lambda = \ell-i$, for $1 \leq i \leq \ell$, is an eigenvalue of $M^+(m,n)$ with corresponding eigenvector 

    \begin{align*}
        \vl &= (\underbrace{0,\ldots,0}_{m(\ell-i) \text{ times}},\underbrace{-2i,\ldots,-2i}_{m\text{ times}}\,\underbrace{1,\ldots,1}_{2mi\text{ times}},\underbrace{0,\ldots,0}_{m(\ell-i)\text{ times}})^\top\\
        &= (\underbrace{\vec{0}_m, \ldots, \vec{0}_m}_{\ell-i\text{ times}}, \overrightarrow{(-2i)}_m, \underbrace{\vec{1}_m, \ldots, \vec{1}_m}_{2i\text{ times}}, \underbrace{\vec{0}_m, \ldots, \vec{0}_m}_{(\ell-i)\text{ times}})^\top.
    \end{align*}

    To show $M^+(m,n) \vl=\lambda \vl = C^+(m,n) \vl + \frac{1}{2}D(m,n) \vl$ we argue by cases depending on the entries of $M^+(m,n) \vl $ by considering an arbitrary row $j$ of the $M^+(m,n)$, considered as a block matrix. 

        \[\begin{bmatrix}
            \vdots \qquad \vdots & \vdots \qquad \vdots\\
            \underbrace{C^+(m) \; \cdots \; C^+(m)}_{2\ell-j+2\text{ times}} & \underbrace{\mathbf{0}_m \; \cdots \; \mathbf{0}_m}_{j-1\text{ times}}\\
            \vdots \qquad \vdots & \vdots \qquad \vdots\\
        \end{bmatrix} \vl + \begin{bmatrix}
            \vdots \qquad \vdots & \vdots & \vdots \qquad \vdots\\
            \underbrace{\mathbf{0}_m \; \cdots \; \mathbf{0}_m}_{j-1\text{ times}} & (j-1)I_m & \underbrace{\mathbf{0}_m \; \cdots \; \mathbf{0}_m}_{2\ell-j+1\text{ times}}\\
            \vdots \qquad \vdots & \vdots & \vdots \qquad \vdots\\
        \end{bmatrix} \vl.
        \]
    The matrix $C^+(m)$ has only one non-zero entries of one in each row and we consider $\vl$ as a ``block vector'' with $n$ blocks of length $m$, we can consider the product of $C^+(m,n)$ with $\vl$ ``block-wise'' where the analogous ``scalar'' multiplication results in just the entries of $\vl$ in the resulting product vector $C^+(m,n) \vl$. The product of $\frac{1}{2}D(m,n)$ and $\vl$ can also be done ``block-wise.'' We now examine the cases based on the values of $1 \leq j \leq 2\ell+1 = n$.

    \textbf{When $1 \leq j \leq \ell-i$, entries of $C^+(m,n) \vl$} are all  
    \begin{align*}
        \vec{0}_m^{\;\top} &= C^+(m) \vec{0}_m^{\;\top} \cdot (\ell-i) + C^+(m)\overrightarrow{(-2i)}_m^\top + C^+(m)\vec{1}_m^{\;\top} \cdot (2i) \\ &\qquad + C^+(m) \vec{0}_m^{\;\top} \cdot (\ell-j-i+1) + \mathbf{0}_m + \vec{0}_m^{\;\top} \cdot(j-1)\\
        &= \vec{0}_m^{\;\top} + \overrightarrow{(-2i)}_m^\top + \overrightarrow{(2i)}_m^\top + \vec{0}_m^{\;\top}.
    \end{align*} 
    The entries of $\frac{1}{2}D(m,n) \vl$ are all 
    \begin{align*} 
        \vec{0}_m^{\;\top} &= \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (j-1) + (j-1)I_m \vec{0}_m^{\;\top} + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i-j) \\ &\qquad + \mathbf{0}_m \overrightarrow{(-2i)}_m^\top + \mathbf{0}_m \vec{1}_m^{\;\top} \cdot (2i) + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i)\\
        &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    Thus, the entry in $M^+(m,n) \vl$ in position $j$ is $\vec{0}_m^{\;\top}$.

    \textbf{When $j=\ell-i+1$ the $j^{\text{th}}$ entry of $C^+(m,n) \vl$} is
    \begin{align*}
       \vec{0}_m^{\;\top}  &= C^+(m) \vec{0}_m^{\;\top} \cdot (\ell-i) + C^+(m) \overrightarrow{(-2i)}_m^\top + C^+(m) \vec{1}_m^{\;\top} \cdot (2i) + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i)\\
       &= \vec{0}_m^{\;\top} + \overrightarrow{(-2i)}_m^\top + \vec{(2i)}_m^\top + \vec{0}_m^{\;\top}.
    \end{align*}
    The $j^{\text{th}}$ entry of $\frac{1}{2}D(m,n) \vl$ is
    \begin{align*}
        \overrightarrow{(-2i)(\ell-i)}_m^\top &= \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i) + (j-1)I_m \overrightarrow{(-2i+1)}_m^\top + \mathbf{0}_m \overrightarrow{(1)}_m^\top \cdot (2i) \\ &\qquad + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i)\\
        &= \vec{0}_m^{\;\top} + \overrightarrow{(-2i)(j-1)}_m^\top + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    Thus, the entry in $M^+(m,n) \vl$ in position $j$ is $\overrightarrow{(\ell-i)(-2i)}_m^\top$.

    \textbf{When $\ell - i + 1 < j \leq \ell + i + 1$ entries of $C^+(m,n) \vl$} are all 
    \begin{align*}
        \overrightarrow{(\ell-j-i+1)}_m^\top &= C^+(m)\vec{0}_m^{\;\top} \cdot (\ell-i) + C^+(m)\overrightarrow{(-2i)}_m^\top + C^+(m) \vec{1}_m^{\;\top} \cdot (\ell-j+i+1)\\ & \qquad + \mathbf{0}_m \vec{1}_m^{\;\top} \cdot (j+i-\ell-1) + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i)\\
        &= \vec{0}_m^{\;\top} + \overrightarrow{(-2i)}_m^\top + \overrightarrow{(\ell-j+i+1)}_m^\top + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}
    \end{align*}
    The entries of $\frac{1}{2}D(m,n) \vl$ are all
    \begin{align*}
        \overrightarrow{(j-1)}_m^\top &= \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i) + \mathbf{0}_m \overrightarrow{(-2i)}_m^\top + \mathbf{0}_m \vec{1}_m^{\;\top} \cdot (j+i-\ell-2) \\ &\qquad + (j-1)I_m \vec{1}_m^{\;\top} + \mathbf{0}_m \vec{1}_m^{\;\top} \cdot (\ell-j+i+1) + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i)\\
        &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \overrightarrow{(j-1)}_m^\top + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    Thus, the entry in $M^+(m,n) \vl$ in position $j$ is $\overrightarrow{(\ell-i)}_m^\top$.

    \textbf{Finally, when $\ell+i+1 < j \leq 2\ell+1=n$ the entries of $C^+(m,n) \vl$} are all 
    \begin{align*}
        \vec{0}_m^{\;\top} &= C^+(m) \vec{0}_m^{\;\top} \cdot (2\ell-j+2) + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (j-i-\ell-2) \\ &\qquad + \mathbf{0}_m \overrightarrow{(-2i)}_m^\top + \mathbf{0}_m \vec{1}_m^{\;\top} \cdot (2i) + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i)\\
        &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    The entries of $\frac{1}{2}D(m,n) \vl$ are all
    \begin{align*}
        \vec{0}_m^{\;\top} &= \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (\ell-i) + \mathbf{0}_m \overrightarrow{(-2i)}_m^\top \cdot (n-2i) + \mathbf{0}_m \vec{1}_m^{\;\top} \cdot (2i) \\ &\qquad + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (j-i-\ell-2) + 2(j-1)I_m \vec{0}_m^{\;\top} + \mathbf{0}_m \vec{0}_m^{\;\top} \cdot (2\ell-j+1) \\
        &= \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top} + \vec{0}_m^{\;\top}.
    \end{align*}
    Thus, the entry in $M^+(m,n) \vl$ in position $j$ is $\vec{0}_m^{\;\top}$. 
    Therefore, it follows that $M^+(m,n)\vl=\lambda\vl$, as desired.
\end{proof}

\section{Final remarks}\label{sec:final}

\subsection{Multiplicities} A  question of further interest is determining the multiplicities of the eigenvalues in the spectrum. In the special case where the Cayley graph $Cay(Gr,S)$ is \emph{normal}, meaning that $S$ is closed under conjugation, then one can compute the eigenvalues and multiplicities of the adjacency matrix of $Cay(Gr,S)$ utilizing the characters of all irreducible representations of $Cay(Gr,S)$ (see, for example, Zieschang~\cite{Zieschang88}). Unfortunately, as natural as the prefix reversals are, they are not closed under conjugation. 

Computer calculations, completed to verify the above results, allow us to make the following conjecture, though. 

\begin{conj}
   If $m\equiv 0\pmod 4$, then the multiplicities of each eigenvalue of the form $2k$, with $k \in [n]\setminus \{\lfloor n/2 \rfloor$, %$1\leq k\leq n, k\neq\lfloor n/2\rfloor$ 
   is at least 3. Moreover, the multiplicity of the eigenvalue $2\lfloor n/2\rfloor$ is at least 2. 
\end{conj}


\subsection{Spectral gap and second-largest eigenvalue}

The \emph{spectral gap} of a graph $G$ refers to either the difference between the largest eigenvalue and the second-largest eigenvalue of the adjacency matrix $A_G$ of $G$, or the smallest positive eigenvalue of the \emph{Laplacian matrix} $L_G$ of $G$ (given that the smallest eigenvalue of $L_G$ is always zero). We will consider the former definition, and denote the spectral gap of $G$ by $sp(G)$.

In the case $m=1$, the spectral gap of prefix-reversal graphs is known to be 1, see Cesi or Chung and Tobin~\cite{Cesi09, CT17}. In the case $m>1$, the spectral gap of both $P(m,n)$ and $\pmn$ is unknown. Nonetheless, in~\cite{BB24}, the authors establish that the spectral gap for the case $m=2$ is at most 1 and conjecture that $sp(P(2,n))\to1$ as $n\to\infty$. Theorem~\ref{thm:undirected} shows that $sp(\pmn)\leq 2$ and Theorem~\ref{thm:directed} shows that $sp(P(m,n))\leq 1$. Computationally, we observe that the spectral gap increases for a fixed value of $m$ as $n$ increases, which leads to the following conjecture. 

\begin{conj}\label{conj:sp}
    For fixed $m>1$, $sp(\pmn)\to2$ as $n\to\infty$ and $sp(P(m,n))\to1$ as $n\to\infty$
\end{conj}   

A closely-related question is to give an explicit formula for the second largest eigenvalue of $\pmn$ and $P(m,n)$. In the case $m=1$, the largest eigenvalue of $P_n$ is $n-1$ since $P_n$ is $(n-1)$-regular. Moreover, the work of Cesi~\cite{Cesi09} and Chung and Tobin~\cite{CT17} established that the second-largest eigenvalue of the pancake graph $P_n$ is $n-2$ (the work of Chung and Tobin is more general and addresses a family of graphs that include $P_n$). 

\subsection{Expansion ratio}

We follow the excellent survey by Hoory, Linial, and Wigderson~\cite{Hoory06}. Given a graph $G=(V,E)$ and $S\subseteq V$, the \emph{boundary} of $S$, denoted by $\partial S$, is defined as the set 
\[\partial S=\{e\in E\mid e\text{ has one end point in } S \text{ and one not in }S\}.\]

Then the \emph{expansion ratio} of $G$ is defined as
\[
h(G)=\min_{\left\{S\subseteq V: |S|\leq \frac{|V|}{2}\right\}}\frac{|\partial S|}{|S|}.
\] 

The discrete Cheeger inequality (see~\cite[Theorem 2.4]{Hoory06}) states that if $G$ is $d$-regular with adjacency matrix eigenvalues $\lambda_1(G)\geq \lambda_2(G)\geq\cdots\geq \lambda_{|V|}(G)$, then 
\[
\frac{d-\lambda_2(G)}{2}\leq h(G)\leq \sqrt{2d(d-\lambda_2(G))}.
\] Since $\lambda_2(\pmn)\geq 2(n-1)$, it follows that $h(\pmn)\leq 2\sqrt{2n}$. Notice that this  bound is independent of $m$.

Following~\cite[Definition 2.2]{Hoory06}, a sequence of $d$-regular graphs $\{G_i\}_{i\geq 1}$ of size increasing with $i$ is a \emph{family of expander graphs} if there exists $\varepsilon>0$ such that $h(G_i)\geq\varepsilon$ for all $i$. Notice that $\pmn$ is a $d_n$-regular graph with degree $d_n=n-1$ if $m=1$ and $d_n=2n$ if $m>1$. While $d_n$ increases with $n$, it is independent of $m$. Therefore, it is a reasonable question to ask if the family $\{\pmn\}_{m>1}$, with fixed $n\geq1$ and indexed by $m$, is a family of expander graphs. We conjecture that this is the case. 

\begin{conj}\label{conj:expander}
    Given $n\geq1$, the sequence of $2n$-regular graphs $\{\pmn\}_{m>1}$ indexed by $m$ is an expander family of graphs. 
\end{conj}
Indeed, if Conjecture~\ref{conj:sp} is true, then Conjecture~\ref{conj:expander} is also true. 
