\section{Section \ref{sec:homology} proofs} \label{app:proofs}

The following proofs are based on diagram chasing. Note that this is legitimate as persistence modules can be viewed as actual modules over the incidence algebra of the poset.

\begin{proof}[Proof of Proposition \ref{prop:kernel_quotient}]
Suppose $x\in \text{ker }\partial_\ell$. Since $\alpha_\ell$ is an epimorphism, there exists $y\in G_\ell$ such that $\alpha_\ell(y)=x$. By commutativity we get $\alpha_{\ell\minus 1}\circ f_\ell(y)=\partial_\ell\circ \alpha_\ell(y)=0$ and by exactness of the rows $f_\ell(y)\in \text{ker }\alpha_{\ell\minus 1}=\text{im }p_{\ell\minus 1}^1$. Hence, there is a $z\in R_{\ell\minus 1}$ such that $f_\ell(y)=p^1_{\ell\minus 1}(z)$. Phrased differently $(y,z)\in \text{ker}\begin{pmatrix}f_\ell & p_{\ell\minus 1}^1\end{pmatrix}$ and $\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}(y,z)=\alpha_\ell(y)=x$. Hence, $\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}$ is an epimorphism. 

We have $\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}\circ\begin{pmatrix}p_\ell^1 & 0 \\ \gamma & p_{\ell\minus 1}^2\end{pmatrix}=\begin{pmatrix}\alpha_\ell\circ p_\ell^1 & 0\end{pmatrix}=0$. So $\text{im}\begin{pmatrix}p_\ell^1 & 0 \\ \gamma & p_{\ell\minus 1}^2\end{pmatrix}\subseteq \text{ker}\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}$.

Let $(x,y)\in \text{ker}\begin{pmatrix}f_\ell & p_{\ell\minus 1}^1\end{pmatrix}$ such that $\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}(x,y)=\alpha_\ell(x)=0$. Then $x\in\text{ker }\alpha_\ell=\text{im }p^1_\ell$ and there exists $a\in R_\ell$ such that $p^1_\ell(a)=x$. Moreover, we have 
\begin{equation*}
\begin{aligned}
\begin{pmatrix}f_\ell & p_{\ell\minus 1}^1\end{pmatrix}(x,y)&=f_\ell(x)+p_{\ell\minus 1}^1(y)=f_\ell\circ p_\ell^1(a)+p^1_{\ell\minus 1}(y)\\&=p_{\ell\minus 1}^1\circ \gamma(a)+p_{\ell\minus 1}^1(y)=p_{\ell\minus 1}^1\big(\gamma(a)+y\big)=0
\end{aligned}
\end{equation*}
Hence, $\gamma(a)+y\in\text{ker }p^1_{\ell\minus 1}=\text{im }p^2_{\ell\minus 1}$ and there exists $b\in RR_{\ell\minus 1}$ such that $y=\gamma(a)+p^2_{\ell\minus 1}(b)$. We conclude that $\begin{pmatrix}p_\ell^1 & 0 \\ \gamma & p_{\ell\minus 1}^2\end{pmatrix}(a,b)=(x,y)$ and $\text{im}\begin{pmatrix}p_\ell^1 & 0 \\ \gamma & p_{\ell\minus 1}^2\end{pmatrix}=\text{ker}\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}$.
\end{proof}

\vspace{5pt}

\begin{proof}[Proof of Proposition \ref{prop:homology_quotient}]
In Proposition \ref{prop:kernel_quotient}, we proved that $\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}\colon \text{ker}\begin{pmatrix}f_\ell & p_{\ell\minus 1}^1\end{pmatrix}\rightarrow \text{ker }\partial_\ell$ is an epimorphism. Hence, $\pi\circ \text{ker}\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}$ is an epimorphism. 

Since
\begin{equation*}
\begin{aligned}
\pi\circ\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}\circ \begin{pmatrix}f_{\ell+1} & p^1_{\ell} & 0 \\ \vartheta & \gamma & p^2_{\ell\minus 1}\end{pmatrix}&=\pi\circ \begin{pmatrix}\alpha_\ell\circ f_{\ell+1} & 0 & 0 \end{pmatrix}\\&=\begin{pmatrix}\pi\circ\partial_{\ell+1}\circ\alpha_{\ell+1} & 0 & 0 \end{pmatrix}=0
\end{aligned}
\end{equation*}
we have $\text{im}\begin{pmatrix}f_{\ell+1} & p^1_{\ell} & 0 \\ \vartheta & \gamma & p^2_{\ell\minus 1}\end{pmatrix}\subseteq\text{ker }\pi\circ\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}$.

Suppose $(x,y)\in \text{ker}\begin{pmatrix}f_\ell & p_{\ell\minus 1}^1\end{pmatrix}$ such that $\pi\circ \begin{pmatrix}\alpha_\ell & 0\end{pmatrix}(x,y)=\pi(\alpha_\ell(x),0)=0$. Then there exists $z\in C_{\ell+1}$ such that $\partial_{\ell+1}(z)=\alpha_\ell(x)$. Moreover, since $\alpha_{\ell+1}$ is an epimorphism, there exists $a\in G_{\ell+1}$ such that $\alpha_{\ell+1}(a)=z$. Using commutativity we obtain $\alpha_\ell\circ f_{\ell+1}(a)=\partial_{\ell+1}\circ \alpha_{\ell+1}(a)=\alpha_\ell(x)$. This implies $\alpha_\ell\big(f_{\ell+1}(a)+x\big)=0$, so $f_{\ell+1}(a)+x\in\text{ker }\alpha_\ell=\text{im }p^1_\ell$ and there exists $b\in R_\ell$ such that $x=f_{\ell+1}(a)+p^1_\ell(b)$. Since 
\begin{equation*}
\begin{aligned}
\begin{pmatrix}f_\ell & p_{\ell\minus 1}^1\end{pmatrix}(x,y)&=f_\ell(x)+p^1_{\ell\minus 1}(y)\\&=f_\ell\big(f_{\ell+1}(a)+p^1_\ell(b)\big)+p^1_{\ell\minus 1}(y)\\&=f_\ell\circ f_{\ell+1}(a)+f_\ell\circ p^1_\ell(b)+p^1_{\ell\minus 1}(y)\\&=p^1_{\ell\minus 1}\circ \vartheta(a)+p^1_{\ell\minus 1}\circ \gamma(b)+p^1_{\ell\minus 1}(y)\\&=p^1_{\ell\minus 1}\big(\vartheta(a)+\gamma(b)+y\big)=0
\end{aligned}
\end{equation*}
we obtain $\vartheta(a)+\gamma(b)+y\in\text{ker }p^1_{\ell\minus 1}=\text{im }p^2_{\ell\minus 1}$ and there exists $c\in RR_{\ell\minus 1}$ such that $y=\vartheta(a)+\gamma(b)+p^2_{\ell\minus 1}(c)$. We conclude that $\begin{pmatrix}f_{\ell+1} & p^1_{\ell} & 0 \\ \vartheta & \gamma & p^2_{\ell\minus 1}\end{pmatrix}(a,b,c)=(x,y)$ and $\text{im}\begin{pmatrix}f_{\ell+1} & p^1_{\ell} & 0 \\ \vartheta & \gamma & p^2_{\ell\minus 1}\end{pmatrix}=\text{ker }\pi\circ\begin{pmatrix}\alpha_\ell & 0\end{pmatrix}$.
\end{proof}

\section{Computing presentations from PiReps} \label{app:homology_presentation}

In this section we discuss how we can compute a presentation of the homology of a PiRep as in \eqref{eq:projective_complex_homology}. We consider a chain complex segment 
\begin{equation}\label{eq:segment_Q}
\begin{tikzcd}Q_{\minus 1} & Q_0 \arrow[l,swap,"q_0"] & Q_1 \arrow[l,swap,"q_1"] 
\end{tikzcd}
\end{equation}
where the $Q_i$ are projective and the maps $q_i$ are represented by $P$-graded matrices. We start by extending $Q_{\minus 1}\xleftarrow{q_0} Q_0$ to an exact sequence of projective modules:
\begin{equation}\label{eq:res_ker}
\begin{tikzcd}
Q_{\minus 1} & Q_0 \arrow[l,swap,"q_0"] & U_0 \arrow[l,swap,"u_0"] & U_1 \arrow[l,swap,"u_1"] 
\end{tikzcd}
\end{equation}
This can be done, for example, by using the algorithm\footnote{The algorithm {\sc MakeExact} in \cite{brown2024discretemicrolocalmorsetheory} is formulated in terms of injective resolutions but in our setting the projective case is completely dual.} {\sc MakeExact} in \cite{brown2024discretemicrolocalmorsetheory}.  Since, by exactness $\text{ker }q_0=\text{im }u_0$, $u_1$ is a presentation of $\text{ker }q_0$. Since $\text{im }q_1\subseteq \text{ker }q_0$ we obtain the following diagram:
\begin{equation}\label{eq:ker_res_lift}
\begin{tikzcd}
& Q_1 \arrow[d,swap,"q_1"] \arrow[dr,dashed,"s"] \\
0 & \text{ker }q_0 \arrow[l] & U_0 \arrow[l,swap,"u_0"] & U_1 \arrow[l,swap,"u_1"]
\end{tikzcd}
\end{equation}
where $u_0$ is an epimorphism. Therefore, by the lifting property of projective modules, we get a lift $s$ of $q_1$ along $u_0$. This lift can be computed by solving a linear system as discussed in the beginning of Section \ref{subsec:graph_equations}. We can interpret $U_0$ and $U_1$ as the generators and relations of the kernel and $Q_1$ as the initial relations on $Q_0$. We have now all ingredients for a presentation of the homology. Let $\pi\colon \text{ker }q_0\rightarrow \text{ker }q_0/\text{im }q_1$ denote the projection to the cokernel.

\begin{theorem} \label{prop:ker_res_lift}
The following exact sequence:
\begin{equation} \label{eq:final_presentation_from_pirep}
\begin{tikzcd}[ampersand replacement=\&,every label/.append style = {font = \small}]
0 \& \text{ker }q_0/\text{im }q_1 \arrow[l] \&[15pt] U_0 \arrow{l}[swap]{\pi\circ u_0} \&[25pt] U_1\oplus Q_1 \arrow{l}[swap]{\begin{pmatrix}u_1 & s\end{pmatrix}}
\end{tikzcd}
\end{equation}
is a presentation of the homology of \eqref{eq:segment_Q}.
\end{theorem}

\begin{proof}
Since $u_0$ and $\pi$ are epimorphisms also $\pi\circ u_0$ is an epimorphism. 

Since $\pi\circ u_0\circ \begin{pmatrix}u_1 & s\end{pmatrix}=\begin{pmatrix}\pi\circ u_0\circ u_1 & \pi\circ u_0\circ s\end{pmatrix}=\begin{pmatrix}0 & \pi\circ q_1\end{pmatrix}=0$, we have $\text{im}\begin{pmatrix}u_1 & s\end{pmatrix}\subseteq\text{ker }\pi\circ u_0$.

Let $x\in \text{ker }\pi\circ u_0$. Then $\pi\circ u_0(x)=0$ implies that there exists $y\in Q_1$ such that $u_0(x)=q_1(y)=u_0\circ s(y)$. Since, $u_0\big(x+s(y)\big)=0$ and $x+s(y)\in\text{ker }u_0=\text{im }u_1$, there exists $z\in U_1$ such that $x=u_1(z)+s(y)$. We conclude that $\begin{pmatrix}u_1 & s\end{pmatrix}(z,y)=x$ and $\text{im}\begin{pmatrix}u_1 & s\end{pmatrix}=\text{ker }\pi\circ u_0$.
\end{proof}

\noindent
The presentation of Theorem \ref{prop:ker_res_lift} is not necessarily minimal. But if $U_0\xleftarrow{u_1}U_1$ is a minimal presentation of $\text{ker }q_0$, as provided for example by {\sc MakeExact}, then $U_0$ is also minimal in \eqref{eq:final_presentation_from_pirep}. Thus, we only need to reduce the superfluous relations to obtain a minimal presentation. This is can be done by using a routine similar to {\sc Reduce} in Section \ref{sec:algorithm}. Alternatively, in \cite{brown2024discretemicrolocalmorsetheory} the authors also discuss methods to minimize resolutions.


