\section{Preliminaries}
This section introduces the necessary background for our framework. We begin with an overview of \emph{Linear Temporal Logic} (LTL), then introduce \emph{Büchi automata}, which serves as the automata-theoretic counterpart to LTL formulas. Building upon this foundation, we describe the process of \emph{automata-based language inclusion check} to reason the verification. Finally, we formally state the problem that our work aims to address.
\vspace{-0.4cm}
\subsection{Linear Temporal Logic}\label{sec:LTL}
Linear Temporal Logic (LTL) serves as the foundation for many practical specification languages \cite{43}. The basic components of an LTL formula include Atomic Propositions (AP) and Operators (boolean and temporal). 
In our work, we adopt the syntax and semantics of LTL as defined in \cite{23,28} and recalled them here. 


\vspace{-0.2cm}
\begin{definition}[LTL Syntax and Semantics]
\noindent\textbf{Syntax.}  
Let $AP$ be a finite set of atomic propositions. The set of LTL formulas over $AP$ is defined inductively by the following grammar:
\vspace{-0.2cm}
\[
    \varphi ::= \text{true} \mid a \mid \neg \varphi \mid \varphi_1 \land \varphi_2 \mid X \varphi \mid \varphi_1 \, U \, \varphi_2,
\]
where $a \in AP$ is an atomic proposition, temporal operators such as $X$ (next), $U$ (until) can be used for dynamical properties. 

\noindent\textbf{Semantics.}
Let $\varphi$ be a LTL formula, the semantics of  $\varphi$ is defined over infinite words $\sigma \in (2^{AP})^{\omega}$, with $Words(\varphi)=\left\{\sigma \in\left(2^{AP}\right)^{\omega} \mid \sigma \models \varphi\right\}$ being the LT property induced by $\varphi$. Let $\sigma = A_0 A_1 A_2 \ldots$ (symbol $A_{i}\in AP$), where the satisfaction relation $\models \subseteq (2^{AP})^{\omega} \times \text{LTL}$ is defined as follows:
\vspace{-0.45cm}
\begin{itemize}
    \item $\sigma \models \text{true}$,
    \item $\sigma \models a$ iff $a \in A_0$,
    \item $\sigma \models \neg \varphi$ iff $\sigma \not\models \varphi$,
    \item $\sigma \models \varphi_1 \land \varphi_2$ iff $\sigma \models \varphi_1$ and $\sigma \models \varphi_2$,
    \item $\sigma \models X \varphi$ iff $\sigma[1...] = A_1 A_2 \ldots \models \varphi$,
    \item $\sigma \models \varphi_1 \, U \, \varphi_2$ iff $\exists j \geq 0$. $\sigma[j...] \models \varphi_2$ and for all $0 \leq i < j$, $\sigma[i...] \models \varphi_1$.
\end{itemize}
\label{def:LTL}
\end{definition}
\vspace{-0.7cm}



%LTL formulas express properties of state paths (or their traces). Thus, the semantics of LTL is interpreted over paths and states of a reactive system.
%LTL plays a critical and wide-ranging role. 
\vspace{-0.2cm}
\subsection{Büchi automaton}
To bridge the gap between logical formulations and algorithmic reasoning, a typical step is to convert LTL into automata, like Büchi automaton (BA) \cite{2}.
\vspace{-0.1cm}
\begin{definition}[Büchi Automata]
    A Büchi automaton (BA) is defined as a tuple $\mathcal{A} = (\Sigma, Q,\mathcal{I}, \mathcal{F},\delta)$, where $\Sigma$ is an finite alphabet,  $Q$ is a finite set of states, $\mathcal{I} \subseteq Q$ is the set of initial states, $\mathcal{F} \subseteq Q$ is the set of accepting states and $\delta: Q \times \Sigma \times 2^Q$ is the transition relation. A run of $\mathcal{A}$ on an infinite word $w = \sigma_1 \sigma_2 \dots \in \Sigma^\omega$, with symbol $\sigma_i \in \Sigma$, $i\in \mathbb{N}$, starting from a state $q_0 \in Q$, is an infinite sequence of states $q_0 q_1 q_2 \dots$ such that $(q_{j-1}, \sigma_j, q_j) \in \delta$ for all $j > 0$. The run is accepted if $q_i \in F$ for infinitely many $i$. The accepted language $L(\mathcal{A})$ consists of all infinite words over $\Sigma^\omega$ for which there exists an accepted run.
    \end{definition}
\vspace{-0.1cm}

For every LTL formula $\varphi$, there exists a corresponding Büchi automaton $\mathcal{A}$ such that:
\(
L(\mathcal{A})=Words(\varphi)
\). The conversion from LTL to Büchi automaton has a well-established theoretical foundation \cite{25,26}, and existing research has proposed numerous effective methods and tools for converting LTL to Büchi automata \cite{27,28,29,30,31,32,33}. The aim of this conversion lies in using Büchi automata to model a system’s dynamic behavior. Simulation relations, such as forward and backward simulation, are then used to establish step-by-step correspondence by linking successive state transitions, thereby capturing all dynamic behaviors expressed by the BA.
\vspace{-0.1cm}
\begin{definition}[Forward and Backward Simulation on Büchi Automata]
Let $\mathcal{A} = (\Sigma, Q,\mathcal{I}, \mathcal{F},\delta)$ be a Büchi automaton. A relation $R \subseteq Q \times Q$ is called (1) a \emph{forward simulation} on $\mathcal{A}$ if for any $(p, r) \in R$, the following conditions hold: 1)If $p \in \mathcal{F}$, then $r \in \mathcal{F}$ and 2) $\forall(p, \sigma, p') \in \delta$, $\exists(r, \sigma, r') \in \delta$ s.t. $(p', r') \in R$. (2) a \emph{backward simulation} on $\mathcal{A}$ if for any $(p', r') \in R$, the following conditions hold: 1) If $p' \in \mathcal{F}$, then $r' \in \mathcal{F}$, 2) If $p' \in \mathcal{I}$, then $r' \in \mathcal{I}$, and 3) $\forall (p, \sigma, p') \in \delta$, $\exists(r, \sigma, r') \in \delta$ s.t. $(p, r) \in R$.
\end{definition}
\vspace{-0.1cm}

To support the subsequent Section~\ref{sec:3.3}, we introduce the notion of a \emph{path} in a Büchi automaton, which uses simulation to describe how an input word drives a sequence of state transitions. Since the same symbol \( \sigma_i \in \sigma \) can trigger different transitions depending on the current state of the automata, there exists a set of paths over the same input word $\sigma$. 

\vspace{-0.1cm}
\begin{definition}[Path of a Büchi Automaton]
Let $\mathcal{A} = (\Sigma, Q,\mathcal{I}, \mathcal{F},\delta)$ be a Büchi automaton and let Word $\sigma = \sigma_0 \sigma_1 \sigma_2 \ldots \in \Sigma^{w}$ 
 with symbol $\sigma_i \in \Sigma$, $i\in\mathbb{N}$. A \emph{path} $\rho$ of $\mathcal{A}$ over $\sigma$ is a state-and-word sequence:
\vspace{-0.2cm}
\[
q_0 \xrightarrow{\sigma_0} q_1 \xrightarrow{\sigma_1} q_2 \xrightarrow{\sigma_2} \cdots
\]
where $q_0 \in \mathcal{I}$ is an initial state and for each $i \geq 0$, $(q_i, \sigma_i, q_{i+1}) \in \delta$. 
A path $\rho$ is \emph{simulable} w.r.t. $\sigma$ if: 1) it traverses every $\sigma_i \in \sigma$  and the corresponding transitions $(q_i, \sigma_i, q_{i+1}) \in \delta$;  
2) it ends in or visits some accepting state $q_f \in \mathcal{F}$ infinitely often. The set of paths over $\sigma$ in \( \mathcal{A} \) is denoted by \( \mathcal{P}_\sigma \), where:
\vspace{-0.2cm}
\begin{equation}\label{Psigma}
    \mathcal{P}_\sigma = \{ q_0 \xrightarrow{\sigma_0} q_1 \xrightarrow{\sigma_1} \cdots \mid q_i \in Q,\ \sigma_i \in \sigma,\ (q_i, \sigma_i, q_{i+1}) \in \delta \} 
\end{equation}
\label{def:Path} 
\end{definition}
\vspace{-0.2cm}
\vspace{-0.8cm}
A fundamental concept in automata-based verifications is the notion of \emph{language inclusion}, capturing the containment relationship between two automata.

\vspace{-0.1cm}
\begin{definition}[Language Inclusion]
Let $\mathcal{A}_1$ and $\mathcal{A}_2$ be two Büchi automata over the same input alphabet $\Sigma$. If every infinite word accepted by $\mathcal{A}_1$ is also accepted by $\mathcal{A}_2$, then the language of $\mathcal{A}_1$ is \emph{included} in the language of $\mathcal{A}_2$, denoted as $L(\mathcal{A}_1) \subseteq L(\mathcal{A}_2)$:
\vspace{-0.2cm}
\[
L(\mathcal{A}_1) \subseteq L(\mathcal{A}_2) \iff \forall w \in \Sigma^\omega, \; w \in L(\mathcal{A}_1) \Rightarrow w \in L(\mathcal{A}_2).
\]
\end{definition}
\vspace{-0.3cm}

