\title{Going Beyond Heuristics by Imposing Policy Improvement as a Constraint}



\author{%
  Chi-Chang Lee$^1$\thanks{ indicates equal contribution. $^1$ National Taiwan University, Taiwan. $^2$ Improbable AI Lab, MIT, USA.} , Zhang-Wei Hong$^2$$^*$ , Pulkit Agrawal$^2$ \\
  Improbable AI Lab\\ 
  Massachusetts Institute of Technology
