In order to prove Theorem \ref{thm-gen-lsc-of-card-geo-fiber}, we extend the classical trace pairing technique to the free module of finite rank case now.
\begin{definition}\label{def-para-HQF}
	If $A$ is a finitely generated $k$-algebra and $B$ is an $A$-algebra that is also a free $A$-module of finite rank, then we define the \textbf{relative Hermite Quadratic Form} of $B$ to be:
	$$H:\begin{array}{rcl}
		B \times B & \to & A \\
		(f,g)  & \mapsto & \tr L_{fg}.
	\end{array}$$
	This is well-defined because $B$ is a free $A$-module of finite rank.

	Similarly, if $h\in B$, we define the \textbf{relative Hermite Quadratic Form associated with} $h$ of $B$ to be:
	$$H_h:\begin{array}{rcl}
		B \times B & \to & A \\
		(f,g)  & \mapsto & \tr L_{fhg}.
	\end{array}$$
	%Suppose $p\unlhd B$ is a prime ideal, the specialization of $H$ on $p$ is defined to be 
	%$$H_p:\begin{array}{rcl}
	%	 A \otimes_B k \times A \otimes_B k & \to & k \\
	%	 (f,g) & \mapsto & \tr L_{fg}
	%\end{array}$$
	%where $k=\Frac B/p$. 

	%Let $X=\spec S'$, $Y=\spec S$ be affine $k$-varieties. Suppose $Y$ is integral and $f:X\to Y$ is a generically finite dominant $k$-morphism. By generic freeness and generic finiteness, there is $w\in S$ such that $S'_w$ is a free $S_w$-module of finite rank. Define the \textbf{parametric Hermite Quadratic Form}: 
	%$$H: \begin{array}{rcl} S_w' \times S_w' &\to& S_w \\ (f,g) &\mapsto &\tr L_{fg}\end{array}.$$
	%This is well-defined because $S_w'$ is a free $S_w$-module of finite rank.
\end{definition}

\begin{lemma}[Specialization Property of relative Hermite Quadratic Form]
	\label{lem-specialization-of-para-HQF}
	%Let $f:X\to Y$ be a generically finite, dominant morphism of affine $k$-varieties, and $Y=\spec S$ is integral. Denote the generic point of $Y$ by $\eta$, then there is $g\in \Gamma(Y,\mathcal{O}_Y)$ such that the Hermite Quadratic Form $H$ defined on $\eta$ specializes to all $p\in D(g)$.
	%There exists $g\in \Gamma(Y,\mathcal{O}_Y)$ such that $H: S'_g \times S'_g \to S_g, (f,g)\mapsto \tr L{fg}$ specializes to all $p\in D(g)$.
	%The parametric Hermite Quadratic Form specializes to all $p\in D(g)$.
	Notations as above and $p\in \spec A$, then the relative Hermite Quadratic Forms $H$ and $H_h$ evaluated at $p$ coincides with the classical Hermite Quadratic Form.
\end{lemma}
\begin{proof}
	Choose a basis $\{b_1,\ldots,b_r\}$ of $B$ as free $A$-module, then $H$ ($H_h$ resp.) can be represented as a matrix $\left(\tr L_{b_ib_j}\right)_{i,j}$ ($\left(\tr L_{b_ihb_j}\right)_{i,j}$ resp.). Let $p$ be a prime ideal of $A$ and $\varphi$ is the canonical map $\varphi: B\to B\otimes_A \Frac(A/p)$, the images of $b_i$ in $B\otimes_A A_p \otimes_{A_p} A_p/pA_p\cong B\otimes_A \Frac(A/p)$ is a basis for $\Frac(A/p)$-vector space $B \otimes_A \Frac(A/p)$.

	Now the matrix of the classical Hermite Quadratic Form is given by the traces of $L_{\varphi(b_ib_j)}$, which are exactly $\tr L_{b_ib_j}$ evaluated at $p$. The same argument works for $H_h$. The proof is completed.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm-gen-lsc-of-card-geo-fiber}]
	%Embed $X$ and $Y$ in affine spaces $\mathbb{A}^m_k$ and $\mathbb{A}^n_k$, then $X$ can be identified with the graph $\{(x,y)\in X\times_k Y| y=f(x)\}$ and $f$ can be identified with the projection map $\pi: \mathbb{A}^{m+n}_k\to \mathbb{A}^{n}_k$. %Explained in EGA I, Corollary 5.3.11

	%So without loss of generality we may assume $X=V(I)\hookrightarrow \spec k[\bs{y},\bs{x}]$ and $Y=V(J)\hookrightarrow \spec k[\bs{y}]$, where $J=I\cap k[\bs{y}]$ and $f$ is the projection from $\spec k[\bs{y},\bs{x}]$ to $\spec k[\bs{y}]$. 

%	Choose a monomial order $T_x$ (resp. $T_y$) in $\bs{x}$ (resp. $T_y$), and let $T=T_x>T_y$ be the block order. Compute a reduced Gr\"{o}bner basis $\mathcal{G}$ for $I$ with respect to $T$.
	%By Lemma \ref{lem-specialization-of-GB}, there is a non-zero $w\in k[\bs{y}]/J$ such that $(k[\bs{y},\bs{x}]/I)_w$ is a free $(k[\bs{y}]/J)_w$-module of finite rank (because $f$ is generically finite), and we can choose the basis to be $\mathscr{B}=\{\bs{x}^\alpha |\bs{x}^\alpha\notin \ideal{\{\lm_{T_x}(g)|g\in\mathcal{G}\backslash J \}}\}$.
	Let $X=\spec B$ and $Y=\spec A$, then $B$ is a free $A$-module of finite rank via the morphism, choose a basis $\{b_i\}$ for $B$.

	By Definition \ref{def-para-HQF} and Lemma \ref{lem-specialization-of-para-HQF}, the relative Hermite Quadratic Form specializes to all $p\in Y$, and Corollary \ref{cor-rel-multi-HQF} shows that the rank of Hermite Quadratic Form specialized at $p$ is equal to $\#X_{\overline{p}}$. Let $H=(\tr L_{b_ib_j})_{b_i,b_j\in \mathscr{B}}$, then $\rank H(p)< r$ if and only if all the $r$-minors of $H(p)$ vanish. Let $I_r$ be the ideal in $A$ generated by all $r$-minors of $H$, then $\{p\in Y|\rank H(p)\leq r\}=V(I_{r+1})$ is closed, i.e.\ $y\mapsto \# X_{\overline{y}}$ is lower semi-continuous on $Y$. By replacing $H$ with $H_h$, we can show the same for $y\mapsto \#U_{\overline{y}}$. This completes the proof.
\end{proof}

\begin{remark}
	Actually, Theorem \ref{thm-gen-lsc-of-card-geo-fiber} is a special case of a Grothendieck theorem \cite[Proposition 15.5.9]{grothendieck1966elements}, which states for a quasi-finite separated flat morphism locally of finite presentation between schemes, using non-constructive techniques like Stein factorization. 
\end{remark}

