\section{The Geometry of Cylindrical Algebraic Decomposition}\label{sect-geometric-cad}
Throughout this section, $k$ is an ordered field and $R$ is the real closure of $k$. Let $C=R(i)=R[x]/\ideal{x^2+1}$ be the algebraic closure of $R$. 

We recall the following two basic facts in real algebraic geometry, which are about semi-algebraic connectedness and continuity of roots, respectively.

\begin{lemma}[{\cite[Proposition 3.12]{basu2008algorithms}}]\label{lem-locally-constant-function-is-constant}
	If $S$ is a semi-algebraically connected semi-algebraic set	and $f : S \to R$ is a locally constant semi-algebraic function (i.e.\ given $x \in S$,	there is an open $U\subset S$ such that for all $y \in U$, $f(y) = f(x)$), then $f$ is a constant.
\end{lemma}

%If $V$ is an $R$-variety, then the Euclidean topology on $V(R)$ can be defined intrinsically, independent of the embedding \cite[Remark 3.2.15]{bochnak2013real}. If $V$ is a $C$-variety, then by the Weil Restriction, it can be considered as an $R$-variety so there is a natural Euclidean topology on the closed points $V(C)$ too. Intuitively speaking, every algebraic set in $C^n$ can be thought as an algebraic set in $R^{2n}$, by separating the real and the imaginary parts.

%Now the continuity of roots in the coefficients can be precisely stated using the Euclidean topology. 
\begin{theorem}[{\cite[Theorem 5.12]{basu2008algorithms}}, Continuity of Roots]\label{thm-continuity-of-roots}	
	Let $P\in R[x_1,\ldots,x_n]$ and let $S$ be a semi-algebraic subset of $R^{n-1}$. Assume that $\deg_{x_n}(P)$ is constant on $S$ and that for some $a'\in S$, $z_1,\ldots,z_j$ are the distinct roots of $P(a';x_n)$ in $C=R[i]$, with multiplicities $\mu_1,\ldots,\mu_j$, respectively. 

	If the open disks $B(z_i,r)\subset C$ are disjoint, then there is an open neighborhood $V$ of $a'$ such that for every $x'\in V\cap S$, the polynomial $P(x';x_n)$ has exactly $\mu_i$ roots, counted with multiplicities, in the disk $B(z_i,r)$, for $i=1,\ldots,j$.
\end{theorem}

\subsection{Geometric Delineability for a Variety}

In this subsection, we will extend Collins's notion of delineability to a variety. The goal is to show that a finite free morphism of $R$-varieties admits semi-algebraic sections on the regions that have a constant geometric fiber cardinality if it factors through the cylinder over the base. We will see that counting the geometric fiber lies at the heart of geometry of cylindrical algebraic decomposition.

%In this subsection, we will show that the geometric fiber classification can be used to classify the real fibers, which is in the heart of the geometry of cylindrical algebraic decomposition.
%\begin{lemma}[Multivariate Hermite Quadratic Form - Real Case]
%	Suppose $k$ is a subfield of $R$. $I$ is a zero-dimensional ideal of $k[x]$. Define Hermite Quadratic Form on $A=k[x]/I$:
%	$$H: \begin{array}{rcl}A \times A &\to& k\\ (f,g)&\mapsto& \tr L_{fg},\end{array}$$
%	then $\sign H=\# V_R(I\otimes_k R)$.
%\end{lemma}
\begin{lemma}[Rank-Signature Lemma]\label{lem-invariant-rank-implies-invariant-signature}
	If $S$ is a semi-algebraically connected semi-algebraic subset of $\mathop{\mathrm{Sym}}(R,n):=\{M\in R^{n\times n}| M_{ij}=M_{ji} \}$ (with the Euclidean topology inherited from $R^{n\times n}$) and all the matrices in $S$ are of the same rank, then all matrices in $S$ have the same signature.
\end{lemma}
\begin{proof}
	Define map 
	$$\chi:\begin{array}{rcl}
		S&\to& R^n \\
		M&\mapsto& (a_{n-1},a_{n-2},\ldots,a_0),
	\end{array}$$
	where $\lambda^n+\sum_{i=0}^{n-1} a_i \lambda^i$ is the characteristic polynomial of $M$. By some abuse of notations, we also use $\chi_M$ to denote the characteristic polynomial of $M$, since this would not cause any confusion. Because $M$ is symmetric and all the entries are in $R$, it is diagonalizable and all the eigenvalues are in $R$ \cite[Theorem 4.43]{basu2008algorithms}. Suppose all the matrices in $S$ are of the same rank $r$, then for all $M\in S$, there are exactly $r$ non-zero eigenvalues. %$$a_0=\cdots=a_{n-1-r}=0, a_{n-r}\ne 0.$$
	To show the signature is invariant, it suffices to show the number of positive eigenvalues (counted with multiplicity) is invariant now.

	 By Theorem \ref{thm-continuity-of-roots}, the continuity of roots in the coefficients, for all $M\in S$, there is a neighborhood $U\subseteq S$ of $M$ such that for all $M'\in U$, $\chi_M$ and $\chi_{M'}$ share the same number of positive roots, counted with multiplicity. Define function 
	 $$\psi:\begin{array}{rcl}
	 	S & \to & R \\
	 	%M &\mapsto& \sum\limits_{\substack{(\lambda-\lambda_i)^{d_i}||\chi_M,\\ \lambda_i>0}} d_i 
	 	M &\mapsto& \sum\limits_{\lambda>0} \nu_{\lambda}(\chi_M)
	 \end{array}$$
	that counts the number of positive roots with multiplicity, where $\nu_{\lambda}(\chi_M)$ is the order of vanishing of $\chi_M$ at $\lambda$. Then $\psi$ is a locally constant function. Because a locally constant semi-algebraic function defined on a semi-algebraically connected semi-algebraic set is a constant (see Lemma \ref{lem-locally-constant-function-is-constant}), it remains to show $\psi$ is a semi-algebraic function now.

	A polynomial $f$ has exactly $p$ distinct positive roots with multiplicity $d_1,\ldots,d_p$ is equivalent to 
	\begin{align*}
		(\exists x_1)\cdots(\exists x_p)\left(\left(\bigwedge_{i=1}^p x_i>0\right) \wedge \bigwedge_{i=1}^p\left(\bigwedge_{j=0}^{d_i-1}f^{(j)}(x_i)=0 \wedge f^{(d_i)}(x_i)\ne 0\right)\right.\\
		\wedge \left.(\forall y)\left(\left((y>0)\wedge (\bigwedge_{i=1}^p y\ne x_i)\right)\implies (f(y)\ne 0)\right)\right).
	\end{align*}
	So by the Tarski-Seidenberg principle \cite[Theorem 2.92]{basu2008algorithms}, 
	\begin{align*}
		C_{d_1,\ldots,d_p}:=\{(a_{n-1},\ldots,a_0)|\lambda^n+\sum_{i=0}^{n-1}a_i\lambda^i=0 \text{ has exactly }p\text{ positive roots}\\ \text{with multiplicity }d_1,\ldots,d_p \}
	\end{align*}
	is a semi-algebraic set. Then 
	\begin{align*}
		B_l:=\{(a_{n-1},\ldots,a_0)|\lambda^n+\sum_{i=0}^{n-1}a_i\lambda^i=0 \text{ has }l \text{ positive roots}\}\\
		=\bigcup_{d_1+\cdots+d_p=l}C_{d_1,\ldots,d_p}
	\end{align*} 
	is also semi-algebraic. So the graph of $\psi$ is just $\bigcup_{l=0}^n (\chi^{-1}(B_l)\times \{l\})$, which is clearly semi-algebraic. Therefore $\psi$ is a semi-algebraic function by definition. Hence $\psi$ is a constant function on $S$ and the signature of matrices in $S$ is invariant.


	%By the Budan-Fourier Theorem \cite[Theorem 2.46]{basu2008algorithms}, the number of positive roots of characteristic polynomial of $M$ is exactly the sign variation in the coefficients (because all the roots are real, see \cite[Remark 2.50]{basu2008algorithms}.)  If there are $M$, $M'$ such that the sign variation of $\chi(M)$ is different from $\chi(M')$, then by semi-algebraic connectedness, there is a (continuous semi-algebraic) path $p:[0,1]\to S$ such that $p(0)=M$ and $p(1)=M'$. 
\end{proof}
%\begin{remark}
%	In the proof of Lemma \ref{lem-invariant-rank-implies-invariant-signature}, we show that a symmetric matrix $M$ over $R$ has rank $\leq r$ if and only if the last $n-r$ coefficients of its characteristic polynomial vanish. This is a more compact description than ``all $r$-minors vanish''. One should not be surprised by this because every real algebraic set can be cut off by a single equation (for example, the sum of squares of the defining equations).
%\end{remark}

%The next theorem shows that by counting geometric fiber, we also learn information about the real fiber.
By counting geometric fiber, we also learn information about the real fiber, as shown in the theorem below.

\begin{theorem}[Geometric Fiber v.s.\ Real Fiber]\label{thm-invariant-number-of-complex-solutions-implies-invariant-number-of-real-solutions}
	Suppose $X=\spec B, Y=\spec A$ are two $R$-varieties and $f:X\to Y$ is a finite free $R$-morphism. Let $h\in B$. Consider the induced morphism of $R$-rational points $f_0: X(R)\to Y(R)$. Let $S\subseteq Y(R)$ be a semi-algebraically connected semi-algebraic set such that $\# (D(h))_{\overline{y}}$ is a constant for all $y\in S$, then $\# (f_0^{-1}(y)\cap D(h))$ is a constant over $S$.
	%Embed $A\otimes_R C$ and $B\times_R C$ in the affine space $C^m$ and $C^{m+n}$, suppose $S\subseteq R^m\cap V(A)$ is a semi-algebraically connected semi-algebraic set such that for all $p\in S$, the cardinality of fiber over $p$ is invariant, then the cardinality of the real fiber over $p$ is invariant too.
\end{theorem}
\begin{proof}
	Because we can define $H_{h^2}$, the relative Hermite Quadratic Form associated with $h^2$ of $B$ (Definition \ref{def-para-HQF}) and it specializes to all points in $\spec A$ (Lemma \ref{lem-specialization-of-para-HQF}). By Lemma \ref{lem-multi-HQF}, the rank of $H_{h^2}$ is invariant over $S$, since $D(h)=D(h^2)$. Then Lemma $\ref{lem-invariant-rank-implies-invariant-signature}$ tells us the signature of $H_{h^2}$ is also invariant over $S$. Therefore using Lemma \ref{lem-multi-HQF} again, we see that the cardinality of real fibers $\# (f_0^{-1}(y)\cap D(h))$ is invariant over $S$ (notice that $f_0^{-1}(y)=X_y(R)$).%$A\subseteq B$ is an integral extension of rings, so for any $q\in \spec B$, $q\cap A$ is maximal if and only if $q$ is maximal \cite[Corollary 4.17]{eisenbud2013commutative} and the fiber $X_y$ consists of closed points).
\end{proof}

