		%	\end{tikzcd}		
	%\end{center}
	Let $X$, $Y$ be affine $k$-varieties and $\pi: X\to Y$ is a $k$-morphism. Suppose $\pi$ factors through the cylinder $Y\times_k \mathbb{A}_k^1$:
	\begin{center}
		\begin{tikzcd}[column sep=small]
			X \arrow[rr, "\pi"]\arrow[dr,hook]& & Y \\
			& Y\times_k \mathbb{A}_k^1 \arrow[ur] & \\
		\end{tikzcd}
	\end{center}
	and $X\to Y\times_k \mathbb{A}_k^1$ is a closed immersion.
	Then we say $f:X\to Y$ is a \textbf{Cylindrical Projection}.
\end{definition}

The following lemma says a Cylindrical Projection is finite and free, if and only if $X$ can be cut out by a monic polynomial in the cylinder $Y\times_k \mathbb{A}_k^1=\mathbb{A}_Y^1$.
\begin{lemma}[{\cite[Prop. 4.1]{eisenbud2013commutative}}]\label{lem-f.g.-free-A-module-iff-principal}
	Let $A$ be a ring and let $J\lhd A[x]$ be an ideal in the polynomial ring in one variable over $A$. Let $B=A[x]/J$, and let $s$ be the image of $x$ in $B$.
	\begin{enumerate}[label=\alph*.]
		\item $B$ is generated by $\leq n$ elements as an $A$-module if and only if $J$ contains a monic polynomial of degree $\leq n$. In this case $B$ is generated by $1,s,\ldots,s^{n-1}$. In particular, $B$ is a finitely generated $A$-module if and only if $J$ contains a monic polynomial.
		\item $B$ is a finitely generated free $A$-module if and only if $J$ can be generated by a monic polynomial. In this case $B$ has a basis of the form $1,s,\ldots,s^{n-1}$.
	\end{enumerate}
\end{lemma}

The next theorem shows that, if $X\to Y$ is a finite free Cylindrical Projection of $R$-varieties, then the real fibers are continuous functions on the base.

\begin{theorem}\label{thm-freeness-implies-geometric-delineability}
	Suppose $\pi:X\to Y$ is finite free Cylindrical Projection between affine $R$-varieties. Let $S\subseteq Y(R)$ be a semi-algebraic connected semi-algebraic set on which $\#X_{\overline{y}}$ is a constant, then there are semi-algebraic continuous functions $\xi_1,\ldots,\xi_l:S\to \pi^{-1}_0(S)$ such that $\pi\circ \xi_i=\mathrm{id}_S$ and $\{\xi_i(y)\}_{i=1}^{l}$ is the real fiber of $y$ in $X(R)$.
\end{theorem}
