To show our theory does generalize Collins's original cylindrical algebraic decomposition, we will show that \cite[Theorem 1]{collins1975quantifier} is a special case of Theorem \ref{thm-freeness-implies-geometric-delineability}.

\begin{definition}[Collins's Delineability]\label{def-collins-delineability}
	Let $f(x_1,\ldots,x_r)\in R[x_1,\ldots,x_r]\, (r\geq 2)$, and let $S\subseteq R^{r-1}$ be a semi-algebraic set. The roots of $f$ are delineable over $S$ and that $\xi_1,\ldots,\xi_k\, (k\geq 0)$ delineate the real roots of $f$ over $S$ if the following conditions are satisfied:
	\begin{enumerate}
		\item There are $m\geq k$ positive integers $\mu_i$ such that if $(a_1,\ldots,a_{r-1})\in S$ then $f(a_1,\ldots,a_{r-1},x)=0$ has exactly $m$ distinct roots (in $C$), with multiplicities $\mu_1,\ldots,\mu_m$.
		\item $\xi_1<\xi_2<\cdots<\xi_k$ are semi-algebraic continuous functions from $S$ to $R$.
		\item If $(a_1,\ldots,a_{r-1})\in S$ then $\xi_i(a_1,\ldots,a_{r-1})$ is a root of $f(a_1,\ldots,a_{r-1},x)=0$ of multiplicity $\mu_i$ for all $1\leq i\leq k$ and $(a_1,\ldots,a_{r-1})\in S$.
		\item If $(a_1,\ldots,a_{r-1})\in S$, $b\in R$ and $f(a_1,\ldots,a_{r-1},b)=0$ then $b=\xi_i(a_1,\ldots,a_{r-1})$ for some $i$.
	\end{enumerate}
\end{definition}
\begin{corollary}[Collins {cf.\cite[Theorem 1]{collins1975quantifier}}]\label{cor-collins-thm-1}
	Let $f(x_1,\ldots,x_r)$ be an $R$-polynomial, $r\geq 2$. Let $S$ be a semi-algebraically connected semi-algebraic subset of $R^{r-1}$. If $\lc_{x_r}(f)$ has no zero on $S$ and the number of distinct roots of $f$ in $x_r$ is invariant on $S$, then the roots of $f$ are delineable on $S$.
\end{corollary}
\begin{proof}
	Set $A=R[x_1,\ldots,x_{r-1}]$ and $B=R[x_1,\ldots,x_{r}]/\ideal{f}.$ Let $X=\spec B$ and $Y=\spec A$. There is a natural morphism $\pi:X\to Y$ induced by the ring map $R[x_1,\ldots,x_{r-1}]\to R[x_1,\ldots,x_{r}]/\ideal{f}$. If $\deg_{x_r}(f)=0$ then we are already done. So let us suppose $\deg_{x_r}(f)>0$ and set $w=\lc_{x_r}(f)$, then $B_w$ is a free $A_w$-module of finite rank (generated by monomials $1,x_r,\ldots,x_r^{\deg_{x_r}(f)-1}$). In other words, $\spec B_w\to \spec A_w$ is a finite free morphism. %By Theorem \ref{thm-invariant-number-of-complex-solutions-implies-invariant-number-of-real-solutions}, we know that the cardinality of real fibers $s=\# \pi_0^{-1}(y)$ is invariant on $S$, where $\pi_0:X(R)\to Y(R)$ is the map on the $R$-rational points induced by $\pi$. Define $\xi_1,\ldots,\xi_s:S\to R$ to be the maps sending $y\in S$ to the largest, the second largest, ..., the least root of $f(s,x_r)=0$, then $\xi_i$ are semi-algebraic functions by the definition. Moreover, they are continuous by the continuity of the roots and each is of a constant multiplicity. So the roots of $f$ are delineable on $S$.
	The rest immediately follows from Theorem \ref{thm-freeness-implies-geometric-delineability} (note that the constant multiplicity is implied in the proof of Theorem \ref{thm-freeness-implies-geometric-delineability}.)
\end{proof}

%Motivated by Collins's Delineability, we will define Geometric Delineability for a basic constructible set.
Motivated by Collins's Delineability, we will define Geometric Delineability for a variety.
\begin{definition}[Geometric Delineability I]\label{def-geo-delineability-part-1}
	Let $T=V(f_1,\ldots,f_s)$ be a variety in $\mathbb{A}^{n+1}_R$, where $f_i\in R[x_1,\ldots,x_{n+1}]$. Let $S$ be a semi-algebraically connected semi-algebraic set in $R^n$. We say $T$ is \textbf{(strictly) geometrically delineable} over $S$, if the following conditions holds:
	\begin{enumerate}
		\item For all $a=(a_1,\ldots,a_n)\in S$, the number of distinct solutions (in $C$) of $$f_1(a;x_{n+1})=\cdots=f_s(a;x_{n+1})=0$$
		is finite and invariant.
		\item There are semi-algebraic continuous functions $\xi_1,\ldots,\xi_k: S\to T(R)$ such that $\pi\circ\xi_i=\mathrm{id}_S$, where $\pi: \mathbb{A}^{n+1}_R\to \mathbb{A}^{n}_R$ is the projection map. Additionally, we can require $\xi_i$ to be arranged in strictly ascending order in the last coordinate.
		\item If $t\in T(R)\cap (S\times R^1)$, then there is some unique $1\leq i\leq k$ such that $t=\xi_i(\pi(t))$.
	\end{enumerate}
	The semi-algebraic continuous functions $\xi_i$ are called the \textbf{sections} of $T$ over $S$.

	We make the convention that if $T\cap (S\times R^1)=S\times R^1$ (i.e., $T$ is a cylinder over $S$), then we say $T$ is \textbf{(vacuously) geometrically delineable} over $S$.
\end{definition}
