We can rephrase Theorem \ref{thm-freeness-implies-geometric-delineability} in our new terminology by just saying $X$ is geometrically delineable over $S$.
\begingroup
\def\thetheorem{\ref{thm-freeness-implies-geometric-delineability}}
\begin{theorem}[Reformulation in Geometric Delineability]
	If $\pi:X\to Y$ is a finite free Cylindrical Projection between affine $R$-varieties. Let $S\subseteq Y(R)$ be a semi-algebraic connected semi-algebraic set such that $\# X_{\overline{y}}$ is invariant over $S$, then $X$ is geometrically delineable over $S$.
\end{theorem}
\addtocounter{theorem}{-1}
\endgroup
\begin{remark}
	While Collins's delineability in \cite{collins1975quantifier} requires constant multiplicity in each section, this requirement is dropped in our definition of geometric delineability. However, these two notions are equivalent for a finite free cylindrical projection from a hypersurface (recall the proof of Theorem \ref{thm-freeness-implies-geometric-delineability}). The constant multiplicity is never used in the c.a.d.\ construction, so we do not include it in the definition. There is an alternative definition of delineability from Arnon, Collins and McCallum that do not require a constant geometric fiber cardinality or a constant multiplicity \cite{arnon1984cylindrical}.
\end{remark}

We propose Algorithm \ref{algo-PROJ1} to compute the regions over which a variety $V(I)$ is geometrically delineable. The extra output will be useful later (Lemma \ref{lem-cad-set-operation}).

\begin{algorithm}[htbp]
	\KwIn{An ideal $I\unlhd k[\bs{y},x]$; Here, $k$ is a subfield of $R$.}
	\SetKwInput{KwOut}{Output 1}
	\KwOut{A list of pairs of ideals in $k[\bs{y}]$: $\{(J_i,J_i')\}$ such that $V(I)$ is geometrically delineable over any semi-algebraically connected semi-algebraic set contained in $V(J_i)\backslash V(J_i').$}
	\SetKwInput{KwOut}{Output 2}
	\KwOut{An extra list of ideals $\{\mathfrak{a}_i\}$ in $k[\bs{y}]$. For each tuples $(J_i,J_i')$ in the Output 1, the locally closed set $V(J_i)\backslash V(J_i')$ is a finite Boolean combination of the sets $\{V(\mathfrak{a}_i)\}$ (using $\cap,\cup,\backslash$).}
	\caption{UnramifiedStratification}\label{algo-PROJ1}

	Compute a reduced Gr\"{o}bner basis $\mathcal{G}$ of $I$ w.r.t some block order $x>T_{\bs{y}}$\;
	$\mathcal{G}_y:=\mathcal{G}\cap k[\bs{y}],\mathcal{G}_x:=\mathcal{G}\backslash\mathcal{G}_y $\;

	\If(\tcp*[f]{$V(I)$ is a cylinder}){$\mathcal{G}_x=\varnothing$}{\Return{$\{(\ideal{\mathcal{G}_y},\ideal{1})\},\{\ideal{\mathcal{G}_y}\}$\label{line-proj1-not-finite}} \tcp*{Vacuously geometrically delineable}}

	$w:=\prod_{f\in \mathcal{G}_x} \lc_{x}(f)$ \tcp*{Effective Generic Freeness}

	$H:=\mathtt{HermiteQuadraticForm}(\mathcal{G}), s:=\mathtt{sizeof}(H)$\; %\tcp*{Compute the parametric Hermite Quadratic Form}

	$o_1:=\{(\ideal{\mathcal{G}_y}+\mathtt{minors}(i+1,H),\ideal{\mathcal{G}_y}+\mathtt{minors}(i,H)\cdot \ideal{w})\}_{i=0}^s$
	\tcc*{$\mathtt{minors}(i,H)$ computes the ideal generated by all $i$-minors in $H$. It returns $\ideal{1}$ when $i=0$, and $\ideal{0}$ when $i=s+1$.}
	$o_2:=\{\ideal{\mathcal{G}_y}+\mathtt{minors}(i+1,H)\}_{i=0}^s$\;

	\ForEach(\tcp*[f]{Recursively look at the non-free locus}){$f\in \mathcal{G}_x$}{
		$w_0:=\lc_{x}(f)$\;
		\If{$\ideal{\mathcal{G}_y}+\ideal{w_0}\neq (I+\ideal{w_0})\cap k[\bs{y}]$}{
			$o_2:=o_2\cup \{\ideal{\mathcal{G}_y}+\ideal{w_0}\}$\; \label{line-proj1-not-dorminant}
		}
		Merge $o_1$ and $o_2$ with $\mathtt{UnramifiedStratification}(I+\ideal{w_0})$\;		
	}

	\Return{$o_1$, $o_2$}\;

\end{algorithm}

\begin{algorithm}[htbp]
	\KwIn{A reduced Gr\"{o}bner Basis $\mathcal{G}$ of an ideal $I\unlhd k[\bs{y},x]$ with respect to some block order $x>T_{\bs{y}}$.}
	\KwOut{The relative Hermite Quadratic Form $H$.}
	\caption{HermiteQuadraticForm}\label{algo-Hermite-Quadratic-Form}

	$\mathcal{G}_y:=\mathcal{G}\cap k[\bs{y}],\mathcal{G}_x:=\mathcal{G}\backslash\mathcal{G}_y $\;
	Choose $f\in \mathcal{G}_x$ of the minimal degree, set $w=\mathtt{LC}_x(f)$\;
	$s:=\deg f$ \tcp*{The monomial basis $\mathscr{B}=\{1,x,\ldots,x^{s-1}\}$}
	\For{$i:=0$ \KwTo $s-1$}{
		\For(\tcp*[f]{Compute the trace of $L_{x^{i+j}}$}){$j:=0$ \KwTo $s-1$}{ 
			$H_{i,j}:=0$\;
			\For(\tcp*[f]{Compute the image of $x^k$ under $L_{x^{i+j}}$}){$k:=0$ \KwTo $s-1$}{
				$r:=\mathtt{PolynomialDivisionRemainder}(x^{i+j+k},f)$
				\tcp*{Polynomial Division over $k(\bs{y})[x]$. This does the NormalForm computation}
				$H_{i,j}:=H_{i,j}+\mathtt{coef}(r,k)$ \tcp*{the $k$-th coefficient of $r$}
			}
		}
	}
	Multiply $H$ by a suitable power of $w$ so entries of $H$ are in $k[\bs{y}]$;\\
	\tcc{The entries of $H$ are in $k[y]_w$, so there is some power $w^\ell$ that cancels all the denominators. This does not affect the rank of $H$.}
	\Return{$H$}\;
\end{algorithm}

\begin{remark}
	The reason for this name ``\texttt{UnramifiedStratification}'' is that the cardinality of geometric fiber remains the same over the regions defined by each pair of ideals in Output 1, so the fiber does not ``ramify'' into different branches.
	It should be also noted that, the regions defined by Output 1 are not necessarily disjoint.
\end{remark}



