Therefore, to show the joint geometric delineability of a family of varieties $\{V_i\}$, it suffices to show the geometric delineability of each variety $V_i$ and intersection $V_i\cap V_j$ for each pair of varieties. The next theorem shows that we can conclude the geometric delineability of a closed subscheme $Z\subseteq X$ (an intersection for example) from a weaker condition, if we have the geometric delineability of $X$.

\begin{theorem}\label{thm-geo-del-of-closed-subscheme}
	Suppose $\pi:X\to Y$ is a finite free Cylindrical Projection of $R$-varieties. Let $Z$ be a closed subscheme of $X$. If $\pi|_Z:Z\to Y$ is also finite free and $S\subseteq Y(R)$ is a semi-algebraically connected semi-algebraic set satisfying that $\# X_{\overline{y}}$ is a constant for all $y\in S$, then $\# Z_{\overline{y}}$ is also a constant for all $y\in S$.

	As a corollary, $Z$ is geometrically delineable over $S$.
\end{theorem}
\begin{proof}
	Let $Y=\spec A$. Since $\pi$ is a finite free morphism, $X$ can be identified as $\spec A[x]/\ideal{f}$ for some monic $f\in A[x]$ by Lemma \ref{lem-f.g.-free-A-module-iff-principal}. Because $\pi|_Z: Z\to Y$ is finite and free, $Z\cong \spec A[x]/\ideal{g}$ for some monic $g\in A[x]$ by Lemma \ref{lem-f.g.-free-A-module-iff-principal} again.

	Now embed $Y$ in some affine space $\mathbb{A}_R^n=\spec R[y_1,\ldots,y_n]$ as a closed subscheme, so the monic polynomials $f,g$ can be taken from $R[y_1,\ldots,y_n,x]$ by a slight abuse of notations. Let $(c_1,\ldots,c_n)\in S$ and let $x_1,\ldots,x_l\in C$ be the distinct solutions of $f(c_1,\ldots,c_n;x)=0$ in $C$. Denote the multiplicity of $x_i$ as a root of $f(c_1,\ldots,c_n;x)=0$ by $\mu_i$. Notice that $Z$ is a subscheme of $X$, so by renumbering the roots if necessary, we can assume that $x_1,\ldots,x_m$ are the all distinct solutions of $g(c_1,\ldots,c_n;x)=0$ in $C$ ($0\leq m\leq l$). Denote the multiplicity of $x_i$ as a root of $g(c_1,\ldots,c_n;x)=0$ by $\lambda_i$.

	Choose disjoint open Euclidean neighborhoods $U_1,\ldots,U_l$ for $x_1,\ldots,x_l$. By the continuity of roots (Theorem \ref{thm-continuity-of-roots}), there is a open Euclidean neighborhood $U$ of $(c_1,\ldots,c_n)$ such that for all $(c'_1,\ldots,c'_n)\in U\cap S$, the equation $f(c'_1,\ldots,c'_n;x)=0$ has exactly $\mu_i$ solutions, counting multiplicity in $U_i$ for all $1\leq i\leq l$, and the equation $g(c'_1,\ldots,c'_n;x)=0$ has exactly $\lambda_i$ solutions, counting multiplicity in $U_i$ for all $1\leq i\leq m$.

	Because $\# X_{\overline{y}}$ is a constant over $S$, for all $(c'_1,\ldots,c'_n)\in U\cap S$, the equation $f(c'_1,\ldots,c'_n;x)=0$ should have only one solution of multiplicity $\mu_i$ in $U_i$ for all $1\leq i \leq l$. Notice that the roots of $g(c'_1,\ldots,c'_n;x)=0$ are also roots of $f(c'_1,\ldots,c'_n;x)=0$, hence the equation $g(c'_1,\ldots,c'_n;x)=0$ have only one solution of multiplicity $\lambda_i$ in $U_i$ for all $1\leq i\leq m$, and these are all the roots of $g$ by counting degree. Therefore for all $(c'_1,\ldots,c'_n)\in U\cap S$, the number of distinct complex solutions to the equation $g(c'_1,\ldots,c'_n;x)=0$ is a constant $m$. In other words, $\# Z_{\overline{y}}$ is a locally constant function on $S$. It is easy to show that this is a semi-algebraic function using an argument similar to Lemma \ref{lem-invariant-rank-implies-invariant-signature}. So by Lemma \ref{lem-locally-constant-function-is-constant}, $\# Z_{\overline{y}}$ is a constant on $S$.

	The last assertion follows immediately from Theorem \ref{thm-freeness-implies-geometric-delineability}.
\end{proof}

\begin{corollary}\label{cor-geo-del-of-closed-subscheme}
	Suppose $X,Z$ are closed subschemes of $\mathbb{A}_R^{n+1}$ and $Z$ is a closed subscheme of $X$. Let $Y,W$ be affine subschemes of $\mathbb{A}_R^n$ and let $\pi:\mathbb{A}_R^{n+1}\to \mathbb{A}_R^n$ be the projection map (a subscheme is an open subscheme of a closed subscheme). If $X\times_{\mathbb{A}_R^n} Y\to Y$ and $Z\times_{\mathbb{A}_R^n} W\to W$ are finite free morphisms, and $S\subseteq (Y\cap W)(R)$ is a semi-algebraically connected semi-algebraic set on which $X_{\overline{y}}$ is a constant, then $Z$ is geometrically delineable over $S$.
\end{corollary}
\begin{proof}
	We have the following commutative diagram.
	\begin{center} 
		\begin{tikzcd}[scale cd=1.0]
				& Z\times_{\mathbb{A}_R^n} (Y\cap W) \arrow[dl,hook,"closed"{rotate=18,above}]\arrow[dr,phantom,"\square"]\arrow[r] \arrow[d] & Z\times_{\mathbb{A}_R^n} W \arrow[d] \\
			X\times_{\mathbb{A}_R^n} (Y\cap W) \arrow[r]\arrow[dr,phantom,"\square"]\arrow[d] & Y\cap W \arrow[r]\arrow[dr,phantom,"\square"]\arrow[d] & W \arrow[d] \\
			X\times_{\mathbb{A}_R^n} Y \arrow[r] & Y \arrow[r] & \mathbb{A}_R^n
		\end{tikzcd}
	\end{center}
	Notice that finite free morphisms are stable under base change, so $Z\times_{\mathbb{A}_R^n} (Y\cap W)\to Y\cap W$ and $X\times_{\mathbb{A}_R^n} (Y\cap W)\to Y\cap W$ are also finite free morphisms. Applying Theorem \ref{thm-geo-del-of-closed-subscheme} to the upper-left triangle in the diagram completes the proof.
\end{proof}

