\KwOut{An extra list of ideals $\{\mathfrak{a}_i\}$ in $k[\bs{y}]$. For each tuples $(J_i,J_i')$ in the Output 1, the locally closed set $V(J_i)\backslash V(J_i')$ is a finite Boolean combination of the sets $\{V(\mathfrak{a}_i)\}$ (using $\cap,\cup,\backslash$)}
\caption{FreeStratification}\label{algo-PROJ2}

Compute a reduced Gr\"{o}bner basis $\mathcal{G}$ of $I$ w.r.t some block order $x>T_{\bs{y}}$\;
$\mathcal{G}_y:=\mathcal{G}\cap k[\bs{y}],\mathcal{G}_x:=\mathcal{G}\backslash\mathcal{G}_y $\;

\If(\tcp*[f]{$V(I)$ is a cylinder}){$\mathcal{G}_x=\varnothing$}{\Return{$\{(\ideal{\mathcal{G}_y},\ideal{1})\},\{\ideal{\mathcal{G}_y}\}$\label{line-proj2-not-finite}} \tcp*{Clearly a free morphism}}

$w:=\prod_{f\in \mathcal{G}_x} \lc_{x}(f)$ \tcp*{Effective Generic Freeness}

%$H:=\mathtt{HermiteQuadraticForm}(\mathcal{G}), s:=\mathtt{sizeof}(H)$\; %\tcp*{Compute the parametric Hermite Quadratic Form}

$o_1:=\{(\ideal{\mathcal{G}_y},\ideal{\mathcal{G}_y}+ \ideal{w})\}$;\\
\tcc{Notice that $V(\ideal{\mathcal{G}_y})\backslash V(\ideal{\mathcal{G}_y}+ \ideal{w})=\spec k[\bs{y}]_w/\ideal{\mathcal{G}_y}_w$ is affine. Thus it makes sense to say the projection is free on this set.}
$o_2:=\{\ideal{\mathcal{G}_y}\}$\;

\ForEach(\tcp*[f]{Recursively look at the non-free locus}){$f\in \mathcal{G}_x$}{
	$w_0:=\lc_{x}(f)$\;
	\If{$\ideal{\mathcal{G}_y}+\ideal{w_0}\neq (I+\ideal{w_0})\cap k[\bs{y}]$}{
		$o_2:=o_2\cup \{\ideal{\mathcal{G}_y}+\ideal{w_0}\}$\; \label{line-proj2-not-dorminant}
	}
	Merge $o_1$ and $o_2$ with $\mathtt{FreeStratification}(I+\ideal{w_0})$\;		
}

\Return{$o_1$, $o_2$}\;
\end{algorithm}

\begin{theorem} \label{thm-correctness-of-Proj2}
	%Algorithm \ref{algo-Proj2} is correct and terminates.
	Algorithm \ref{algo-PROJ2} terminates. For each tuples $(J_i,J_i')$ in the Output 1, the projection is free over $V(J_i)\backslash V(J_i')$.

	Moreover, for each tuples $(J_i,J_i')$ in the Output 1, the locally closed set $V(J_i)\backslash V(J_i')$ can be obtained by finite intersections, unions and differences of varieties defined by the ideals $\{\mathfrak{a}_i\}$ in the Output 2. %Also, the union of varieties \{$V(\mathfrak{a}_i)$\} is the scheme-theoretic image $V(I\cap k[\bs{y}])$.
\end{theorem}
\begin{proof}
	The proof is identical to Theorem \ref{thm-correctness-of-algo-PROJ1}. 	
\end{proof}

