\subsection{The Algorithm}
%We assume the existence of an algorithm $\mathtt{Partition1D}$ that partition $R^1$ into intervals and points such that a given collection of polynomials is sign-invariant on each point and each interval. 
We assume that field operations in $R$ ($+,-,\times,/,<,=$) can be effectively performed, so the real roots of a univariate equation can be effectively represented and computed (e.g.\ $R=\mathbb{R}_{\mathrm{alg}}$). Solving equations can be done by the real root isolation algorithm when $R$ is archimedean (see \cite[Algorithm 10.55]{basu2008algorithms}) and Thom Encoding if $R$ is a general real closed field (see \cite[Algorithm 10.105, 10.106]{basu2008algorithms}).

%We shall define cylindrical algebraic decomposition now. Our definition is almost the same as \cite[Definition 5.1]{basu2008algorithms}, but some adjustments are made.

The following simple lemma is crucial in our algorithm for cylindrical algebraic decomposition.

\begin{lemma}\label{lem-cad-set-operation}
	Let $\mathcal{T}=\{T_i\}$ be a finite family of semi-algebraic sets in $R^n$, and $\mathfrak{D}$ is a cylindrical algebraic decomposition adapted to $\mathcal{T}$. Suppose $\mathcal{T}'=\{T'_j\}$ is another finite family of semi-algebraic sets in $R^n$ such that each $T'_j$ can be obtained by a finite number of intersections, unions, and differences of elements in $\mathcal{T}$. Then $\mathfrak{D}$ is also a cylindrical algebraic decomposition adapted to $\mathcal{T}'$.
\end{lemma}
\begin{proof}
	It suffices to prove that for any $T_i,T_j\in \mathcal{T}$, $\mathfrak{D}$ is also adapted to $\mathcal{T}\cup \{T_i\cap T_j, T_i\cup T_j, T_i\backslash T_j\}$.

	To see this, write $T_i=\cup_{\alpha\in \Lambda} S_{\alpha}$ and $T_j=\cup_{\alpha\in \Lambda'} S_{\alpha}$ as unions of disjoint cells of level $n$. Then $T_i\cup T_j=\cup_{\alpha\in \Lambda\cup \Lambda'} S_{\alpha}$ is a union of cells of level $n$. Similarly $T_i\cap T_j=\cup_{\alpha\in \Lambda\cap \Lambda'} S_{\alpha}$ and $T_i\backslash T_j=\cup_{\alpha\in \Lambda\backslash \Lambda'} S_{\alpha}$.
\end{proof}

\begin{algorithm}[htbp]
	\KwIn{A list of ideals $\{I_k\}_{k=1}^s$ in $k[\bs{y},x]$.}
	\SetKwInput{KwOut}{Output 1}
	\KwOut{A list of pairs of ideals in $k[\bs{y}]$: $\{(J_i,J_i')\}$.}
	\SetKwInput{KwOut}{Output 2}
	\KwOut{An extra list of ideals $\{\mathfrak{a}_i\}$ in $k[\bs{y}]$.}	
	\caption{CADProjection}\label{algo-CAD-Projection}
	$o_1=\varnothing, o_2=\varnothing$\;
	\For{$k:=1$ \KwTo $s$}{
			Merge $o_1,o_2$ with $\mathtt{UnramifiedStratification}(I_k)$
		}
	\For{$k:=1$ \KwTo $s$}{
			\For{$j:=1$ \KwTo $k-1$}{Merge $o_1,o_2$ with $\mathtt{FreeStratification}(I_j+I_k)$\;}
		}
	\Return{$o_1,o_2$}\;
\end{algorithm}

Algorithm \ref{algo-CAD-Projection} reduces a higher-dimensional c.a.d.\ computation to a lower-dimensional c.a.d.\ computation. It can be thought as an adaptation of Projection Operator to the geometric context.

\begin{theorem}\label{thm-CAD-lifting}
	Suppose $\{V(I_k)\}$ is a finite family of varieties in $\mathbb{A}_R^n$. A cylindrical algebraic decomposition $\mathfrak{D}'$ adapted to varieties defined by Output 2 of Algorithm \ref{algo-CAD-Projection}, $\mathtt{CADProjection}(\{I_k\})$ can be lifted to a cylindrical algebraic decomposition $\mathfrak{D}$ adapted to $\{V(I_k)\}$.
\end{theorem}
\begin{proof}
	Observe that cells in a cylindrical algebraic decomposition are always semi-algebraically connected, because a cell of level $>1$ is either a graph of a semi-algebraic continuous function defined over its silhouette, or a band between two graphs and a cell of level $1$ is either an interval or a point, so our assertion follows from an easy induction. 

	Using Lemma \ref{lem-cad-set-operation}, it suffices to prove that a cylindrical algebraic decomposition $\mathfrak{D}'$ adapted to the family of constructible sets $\{V(J_i)\backslash V(J_i')\}$ can be lifted to a cylindrical algebraic decomposition $\mathfrak{D}$ of $\{V(I_k)\}$, where $\{(J_i,J_i')\}$ is the Output 1 (recall Theorem \ref{thm-correctness-of-algo-PROJ1} and Theorem \ref{thm-correctness-of-Proj2}).

	Let $S$ be a level $n-1$ cell of $\mathfrak{D}'$. For each $I_k$, since $\mathtt{CADProjection}$ contains the Output 1 of $\mathtt{UnramifiedStratification}(I_k)$, $V(I_k)$ is geometrically delineable over $S$ by Theorem \ref{thm-correctness-of-algo-PROJ1}.

	Next, we will show the joint geometric delineability of every pair of varieties $(V(I_j),V(I_{k}))$ on $S$. By Lemma \ref{lem-joint-geo-del-from-intersection}, it suffices to show the intersection $V(I_j)\cap V(I_{k})=V(I_j+I_{k})$ is geometrically delineable over $S$. We may assume that $V(I_j)$ is not a cylinder over $S$ and $V(I_j+I_k)$ is non-empty over $S$ (otherwise the geometric delineability is trivial). Because $\mathtt{CADProjection}$ contains the Output 1 of $\mathtt{FreeStratification}(I_j+I_k)$, the projection of $V(I_j+I_k)$ is free over $S$. By applying Corollary \ref{cor-geo-del-of-closed-subscheme}, we see that $V(I_j+I_k)$ is indeed geometrically delineable over $S$.

	It remains to write down a cylindrical algebraic decomposition $\mathfrak{D}$ adapted to $\{V(I_k)\}$. We start with $\mathfrak{D}'$ and construct the cells of level $n$ to complete $\mathfrak{D}$. Let $S$ be cell of level $n-1$ in $\mathfrak{D}'$, each $V(I_k)$ is geometrically delineable over $S$ and the sections are either disjoint or identical. So we let the image of sections to be the cells of level $n$ over $S$. If there is some $V(I_k)$ vacuously geometrically delineable over $S$ then we also let the bands between sections/above the highest section/below the lowest section to be the cells of level $n$ over $S$. Clearly the cells are disjoint semi-algebraic sets. Therefore $\mathfrak{D}$ is indeed a cylindrical algebraic decomposition adapted to $\{V(I_k)\}$.
\end{proof}

It is time to introduce our cylindrical algebraic decomposition Algorithm based on the geometric tools we developed (see Algorithm \ref{algo-GeometricCAD}). The correctness of Algorithm \ref{algo-GeometricCAD} is obvious from Theorem \ref{thm-CAD-lifting}.

\begin{algorithm}[htbp]
	\KwIn{A list of varieties $\{V(I_k)\}_{k=1}^s$ in $\mathbb{A}_R^n$.}
	\KwOut{A cylindrical algebraic decomposition adapted to $\{V(I_1),\ldots,V(I_s)\}$.}
	\caption{GeometricCAD}\label{algo-GeometricCAD}

	\If(\tcp*[f]{The Projection Phase}){$n>1$}{
		$o_1,o_2:=\mathtt{CADProjection}(\{I_k\}_{k=1}^s)$\;
		$\mathfrak{D}:=\mathtt{GeometricCAD}(o_2)$ \tcp*{Compute a c.a.d.\ adapted to $o_2$}
	}
	\Else{		
		$\mathfrak{D}:=\{\bullet\}$ \tcp*{A c.a.d.\ of $R^0$}
	}
	$\mathtt{cells}:=\varnothing $ \tcp*{The cells of level $n$, initialized to be an empty list}
	\ForEach(\tcp*[f]{The Lifting Phase}){cell $S$ of level $n-1$ in $\mathfrak{D}$}{
		Choose a sample point $s\in S\subseteq R^{n-1}$\;
		$b:=\mathtt{False}$\;
		$\xi:=\varnothing$ \tcp*{The sections over $S$, initialized to be an empty list}
		\ForEach{ideal $I_k$}{
			$\ideal{f}$:=Specialize $I_k$ with $s\in S$ \tcp*{After specialization, the result is a principal ideal in $R[x_n]$}
			\If{$f\neq 0$}{
				$\{\rho_i\}:=$ The real roots of $f$ in ascending order\;
				\ForEach{$\rho_i$}{Append $\{(s,x)|s\in S,\allowbreak x \text{ is the i-th least real root of } I_k \text{ specialized at } s\}$ to $\xi$\;}
			}
			\Else(\tcp*[f]{$V(I_k)$ is vacuously geometrically delineable over $S$}){$b:=\mathtt{True}$\;}
		}
		Sort $\xi$ in ascending order, $\mathtt{cells}:=\mathtt{cells}\cup \xi$\;
		\If{$b$}{Append the bands over $S$ to $\mathtt{cells}$\;}		
	}
	Append $\mathtt{cells}$ to $\mathfrak{D}$,
	\Return{$\mathfrak{D}$}\;

