				%\hline
				Level 4 & $(x+y)^2 u - y z$  & $V(0), V((x+y)^2 u - y z)$ \\
				%\hline
				Level 3 & $(x+y)^2,yz$ & $V(0), V(x+y), V(x+y,y z)$ \\
				%\hline
				Level 2 & $x+y,y$  & $V(0), V(x+y), V(x,y)$ \\
				%\hline
				Level 1 & $x$ & $V(0), V(x)$ \\
