\section{NMARL problem}\label{SectionProblemformulation}
%This section {\color{blue}introduces the model and the related knowledge of the NMARL problem.}
%This section introduces the NMARL problem and discusses the fundamental concepts and challenges associated with employing function approximation for solving the NMARL problem.
\subsection{Description of NMARL problem}\label{describednetworkMARL}
NMARL problem can be described as $\big(\mathcal{G}_{t}(\mathcal{N},\mathcal{E}_{t}),$ $\{\mathcal{S}_{i}\}_{i\in\mathcal{N}},\{\mathcal{A}_{i}\}_{i\in\mathcal{N}},\mathcal{P},\{r_{i}\}_{i\in\mathcal{N}},\zeta,\gamma\big)$, where the detailed description of each element is summarized as follows.
%where $\mathcal{N}=\{1,$ $\cdots,N\}$ represents the set of agents.
\par
\textbf{State and action}:
$\mathcal{S}_{i}$ and $\mathcal{A}_{i}$ represent the local state space and the local action space of agent $i\in\mathcal{N}$, respectively.
$s_{i}\in\mathcal{S}_{i}$ and $a_{i}\in\mathcal{A}_{i}$ denote the local state and local action of agent $i$, respectively.
Define the global state as $\bm{s} = (s_1, \cdots, s_N) \in \mathcal{S} = \mathcal{S}_1 \times \cdots \times \mathcal{S}_N$, and analogously define the global action as $\bm{a} = (a_1, \cdots, a_N) \in \mathcal{A} = \mathcal{A}_1 \times \cdots \times \mathcal{A}_N$.
$\bm{s}_t = (s_{1,t}, \cdots, s_{N,t})$ and $\bm{a}_t = (a_{1,t}, \cdots, a_{N,t})$ denote the global state and global action at time $t$, respectively.
%Define the global state as $\bm{s}=(s_{1},\cdots,s_{N})\in\mathcal{S}=\mathcal{S}_{1}\times\cdots\times\mathcal{S}_{N}$ and similarly the global action as $\bm{a}=(a_{1},\cdots,a_{N})\in\mathcal{A}=\mathcal{A}_{1}\times\cdots\times\mathcal{A}_{N}$.
%Moreover, $\bm{s}_{t}=(s_{1,t},\cdots,s_{N,t})$ and $\bm{a}_{t}=(a_{1,t},\cdots,a_{N,t})$ represent the global state and global action at time $t$, respectively.
\par
\textbf{State transition probability function}:
$\mathcal{P}(\bm{s}'|\bm{s},\bm{a}):\mathcal{S}\times\mathcal{A}\times\mathcal{S}\rightarrow[0,1]$ is the state transition probability function.
\par
\textbf{Reward function}:
$r_{i}(\bm{s},\bm{a}):\mathcal{S}\times\mathcal{A}\rightarrow\mathbb{R}$ denotes the local reward function for agent $i$.
Define $\bar{r}(\bm{s},\bm{a})=(1/N)\sum_{i=1}^{N}r_{i}(\bm{s},\bm{a})$ as the average reward function.
%Specially, define
%$r_{i,t}=r_{i}(\bm{s}_{t},\bm{a}_{t})$ as the instantaneous reward of agent $i$ at time $t$ and $\bar{r}_{t}=(1/N)\sum_{i=1}^{N}r_{i,t}$ as the average reward at time $t$.
Specifically, define $r_{i,t} = r_{i}(\bm{s}_{t}, \bm{a}_{t})$ as the instantaneous reward for agent $i$ at time $t$, and $\bar{r}_{t} = (1/N) \sum_{i=1}^{N} r_{i,t}$ as the average reward across all agents at time $t$.
Similar to the NMARL problems discussed in~\cite{Zhang2018ICML}-\cite{Dai2022TNNLS} and~\cite{Doan2019ICML}-\cite{Suttle2020IFAC}, we assume that each agent can access the global state-action, while the reward function remains private and is solely utilized by the respective agent.
\par
\textbf{Initial state distribution}: $\zeta$ is the distribution of the initial state $\bm{s}_{0}$
\par
\textbf{Discount factor}: $0<\gamma<1$ is the discount factor.
\par
Define the local policy of each agent $i$ as  $\pi_{\theta_{i}}=\pi_{i}(\cdot|\bm{s};\theta_{i})$, where $\theta_{i}$ represents the local policy parameter of agent $i$.
The joint policy of all agents is defined as $\bm{\pi}_{\bm{\theta}}(\cdot|\bm{s})=\prod_{i=1}^{N}\pi_{i}(\cdot|\bm{s};\theta_{i})$, where $\bm{\theta}=(\theta^{\top}_{1},\cdots,\theta^{\top}_{N})^{\top}$ is the joint policy parameter.
%\par
%In the NMARL problem, define $J(\bm{\pi_{\theta}})$ as
%the discounted average cumulative reward under joint policy $\bm{\pi_{\theta}}$, which is given by
In the NMARL problem, define $J(\bm{\pi_{\theta}})$ as the discounted average cumulative rewards under the joint policy $\bm{\pi_{\theta}}$, which is formulated as
\begin{align}\label{thedefinelongtermreturninMARL}
J(\bm{\pi_{\theta}})=(1-\gamma)\mathbb{E}_{\bm{s}\sim\zeta}\Big[\sum_{t=0}^{\infty}\gamma^{t}\bar{r}_{t}\Big|\bm{s}_{0}=\bm{s},\bm{a}_{t}\!\sim\!\bm{\pi}_{\bm{\theta}}(\cdot|\bm{s}_{t})\Big].
\end{align}
%\begin{align}\label{thelongtermreturninMARL}
%\max_{\bm{\pi}}J(\bm{\pi})=(1-\gamma)\mathbb{E}\Big[\sum_{t=0}^{\infty}\gamma^{t}r_{\mathrm{ave},t}|\bm{a}_{t}\sim\bm{\pi}(\cdot|s_{t})\Big],
%\end{align}
The objective of agents is to find the optimal policy to maximize $J(\bm{\pi_{\theta}})$, i.e.,
$\max_{\bm{\pi_{\theta}}}J(\bm{\pi_{\theta}})$.
\subsection{Policy gradient in NMARL problem}
In the NMARL problem, for any joint policy $\bm{\pi_{\theta}}$, define the global $Q$-function as
%$Q^{\bm{\pi_{\theta}}}(\bm{s},\bm{a})$ as
\begin{align}\label{theglobalQfunction}
Q^{\bm{\pi}_{\bm{\theta}}}(\bm{s},\bm{a})=(1-\gamma)\mathbb{E}_{\bm{\pi_{\theta}}}\Big[\sum_{t=0}^{\infty}\gamma^{t}\bar{r}_{t}\Big|\bm{s}_{0}=\bm{s},\bm{a}_{0}=\bm{a}\Big] \end{align}
and the Bellman evaluation operator $\mathcal{T}^{\bm{\pi}_{\bm{\theta}}}(\cdot)$ as
\begin{align}\label{theBellmanevaluationoperatorofpiTheta}
\big[\mathcal{T}^{\bm{\pi}_{\bm{\theta}}}(Q)\big](\bm{s},\bm{a})=&\mathbb{E}_{\bm{\pi_{\theta}}}\big[(1-\gamma)\bar{r}(\bm{s},\bm{a})+\gamma Q(\bm{s}',\bm{a}')\big|\notag\\
&\bm{s}'\sim\mathcal{P}(\cdot|\bm{s},\bm{a}),\bm{a}'\sim\bm{\pi_{\theta}}(\cdot|\bm{s}')\big],
\end{align}
where $Q\in\mathbb{R}^{|\mathcal{S}||\mathcal{A}|}$.
%where $r_{\mathrm{ave}}(s,\bm{a})=(1/N)\sum_{i=1}^{N}r_{i}(s,\bm{a})$ is the average reward of all agents.
