\begin{align}\label{thefixedpoint}
Q^{\bm{\pi}_{\bm{\theta}}}(\bm{s},\bm{a})=\big[\mathcal{T}^{\bm{\pi}_{\bm{\theta}}}(Q^{\bm{\pi}_{\bm{\theta}}})\big](\bm{s},\bm{a}),\forall(\bm{s},\bm{a})\in\mathcal{S}\times\mathcal{A}.
\end{align}
