\subsection{Approximate $Q$-function in NMARL problem}
%For convenience of expression in the subsequent, we represent the global state-action $(\bm{s},\bm{a})$ by $\bm{z}$.
%In contrast to the existing linear function approximation methods,
%a novel neural network (i.e., approximate function) is designed in Fig.~\ref{neuralnetwork} to approximate the global $Q$-function $Q^{\bm{\pi_{\theta}}}(\bm{z})$ in (\ref{theglobalQfunction}).
For the sake of concise expression in the subsequent discussion, we denote the global state-action pair $(\bm{s},\bm{a})$ by $\bm{z}$. Unlike existing linear function approximation methods, a novel neural network architecture (serving as the approximate function) is designed, as illustrated in Fig.~\ref{neuralnetwork}, to approximate the global $Q$-function $Q^{\bm{\pi_{\theta}}}(\bm{z})$ in (\ref{theglobalQfunction}).
\begin{figure}[!htb]
\centering
\includegraphics[width=0.7\hsize]{neural_network.pdf}
\caption{Two novel neural
networks for the approximate function and policy function, respectively.}\label{neuralnetwork}
\end{figure}
%As shown in Fig.~\ref{neuralnetwork}, the approximate function is represented as
As depicted in Fig.~\ref{neuralnetwork}, the approximate function is represented as
\begin{align}\label{origitwo-layerneuralnetworkofQfunction}
\widehat{Q}(\bm{z};W')\!=\!\frac{1}{(mN)^{p}}\sum_{r=1}^{mN}b_{r}\mathrm{ReLU}\big((W'_{r})^{\top}x_{\lfloor(r-1)/m\rfloor+1}\big),
\end{align}
where $x_{i}=\phi_{i}(\bm{s},a_{i})\in\mathbb{R}^{d}$ is the feature vector of state-action pair $(\bm{s},a_{i})$ and satisfies $\|x_{i}\|_{2}=1$,
$W'\in\mathbb{R}^{dmN}$ is the approximate parameter, $m$ is the number of neurons, and $\mathrm{ReLU}(\cdot)$ is the rectified linear unit activation function.
For any joint policy $\bm{\pi_{\theta}}$,
denote $\varsigma_{\bm{\pi_{\theta}}}$ as the stationary distribution of $\bm{z}$.
%{\color{blue}By the definition of $\widehat{Q}(\bm{z};W')$ in (\ref{origitwo-layerneuralnetworkofQfunction}),
The approximate parameter $W'$ can be optimized by minimizing the following mean-squared Bellman error (MSBE) problem:
%\begin{align}\label{theMSBEofmathbfW}
%\min_{\bm{W}\in S^{W}_{B}}\mathrm{MSBE}(\bm{W})=\mathbb{E}_{\varsigma_{\bm{\theta}}}\big[\big(\widehat{Q}(s,\bm{a};\bm{W})-\mathcal{T}^{\bm{\pi}_{\bm{\theta}}}\widehat{Q}(s,\bm{a};\bm{W})\big)^{2}\big],
%\end{align}
%\begin{align}\label{theMSBEofmathbfW}
%\min_{\bm{W}\in S^{W}_{B}}\!\!\mathrm{MSBE}(\bm{W})\!\!=\!\!\mathbb{E}_{\varsigma_{\bm{\theta}}}\big[\big(\widehat{Q}(s,\bm{a};\bm{W})\!\!-\!\!\mathcal{T}^{\bm{\pi}_{\bm{\theta}}}\widehat{Q}(s,\bm{a};\bm{W})\big)^{2}\big],
%\end{align}
\begin{align}\label{theMSBEofmathbfWfirst}
\min_{W'\in S^{W}_{B}}\mathbb{E}_{\varsigma_{\bm{\pi_{\theta}}}}\Big[\Big(\widehat{Q}(\bm{z};W')-\big[\mathcal{T}^{\bm{\pi}_{\bm{\theta}}}\big(\widehat{Q}(W')\big)\big](\bm{z})\Big)^{2}\Big],
\end{align}
where $\widehat{Q}(W')=\big[\widehat{Q}(\bm{z};W')\big]_{\bm{z}\in\mathcal{S}\times\mathcal{A}}$, $S^{W}_{B}=\big\{W'\in\mathbb{R}^{dmN}:\|W'_{(j-1)m+1:jm}-W'_{(j-1)m+1:jm}(0)\|_{2}\leq B/\sqrt{N},\forall\;j=1,\cdots,N\big\}$ denotes the parameter space with $W'(0)\in\mathbb{R}^{dmN}$ serving as the initial value.
Note that $B/\sqrt{N}$ is utilized to characterize the convergence error of the neural network approximation.
%is the parameter space with $W'(0)\in\mathbb{R}^{dmN}$ as the initial value.
%Specially, $B/\sqrt{N}$ is used to character the convergence error of the neural network approximation.
\par
For MSBE problem (\ref{theMSBEofmathbfWfirst}), the approximate parameter can be updated by the following iteration:
\begin{align}\label{thecentralizediteration}
W'(t+1)=&P_{S^{W}_{B}}\Big(W'(t)-\eta_{c}\mathbb{E}_{\varsigma^{+}_{\bm{\pi_{\theta}}}}\big[\delta\big(\bm{z},\bm{z}';W'(t)\big)\notag\\
&\nabla_{W'}\widehat{Q}\big(\bm{z};W'(t)\big)\big]\Big),
\end{align}
where $P_{S^{W}_{B}}(\cdot)$ is the projection operator, $\eta_{c}$ is the learning rate, $\varsigma^{+}_{\bm{\pi_{\theta}}}$ is the stationary distribution of $(\bm{z},\bm{z}')$ generated by $\bm{\pi_{\theta}}$, and  $\delta\big(\bm{z},\bm{z}';W'(t)\big)=\widehat{Q}\big(\bm{z};W'(t)\big)-(1-\gamma)\bar{r}(\bm{z})-\gamma\widehat{Q}\big(\bm{z}';W'(t)\big)$ is the temporal difference (TD) error.
\par
By leveraging (\ref{thepolicygradienttheorem}) and (\ref{thecentralizediteration}), the NMARL problem can be addressed in a centralized way.
However, several substantial challenges remain.
For example, the update of the approximate parameter $W'(t+1)$ in (\ref{thecentralizediteration}) depends on the average reward $\bar{r}(\bm{z})$, which is not directly accessible due to the privacy constraints associated with each agent's individual reward.
Consequently, this necessitates the development of a distributed algorithm that avoids utilizing the average reward of agents directly.
%This motivates us to develop a distributed algorithm that avoids using the average reward of agents.
%Based on the above description, the NMARL problem can be addressed in a centralized way by (\ref{thepolicygradienttheorem}) and (\ref{thecentralizediteration}).
%However, it still poses several significant challenges.
%For instance, the update of approximate parameter $W'(t+1)$ in (\ref{thecentralizediteration}) relies on the average reward $\bar{r}(\bm{z})$, which cannot be directly available due to the privacy of each agent's reward.
