\begin{align}\label{theMSBEofmathbfWtwo}
\min_{Q\in\mathbb{R}^{|\mathcal{S}||\mathcal{A}|}}\mathbb{E}_{\varsigma_{\bm{\pi_{\theta}}}}\Big[\Big(Q(\bm{z})-\big[P_{\mathcal{F}_{B,m}}\mathcal{T}^{\bm{\pi}_{\bm{\theta}}}\big(Q\big)\big](\bm{z})\Big)^{2}\Big].
\end{align}
