and have the
following proposition.
\begin{proposition}\label{ThepolicygradienttheoremforMARL}
For the local policy $\pi_{i}(a_{i}|\bm{s};\theta_{i})$ of each agent $i\in\mathcal{N}$ as defined in (\ref{theparameterizedpolicy}),
the policy gradient of $J(\bm{\pi}_{\bm{\theta}})$ with respect to $\theta_{i}$ is represented as
\begin{align}\label{theresultofpolicygradientforagenti}
\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}})=&\mathbb{E}_{\sigma_{\bm{\pi}_{\bm{\theta}}}}\Big[Q^{\bm{\pi}_{\bm{\theta}}}(\bm{s},\bm{a})\overline{\psi}_{i}(\bm{s},a_{i};\theta_{i})\Big].
\end{align}
\end{proposition}
\begin{proof}
By the definition of $\pi_{i}(a_{i}|\bm{s};\theta_{i})$ in (\ref{theparameterizedpolicy}), we have
\begin{align}\label{theresultofnablalogpii}
&\nabla_{\theta_{i}}\log{\pi_{i}(a_{i}|\bm{s};\theta_{i})}\notag\\
=&\nabla_{\theta_{i}}f_{i}(\bm{s},a_{i};\theta_{i})-\frac{\sum_{a'_{i}\in\mathcal{A}_{i}}\nabla_{\theta_{i}}f_{i}(\bm{s},a'_{i};\theta_{i})\exp[f_{i}(\bm{s},a'_{i};\theta_{i})]}{\sum_{a'_{i}\in\mathcal{A}_{i}}\exp[f_{i}(\bm{s},a'_{i};\theta_{i})]}\notag\\
=&\nabla_{\theta_{i}}f_{i}(\bm{s},a_{i};\theta_{i})-\mathbb{E}_{a'_{i}\sim\pi_{i}(\cdot|\bm{s};\theta_{i})}[\nabla_{\theta_{i}}f_{i}(\bm{s},a'_{i};\theta_{i})]\notag\\
=&\psi_{i}(\bm{s},a_{i};\theta_{i})-\mathbb{E}_{\pi_{\theta_{i}}}[\psi_{i}(\bm{s},a'_{i};\theta_{i})]\notag\\
=&\overline{\psi}_{i}(\bm{s},a_{i};\theta_{i}),
\end{align}
where the third equality comes from (\ref{thevarofneuralpolicy}).
Substituting (\ref{theresultofnablalogpii}) into (\ref{thepolicygradienttheorem}), we can complete the proof.
