\textbf{Distributed critic step}:
%Assume that the joint policy is ,
Let $\bm{\pi}_{\bm{\theta}(k)}$ be joint policy in the $k$-th iteration of policy, where $\bm{\theta}(k)=\big(\theta^{\top}_{1}(k),\dots,\theta^{\top}_{N}(k)\big)^{\top}$ denotes the joint policy parameter.
Define
$\varsigma^{+}_{k}$ as the stationary distribution of $(\bm{z},\bm{z}')$ generated by $\bm{\pi}_{\bm{\theta}(k)}$.
For each agent $i$, the update of approximate parameter $W_{i}(t+1)$ with initial value $W_{i}(0)$ is designed as
\begin{subequations}\label{thekeystepindistributedneuralTDalgorithm}
\begin{numcases}{}
g^{k}_{i}(t)=\delta^{k}_{i}(t)\nabla_{W_{i}}\widehat{Q}_{i}\big(\bm{z};W_{i}(t)\big)\label{theTDlearningindistributedneuralTDalgorithm1}\\
\widetilde{W}_{i}(t+1)=\sum_{j\in\mathcal{N}_{i}(t)}a_{ij}(t)W_{j}(t)-\eta_{c,t}g^{k}_{i}(t)\label{theTDlearningindistributedneuralTDalgorithm}\\
W_{i}(t+1)=P_{S^{W}_{B}}\big(\widetilde{W}_{i}(t+1)\big),\label{theprojectindistributedneuralTDalgorithm}
\end{numcases}
\end{subequations}
where $\delta^{k}_{i}(t)=\widehat{Q}_{i}\big(\bm{z};W_{i}(t)\big)-(1-\gamma)r_{i}(\bm{z})-\gamma\widehat{Q}_{i}\big(\bm{z}';W_{i}(t)\big)$ is the TD error with $(\bm{z},\bm{z}')$ sampling drawn from the stationary distribution $\varsigma^{+}_{k}$,
$g^{k}_{i}(t)$ is the stochastic semigradient of agent $i$, and $\eta_{c,t}$ is the learning rate in the distributed critic step.
Note that in (\ref{theTDlearningindistributedneuralTDalgorithm}), the update of the approximate parameters for agents is performed in a distributed manner, where each agent $i$ relies exclusively on the approximate parameters of its neighboring agents.
%(\ref{theTDlearningindistributedneuralTDalgorithm}) shows that the update of the approximate parameters of agents are performed in a distributed way, with each agent $i$ solely relying on its neighbors' approximate parameters.
%After $T_{c}-1$ iterations of (\ref{thekeystepindistributedneuralTDalgorithm}), each agent $i$ can obtain an estimate of the global $Q$-function $Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})$, denoted as
After $T_{c}-1$ iterations of (\ref{thekeystepindistributedneuralTDalgorithm}), each agent $i$ is able to obtain an estimate of the global $Q$-function $Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})$, denoted as
\begin{align}\label{theQiout}
\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})=\widehat{Q}_{i}\big(\bm{z};W_{i,\mathrm{out}}\big),
\end{align}
where $W_{i,\mathrm{out}}=\frac{1}{\sum_{t=0}^{T_{c}-1}\eta_{c,t}}\sum_{t=0}^{T_{c}-1}\eta_{c,t}W_{i}(t)$.
