\begin{align}\label{theupdateofpolicyparameter}
\theta_{i}(k+1)=P_{S^{\theta}_{i,B}}\big(\theta_{i}(k)+\eta_{a}\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})\big),
\end{align}
