\begin{assumption}\label{Regularity Condition}
For any joint policies $\bm{\pi}$ and $\bm{\pi}'$, there exists a constant $c_{0}>0$ such that for all $i\in\mathcal{N}$, $u>0$, and $y\in\mathbb{R}^{d}$,
%the following inequality holds:
\begin{align}
\mathbb{E}_{\bm{\pi}'\cdot\nu_{\bm{\pi}}}\big[\mathds{1}\{|y^{\top}x_{i}|\leq u\}\big]\leq c_{0}\cdot u/\|y\|_{2}
\end{align}
where $\nu_{\bm{\pi}}$ is the state visitation measure of joint policy $\bm{\pi}$.
\end{assumption}
