\begin{lemma}\label{lemmaofaverageconsensus}
Suppose Assumptions~\ref{theassumptionofcommunication}-\ref{Regularity Condition} hold.
%In the $k$-th iteration of  Algorithm~\ref{distributedneuralpolicygradientAlgorithm},
Let the learning rate $\eta_{c,t}=\frac{1-\gamma}{24\sqrt{t+1}}$ and
$C=I_{N}-(1/N)\mathbf{1}_{N}\mathbf{1}_{N}^{\top}$, then we have that
\begin{align}
&\mathbb{E}_{\mathrm{init}}[\|(C\otimes I_{dmN})W_{tot}(t)\|_{2}]\notag\\
\leq&\frac{\sqrt{md_{1}}N}{\lambda}\lambda^{t}_{D}\!+\!\sum_{t'=0}^{t-1}\frac{(1-\gamma)\lambda^{t-1-t'}_{D}}{24\lambda\sqrt{t'+1}}\mathcal{O}(Bm^{\frac{1}{2}-p}N^{1-p}),
\end{align}
where $W_{tot}(t)=\big(W^{\top}_{1}(t),\cdots,W^{\top}_{N}(t)\big)^{\top}$,  $\lambda=\min\big\{1-1/(2N^{3}),\sup_{t\geq0}\sigma_{2}\big(A(t)\big)\big\}$,
$\sigma_{2}\big(A(t)\big)$ is the second largest singular value of $A(t)$, and $\lambda_{D}=\lambda^{\frac{1}{D}}$.
\end{lemma}
%\begin{proof}
%{\color{blue}The proof can be found in Appendix~\ref{theproofoflemmaofaverageconsensus}.}
%\end{proof}
\par
Lemma~\ref{lemmaofaverageconsensus} establishes the average consensus convergence of $W_{i}(t)$ to $\overline{W}(t)$.
The detailed proof is provided in Appendix~\ref{theproofoflemmaofaverageconsensus}.
By leveraging the result from Lemma~7 in~\cite{nedic2010}, which states that $\lim_{t\rightarrow\infty}\sum_{t'=0}^{t-1}(\lambda^{t-1-t'}_{D}/\sqrt{t'+1})=0$, we further have that $\mathbb{E}_{\mathrm{init}}[\|(C\otimes I_{dmN})W_{\mathrm{tot}}(t)\|_{2}] \to 0$ as $m \to \infty$ and $t \to \infty$.
