\begin{lemma}\label{StochasticDescentLemma}
Suppose Assumptions~\ref{theassumptionofcommunication}-\ref{Regularity Condition} hold.
In the $k$-th iteration of policy in Algorithm~\ref{distributedneuralpolicygradientAlgorithm},
the average parameter $\overline{W}(t)$ satisfies
\begin{align}
&\mathbb{E}_{\mathrm{init}}[\|\overline{W}(t+1)-W^{*}_{k}\|^{2}_{2}]\notag\\
\leq&\mathbb{E}_{\mathrm{init}}[\|\overline{W}(t)-W^{*}_{k}\|^{2}_{2}]-\big(2\eta_{c,t}(1-\gamma)-24\eta_{c,t}^{2}\big)\cdot\notag\\
&\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z};\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\Big)^{2}\Big]\notag\\
&+\eta_{c,t}\mathcal{O}\big(B^{\frac{5}{2}}(mN)^{\frac{1}{2}-p}\big)+\eta^{2}_{c,t}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big).\notag
\end{align}
\end{lemma}
