\begin{theorem}\label{ConvergenceofStochasticUpdate}
Suppose Assumptions~\ref{theassumptionofcommunication}-\ref{Regularity Condition} hold.
%In the $k$-th iteration of  Algorithm~\ref{distributedneuralpolicygradientAlgorithm},
Let the learning rate $\eta_{c,t}=\frac{1-\gamma}{24\sqrt{t+1}}$,
the output $\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})$ in distributed critic step satisfies
\begin{align}
&\mathbb{E}_{\mathrm{init},\varsigma_{k}}\big[\big(\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\big)^{2}\big]\notag\\
\leq&\frac{48B^{2}}{(1-\gamma)\sqrt{T_{c}}}+\frac{1+\ln{T_{c}}}{12\sqrt{T_{c}}}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big)\notag\\
&+\mathcal{O}\big(B^{3}(mN)^{\frac{1}{2}-p}\big).\label{theresultoftheorem1}
\end{align}
%where $\bm{W}^{*}$ is an approximate stationary point and satisfies \begin{align}
%\mathbb{E}_{\varsigma^{+}_{t'}}[\delta_{0}(s,\bm{a},r_{\mathrm{ave}},s',\bm{a}';\bm{W}^{*})\nabla_{\bm{W}}\widehat{Q}_{0}(s,\bm{a};\bm{W}^{*})]^{\top}(\bm{W}-\bm{W}^{*})\geq0,\;\;\mathrm{for\;all}\;\bm{W}\in S_{B}.
%\end{align}
%Here, $\delta_{0}(s,\bm{a},r_{\mathrm{ave}},s',\bm{a}';\bm{W}^{*})=\widehat{Q}_{0}(s,\bm{a};\bm{W}^{*})-(1-\gamma)r_{\mathrm{ave}}-\gamma\widehat{Q}_{0}(s',\bm{a}';\bm{W}^{*})$.
\end{theorem}
\begin{proof}
%Consider $\mathbb{E}_{\mathrm{init},\varsigma_{t}}\Big[\Big(\widehat{Q}_{0}\big(s,\bm{a},\bm{W}_{i}(k)\big)-\widehat{Q}_{0}\big(s,\bm{a};\bm{W}^{*}\big)\Big)^{2}\Big]$, we have
Recall the definition of $\widehat{Q}_{0}(\bm{z};W')$ in (\ref{theQ0xW}), we have
\begin{align}\label{keystepinConvergenceofPopulationUpdate}
&\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z};W_{i}(t)\big)-\widehat{Q}_{0}\big(\bm{z};W^{*}_{k}\big)\Big)^{2}\Big]\notag\\
\leq&2\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z};W_{i}(t)\big)-\widehat{Q}_{0}\big(\bm{z};\overline{W}(t)\big)\Big)^{2}\Big]\notag\\
&+2\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z};\overline{W}(t)\big)-\widehat{Q}_{0}\big(\bm{z};W^{*}_{k}\big)\Big)^{2}\Big]\notag\\
\leq& 2\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z};\overline{W}(t)\big)-\widehat{Q}_{0}\big(\bm{z};W^{*}_{k}\big)\Big)^{2}\Big]\notag\\
&+8B^{2}(Nm)^{1-2p},
\end{align}
where the last inequality uses (iii) of Fact~\ref{thefactinpaper} and the fact that $W_{i}(t),\overline{W}(t)\in S^{W}_{B}$.
According to Lemma \ref{StochasticDescentLemma}, we have
\begin{align}\label{changeresultofLemmaPopulationDescentLemma}
&\eta_{c,t}(1-\gamma)\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z},\overline{W}(t)\big)-\widehat{Q}_{0}\big(\bm{z};W^{*}_{k}\big)\Big)^{2}\Big]\notag\\
\leq&\mathbb{E}_{\mathrm{init}}[\|\overline{W}(t)-W^{*}_{k}\|^{2}_{2}]-\mathbb{E}_{\mathrm{init}}[\|\overline{W}(t+1)-W^{*}_{k}\|^{2}_{2}]\notag\\
&+\eta_{c,t}\mathcal{O}\big(B^{\frac{5}{2}}(mN)^{\frac{1}{2}-p}\big)+\eta^{2}_{c,t}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big).
\end{align}
By combining (\ref{keystepinConvergenceofPopulationUpdate}) and (\ref{changeresultofLemmaPopulationDescentLemma}), we have
\begin{align}\label{simpleConvergenceofPopulationUpdate}
&\frac{\eta_{c,t}(1-\gamma)}{2}\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z};W_{i}(t)\big)-\widehat{Q}_{0}\big(\bm{z};W^{*}_{k}\big)\Big)^{2}\Big]\notag\\
\leq&\mathbb{E}_{\mathrm{init}}[\|\overline{W}(t)-W^{*}_{k}\|^{2}_{2}]-\mathbb{E}_{\mathrm{init}}[\|\overline{W}(t+1)-W^{*}_{k}\|^{2}_{2}]\notag\\
&+\eta_{c,t}\mathcal{O}\big(B^{\frac{5}{2}}(mN)^{\frac{1}{2}-p}+B^{2}(mN)^{1-2p}\big)\notag\\
&+\eta^{2}_{c,t}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big).
\end{align}
Telescoping (\ref{simpleConvergenceofPopulationUpdate}) for $t=0,1,\cdots,T_{c}-1$, we have
\begin{align}\label{TelescopingsimpleConvergenceofPopulationUpdate}
&\frac{1-\gamma}{2}\sum_{t=0}^{T_{c}-1}\eta_{c,t}\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z};W_{i}(t)\big)-\widehat{Q}_{0}\big(\bm{z};W^{*}_{k}\big)\Big)^{2}\Big]\notag\\
\leq&\mathbb{E}_{\mathrm{init}}[\|\overline{W}(0)-W^{*}_{k}\|^{2}_{2}]-\mathbb{E}_{\mathrm{init}}[\|\overline{W}(T_{c})-W^{*}_{k}\|^{2}_{2}]\notag\\
&+\sum_{t=0}^{T_{c}-1}\eta_{c,t}\mathcal{O}\big(B^{\frac{5}{2}}(mN)^{\frac{1}{2}-p}\big)\notag\\
&+\sum_{t=0}^{T_{c}-1}\eta^{2}_{c,t}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big).
\end{align}
Dividing (\ref{TelescopingsimpleConvergenceofPopulationUpdate}) by $\frac{1-\gamma}{2}\sum_{t=0}^{T_{c}-1}\eta_{c,t}$ and using the Jensen's inequality, we can have
\begin{align}
&\mathbb{E}_{\mathrm{init},\varsigma_{k}}\big[\big(\widehat{Q}_{0}(\bm{z};W_{i,\mathrm{out}})-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\big)^{2}\big]\notag\\
\leq&\frac{24\big(\mathbb{E}_{\mathrm{init}}[\|\overline{W}(0)-W^{*}_{k}\|^{2}_{2}]-\mathbb{E}_{\mathrm{init}}[\|\overline{W}(T_{c})-W^{*}_{k}\|^{2}_{2}]\big)}{(1-\gamma)^{2}\sqrt{T_{c}}}\notag\\
&+\frac{1+\ln{T_{c}}}{24\sqrt{T_{c}}}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big)+\mathcal{O}\big(B^{\frac{5}{2}}(mN)^{\frac{1}{2}-p}\big),\label{themidresulrintheorem1}
\end{align}
where the inequality comes from the integral test yields in~\cite{Doan2019ICML} that
\begin{gather}
\frac{1-\gamma}{2}\sum_{t=0}^{T_{c}-1}\eta_{t}\geq\frac{(1-\gamma)^{2}\sqrt{T_{c}}}{24},\notag\\ \sum_{t=0}^{T_{c}-1}\eta^{2}_{t}\leq \frac{(1-\gamma)^{2}(1+\ln{T_{c}})}{576}.\notag
\end{gather}
Recall $\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})=\widehat{Q}_{i}(\bm{z};W_{i,\mathrm{out}})$ in (\ref{theQiout}), we further have
\begin{align}
&\mathbb{E}_{\mathrm{init},\varsigma_{k}}\big[\big(\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\big)^{2}\big]\notag\\
\leq&2\mathbb{E}_{\mathrm{init},\varsigma_{k}}\big[\big(\widehat{Q}_{i}(\bm{z};W_{i,\mathrm{out}})-\widehat{Q}_{0}(\bm{z};W_{i,\mathrm{out}})\big)^{2}\big]\notag\\
&+2\mathbb{E}_{\mathrm{init},\varsigma_{k}}\big[\big(\widehat{Q}_{0}(\bm{z};W_{i,\mathrm{out}})-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\big)^{2}\big]\notag\\
\leq&\frac{48B^{2}}{(1-\gamma)\sqrt{T_{c}}}+\frac{1+\ln{T_{c}}}{12\sqrt{T_{c}}}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big)\notag\\
&+\mathcal{O}\big(B^{3}(mN)^{\frac{1}{2}-p}\big),\notag
\end{align}
where the last inequality can be achieved by (\ref{themidresulrintheorem1}) and (iii) of Lemma~\ref{Lemma1to3}.
%Hence, the proof of Theorem~\ref{ConvergenceofStochasticUpdate} is completed.
\end{proof}
\par
