\leq&\frac{96B^{2}}{(1-\gamma)\sqrt{T_{c}}}+\frac{1+\ln{T_{c}}}{6\sqrt{T_{c}}}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big)\notag\\
&+\frac{2\mathbb{E}_{\varsigma_{k}}\big[\big(P_{\mathcal{F}_{B,m}}Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})\big)^{2}\big]}{(1-\gamma)^{2}}\notag\\
&+\mathcal{O}\big(B^{3}(mN)^{\frac{1}{2}-p}\big).\label{theinequalityofcorollary2}
\end{align}
\end{corollary}
\begin{proof}
Similar to the definition of $\mathcal{T}^{\bm{\pi}_{\bm{\theta}}}(\cdot)$ in (\ref{theBellmanevaluationoperatorofpiTheta}),
define $\mathcal{T}^{\bm{\pi}_{\bm{\theta}(k)}}(\cdot)$ as the Bellman evaluation operator of joint policy $\bm{\pi}_{\bm{\theta}(k)}$.
%For $Q^{\bm{\pi}_{\bm{\theta}(t)}}=[Q^{\bm{\pi}_{\bm{\theta}(t)}}(\bm{z})]_{\bm{z}\in\mathcal{S}\times\mathcal{A}}$, we have
