By the property of approximate stationary $W^{*}_{k}$
in Section~\ref{thesectionofApproximatestationary}, we have
\begin{align}
&\|\widehat{Q}_{0}(W^{*}_{k})-Q^{\bm{\pi}_{\bm{\theta}(k)}}\|_{\varsigma_{k}}\notag\\
\leq&\|\widehat{Q}_{0}(W^{*}_{k})-P_{\mathcal{F}_{B,m}}Q^{\bm{\pi}_{\bm{\theta}(k)}}\|_{\varsigma_{k}}\!+\!\|P_{\mathcal{F}_{B,m}}Q^{\bm{\pi}_{\bm{\theta}(k)}}-Q^{\bm{\pi}_{\bm{\theta}(k)}}\|_{\varsigma_{k}}\notag\\
\leq&\|P_{\mathcal{F}_{B,m}}\mathcal{T}^{\bm{\pi}_{\bm{\theta}(k)}}\widehat{Q}_{0}(W^{*}_{k})-P_{\mathcal{F}_{B,m}}\mathcal{T}^{\bm{\pi}_{\bm{\theta}(k)}}Q^{\bm{\pi}_{\bm{\theta}(k)}}\|_{\varsigma_{k}}\notag\\
&+\|P_{\mathcal{F}_{B,m}}Q^{\bm{\pi}_{\bm{\theta}(k)}}-Q^{\bm{\pi}_{\bm{\theta}(k)}}\|_{\varsigma_{k}}\notag\\
\leq&\gamma\|\widehat{Q}_{0}(W^{*}_{k})\!-\!Q^{\bm{\pi}_{\bm{\theta}(k)}}\|_{\varsigma_{k}}\!+\!\|P_{\mathcal{F}_{B,m}}Q^{\bm{\pi}_{\bm{\theta}(k)}}\!-\!Q^{\bm{\pi}_{\bm{\theta}(k)}}\|_{\varsigma_{k}},\label{theinequalityinCorollary2}
\end{align}
where the second inequality follows from the fact that $\mathcal{T}^{\bm{\pi}_{\bm{\theta}(k)}}Q^{\bm{\pi}_{\bm{\theta}(k)}}=Q^{\bm{\pi}_{\bm{\theta}(k)}}$
%and  $\widehat{Q}(\cdot,\cdot;\bm{W}^{*})=\Pi_{\mathcal{F}_{B,m}}\mathcal{T}^{\bm{\pi}_{\bm{\theta}(t)}}\widehat{Q}(\cdot,\cdot;\bm{W}^{*})$ and $Q^{\bm{\pi}_{\bm{\theta}(t)}}=\mathcal{T}^{\bm{\pi}_{\bm{\theta}(t)}}Q^{\bm{\pi}_{\bm{\theta}(t)}}$,
and the last inequality is derived from Lemma 4.2 in~\cite{Cai2019}, which establishes that $P_{\mathcal{F}_{B,m}}\mathcal{T}^{\bm{\pi}_{\bm{\theta}(k)}}$ is a $\gamma$-contraction.
Based on (\ref{theinequalityinCorollary2}), we further have
\begin{align}\label{inequalityofdistance}
&\mathbb{E}_{\varsigma_{k}}[|\widehat{Q}_{0}(\bm{z};W^{*}_{k})-Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})|^{2}]\notag\\
\leq&\frac{1}{(1-\gamma)^{2}}\mathbb{E}_{\varsigma_{k}}[|P_{\mathcal{F}_{B,m}}Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})|^{2}].
\end{align}
Since
\begin{align}
&\mathbb{E}_{\mathrm{init},\varsigma_{k}}\big[\big(\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})-Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})\big)^{2}\big]\notag\\
\leq&2\mathbb{E}_{\mathrm{init},\varsigma_{k}}\big[\big(\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\big)^{2}\big]\notag\\
&+2\mathbb{E}_{\mathrm{init},\varsigma_{k}}\big[\big(\widehat{Q}_{0}(\bm{z};W^{*}_{k})-Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})\big)^{2}\big],\label{beforethecorollary1}
%\leq&\frac{192B^{2}}{(1-\gamma)^{2}K_{c}}+\frac{2\mathbb{E}_{\varsigma_{t}}\big[\big(\Pi_{\mathcal{F}_{B,m}}Q^{\bm{\pi}_{\bm{\theta}(t)}}(\bm{z})-Q^{\bm{\pi}_{\bm{\theta}(t)}}(\bm{z})\big)^{2}\big]}{(1-\gamma)^{2}}\notag\\
%&+\mathcal{O}\big(B^{3}(mN)^{\frac{1}{2}-p}\big).\notag
\end{align}
substituting (\ref{inequalityofdistance}) and (\ref{theresultoftheorem1}) into (\ref{beforethecorollary1}), we can complete the proof.
\end{proof}
