Based on the above definitions, the stationarity convergence of Algorithm~\ref{distributedneuralpolicygradientAlgorithm} is established as follows.
\begin{theorem}\label{ConvergencetoStationaryPoint}
Suppose Assumptions~\ref{theassumptionofcommunication}-\ref{RegularityConditiononsigmaandvarsigma} hold.
In the Algorithm~\ref{distributedneuralpolicygradientAlgorithm}, let the learning rate $\eta_{a}\in(0,\frac{1}{2L})$, $K\geq4L^{2}$, and $T_{c}=\mathcal{O}\big((mN)^{2p-1}\big)$.
If $Q^{\bm{\pi}_{\bm{\theta}(k)}}\in\mathcal{F}_{B,\infty}$ for all $k=0,\cdots,K-1$ during the iteration process, then it holds that
\begin{align}\label{theresultinlemmakeyfinal}
\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\bm{\rho}(k)\|^{2}_{2}]\leq&\frac{16R_{0}}{\eta_{a}K}+\frac{4\sigma^{2}_{\xi}}{|\mathcal{B}|}+\tilde{\mathcal{O}}\big(B^{\frac{5}{2}}N^{\frac{1}{2}}T^{-\frac{1}{2}}_{c}\big)\notag\\
&+\mathcal{O}\big(B^{\frac{5}{2}}m^{\frac{1-2p}{4}}N^{\frac{3-2p}{4}}\big).
\end{align}
%{\color{blue}where $\hat{T}$ is uniformly sampled among $\{0,\cdots,T-1\}$.}
\end{theorem}
\begin{proof}
By using Assumption~\ref{LipschitzContinuousPolicyGradient}, we have
\begin{align}
&J(\bm{\pi}_{\bm{\theta}(k+1)})-J(\bm{\pi}_{\bm{\theta}(k)})\notag\\
\geq&\eta_{a}\nabla_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})^{\top}\delta^{\bm{\theta}}_{k}-\frac{L}{2}\|\bm{\theta}(k+1)-\bm{\theta}(k)\|^{2}_{2}.\label{theinequalityofLipschitz}
\end{align}
%where $\delta^{\bm{\theta}}_{t}=\big((\delta^{\bm{\theta}}_{1,t})^{\top},\cdots,(\delta^{\bm{\theta}}_{N,t})^{\top}\big)^{\top}$ with $\delta^{\bm{\theta}}_{i,t}=\big(\bm{\theta}_{i}(t+1)-\bm{\theta}_{i}(t)\big)/\eta$.
Recall that $\xi_{i,k}=\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})-\mathbb{E}_{\sigma_{k}}[\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})]$, we have
\begin{align}\label{theequalityofLipschitz}
\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})^{\top}\delta^{\bm{\theta}}_{i,k}=&\!\underbrace{\big(\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})\!-\!\mathbb{E}_{\sigma_{k}}[\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})]\big)^{\top}\delta^{\bm{\theta}}_{i,k}}_{(\mathrm{i})}\notag\\
&\underbrace{-\xi^{\top}_{i,k}\delta^{\bm{\theta}}_{i,k}}_{(\mathrm{ii})}+\underbrace{\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})^{\top}\delta^{\bm{\theta}}_{i,k}}_{(\mathrm{iii})}.
\end{align}
\par
For the $(\mathrm{i})$-th term on the right-hand side of (\ref{theequalityofLipschitz}), we use Proposition~\ref{ThepolicygradienttheoremforMARL} and have
\begin{align}
&\Big|\big(\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})-\mathbb{E}_{\sigma_{k}}[\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})]\big)^{\top}\delta^{\bm{\theta}}_{i,k}\Big|\notag\\
=&\Big|\mathbb{E}_{\sigma_{k}}\big[\overline{\psi}_{i}(\bm{s},a_{i};\theta_{i})\big(Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})\big)\big]^{\top}\delta^{\bm{\theta}}_{i,k}\Big|\notag\\
\leq&\|\delta^{\bm{\theta}}_{i,k}\|_{2}\big\|\mathbb{E}_{\sigma_{k}}\big[\overline{\psi}_{i}(\bm{s},a_{i};\theta_{i})\big(Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})\big)\big]\big\|_{2}\notag\\
\leq&\|\delta^{\bm{\theta}}_{i,k}\|_{2}\mathbb{E}_{\sigma_{k}}[\|\overline{\psi}_{i}(\bm{s},a_{i};\theta_{i})\|_{2}|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})|]\notag\\
\leq&4\eta^{-1}_{a}BN^{-\frac{1}{2}}\mathbb{E}_{\sigma_{k}}[|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})|]\notag\\
\leq&4\eta^{-1}_{a}BN^{-\frac{1}{2}}\Big\{\mathbb{E}_{\varsigma_{k}}\big[\big(\mathrm{d}\sigma_{k}(\bm{z})/\mathrm{d}\varsigma_{k}(\bm{z})\big)^{2}\big]\Big\}^{1/2}\cdot\notag\\
&\|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})\|_{\varsigma_{k}}\notag\\
\leq&4\kappa_{a}\eta^{-1}_{a}BN^{-\frac{1}{2}}\|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})\|_{\varsigma_{k}},\label{thei-thtermintheequalityofLipschitz}
\end{align}
where the second inequality follows from the Jensen's inequality, the third inequality uses the fact that $\|\delta^{\bm{\theta}}_{i,t}\|_{2}\leq2\eta^{-1}_{a}BN^{-\frac{1}{2}}$ and $\|\overline{\psi}_{i}(\bm{s},a_{i};\theta_{i})\|_{2}\leq2(mN)^{\frac{1}{2}-p}\leq2$, the forth inequality comes from the Cauchy-Schwartz inequality, and the last inequality uses Assumption~\ref{RegularityConditiononsigmaandvarsigma}.
%\begin{align}\label{thei-thtermintheequalityofLipschitz}
%&\big(\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})-\mathbb{E}_{\sigma_{k}}[\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})]\big)^{\top}\delta^{\bm{\theta}}_{i,k}\notag\\
%\geq&-4\kappa_{a}\eta^{-1}_{a}BN^{-\frac{1}{2}}\|Q^{\bm{\pi}_{\bm{\theta}(k)}}-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}\|_{\varsigma_{k}}.
%\end{align}
\par
For the $(\mathrm{ii})$-th term on the right-hand side of (\ref{theequalityofLipschitz}), we have
\begin{align}\label{theii-thtermintheequalityofLipschitz}
-\xi^{\top}_{i,k}\delta^{\bm{\theta}}_{i,k}\geq-\frac{1}{2}(\|\xi_{i,k}\|^{2}_{2}+\|\delta^{\bm{\theta}}_{i,k}\|^{2}_{2}).
\end{align}
\par
For the $(\mathrm{iii})$-th term on the right-hand side of (\ref{theequalityofLipschitz}), we use (\ref{thedeltainactorstep}) and have
\begin{align}\label{theiii-thtermintheequalityofLipschitz}
&\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})^{\top}\delta^{\bm{\theta}}_{i,k}\notag\\
=&\Big[\delta^{\bm{\theta}}_{i,k}-\Big(\theta_{i}(k+1)-\big(\theta_{i}(k)+\eta_{a}\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})\big)\Big)\Big/\eta_{a}\Big]\delta^{\bm{\theta}}_{i,k}\notag\\
\geq&\|\delta^{\bm{\theta}}_{i,k}\|^{2}_{2},
\end{align}
where the inequality comes from the property of projection operation that for all $\bm{\theta}',\bm{\theta}''\in S^{\theta}_{B}$,
\begin{align}\label{thepropertyofprojectionoperation}
&\Big(P_{S^{\theta}_{i,B}}\big(\theta_{i}'+\eta_{a}\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}'})\big)-\big(\theta_{i}'+\eta_{a}\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}'})\big)\Big)^{\top}\notag\\
&\Big(P_{S^{\theta}_{i,B}}\big(\theta_{i}'+\eta_{a}\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}'})\big)-\theta_{i}''\Big)\leq0.
\end{align}
Substituting (\ref{thei-thtermintheequalityofLipschitz}), (\ref{theii-thtermintheequalityofLipschitz}), and (\ref{theiii-thtermintheequalityofLipschitz}) into (\ref{theequalityofLipschitz}), we have
\begin{align}\label{thei-ii-iii-equalityofLipschitz}
\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})^{\top}\delta^{\bm{\theta}}_{i,k}
\geq&-4\kappa_{a}\eta^{-1}_{a}BN^{-\frac{1}{2}}\|Q^{\bm{\pi}_{\bm{\theta}(k)}}-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}\|_{\varsigma_{k}}\notag\\
&-\frac{1}{2}\|\xi_{i,k}\|^{2}_{2}+\frac{1}{2}\|\delta^{\bm{\theta}}_{i,k}\|^{2}_{2}.
\end{align}
By combining (\ref{theinequalityofLipschitz}) and (\ref{thei-ii-iii-equalityofLipschitz}), we have
\begin{align}
\frac{1-L\eta_{a}}{2}\mathbb{E}&[\|\delta^{\bm{\theta}}_{k}\|^{2}_{2}]\leq\frac{1}{\eta_{a}}\mathbb{E}[J(\bm{\pi}_{\bm{\theta}(k+1)})-J(\bm{\pi}_{\bm{\theta}(k)})]\notag\\
&+4\kappa_{a}\eta^{-1}_{a}BN^{-\frac{1}{2}}\sum_{i=1}^{N}\mathbb{E}[\|Q^{\bm{\pi}_{\bm{\theta}(k)}}-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}\|_{\varsigma_{k}}]\notag\\
&+\frac{1}{2}\mathbb{E}[\|\xi_{k}\|^{2}_{2}].\label{theresultequalityofLipschitz}
\end{align}
Recall that $0<\eta_{a}<\frac{1}{2L}$ and $K\geq4L^{2}$, we have
\begin{align}\label{theinequalityofrho}
%&\mathbb{E}[\|\bm{\rho}(\hat{K})\|^{2}_{2}]\leq
&\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\bm{\rho}(k)\|^{2}_{2}]\notag\\
\leq&\frac{1}{K}\sum_{k=0}^{K-1}\big(2\mathbb{E}[\|\delta^{\bm{\theta}}_{k}\|^{2}_{2}\|]+2\mathbb{E}[\|\bm{\rho}(k)-\delta^{\bm{\theta}}_{k}\|^{2}_{2}]\big)\notag\\
\leq&\frac{1}{K}\sum_{k=0}^{K-1}\big(4(1-L\eta_{a})\mathbb{E}[\|\delta^{\bm{\theta}}_{k}\|^{2}_{2}\|]+2\mathbb{E}[\|\bm{\rho}(k)-\delta^{\bm{\theta}}_{k}\|^{2}_{2}]\big).
\end{align}
Based on the definitions of $\bm{\rho}(k)$ in (\ref{thedefinnitionofrho}) and $\delta^{\bm{\theta}}_{i,k}$ in (\ref{thedeltainactorstep}), we have
\begin{align}\label{theinequalityoferrorbetweenrhoanddelta}
\|\bm{\rho}(k)-\delta^{\bm{\theta}}_{k}\|_{2}=&\frac{1}{\eta_{a}}\mathbb{E}\big[\big\|P_{S^{\theta}_{B}}\big(\bm{\theta}(k)+\eta_{a}\nabla_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})\big)\notag\\
&-P_{S^{\theta}_{B}}\big(\bm{\theta}(k)+\eta_{a}\widehat{\nabla}_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})\big)\big]\notag\\
\leq&\|\nabla_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})-\widehat{\nabla}_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})\|_{2}.
\end{align}
Substituting (\ref{theinequalityoferrorbetweenrhoanddelta}) into (\ref{theinequalityofrho}), we further have
\begin{align}
\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\bm{\rho}(k)\|^{2}_{2}]\leq&\frac{1}{K}\sum_{k=0}^{K-1}\Big(4(1-L\eta_{a})\mathbb{E}[\|\delta^{\bm{\theta}}_{k}\|^{2}_{2}\|]\notag\\
&+2\mathbb{E}[\|\nabla_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})-\widehat{\nabla}_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})\|^{2}_{2}]\Big)\notag\\
\leq&\frac{8}{K\eta_{a}}\mathbb{E}[J(\bm{\pi}_{\bm{\theta}(K)})-J(\bm{\pi}_{\bm{\theta}(0)})]\notag\\
&+\frac{4}{K}\sum_{k=0}^{K-1}\mathbb{E}\|\xi_{k}\|^{2}_{2}+\tilde{\mathcal{O}}\big(B^{\frac{5}{2}}N^{\frac{1}{2}}T^{-\frac{3}{4}}_{c}\big)\notag\\
&+\mathcal{O}\big(B^{\frac{5}{2}}m^{\frac{1-2p}{4}}N^{\frac{3-2p}{4}}\big)\notag\\
\leq&\frac{16R_{0}}{K\eta_{a}}+\frac{4\sigma^{2}_{\xi}}{|\mathcal{B}|}+\tilde{\mathcal{O}}\big(B^{\frac{5}{2}}N^{\frac{1}{2}}T^{-\frac{3}{4}}_{c}\big)\notag\\
&+\mathcal{O}\big(B^{\frac{5}{2}}m^{\frac{1-2p}{4}}N^{\frac{3-2p}{4}}\big),\notag
\end{align}
where the second inequality follows from (\ref{theresultequalityofLipschitz}) and  Theorem~\ref{ConvergenceofStochasticUpdate}, and the last inequality uses Assumption~\ref{LipschitzContinuousPolicyGradient}.
%In particular, the $\varepsilon_{Q}(T)$ is defined as
%\begin{align}
%\varepsilon_{Q}(T)
%=&(4\kappa\eta^{-1}_{a}BN^{-\frac{1}{2}})\sum_{t=1}^{T}\sum_{i=1}^{N}\mathbb{E}[\|Q^{\bm{\pi}_{\bm{\theta}(t)}}-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(t)}}_{i,\mathrm{out}}\|_{\varsigma_{t}}]\notag\\
%&+16\kappa^{2}(mN)^{1-2p}\sum_{t=1}^{T}\sum_{i=1}^{N}\mathbb{E}[\|Q^{\bm{\pi}_{\bm{\theta}(t)}}-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(t)}}_{i,\mathrm{out}}\|^{2}_{\varsigma_{t}}]\notag\\
%=&\mathcal{O}\big(B^{5/2}(Nm)^{1/4-p/2}T^{-1}\big), \label{thekeyconclusionintheorem2}
%\end{align}
%where (\ref{thekeyconclusionintheorem2}) uses the conclusion (\ref{therestrictiveconclusion}).
%Hence, the proof of Theorem~\ref{ConvergencetoStationaryPoint} is completed.
\end{proof}
\par
Theorem~\ref{ConvergencetoStationaryPoint} indicates that  Algorithm~\ref{distributedneuralpolicygradientAlgorithm} can convergence to a stationary point at a rate of $\mathcal{O}(\frac{1}{K})$ with some error terms.
It is important to note that the terms $\tilde{\mathcal{O}}\big(B^{\frac{5}{2}}N^{\frac{1}{2}}T^{-\frac{3}{4}}_{c}\big)+\mathcal{O}\big(B^{\frac{5}{2}}m^{\frac{1-2p}{4}}N^{\frac{3-2p}{4}}\big)$  on the right side of (\ref{theresultinlemmakeyfinal}) represents the error cased by function approximation in the distributed critic step, while $\frac{4\sigma^{2}_{\xi}}{|\mathcal{B}|}$ denotes the approximation error of policy gradient in the decentralized actor step.
