\begin{align}\label{thedefinitionofuwidehattheta}
u_{\widehat{\bm{\theta}}}(\bm{z})=\frac{\mathrm{d}\sigma_{\bm{\pi}^{*}}}{\mathrm{d}\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}(\bm{z})-\frac{\mathrm{d}\nu_{\bm{\pi}^{*}}}{\mathrm{d}\nu_{\bm{\pi}_{\widehat{\bm{\theta}}}}}(\bm{s})+\bm{\psi}^{\top}_{\widehat{\bm{\theta}}}\widehat{\bm{\theta}},
