\begin{lemma}\label{thetheoremofGlobalOptimalityofStationaryPoint}
Suppose Assumptions~\ref{theassumptionofcommunication}-\ref{RegularityConditiononsigmaandvarsigma} hold.
If the stationary policy $\bm{\pi}_{\widehat{\bm{\theta}}}$ satisfies $u_{\widehat{\bm{\theta}}}\in\mathcal{F}_{B,\infty}$, then it holds that  \begin{align}\label{theresuleoftheoremofGlobalOptimalityofStationaryPoint}
(1-\gamma)\mathbb{E}_{\mathrm{init}}[J(\bm{\pi}^{*})-J(\bm{\pi}_{\widehat{\bm{\theta}}})]=\mathcal{O}\big(B^{\frac{3}{2}}(mN)^{\frac{1}{4}-p}\big).
\end{align}
%where the expectations are taken over the random initialization.
\end{lemma}
\begin{proof}
%Let $u_{\widehat{\bm{\theta}}}=[u_{\widehat{\bm{\theta}}}(\bm{z})]_{\bm{z}\in\mathcal{S}\times\mathcal{A}}$, we use the Theorem~4.8 in~\cite{Wang2019} and have
Let $u_{\widehat{\bm{\theta}}}=[u_{\widehat{\bm{\theta}}}(\bm{z})]_{\bm{z}\in\mathcal{S}\times\mathcal{A}}$.
By invoking Theorem 4.8 from~\cite{Wang2019}, we obtain
\begin{align}
&(1-\gamma)\big(J(\bm{\pi}^{*})-J(\bm{\pi}_{\widehat{\bm{\theta}}})\big)\notag\\
\leq&2R_{0}\inf_{\bm{\theta}\in S^{\theta}_{B}}\big\{\|u_{\widehat{\bm{\theta}}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\bm{\theta}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\big\}.\label{thefirstinequalityinTheorem3}
\end{align}
For $\inf_{\bm{\theta}\in S^{\theta}_{B}}\|u_{\widehat{\bm{\theta}}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\bm{\theta}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}$ in (\ref{thefirstinequalityinTheorem3}), we have
\begin{align}\label{thefirstinequalityoftheoremofGlobalOptimalityofStationaryPoint}
&\inf_{\bm{\theta}\in
S^{\theta}_{B}}\big\{\|u_{\widehat{\bm{\theta}}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\bm{\theta}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\big\}\notag\\
\leq&\|u_{\widehat{\bm{\theta}}}-P_{\mathcal{F}_{B,m}}u_{\widehat{\bm{\theta}}}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\notag\\
&+\inf_{\bm{\theta}\in S^{\theta}_{B}}\big\{\|P_{\mathcal{F}_{B,m}}u_{\widehat{\bm{\theta}}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\bm{\theta}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\big\}.
\end{align}
Let $\widetilde{\bm{\theta}}\in S^{\theta}_{B}$ and satisfy $P_{\mathcal{F}_{B,m}}u_{\widehat{\bm{\theta}}}=\bm{\psi}^{\top}\big(\bm{\theta}(0)\big)\widetilde{\bm{\theta}}\in\mathcal{F}_{B,m}$, we have
\begin{align}\label{thesecondinequalityoftheoremofGlobalOptimalityofStationaryPoint}
&\inf_{\bm{\theta}\in S^{\theta}_{B}}\big\{\|u_{\widehat{\bm{\theta}}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\bm{\theta}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\big\}\notag\\
\leq&\|u_{\widehat{\bm{\theta}}}-P_{\mathcal{F}_{B,m}}u_{\widehat{\bm{\theta}}}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}+\|\bm{\psi}^{\top}\big(\bm{\theta}(0)\big)\widetilde{\bm{\theta}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\widetilde{\bm{\theta}}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}.
\end{align}
%Since $u_{\widehat{\bm{\theta}}}\in\mathcal{F}_{B,\infty}$, similar to Eq.~(B.5) in~\cite{Wang2019}, we have
Given that $u_{\widehat{\bm{\theta}}} \in \mathcal{F}_{B,\infty}$, analogous to Eq.~(B.5) in~\cite{Wang2019}, it follows that
\begin{align}\label{theinequalityoferrorbetweenPiuandu}
\mathbb{E}_{\mathrm{init}}\big[\|P_{\mathcal{F}_{B,m}}u_{\widehat{\bm{\theta}}}-u_{\widehat{\bm{\theta}}}\|^{2}_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\big]
%=&\int_{0}^{\infty}\mathbb{P}\big(\|\Pi_{\mathcal{F}_{B,m}}u_{\widehat{\bm{\theta}}}-u_{\widehat{\bm{\theta}}}\|^{2}_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\geq t\big)\mathrm{d}t\notag\\
%\leq&\int_{0}^{\infty}\exp{\Big(-\frac{1}{2}\big(\frac{t(mN)^{p-\frac{1}{2}}}{B}-1\big)^{2}\Big)}\mathrm{d}t\notag\\
\leq&\mathcal{O}\big(B(mN)^{-p}\big).
\end{align}
According to (iii) of Lemma \ref{Lemma1to3}, we also have
\begin{align}
&\mathbb{E}_{\mathrm{init}}\big[\|\bm{\psi}^{\top}\big(\bm{\theta}(0)\big)\widetilde{\bm{\theta}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\widetilde{\bm{\theta}}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\big]\notag\\
\leq&\Big(\mathbb{E}_{\mathrm{init}}\big[\|\bm{\psi}^{\top}\big(\bm{\theta}(0)\big)\widetilde{\bm{\theta}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\widetilde{\bm{\theta}}\|^{2}_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\big]\Big)^{1/2}\notag\\
\leq&\mathcal{O}\big(B^{\frac{3}{2}}(mN)^{\frac{1}{4}-p}\big).\label{theinequalityofthelocalerror}
\end{align}
By substituting (\ref{thesecondinequalityoftheoremofGlobalOptimalityofStationaryPoint}) (\ref{theinequalityoferrorbetweenPiuandu}), and (\ref{theinequalityofthelocalerror}) into (\ref{thefirstinequalityinTheorem3}) and subsequently taking the expectation, we have
\begin{align}
&(1-\gamma)\mathbb{E}_{\mathrm{init}}[J(\bm{\pi}^{*})-J(\bm{\pi}_{\widehat{\bm{\theta}}})]\notag\\
\leq&2R_{0}\mathbb{E}_{\mathrm{init}}\Big[\inf_{\bm{\theta}\in S^{\theta}_{B}}\big\{\|u_{\widehat{\bm{\theta}}}-\bm{\psi}^{\top}(\widehat{\bm{\theta}})\bm{\theta}\|_{\sigma_{\bm{\pi}_{\widehat{\bm{\theta}}}}}\big\}\Big]\notag\\
\leq&\mathcal{O}\big(B^{\frac{3}{2}}(mN)^{\frac{1}{4}-p}\big),\notag
\end{align}
which completes the proof of Lemma~\ref{thetheoremofGlobalOptimalityofStationaryPoint}.
\end{proof}
