By invoking Lemma~\ref{thetheoremofGlobalOptimalityofStationaryPoint} and imposing the additional, more stringent assumption that $u_{\bm{\theta}(k)} \in \mathcal{F}_{B,\infty}$, we can establish the subsequent theorem.
\begin{theorem}\label{thecorollaryofneuralpolicygradientmethod}
Suppose Assumptions~\ref{theassumptionofcommunication}-\ref{RegularityConditiononsigmaandvarsigma} hold.
In the Algorithm~\ref{distributedneuralpolicygradientAlgorithm}, let the learning rate $\eta_{a}\in(0,\frac{1}{2L})$, $K\geq4L^{2}$, and $T_{c}=\mathcal{O}\big((mN)^{2p-1}\big)$.
If $Q^{\bm{\pi}_{\bm{\theta}(k)}},u_{\bm{\theta}(k)}\in\mathcal{F}_{B,\infty}$ for all $k=0,\cdots,K-1$ during the iteration process, then it holds
%the joint policy parameter sequence $\{\bm{\theta}(k)\}^{K-1}_{k=0}$ satisfies
\begin{align}
&\frac{1-\gamma}{K}\sum_{k=0}^{K-1}\mathbb{E}[J(\bm{\pi}^{*})-J(\bm{\pi}_{\bm{\theta}(k)})]\notag\\
\leq&\frac{8(B+\eta_{a}R_{0})\sqrt{R_{0}}}{\sqrt{\eta_{a}K}}+\frac{4(B+\eta_{a}R_{0})\sigma_{\xi}}{\sqrt{|\mathcal{B}|}}+\tilde{\mathcal{O}}\big(B^{\frac{9}{4}}N^{\frac{1}{4}}T^{-\frac{3}{8}}_{c}\big)\notag\\
&+\mathcal{O}\big(B^{\frac{9}{4}}m^{\frac{1-2p}{8}}N^{\frac{3-2p}{8}}\big).\label{thelastinequalityintheorem}
\end{align}
%{\color{blue}where $\hat{K}$ is uniformly sampled among $\{0,\cdots,K-1\}$.}
\end{theorem}
\begin{proof}
%By recalling the definition of $\bm{\rho}(k)$ in (\ref{thedefinnitionofrho}), we use the property of the projection operator and have
By revisiting the definition of $\bm{\rho}(k)$ in (\ref{thedefinnitionofrho}), we leverage the property of the projection operator and have
\begin{align}\label{theprojectionoperateinequality}
\big(\eta_{a}\bm{\rho}(k)\!-\eta_{a}\nabla_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})\big)^{\top}\big(\eta_{a}\bm{\rho}(k)\!+\bm{\theta}(k)-\bm{\theta}\big)\leq0,
\end{align}
for all $\bm{\theta}\in S^{\theta}_{B}$.
According to (\ref{theprojectionoperateinequality}), we further have
\begin{align}
&\nabla_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})^{\top}\big(\bm{\theta}-\bm{\theta}(k)\big)\notag\\
\leq&\bm{\rho}^{\top}(k)\big(\bm{\theta}-\bm{\theta}(k)\big)-\eta_{a}\|\bm{\rho}(k)\|^{2}_{2}+\eta_{a}\bm{\rho}^{\top}(k)\nabla_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})\notag\\
\leq&\|\bm{\rho}(k)\|_{2}\big(\|\bm{\theta}-\bm{\theta}(k)\|_{2}+\eta_{a}\|\nabla_{\bm{\theta}}J(\bm{\pi}_{\bm{\theta}(k)})\|_{2}\big)\notag\\
\leq&\|\bm{\rho}(k)\|_{2}\Big(\|\bm{\theta}-\bm{\theta}(k)\|_{2}\notag\\
&+\eta_{a}\mathbb{E}_{\sigma_{k}}\big[\big|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})\big|\big\|\overline{\bm{\psi}}\big(\bm{z};\bm{\theta}(k)\big)\big\|_{2}\big]\Big)\notag\\
\leq&(2B+2\eta_{a}R_{0})\|\bm{\rho}(k)\|_{2},\label{theinequalityofthecorollaryofneuralpolicygradientmethod}
\end{align}
where the third inequality comes from (\ref{theresultofpolicygradientforagenti}) and the last inequality uses $\overline{\bm{\psi}}(\bm{z};\bm{\theta})$ in (\ref{thejointfeaturemapping}) and the fact that $\bm{\theta},\bm{\theta}(t)\in S^{\theta}_{B}$.
Note that the right-hand side of (\ref{theinequalityofthecorollaryofneuralpolicygradientmethod}) quantifies the deviation of $\bm{\theta}(k)$ from a stationary point $\bm{\widehat{\theta}}$.
By leveraging Lemma~\ref{thetheoremofGlobalOptimalityofStationaryPoint} and (\ref{theinequalityofthecorollaryofneuralpolicygradientmethod}), we have
%\par
%{\color{blue}Similar analysis to Theorem 4.9} in~\cite{Wang2019}, we have
\begin{align}
&\frac{1-\gamma}{K}\sum_{k=0}^{K-1}\mathbb{E}[J(\bm{\pi}^{*})-J(\bm{\pi}_{\bm{\theta}(k)})]\notag\\
\leq&\frac{2B+2\eta_{a}R_{0}}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\bm{\rho}(k)\|_{2}]+\mathcal{O}\big(B^{\frac{3}{2}}(mN)^{\frac{1}{4}-p}\big)\label{beforelastinequality}
%\leq&{\color{blue}\frac{4B\sqrt{R_{0}}}{\sqrt{\eta_{a}T}}+\frac{2\sqrt{2}B\sigma_{\xi}}{\sqrt{|\mathcal{B}|}}+\tilde{\mathcal{O}}\big(B^{\frac{3}{2}}(mN)^{\frac{1}{8}-\frac{p}{4}}\big)},\notag\\
%\leq&\frac{8(B+\eta_{a}R_{0})\sqrt{R_{0}}}{\sqrt{\eta_{a}K}}+\frac{4(B+\eta_{a}R_{0})\sigma_{\xi}}{\sqrt{|\mathcal{B}|}}+\tilde{\mathcal{O}}\big(B^{\frac{9}{4}}N^{\frac{1}{4}}T^{-\frac{1}{4}}_{c}\big)\notag\\
%&+\mathcal{O}\big(B^{\frac{9}{4}}m^{\frac{1-2p}{8}}N^{\frac{3-2p}{8}}\big),\notag
\end{align}
%By combining Theorem~\ref{ConvergencetoStationaryPoint} and (\ref{beforelastinequality}), this theorem can be proved.
By integrating Theorem~\ref{ConvergencetoStationaryPoint} with inequality~(\ref{beforelastinequality}), the proof of this theorem can be rigorously established.
\end{proof}
\par
Theorem~\ref{thecorollaryofneuralpolicygradientmethod} establishes the global convergence of Algorithm~\ref{distributedneuralpolicygradientAlgorithm}.
Note that in the right-hand side of (\ref{thelastinequalityintheorem}), the term $\tilde{\mathcal{O}}\big(B^{\frac{9}{4}}N^{\frac{1}{4}}T^{-\frac{3}{8}}_{c}\big)+\mathcal{O}\big(B^{\frac{9}{4}}m^{\frac{1-2p}{8}}N^{\frac{3-2p}{8}}\big)$ corresponds to the error introduced by function approximation in the distributed critic step, while the term $\frac{4(B+\eta_{a}R_{0})\sigma_{\xi}}{\sqrt{|\mathcal{B}|}}$ represents the policy gradient approximation error incurred in the decentralized actor step.
