\subsection{Proof of Lemma~\ref{lemmaofaverageconsensus}}\label{theproofoflemmaofaverageconsensus}
\begin{proof}
%Consider $\bm{W}_{\mathrm{tot}}(t+1)-\mathbf{1}\otimes\overline{\bm{W}}(t+1)$,
Recall that $g^{k}_{i}(t)$ in (\ref{theTDlearningindistributedneuralTDalgorithm1}) and $e^{k}_{i}(t)$ in (\ref{thedefinitionofstochastic-5}), define $\mathbf{G}^{k}(t)=\big(g^{k}_{1}(t)^{\top},\cdots,g^{k}_{N}(t)^{\top}\big)^{\top}$ and $\mathbf{E}^{k}(t)=\big(e^{k}_{1}(t)^{\top},\cdots,e^{k}_{N}(t)^{\top}\big)^{\top}$.
According to definition of $C=I_{N}-(1/N)\mathbf{1}_{N}\mathbf{1}_{N}^{\top}$, we have
\begin{align}
&(C\otimes I_{dmN})W_{tot}(t+1)\notag\\
=&W_{tot}(t+1)-\mathbf{1}_{N}\otimes\overline{W}(t+1)\notag\\
=&\big(A(t)\otimes I_{dmN}\big)W_{tot}(t)-\eta_{c,t}\mathbf{G}^{k}(t)-\mathbf{E}^{k}(t)\notag\\
&-\big(\mathbf{1}_{N}\otimes\overline{W}(t)-\eta_{c,t}\mathbf{1}_{N}\otimes g^{k}_{\mathrm{ave}}(t)-\mathbf{1}_{N}\otimes e^{k}_{\mathrm{ave}}(t)\big)\label{theequalityofaverageconsensusinequality}\\
=&\big(A(t)\otimes I_{dmN}\big)(C\otimes I_{dmN})W_{tot}(t)\notag\\
&-\eta_{c,t}(C\otimes I_{dmN})\mathbf{G}^{k}(t)-(C\otimes I_{dmN})\mathbf{E}^{k}(t)\notag\\
=&\prod_{t'=0}^{t}\big(A(t-t')\otimes I_{dmN}\big)(C\otimes I_{dmN})W_{tot}(0)\notag\\
&+\sum_{t'=0}^{t}\eta_{c,t'}\prod_{l=t'+1}^{t}\big(A(l)\otimes I_{dmN}\big)(C\otimes I_{dmN})\mathbf{G}^{k}(t')\notag\\
&-\sum_{t'=0}^{t}\prod_{l=t'+1}^{t}\big(A(l)\otimes I_{dmN}\big)(C\otimes I_{dmN})\mathbf{E}^{k}(t'),\label{theequalityofaverageconsensus}
\end{align}
where (\ref{theequalityofaverageconsensusinequality}) comes from (\ref{thekeystepindistributedneuralTDalgorithm}).
By taking the norm on both sides of (\ref{theequalityofaverageconsensus}), we have
\begin{align}
&\|(C\otimes I_{dmN})W_{tot}(t+1)\|_{2}\notag\\
\leq&\Big\|\Big(\prod_{t'=0}^{t}A(t-t')\Big)C\otimes I_{dmN}\Big\|_{2}\big\|W_{tot}(0)\big\|_{2}\notag\\
&+\sum_{t'=0}^{t}\eta_{c,t'}\Big\|\Big(\prod_{l=t'+1}^{t}A(l)\Big)C\otimes I_{dmN}\Big\|_{2}\big\|\mathbf{G}^{k}(t')\big\|_{2}\notag\\
&+\sum_{t'=0}^{t}\Big\|\Big(\prod_{l=t'+1}^{t}A(l)\Big)C\otimes I_{dmN}\Big\|_{2}\big\|\mathbf{E}^{k}(t')\big\|_{2}\notag\\
\leq&\frac{\lambda^{t+1}_{D}}{\lambda}\|W_{tot}(0)\|_{2}+\sum_{t'=0}^{t}\frac{\lambda^{t-t'}_{D}}{\lambda}\eta_{c,t'}\|\mathbf{G}^{k}(t')\|_{2}\notag\\
&+\sum_{t'=0}^{t}\frac{\lambda^{t-t'}_{D}}{\lambda}\|\mathbf{E}^{k}(t')\|_{2},\label{inequalityofaverageconsensus}
\end{align}
where the first inequality uses the triangle inequality and the fact that the norm of $C$ is less than 1, and the last inequality follows from Proposition~4 in~\cite{nedic2018}.
%\begin{align}
%\big\|\big(A(t)C\otimes I_{dmN}\big)W_{tot}\big\|_{2}\leq\lambda\|(C\otimes I_{dmN})W_{tot}\|_{2}.
%\end{align}
%Based on (\ref{inequalityofaverageconsensus}), we have
%\begin{align}
%&\|(C\otimes I_{dmN})W_{tot}(t+1)\|^{2}_{2}\notag\\
%\leq&3\lambda^{2t+2}\|W_{tot}(0)\|^{2}_{2}+3\sum_{t'=0}^{t}\lambda^{t-t'}\eta_{t'}\|\mathbf{G}^{k}(t')\|_{2}\notag\\
%&+\sum_{t'=0}^{t}\lambda^{t-t'}\|\mathbf{E}^{k}(t')\|_{2},\label{inequalityofaverageconsensusafter}
%\end{align}
%Similar to proof of Lemma 1 in \cite{Doan2019ICML},
By taking expectation on both sides of (\ref{inequalityofaverageconsensus}), we have
%Taking expectation on both sides of (\ref{inequalityofaverageconsensus}), we have
\begin{align}
&\mathbb{E}_{\mathrm{init}}[\|(C\otimes I_{dmN})W_{tot}(t+1)\|_{2}]\notag\\
\leq&\frac{\lambda^{t+1}_{D}}{\lambda}\mathbb{E}_{\mathrm{init}}[\|W_{tot}(0)\|_{2}]+\sum_{t'=0}^{t}\frac{\lambda^{t-t'}_{D}}{\lambda}\eta_{c,t'}\mathbb{E}_{\mathrm{init}}[\|\mathbf{G}^{k}(t')\|_{2}]\notag\\
&+\sum_{t'=0}^{t}\frac{\lambda^{t-t'}_{D}}{\lambda}\mathbb{E}_{\mathrm{init}}[\|\mathbf{E}^{k}(t')\|_{2}].\label{resultofinequalityofaverageconsensusbefore}
\end{align}
\par
For $\mathbf{G}^{k}(t')$ the right-hand side of (\ref{resultofinequalityofaverageconsensusbefore}), we can use (\ref{theTDlearningindistributedneuralTDalgorithm1}) and obtain
\begin{align}
&\mathbb{E}_{\mathrm{init}}[\|g^{k}_{i}(t')\|^{2}_{2}]\notag\\
=&\mathbb{E}_{\mathrm{init}}\big[\big\|\delta^{k}_{i}(t')\nabla_{W_{i}}\widehat{Q}_{i,t'}(\bm{z})\big\|^{2}_{2}\big]\notag\\
\leq& (mN)^{1-2p}\mathbb{E}_{\mathrm{init}}\big[\big|\delta^{k}_{i,t'}\big|^{2}\big]\notag\\
\leq& (mN)^{1-2p}\mathbb{E}_{\mathrm{init}}\big[\big(\widehat{Q}_{i,t'}(\bm{z})-(1-\gamma)r_{i}(\bm{z})-\gamma\widehat{Q}_{i,t'}(\bm{z}')\big)^{2}\big]\notag\\
\leq&3(mN)^{1-2p}\mathbb{E}_{\mathrm{init}}\big[\widehat{Q}_{i,t'}(\bm{z})^{2}+\widehat{Q}_{i,t'}(\bm{z}')^{2}+R^{2}_{0}\big]\notag\\
\leq& (mN)^{1-2p}\mathbb{E}_{\mathrm{init}}\big[12\widehat{Q}_{0}(\bm{z})^{2}+12B^{2}(mN)^{1-2p}+3R^{2}_{0}\big]\notag\\
\leq& 3R^{2}_{0}(mN)^{1-2p}+(12d_{1}+12B^{2})(mN)^{2-4p},\label{thesecondinequalityofVarianceBound}
\end{align}
where the first inequality follows from (iv) of Fact \ref{thefactinpaper}, the third inequality uses Assumption \ref{theassumptionofreward} and the fact that $(a + b + c)^2 \leq 3a^2 + 3b^2 + 3c^2$ for all $a, b, c \in \mathbb{R}$, the forth inequality is obtained from (v) of Fact \ref{thefactinpaper}, and the last inequality follows from (ii) of Fact \ref{thefactinpaper}.
According to (\ref{thesecondinequalityofVarianceBound}), we further have
\begin{align}\label{theboundofg}
\mathbb{E}_{\mathrm{init}}[\|g^{k}_{i}(t')\|_{2}]\leq\mathcal{O}\big(B(mN)^{\frac{1}{2}-p}\big).
\end{align}
\par
For $\mathbf{E}^{k}(t')$ in the right-hand side of  (\ref{resultofinequalityofaverageconsensusbefore}), we use (\ref{thedefinitionofstochastic-5}) and the projection property to derive
\begin{align}\label{theprojectionpropertyofe}
\|e^{k}_{i}(t')\|_{2}\leq\eta_{c,t'}\|g^{k}_{i}(t)\|_{2}.
\end{align}
Substituting (\ref{theboundofg}) and (\ref{theprojectionpropertyofe}) in (\ref{resultofinequalityofaverageconsensusbefore}), we have
\begin{align}
&\mathbb{E}_{\mathrm{init}}[\|(C\otimes I_{dmN})W_{tot}(t+1)\|_{2}]\notag\\
\leq&\frac{\sqrt{md_{1}}N}{\lambda}\lambda^{t+1}_{D}+\sum_{t'=0}^{t}\frac{\lambda^{t-t'}_{D}}{\lambda}\eta_{c,t'}\mathcal{O}(Bm^{\frac{1}{2}-p}N^{1-p}).\label{resultofinequalityofaverageconsensus}
\end{align}
%where (\ref{resultofinequalityofaverageconsensus}) can be get from (i) and (ii) in Lemma \ref{thelemmainpopulationsemigradient}.
Substituting $\eta_{c,t}=\frac{1-\gamma}{24\sqrt{t+1}}$ into (\ref{resultofinequalityofaverageconsensus}), we have
\begin{align}
&\mathbb{E}_{\mathrm{init}}[\|(C\otimes I_{dmN})W_{tot}(t)\|_{2}]\notag\\
\leq&\frac{\sqrt{md_{1}}N}{\lambda}\lambda^{t}_{D}+\sum_{t'=0}^{t-1}\frac{(1-\gamma)\lambda^{t-1-t'}_{D}}{24\lambda\sqrt{t'+1}}\mathcal{O}(Bm^{\frac{1}{2}-p}N^{1-p}),\notag
\end{align}
which completes the proof.
\end{proof}


