\leq&2\mathbb{E}_{\mathrm{init}}[\|g^{k}_{i}(t)\|^{2}_{2}]+2\mathbb{E}_{\mathrm{init}}[\|\bar{g}^{k}_{i}(t)\|^{2}_{2}].
\end{align}
By using $\bar{g}^{k}_{i}(t)=\mathbb{E}_{\varsigma^{+}_{k}}[g^{k}_{i}(t)]$ in (\ref{thedefinitionofstochastic-2}) and (\ref{thesecondinequalityofVarianceBound}), we have
\begin{align}
&\mathbb{E}_{\mathrm{init},\varsigma^{+}_{k}}[\|g^{k}_{i}(t)-\bar{g}^{k}_{i}(t)\|^{2}_{2}]\notag\\
\leq& 12R^{2}_{0}(mN)^{1-2p}+(48d_{1}+48B^{2})(mN)^{2-4p}.\label{fromthefacti}
\end{align}
