\underline{For (ii) of Lemma \ref{Lemma4-6}:}
By the definitions of $\bar{g}^{k}_{i}(t)$ in (\ref{thedefinitionofstochastic-2}) and $\bar{g}^{k}_{0,\mathrm{ave}}(t)$ in (\ref{thedefinitionofstochastic2-3}), we have
\begin{align}\label{gradientdifference}
&\|\bar{g}^{k}_{i}(t)-\bar{g}^{k}_{0,\mathrm{ave}}(t)\|_{2}\notag\\
=&\big\|\mathbb{E}_{\varsigma_{k}^{+}}\big[\delta^{k}_{i}(t)\nabla_{W_{i}}\widehat{Q}_{i,t}(\bm{z})\big]\notag\\
&-\mathbb{E}_{\varsigma_{k}^{+}}\big[\delta^{k}_{0,\mathrm{ave}}(t)\nabla_{W'}\widehat{Q}_{0}\big(\bm{z};\overline{W}(t)\big)\big]\big\|_2\notag\\
=&\Big\|\mathbb{E}_{\varsigma_{k}^{+}}\Big[\Big(\delta^{k}_{i}(t)-\delta^{k}_{0,\mathrm{ave}}(t)\Big)\nabla_{W_{i}}\widehat{Q}_{i,t}(\bm{z})\notag\\
&+\delta^{k}_{0,\mathrm{ave}}(t)\Big(\nabla_{W_{i}}\widehat{Q}_{i,t}(\bm{z})-\nabla_{W'}\widehat{Q}_{0}\big(\bm{z};\overline{W}(t)\big)\Big)\Big]\Big\|_{2}\notag\\
\leq&\mathbb{E}_{\varsigma_{k}^{+}}\Big[(mN)^{\frac{1}{2}-p}\big|\delta^{k}_{i}(t)-\delta^{k}_{0,\mathrm{ave}}(t)\big|\notag\\
&+\big|\delta^{k}_{0,\mathrm{ave}}(t)\big|\big\|\nabla_{W_{i}}\widehat{Q}_{i,t}(\bm{z})-\nabla_{W'}\widehat{Q}_{0}\big(\bm{z};\overline{W}(t)\big)\big\|_{2}\Big],
\end{align}
where the inequality is obtained from (iv) of Fact \ref{thefactinpaper}.
