\leq& 3\mathbb{E}_{\mathrm{init}}\big[\|\bar{g}^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{0,\mathrm{ave}}(t)\|^{2}_{2}\big]\notag\\
&+3\mathbb{E}_{\mathrm{init}}\big[\|\bar{g}^{k}_{0,\mathrm{ave}}(t)-\bar{g}^{k*}_{0,\mathrm{ave}}\|^{2}_{2}\big]+3\mathbb{E}_{\mathrm{init}}\big[\|\bar{g}^{k*}_{0,\mathrm{ave}}\|^{2}_{2}\big]\notag\\
\leq&\underbrace{\frac{3}{N}\mathbb{E}_{\mathrm{init}}\Big[\sum_{i=1}^{N}\|\bar{g}^{k}_{i}(t)-\bar{g}^{k}_{0,\mathrm{ave}}(t)\|^{2}\Big]}_{\mathrm{(i)}}\notag\\
&+\underbrace{3\mathbb{E}_{\mathrm{init}}\big[\|\bar{g}^{k}_{0,\mathrm{ave}}(t)\!-\!\bar{g}^{k*}_{0,\mathrm{ave}}\|^{2}_{2}\big]}_{\mathrm{(ii)}}+\underbrace{3\mathbb{E}_{\mathrm{init}}\big[\|\bar{g}^{k*}_{0,\mathrm{ave}}\|^{2}_{2}\big]}_{\mathrm{(iii)}},\label{firstinequalitythelemmaofbargave}
\end{align}
where the last inequality uses (\ref{thedefinitionofstochastic2-3}).
\par
For the $\mathrm{(i)}$-th term in (\ref{firstinequalitythelemmaofbargave}), we can use (ii) of
Lemma~\ref{Lemma4-6} and have
