&\mathbb{E}_{\mathrm{init}}\big[\|\bar{g}^{k*}_{0,\mathrm{ave}}\|^{2}_{2}\big]\notag\\
=&\mathbb{E}_{\mathrm{init}}\big[\|\mathbb{E}_{\varsigma_{k}^{+}}[\delta^{k*}_{0,\mathrm{ave}}\nabla_{W'}\widehat{Q}_{0}(\bm{z};W^{*}_{k})]\|^{2}_{2}\big]\notag\\
