\subsection{Proof of Lemma \ref{StochasticDescentLemma}}\label{theproofofStochasticDescentLemma}
%Recall the definitions of {\color{blue}$g_{i}(k)$ in (\ref{thedefinitionofstochastic-1}), $g_{\mathrm{ave}}(k)$ in (\ref{thedefinitionofstochastic-2}), $e_{i}(k)$ in (\ref{thedefinitionofstochastic-5}), and $e_{\mathrm{ave}}(k)$ in (\ref{thedefinitionofstochastic-6}),}
By recalling the update of $W_{i}(t+1)$ in (\ref{thekeystepindistributedneuralTDalgorithm}),
we have
%\begin{align}\label{inequalityofStochasticDescentLemma}
%&\mathbb{E}_{\mathrm{init}}[\|\overline{\bm{W}}(k+1)-\bm{W}^{*}\|^{2}_{2}]\notag\\
%=&\mathbb{E}_{\mathrm{init}}[\|\overline{\bm{W}}(k)-\bm{W}^{*}\|^{2}_{2}+\eta_{c}^{2}\|g_{\mathrm{ave}}(k)\|^{2}_{2}+\|e_{\mathrm{ave}}(k)\|^{2}_{2}\notag\\
%&-2\eta_{c}\big(\overline{\bm{W}}(k)-\bm{W}^{*}\big)^{\top}g_{\mathrm{ave}}(k)\notag\\
%&-2\big(\overline{\bm{W}}(k)-\bm{W}^{*}\big)^{\top}e_{\mathrm{ave}}(k)+2\eta_{c} g^{\top}_{\mathrm{ave}}(k)e_{\mathrm{ave}}(k).
%\end{align}
%Taking expectation on both sides of (\ref{inequalityofStochasticDescentLemma}), we can obtain
\begin{align}\label{expectationinequalityofStochasticDescentLemma}
&\mathbb{E}_{\mathrm{init}}[\|\overline{W}(t+1)-W^{*}_{k}\|^{2}_{2}]\notag\\
=&\mathbb{E}_{\mathrm{init}}\big[\|\overline{W}(t)-W^{*}_{k}\|^{2}_{2}+\eta_{c,t}^{2}\|g^{k}_{\mathrm{ave}}(t)\|^{2}_{2}+\|e^{k}_{\mathrm{ave}}(t)\|^{2}_{2}\notag\\
&-2\eta_{c,t}\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}g^{k}_{\mathrm{ave}}(t)\notag\\
&-2\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}e^{k}_{\mathrm{ave}}(t)+2\eta_{c,t}g^{k}_{\mathrm{ave}}(t)^{\top}e^{k}_{\mathrm{ave}}(t)\big]\notag\\
=&\mathbb{E}_{\mathrm{init}}[\|\overline{W}(t)-W^{*}_{k}\|^{2}_{2}]+\underbrace{\eta_{c,t}^{2}\mathbb{E}_{\mathrm{init}}[\|g^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]}_{\mathrm{(i)}}\notag\\
&+\underbrace{\mathbb{E}_{\mathrm{init}}[\|e^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]}_{\mathrm{(ii)}}\notag\\
&\underbrace{-2\eta_{c,t}\mathbb{E}_{\mathrm{init}}\big[\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}g^{k}_{\mathrm{ave}}(t)\big]}_{\mathrm{(iii)}}\notag\\
&\underbrace{-2\mathbb{E}_{\mathrm{init}}\big[\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}e^{k}_{\mathrm{ave}}(t)\big]}_{\mathrm{(iv)}}\notag\\
&+\underbrace{2\eta_{c,t}\mathbb{E}_{\mathrm{init}}[g^{k}_{\mathrm{ave}}(t)^{\top}e^{k}_{\mathrm{ave}}(t)]}_{\mathrm{(v)}}.
\end{align}
\par
For the $\mathrm{(i)}$-th term %$\eta_{c}^{2}\mathbb{E}\big[\|g_{\mathrm{ave}}(k)\|^{2}_{2}\big]$
in (\ref{expectationinequalityofStochasticDescentLemma}), according to the definition of $g^{k}_{\mathrm{ave}}(t)$ in (\ref{thedefinitionofstochastic-2}), we have
\begin{align}
&\eta^{2}_{c,t}\mathbb{E}_{\mathrm{init}}[\|g^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]\notag\\
\leq&2\eta^{2}_{c,t}\mathbb{E}_{\mathrm{init}}[\|g^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]+2\eta^{2}_{c,t}\mathbb{E}_{\mathrm{init}}[\|\bar{g}^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]\notag\\
\leq&\frac{2\eta^{2}_{c,t}}{N}\sum_{i=1}^{N}\mathbb{E}_{\mathrm{init}}[\|g^{k}_{i}(t)-\bar{g}^{k}_{i}(t)\|^{2}_{2}]+2\eta^{2}_{c,t}\mathbb{E}_{\mathrm{init}}[\|\bar{g}^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]\notag\\
\leq&24\eta^{2}_{c,t}\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z};\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\Big)^{2}\Big]\notag\\
&+\eta^{2}_{c,t}\mathcal{O}\big(B^{3}(mN)^{1-2p}\big),\label{newconclusioninequality}
\end{align}
where the last inequality uses the (i) and (iii) of Lemma~\ref{Lemma4-6}.
\par
For the $\mathrm{(ii)}$-th term in (\ref{expectationinequalityofStochasticDescentLemma}), we use the properties of projection operation and have
\begin{align}\notag
\|e^{k}_{\mathrm{ave}}(t)\|^{2}_{2}\leq\frac{1}{N}\sum_{i=1}^{N}\|e^{k}_{i}(t)\|^{2}_{2}\leq\frac{1}{N}\sum_{i=1}^{N}\eta_{c,t}^{2}\|g^{k}_{i}(t)\|^{2}_{2}.
\end{align}
By using (\ref{theboundofg}), we further have
\begin{align}\label{expectationresultofiithinequalityofStochasticDescentLemma}
&\mathbb{E}_{\mathrm{init}}[\|e^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]\notag\\
\leq&3\eta_{c,t}^{2}R^{2}_{0}(mN)^{1-2p}+\eta_{c,t}^{2}(12d_{1}+12B^{2})(mN)^{2-4p}\notag\\
=&\eta^{2}_{c,t}\mathcal{O}\big(B^{2}(mN)^{1-2p}\big).
\end{align}
\par
For the $\mathrm{(iii)}$-th term in (\ref{expectationinequalityofStochasticDescentLemma}),
%since $\bm{W}^{*}$ is an approximate stationary point of (\ref{theMSBEofmathbfW}),
we have
\begin{align}
&-2\eta_{c,t}\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}g^{k}_{\mathrm{ave}}(t)\notag\\
\leq&-2\eta_{c,t}\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}\big(g^{k}_{\mathrm{ave}}(t)-\bar{g}^{k*}_{0,\mathrm{ave}}\big)\label{eq:explain}\\
=&-2\eta_{c,t}\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}\big(g^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{\mathrm{ave}}(t)+\bar{g}^{k}_{\mathrm{ave}}(t)\notag\\
&-\bar{g}^{k}_{0,\mathrm{ave}}(t)\big)-2\eta_{c,t}\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}\big(\bar{g}^{k}_{0,\mathrm{ave}}(t)-\bar{g}^{k*}_{0,\mathrm{ave}}\big), \label{iiithterminequationofPopulationDescentLemma}
\end{align}
where the first inequality follows from (\ref{theinequalityofstationarypoint}).
Since $\overline{W}(t),W^{*}_{k}\in S^{W}_{B}$, we have
\begin{align}\label{1thiiithterminequationofPopulationDescentLemma}
&\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}\big(g^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{\mathrm{ave}}(t)+\bar{g}^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{0,\mathrm{ave}}(t)\big)\notag\\
\geq&-2B\big(\|g^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{\mathrm{ave}}(t)\|_{2}+\|\bar{g}^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{0,\mathrm{ave}}(t)\|_{2}\big).
\end{align}
%Note that $\big(\overline{\bm{W}}(k)-\bm{W}^{*}\big)^{\top}\big(\bar{g}_{0,\mathrm{ave}}(k)-\bar{g}^{*}_{0}\big)$ in (\ref{iiithterminequationofPopulationDescentLemma}) obeys
According to the definitions of $\bar{g}^{k}_{0,\mathrm{ave}}(t)$ in (\ref{thedefinitionofstochastic2-3}) and $\bar{g}^{k*}_{0,\mathrm{ave}}$ in (\ref{thedefinitionofstochastic2-1}), we have
\begin{align}\label{2thiiithterminequationofPopulationDescentLemma}
&\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}\big(\bar{g}^{k}_{0,\mathrm{ave}}(t)-\bar{g}^{k*}_{0,\mathrm{ave}}\big)\notag\\
=&\mathbb{E}_{\varsigma^{+}_{k}}\Big[\Big(\delta^{k}_{0,\mathrm{ave}}(t)-\delta^{k*}_{0,\mathrm{ave}}\Big)\cdot\notag\\
&\Big(\nabla_{W'}\widehat{Q}_{0}\big(\bm{z};W'(0)\big)^{\top}\big(\overline{W}(t)-W^{*}_{k}\big)\Big)\Big]\notag\\
=&\mathbb{E}_{\varsigma^{+}_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z},\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\Big)^{2}\notag\\
&-\gamma\Big(\widehat{Q}_{0}\big(\bm{z}',\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z}';W^{*}_{k})\Big)\cdot\notag\\
&\Big(\widehat{Q}_{0}\big(\bm{z},\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\Big)\Big]\notag\\
\geq&(1-\gamma)\mathbb{E}_{\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z},\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\Big)^{2}\Big],
\end{align}
where the last inequality follows from the fact that $\bm{z}$ and $\bm{z}'$ have the same stationary station-action distribution over $\varsigma_{k}$.
Substituting (\ref{1thiiithterminequationofPopulationDescentLemma}) and (\ref{2thiiithterminequationofPopulationDescentLemma}) into
(\ref{iiithterminequationofPopulationDescentLemma}), we have
\begin{align}\label{resultofiiithterminequationofPopulationDescentLemma}
&-2\eta_{c,t}\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}g^{k}_{\mathrm{ave}}(t)\notag\\
\leq&-2(1-\gamma)\eta_{c,t}\mathbb{E}_{\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}(\bm{z},\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\Big)^{2}\Big]\notag\\
&+4\eta_{c,t} B\big(\|g^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{\mathrm{ave}}(t)\|_{2}+\|\bar{g}^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{0,\mathrm{ave}}(t)\|_{2}\big).
\end{align}
Taking expectation on both sides of (\ref{resultofiiithterminequationofPopulationDescentLemma}), we have
\begin{align}\label{expectationresultofiiithterminequationofPopulationDescentLemma}
&-2\eta_{c,t}\mathbb{E}_{\mathrm{init}}\big[\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}g^{k}_{\mathrm{ave}}(t)\big]\notag\\
\leq&-2(1-\gamma)\eta_{c,t}\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}(\bm{z},\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\Big)^{2}\Big]\notag\\
&+4\eta_{c,t} B\mathbb{E}_{\mathrm{init}}[\|g^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{\mathrm{ave}}(t)\|_{2}]\notag\\
&+4\eta_{c,t} B\mathbb{E}_{\mathrm{init}}[\|\bar{g}^{k}_{\mathrm{ave}}(t)-\bar{g}^{k}_{0,\mathrm{ave}}(t)\|_{2}]\notag\\
\leq&-2\eta_{c,t}(1-\gamma)\mathbb{E}_{\mathrm{init},\varsigma_{k}}\Big[\Big(\widehat{Q}_{0}\big(\bm{z},\overline{W}(t)\big)-\widehat{Q}_{0}(\bm{z};W^{*}_{k})\Big)^{2}\Big]\notag\\
&+\eta_{c,t}\mathcal{O}\big(B^{\frac{5}{2}}(mN)^{\frac{1}{2}-p}\big),
\end{align}
where the last inequality follows from (i) and (ii) of Lemma~\ref{Lemma4-6}.
\par
For the $\mathrm{(iv)}$-th term
%$-2\mathbb{E}\big[\big(\overline{\bm{W}}(k)-\bm{W}^{*}\big)^{\top}e_{\mathrm{ave}}(k)\big]$
in (\ref{expectationinequalityofStochasticDescentLemma}), we use (\ref{expectationresultofiithinequalityofStochasticDescentLemma}) and have
\begin{align}\label{expectationresultofivthinequalityofStochasticDescentLemma}
-2\mathbb{E}_{\mathrm{init}}\big[\big(\overline{W}(t)-W^{*}_{k}\big)^{\top}e^{k}_{\mathrm{ave}}(t)\big]\leq&4B\mathbb{E}_{\mathrm{init}}[\|e^{k}_{\mathrm{ave}}(t)\|_{2}]\notag\\
=&\eta_{c,t}\mathcal{O}\big(B^{2}(mN)^{\frac{1}{2}-p}\big).
\end{align}
\par
For the $\mathrm{(v)}$-th term in (\ref{expectationinequalityofStochasticDescentLemma}), we use Cauchy-Schwartz inequality and have
\begin{align}\label{expectationresultofvthinequalityofStochasticDescentLemma}
&2\eta_{c,t}\mathbb{E}_{\mathrm{init}}[g^{k}_{\mathrm{ave}}(t)^{\top}e^{k}_{\mathrm{ave}}(t)]\notag\\
\leq&2\eta_{c,t}\mathbb{E}_{\mathrm{init}}[\|g^{k}_{\mathrm{ave}}(t)\|_{2}\|e^{k}_{\mathrm{ave}}(t)\|_{2}]\notag\\
\leq&2\eta_{c,t}\mathbb{E}_{\mathrm{init}}[\|g^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]^{\frac{1}{2}}\mathbb{E}_{\mathrm{init}}[\|e^{k}_{\mathrm{ave}}(t)\|^{2}_{2}]^{\frac{1}{2}}\notag\\
=&\eta^{2}_{c,t}\mathcal{O}\big(B^{2}(mN)^{1-2p}\big),
\end{align}
where the last inequality follows from (\ref{theboundofg}) and (\ref{theprojectionpropertyofe}).
Substituting (\ref{newconclusioninequality}), (\ref{expectationresultofiithinequalityofStochasticDescentLemma}), (\ref{expectationresultofiiithterminequationofPopulationDescentLemma}), (\ref{expectationresultofivthinequalityofStochasticDescentLemma}), and (\ref{expectationresultofvthinequalityofStochasticDescentLemma}) into (\ref{expectationinequalityofStochasticDescentLemma}), we can complete the proof of Lemma~\ref{StochasticDescentLemma}.
\subsection{Proof of Lemma~\ref{thefirstlemmaoftheequalityofLipschitzbefore}}\label{theproofofthefirstlemmaoftheequalityofLipschitzbefore}
Recall that $\xi_{i,k}=\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})-\mathbb{E}_{\sigma_{k}}[\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})]$,
we have
\begin{align}\label{thei-thinequalityofthelemmaoferrorbetweennablaandwidenabla}
&\mathbb{E}[\|\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})-\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})\|^{2}_{2}]\notag\\
\leq&2\mathbb{E}[\|\xi_{i,k}\|^{2}_{2}]+2\mathbb{E}[\|\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})-\mathbb{E}_{\sigma_{k}}[\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})]\|^{2}_{2}].
\end{align}
Based on (\ref{theresultofpolicygradientforagenti}) in Proposition~\ref{ThepolicygradienttheoremforMARL}, we have
\begin{align}\label{theii-thinequalityofthelemmaoferrorbetweennablaandwidenabla}
&\|\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})-\mathbb{E}_{\sigma_{k}}[\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})]\|_{2}\notag\\
=&\big\|\mathbb{E}_{\sigma_{k}}\big[\overline{\psi}_{i}\big(\bm{s},a_{i};\theta_{i}(k)\big)\big(Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})\big)\big]\big\|_{2}\notag\\
\leq&\mathbb{E}_{\sigma_{k}}\big[\big\|\overline{\psi}_{i}\big(\bm{s},a_{i};\theta_{i}(k)\big)\big\|_{2}\big|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})\big|\big]\notag\\
\leq&2(mN)^{\frac{1}{2}-p}\mathbb{E}_{\sigma_{k}}[|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})|]\notag\\
\leq&2\kappa_{a}(mN)^{\frac{1}{2}-p}\|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(t)}}_{i,\mathrm{out}}(\bm{z})\|_{\varsigma_{k}},
\end{align}
where the first inequality comes from the Jensen's inequality, the second inequality holds from the fact that $\|\psi_{i,r}(\bm{s},a_{i};\theta_{i})\|_{2}\leq(mN)^{-p}$ in (\ref{thenormofpsi}), and the last inequality achieves by Assumption~\ref{RegularityConditiononsigmaandvarsigma}.
Substituting (\ref{theii-thinequalityofthelemmaoferrorbetweennablaandwidenabla}) into (\ref{thei-thinequalityofthelemmaoferrorbetweennablaandwidenabla}), we have
\begin{align}
&\mathbb{E}[\|\nabla_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})-\widehat{\nabla}_{\theta_{i}}J(\bm{\pi}_{\bm{\theta}(k)})\|^{2}_{2}]\notag\\
\leq&2\mathbb{E}[\|\xi_{i,k}\|^{2}_{2}]+8\kappa^{2}_{a}(mN)^{1-2p}\mathbb{E}[\|Q^{\bm{\pi}_{\bm{\theta}(k)}}(\bm{z})-\widehat{Q}^{\bm{\pi}_{\bm{\theta}(k)}}_{i,\mathrm{out}}(\bm{z})\|_{\varsigma_{k}}^{2}],\notag
\end{align}
which completes the proof of Lemma~\ref{thefirstlemmaoftheequalityofLipschitzbefore}.
