        \begin{lstlisting}[caption={Default code used when no code can be extracted from the LLM response.}, label={lst: tournament}]
import numpy as np
import random

def selection(individuals, k=100, tour_size=3):
    # Tournament selection
    # Compute mean error for each individual
    mean_errors = [np.mean(ind.case_values) for ind in individuals]
    selected_individuals = []

    # Select `k` individuals
    for _ in range(k):
        # Randomly select competitors
        competitors = random.sample(range(len(individuals)), tour_size)
        # Select the one with the lowest error
        best_idx = min(competitors, key=lambda idx: mean_errors[idx])
        selected_individuals.append(individuals[best_idx])

    return selected_individuals
        \end{lstlisting}


        \section{Analysis of an Evolved Selection Operator}
        \label{sec: Analysis of Evolved Operator}

        \subsection{Code Evolved by LLM-Meta-SR}

        \subsubsection{Static Analysis}
        \Cref{lst:omni-selection} shows the best evolved selection operator among all runs. The code has been simplified by removing logically redundant parts. In selecting the first parent (parent\_a), the operator evaluates two key criteria: specificity—quantified as the lowest error achieved on any subset of the dataset, with lower values indicating superior performance in specialized regions—and a complexity measure that jointly considers the number of nodes in the symbolic expression tree and the height of the tree, thereby reflecting the interpretability of the solution. Candidate solutions are ranked such that subset error is prioritized, with model complexity serving as a secondary criterion when the subset error alone does not sufficiently differentiate candidates. This approach encourages the identification of solutions that balance high accuracy with interpretability.

        For the selection of the second parent (parent\_b), the operator computes the absolute cosine similarity between the residuals of each candidate in the population and the residual of the previously selected first parent. The second parent is then chosen based on a combination of semantic complementarity, as measured by cosine similarity, and model complexity. The trade-off between complementarity and complexity is controlled by a linear function related to the evolutionary stage. In the early stages, the pressure toward parsimony is intentionally relaxed to promote broader exploration of the search space. In contrast, in later stages, the pressure increases to favor models that are both accurate and concise, thus facilitating interpretability.

        Overall, the selection operator satisfies all the desired properties, including interpretability, diversity, complementarity, stage-awareness, and vectorization, as defined in \Cref{sec: Operator Design Principle}.
        \FloatBarrier

        \begin{lstlisting}[caption={Omni Selection}, label={lst:omni-selection}]
def omni_selection(population, k=100, status={}):
    stage = np.clip(status.get("evolutionary_stage", 0), 0, 1)
    n = len(population)
    half_k = k // 2
    y = population[0].y
    n_cases = y.size

    ssize = max(7, n_cases // max(1, 2 * half_k))
    half_struct = half_k // 2
    structured = [
        np.arange(i * ssize, min((i + 1) * ssize, n_cases)) for i in range(half_struct)
    ]
    random_ = [
        np.random.choice(n_cases, ssize, replace=False)
        for _ in range(half_k - half_struct)
    ]
    subsets = structured + random_

    residuals = np.vstack([ind.y - ind.predicted_values for ind in population])
    complexity = np.array([len(ind) + ind.height for ind in population], float)
    complexity /= max(1, complexity.max())
    subset_mse = np.array(
        [
            [((residuals[i, s]) ** 2).mean() if s.size else np.inf for s in subsets]
            for i in range(n)
        ]
    )
    comp_factor = 0.25 + 0.25 * stage

    parent_a = [
        population[np.lexsort((complexity, subset_mse[:, i]))[0]]
        for i in range(len(subsets))
    ]

    idx_map = {ind: i for i, ind in enumerate(population)}
    norms = np.linalg.norm(residuals, axis=1) + 1e-12

    parent_b = []
    for a in parent_a:
        i_a = idx_map[a]
        res_a = residuals[i_a]
        cors = (residuals @ res_a) / (norms * norms[i_a])
        cors[i_a] = 1
        comp_score = np.abs(cors) + comp_factor * complexity
        b_idx = np.argmin(comp_score)
        parent_b.append(population[b_idx])

    return [ind for pair in zip(parent_a, parent_b) for ind in pair][:k]
        \end{lstlisting}
